void MenuText(inout vec3 color, vec2 p, in AppState s)
{
	p -= vec2(-160, -1);

	vec2 scale = vec2(4., 8.);
	vec2 t = floor(p / scale);

	float tab = 1.;
	if (t.y >= 6. && t.y < 10.)
	{
		p.x -= tab * scale.x;
		t.x -= tab;
	}
	if (t.y >= 0. && t.y < 5.)
	{
		p.x -= tab * scale.x;
		t.x -= tab;
	}
	if (t.y >= 0. && t.y < 3.)
	{
		p.x -= tab * scale.x;
		t.x -= tab;
	}

	uint v = 0u;
	v = t.y == 10. ? (t.x < 4. ? 1718777171u : (t.x < 8. ? 6644577u : 0u)) : v;
	v = t.y == 9. ? (t.x < 4. ? 1635018061u : (t.x < 8. ? 108u : 0u)) : v;
	v = t.y == 8. ? (t.x < 4. ? 1818585412u : (t.x < 8. ? 1920230245u : 25449u)) : v;
	v = t.y == 7. ? (t.x < 4. ? 1735749458u : (t.x < 8. ? 1936027240u : 115u)) : v;
	v = t.y == 6. ? (t.x < 4. ? 1702060354u : (t.x < 8. ? 1819231008u : 29295u)) : v;
	v = t.y == 5. ? (t.x < 4. ? 1751607628u : (t.x < 8. ? 1735289204u : 0u)) : v;
	v = t.y == 4. ? (t.x < 4. ? 1717987652u : (t.x < 8. ? 6648693u : 0u)) : v;
	v = t.y == 3. ? (t.x < 4. ? 1667592275u : (t.x < 8. ? 1918987381u : 0u)) : v;
	v = t.y == 2. ? (t.x < 4. ? 1953720644u : (t.x < 8. ? 1969383794u : 1852795252u)) : v;
	v = t.y == 1. ? (t.x < 4. ? 1936028230u : (t.x < 8. ? 7103854u : 0u)) : v;
	v = t.y == 0. ? (t.x < 4. ? 1836016967u : (t.x < 8. ? 2037544037u : 0u)) : v;
	v = t.x >= 0. && t.x < 12. ? v : 0u;

	float c = float((v >> uint(8. * t.x)) & 255u);

	vec3 textColor = vec3(.3);
	if (t.y == 10. - s.menuId)
	{
		textColor = vec3(0.74, 0.5, 0.12);
	}

	p = (p - t * scale) / scale;
	p.x = (p.x - .5) * .45 + .5;
	float sdf = TextSDF(p, c);
	if (c != 0.)
	{
		color = mix(textColor, color, smoothstep(-.05, +.05, sdf));
	}
}

void DrawMenuControls(inout vec3 color, vec2 p, in AppState s)
{
	p -= vec2(-110, 74);

	// radial
	float c2 = Capsule(p - vec2(0., -3.5), 3., 4.);
	float c1 = Circle(p + vec2(0., 7. - 7. * s.metal), 2.5);

	// roughness slider
	p.y += 15.;
	c1 = min(c1, Capsule(p.yx - vec2(0., 20.), 1., 20.));
	c1 = min(c1, Circle(p - vec2(40. * s.roughness, 0.), 2.5));

	p.y += 8.;
	c1 = min(c1, Rectangle(p - vec2(19.5, 0.), vec2(21.4, 4.)));
	color = mix(color, vec3(0.9), Smooth(-c2 * 2.));
	color = mix(color, vec3(0.3), Smooth(-c1 * 2.));

	for (int i = 0; i < 6; ++i)
	{
		vec2 o = vec2(i == int(s.baseColor) ? 2.5 : 3.5);
		color = mix(color, BASE_COLORS[i], Smooth(-2. * Rectangle(p - vec2(2. + float(i) * 7., 0.), o)));
	}
}

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    vec2 q = fragCoord.xy / iResolution.xy;
	vec2 uv = fragCoord.xy / iResolution.xy;
	vec2 p = vec2(0.);

	AppState s;
	LoadState(s);

	vec3 color = vec3(1., .98, .94) * mix(1.0, 0.4, Smooth(abs(.5 - uv.y)));
	float vignette = q.x * q.y * (1.0 - q.x) * (1.0 - q.y);
	vignette = saturate(pow(32.0 * vignette, 0.05));
	color *= vignette;

#ifdef AA
    vec3 tot = vec3(0.0);
    for( int m=0; m<AA; m++ )
    for( int n=0; n<AA; n++ )
    {
    vec2 o = vec2(float(m),float(n)) / float(AA) - 0.5;
    q = (fragCoord.xy + o) / iResolution.xy;
#endif
	p = -1. + 2. * q;
	p.x *= iResolution.x / iResolution.y;
	p *= 100.;
	DrawScene(color, p, s);
#ifdef AA
    tot += color;
    }
    tot /= float(AA*AA);
    color = tot;
#endif

	Diagram(color, p, s);
	InfoText(color, p, s);
	MenuText(color, p, s);
	DrawMenuControls(color, p, s);

	fragColor = vec4(color, 1.);
}

// control loop

const float MENU_SURFACE = 0.;
const float MENU_METAL = 1.;
const float MENU_DIELECTRIC = 2.;
const float MENU_ROUGHNESS = 3.;
const float MENU_BASE_COLOR = 4.;
const float MENU_LIGHTING = 5.;
const float MENU_DIFFUSE = 6.;
const float MENU_SPECULAR = 7.;
const float MENU_DISTR = 8.;
const float MENU_FRESNEL = 9.;
const float MENU_GEOMETRY = 10.;

const float FOCUS_SLIDER = 1.;
const float FOCUS_OBJ = 2.;
const float FOCUS_COLOR = 3.;

struct AppState
{
    float menuId;
    float metal;
    float roughness;
    float baseColor;
    float focus;
    float focusObjRot;
    float objRot;
};

vec4 LoadValue(int x, int y)
{
    return texelFetch(iChannel0, ivec2(x, y), 0);
}

void LoadState(out AppState s)
{
    vec4 data;

    data = LoadValue(0, 0);
    s.menuId = data.x;
    s.metal = data.y;
    s.roughness = data.z;
    s.baseColor = data.w;

    data = LoadValue(1, 0);
    s.focus = data.x;
    s.focusObjRot = data.y;
    s.objRot = data.z;
}

void StoreValue(vec2 re, vec4 va, inout vec4 fragColor, vec2 fragCoord)
{
    fragCoord = floor(fragCoord);
    fragColor = (fragCoord.x == re.x && fragCoord.y == re.y) ? va : fragColor;
}

vec4 SaveState(in AppState s, in vec2 fragCoord)
{
    vec4 ret = vec4(0.);
    StoreValue(vec2(0., 0.), vec4(s.menuId, s.metal, s.roughness, s.baseColor), ret, fragCoord);
    StoreValue(vec2(1., 0.), vec4(s.focus, s.focusObjRot, s.objRot, 0.), ret, fragCoord);
    ret = iFrame >= 1 ? ret : vec4(0.);
    return ret;
}

float saturate(float x)
{
    return clamp(x, 0., 1.);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    if (fragCoord.x >= 8. || fragCoord.y >= 8.)
    {
        discard;
    }

    AppState s;
    LoadState(s);

    vec4 q = iMouse / iResolution.xyxy;
    vec4 m = -1. + 2. * q;
    m.xz *= iResolution.x / iResolution.y;
    m *= 100.;

    vec4 sliderM = m - vec2(-110, 74).xyxy;
    if (sliderM.z >= -4. && sliderM.z < 44. && sliderM.w >= -20. && sliderM.w < -10.)
    {
        s.focus = FOCUS_SLIDER;
    }
    else if (sliderM.z >= -4. && sliderM.z < 44. && sliderM.w >= -30. && sliderM.w < -20.)
    {
        s.focus = FOCUS_COLOR;
    }
    else if (sliderM.z >= -4. && sliderM.z < 6. && sliderM.w >= -10. && sliderM.w < -4.)
    {
        s.metal = 0.;
        s.menuId = s.menuId == MENU_METAL ? MENU_DIELECTRIC : s.menuId;
    }
    else if (sliderM.z >= -4. && sliderM.z < 6. && sliderM.w >= -4. && sliderM.w < 6.)
    {
        s.metal = 1.;
        s.menuId = s.menuId == MENU_DIELECTRIC ? MENU_METAL : s.menuId;
    }
    else if (m.w > -100. && m.w < 40. && abs(m.z + 20.) < 70.)
    {
        if (s.focus != FOCUS_OBJ)
        {
            s.focusObjRot = s.objRot;
        }
        s.focus = FOCUS_OBJ;
    }
    else
    {
        s.focus = 0.;
        vec2 mp = (m.xy - vec2(-160, -1));
        float menuId = mp.x < 40. || (mp.x < 60. && (mp.y > 18. && mp.y < 24.)) ? 10. - floor(mp.y / 8.) : -1.;
        if (menuId >= 0. && menuId <= 10.)
        {
            s.menuId = menuId;
        }
        s.metal = menuId == MENU_METAL ? 1. : s.metal;
        s.metal = menuId == MENU_DIELECTRIC ? 0. : s.metal;
    }

    if (s.focus == FOCUS_SLIDER)
    {
        s.roughness = saturate(sliderM.x / 40.);
    }
    if (s.focus == FOCUS_COLOR)
    {
        s.baseColor = floor(clamp((sliderM.x * 5.) / 32., 0., 5.));
    }
    if (s.focus == FOCUS_OBJ)
    {
        s.objRot = s.focusObjRot + .04 * (m.x - m.z);
    }

    fragColor = SaveState(s, fragCoord);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord.xy / iResolution.xy;
	vec3 color = vec3(0.0); 

    if( iFrame > 0 ) {
        color = texture( iChannel0, uv ).xyz;
        color /= float( iFrame );
        color = pow( color, vec3(0.4545) );
    }

    fragColor = vec4( color, 1.0 );
}

