// Tetrahedral normal technique with a loop to avoid inlining getSDF()
// This should improve compilation times
// https://iquilezles.org/articles/normalsSDF
vec3 getNormal(vec3 p){
    vec3 n = vec3(0.0);
    int id;
    for(int i = ZERO; i < 4; i++){
        vec3 e = 0.5773*(2.0*vec3((((i+3)>>1)&1),((i>>1)&1),(i&1))-1.0);
        n += e*getSDF(p+e*EPSILON, id);
    }
    return normalize(n);
}

// Get orthonormal basis from surface normal
// https://graphics.pixar.com/library/OrthonormalB/paper.pdf
void pixarONB(vec3 n, out vec3 b1, out vec3 b2){
	float sign_ = n.z >= 0.0 ? 1.0 : -1.0;
	float a = -1.0 / (sign_ + n.z);
	float b = n.x * n.y * a;
	b1 = vec3(1.0 + sign_ * n.x * n.x * a, sign_ * b, -sign_ * n.x);
	b2 = vec3(b, sign_ + n.y * n.y * a, -n.y);
}

// Return the the normal after applying a normal map
vec3 getDetailNormal(vec3 p, vec3 normal, float t, int id){
    vec3 tangent;
    vec3 bitangent;
    // Construct orthogonal directions tangent and bitangent to sample detail gradient in
    pixarONB(normal, tangent, bitangent);

    tangent = normalize(tangent);
    bitangent = normalize(bitangent);

    float EPS = DETAIL_EPSILON * 0.2;

    vec3 delTangent = vec3(0);
    vec3 delBitangent = vec3(0);

    for(int i = ZERO; i < 2; i++){

        // i ->  s
        // 0 ->  1
        // 1 -> -1
        float s = 1.0 - 2.0 * float(i&1);

        delTangent += s * getDetailExtrusion(p + s * tangent * EPS, normal, id);

        delBitangent += s * getDetailExtrusion(p + s * bitangent * EPS, normal, id);

    }

    return normalize(cross(delTangent, delBitangent));
}

//---------------------------- Shadows ----------------------------

// https://iquilezles.org/articles/rmshadows
float softShadow(vec3 pos, vec3 rayDir, float start, float end, float k ){
    float res = 1.0;
    float depth = start;
    int id;
    for(int counter = ZERO; counter < MAX_STEPS; counter++){
        float dist = getSDF(pos + rayDir * depth, id);
        if( abs(dist) < EPSILON){ return 0.0; }       
        if( depth > end){ break; }
        res = min(res, k*dist/depth);
        depth += dist;
    }
    return res;
}

// Ambient occlusion reduces the ambient light strength in areas which are closely shielded 
// by other objects
// https://www.youtube.com/watch?v=22PZF7fWLqI
float ambientOcclusion(vec3 position, vec3 normal){

	float ao = 0.0;
    // step size
    float del = 0.08;
    float weight = 0.1;

    // Travel out from point with fixed step size and accumulate proximity to other surfaces
    // iq slides include 1.0/pow(2.0, i) factor to reduce the effect of farther objects
    // but Peer Play uses just 1.0/dist
    int id;
    for(int i = ZERO; i < 5; i++){
        float dist = float(i+1) * del;
    	// Ignore measurements from inside objects
    	ao += max(0.0, (dist - getSDF(position + normal * dist, id))/dist);
    }
    // Return a weighted occlusion amount
    return 1.0 - weight * ao;
}


//---------------------------- PBR ----------------------------

// Trowbridge-Reitz
float distribution(vec3 n, vec3 h, float roughness){
    float a_2 = roughness * roughness;
	return a_2/(PI * pow(pow(dot_c(n, h), 2.0) * (a_2 - 1.0) + 1.0, 2.0));
}

// GGX and Schlick-Beckmann
float geometry(float cosTheta, float k){
	return (cosTheta) / (cosTheta * (1.0 - k) + k);
}

float smiths(float NdotV, float NdotL, float roughness){
    float k = pow(roughness + 1.0, 2.0) / 8.0; 
	return geometry(NdotV, k) * geometry(NdotL, k);
}

// Fresnel-Schlick
vec3 fresnel(float cosTheta, vec3 F0){
    return F0 + (1.0 - F0) * pow(1.0 - cosTheta, 5.0);
} 

// Cook-Torrance BRDF
vec3 BRDF(vec3 p, vec3 n, vec3 viewDir, vec3 lightDir,
          vec3 albedo, vec3 F0, float roughness, float metalness){

    vec3 h = normalize(viewDir + lightDir);
    float NdotL = dot_c(lightDir, n);
    float NdotV = dot_c(viewDir, n);

    float cosTheta = dot_c(h, viewDir);
    vec3 lambertian = albedo / PI;

    float D = distribution(n, h, roughness);
    vec3 F = fresnel(cosTheta, F0);

    float G = smiths(NdotV, NdotL, roughness);

    vec3 specular =  D * F * G / max(0.0001, (4.0 * NdotV * NdotL));

    vec3 kD = (1.0 - F) * (1.0 - metalness);
    return kD * lambertian + specular;
}

vec3 getSPHIrradiance(vec3 normal){

    vec4 n = vec4(normal, 1.0);

    mat4 redMatrix = mat4(
        texelFetch(iChannel2, ivec2(0,0), 0),
        texelFetch(iChannel2, ivec2(0,1), 0),
        texelFetch(iChannel2, ivec2(0,2), 0),
        texelFetch(iChannel2, ivec2(0,3), 0));


    mat4 grnMatrix = mat4(
        texelFetch(iChannel2, ivec2(1,0), 0),
        texelFetch(iChannel2, ivec2(1,1), 0),
        texelFetch(iChannel2, ivec2(1,2), 0),
        texelFetch(iChannel2, ivec2(1,3), 0));


    mat4 bluMatrix = mat4(
        texelFetch(iChannel2, ivec2(2,0), 0),
        texelFetch(iChannel2, ivec2(2,1), 0),
        texelFetch(iChannel2, ivec2(2,2), 0),
        texelFetch(iChannel2, ivec2(2,3), 0));

    float r = dot(n, redMatrix * n);
    float g = dot(n, grnMatrix * n);
    float b = dot(n, bluMatrix * n);

    return vec3(r, g, b);
}

vec3 getEnvironment(vec3 rayDir){
    vec2 texCoord = vec2((atan(rayDir.z, rayDir.x) / TWO_PI) + 0.5, acos(rayDir.y) / PI);
    return texture(iChannel2, texCoord).rgb;
}

vec3 getIrradiance(vec3 p, vec3 n, vec3 rayDir, vec3 geoNormal, int id){
    vec3 I = vec3(0);

#ifdef ANIMATE_LIGHT
    sunLocation = mod(iTime, 6.28);
#endif

    vec3 albedo = 0.25 * vec3(0.75,0.4,0.2);
    vec3 F0 = vec3(0.01);
    float roughness = 1.0;
    float metalness = 0.0;

    if(id == NOSE || id == EYES){
        albedo = vec3(0.02);
    }

    vec3 lightPosition = 10.0*normalize(vec3(cos(sunLocation), sunHeight, sin(sunLocation)));
    vec3 lightColour = vec3(5);

    vec3 vectorToLight = lightPosition - p;
   	vec3 lightDir = normalize(vectorToLight);
    vec3 radiance = lightColour;
    float shadow = softShadow(p + n * EPSILON * 2.0, lightDir, MIN_DIST,
                              length(vectorToLight), SHADOW_SHARPNESS);
    I += shadow 
        * BRDF(p, n, -rayDir, lightDir, albedo, F0, roughness, metalness) 
        * radiance 
        * dot_c(n, lightDir);


    // Ambient occlusion from geometry. Use texture heightmap for detail ao.
    float ao = ambientOcclusion(p, geoNormal)
        	 * length(getTriplanar(p, normalize(geoNormal), id));

    // Ignore kS until specular irradiance is implemented
	vec3 kD = vec3(1.0 - metalness);
	vec3 irradiance = AMBIENT_STRENGTH * getSPHIrradiance(n);
	vec3 diffuse    = irradiance * albedo / PI;
	vec3 ambient    = kD * diffuse * ao; 

    return ambient + I;
}

//---------------------------- Render ----------------------------

// https://knarkowicz.wordpress.com/2016/01/06/aces-filmic-tone-mapping-curve/
vec3 ACESFilm(vec3 x){
    return clamp((x * (2.51 * x + 0.03)) / (x * (2.43 * x + 0.59) + 0.14), 0.0, 1.0);
}

vec3 getColour(vec3 cameraPos, vec3 rayDir, float dist, int id){

    // If the ray endpoint is not at a surface
    if (dist > MAX_DIST - EPSILON) {
        return getEnvironment(rayDir);
    }

    // Else, determine the surface colour
    vec3 position = cameraPos + rayDir * dist;
    vec3 normal = getNormal(position);

    // Avoid artefacts when trying to sample detail normals across Z-plane. Shape deformation
    // increases the region where visible errors occur.
    if(abs(normal.z) < 1e-5){
    	normal.z = 1e-5;
    }

    normal = normalize(normal);
    vec3 detailNormal = normalize(getDetailNormal(position, normal, dist, id));
    return getIrradiance(position, detailNormal, rayDir, normal, id);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ){

	//----------------- Define a camera -----------------

    vec3 rayDir = rayDirection(60.0, fragCoord);

    vec3 cameraPos = texelFetch(iChannel0, ivec2(0.5, 1.5), 0).xyz;

    vec3 targetDir = -cameraPos;

    vec3 up = vec3(0.0, 1.0, 0.0);

    // Get the view matrix from the camera orientation
    mat3 viewMatrix = lookAt(cameraPos, targetDir, up);

    // Transform the ray to point in the correct direction
    rayDir = normalize(viewMatrix * rayDir);

    //---------------------------------------------------

    // Track which part was hit.
    int id = -1;

    // Find the distance to where the ray stops
    float dist = distanceToScene(cameraPos, rayDir, MIN_DIST, MAX_DIST, id);
    vec3 col = vec3(0);

    if (dist < MAX_DIST) {
        vec3 position = cameraPos + rayDir * dist;
        vec3 normal = getNormal(position);

        // Avoid artefacts when trying to sample detail normals across Z-plane. Shape 
        // deformation increases the region where visible errors occur.
        if(abs(normal.z) < 1e-5){
            normal.z = 1e-5;
        }

        normal = normalize(normal);
        vec3 detailNormal = normalize(getDetailNormal(position, normal, dist, id));
        col = getIrradiance(position, detailNormal, rayDir, normal, id);

        // Tonemapping
        col = ACESFilm(EXPOSURE * col);

    }else{
        col = getEnvironment(rayDir);
    }

    // Gamma
    col = pow(col, vec3(0.4545));


    //col = texture(iChannel2, fragCoord.xy/iChannelResolution[1].xy).rrr;


    fragColor = vec4(col, 1.0);
}

//Track mouse movement and resolution change between frames and set camera position.

#define PI 3.14159
#define EPS 1e-4
#define CAMERA_DIST 3.5

void mainImage( out vec4 fragColor, in vec2 fragCoord ) {

    //Work with just the first four pixels.
    if((fragCoord.x == 0.5) && (fragCoord.y < 4.0)){

        vec4 oldMouse = texelFetch(iChannel0, ivec2(0.5), 0).xyzw;
        vec4 mouse = (iMouse / iResolution.xyxy); 
        vec4 newMouse = vec4(0);

        float mouseDownLastFrame = texelFetch(iChannel0, ivec2(0.5, 3.5), 0).x;

        //If mouse button is down and was down last frame
        if(iMouse.z > 0.0 && mouseDownLastFrame > 0.0){

            //Difference between mouse position last frame and now.
            vec2 mouseMove = mouse.xy-oldMouse.zw;
            newMouse = vec4(oldMouse.xy + vec2(5.0, 3.0)*mouseMove, mouse.xy);
        }else{
            newMouse = vec4(oldMouse.xy, mouse.xy);
        }
        newMouse.x = mod(newMouse.x, 2.0*PI);
        newMouse.y = min(0.99, max(-0.99, newMouse.y));

        //Store mouse data in the first pixel of Buffer B.
        if(fragCoord == vec2(0.5, 0.5)){
            //Set value at first frames
            if(iFrame < 5){
                newMouse = vec4(-2.0, -0.2, 0.0, 0.0);
            }
            fragColor = vec4(newMouse);
        }

        //Store camera position in the second pixel of Buffer B.
        if(fragCoord == vec2(0.5, 1.5)){
            //Set camera position from mouse information.
            vec3 cameraPos = CAMERA_DIST * vec3(sin(newMouse.x), -sin(newMouse.y), -cos(newMouse.x));
            fragColor = vec4(cameraPos, 1.0);
        }

        //Store resolution change data in the third pixel of Buffer B.
        if(fragCoord == vec2(0.5, 2.5)){
            float resolutionChangeFlag = 0.0;
            //The resolution last frame.
            vec2 oldResolution = texelFetch(iChannel0, ivec2(0.5, 2.5), 0).yz;

            if(iResolution.xy != oldResolution){
            	resolutionChangeFlag = 1.0;
            }

        	fragColor = vec4(resolutionChangeFlag, iResolution.xy, 1.0);
        }

        //Store whether the mouse button is down in the fourth pixel of Buffer A
        if(fragCoord == vec2(0.5, 3.5)){
            if(iMouse.z > 0.0){
            	fragColor = vec4(vec3(1.0), 1.0);
            }else{
            	fragColor = vec4(vec3(0.0), 1.0);
            }
        }

    }
}

// Heightmap for a knitted texture.

float saturate(float x){
	return clamp(x, 0.0, 1.0);
}

float remap(float x, float low1, float high1, float low2, float high2){
	return low2 + (x - low1) * (high2 - low2) / (high1 - low1);
}

vec2 rotate(vec2 p, float angle){
	return mat2(cos(angle), sin(angle), -sin(angle), cos(angle)) * p;
}

float circularOut(float f){
  return sqrt((2.0 - f) * f);
}

float getCellHeight(vec2 p, vec2 id){

    vec2 height;

    float d = circularOut(1.0-length(p.x));
    float detail;
    float angle;

    float theta = sin(7.38);
	float detailTheta = sin(1.68);

    float repeat = 4.0;
    float threadRepeat = 10.0;

    if(mod(id.x, 2.0) == 0.0){
        detail = 0.85*abs(cos(repeat*(rotate(p, theta)).x));
        angle = detailTheta;
    }else{
        detail = 0.85*abs(cos(-repeat*(rotate(p, -theta)).x));
        angle = -detailTheta;
    }

    d = pow(d, 2.0) * saturate(remap(d, detail, 1.1, 0.0, 1.0));
    detail = 0.12 * sin(threadRepeat*(rotate(p, angle)).x);

    return saturate(remap(d, detail, 1.0, 0.0, 1.0));

}

void mainImage( out vec4 fragColor, in vec2 fragCoord ){    

    bool resolutionChanged = (texelFetch(iChannel0, ivec2(0.5, 2.5), 0).x == 1.0);

    // Draw map at the first frame or when the resolution has changed.
    if(iFrame < 1 || resolutionChanged || length(texture(iChannel2, vec2(0)).rgb) > 0.0){
    	vec2 scale = vec2(10.0, 10.0);
        vec2 uv;
        float height;
        uv = fragCoord.xy/iResolution.xy;
        uv *= scale;
        vec2 p = fract(uv)-0.5;
        vec2 id = floor(uv);

        height = getCellHeight(p, id);
        fragColor = vec4(height, 
                         length(texture(iChannel2, (fragCoord/iResolution.xy)).rgb), 
                         0.0, 
                         1.0);
    }else{
        fragColor = texelFetch(iChannel1, ivec2(fragCoord), 0);
    }
}

//
//	Diffuse IBL using spherical harmonics
//
// 	Read the environment map and calculate 9 spherical harmonics coefficients for each channel.
//	The coefficients will describe the low frequency data of the environment. We can use them
//	to construct a matrix which, when multiplied with a view vector, will give the data in 
//	that direction. The low frequency data is similar to a convoluted irradiance map and is 
//	used for diffuse image based lighting, which gives us the ambient colour for shading. 
//
//	Based on:
//	[1] https://cseweb.ucsd.edu/~ravir/papers/envmap/envmap.pdf
//	[2] http://orlandoaguilar.github.io/sh/spherical/harmonics/irradiance/map/2017/02/12/SphericalHarmonics.html
//	[3] https://metashapes.com/blog/realtime-image-based-lighting-using-spherical-harmonics/
//	[4]	https://stackoverflow.com/questions/9600801/evenly-distributing-n-points-on-a-sphere/26127012#26127012
//	[5] https://bduvenhage.me/geometry/2019/07/31/generating-equidistant-vectors.html
//  [6] https://andrew-pham.blog/2019/08/26/spherical-harmonics/
//
//	This tab writes the matrix from equaton 12 of [1] used in lighting calculations later.

//Constants cn from equation 12 in [1]
const float c1 = 0.429043;
const float c2 = 0.511664;
const float c3 = 0.743125;
const float c4 = 0.886227;
const float c5 = 0.247708;

//First 9 spherical harmonic coefficients from equation 3 in [1]
const float Y00 = 0.282095;
const float Y1n = 0.488603; // 3 direction dependent values
const float Y2n = 1.092548; // 3 direction dependent values
const float Y20 = 0.315392;
const float Y22 = 0.546274;

vec3 getRadiance(vec3 dir){
    //Shadertoy textures are gamma corrected. Undo for lighting calculations.
    vec3 col = inv_gamma(texture(iChannel2, dir).rgb);
    // Add some bloom to the environment
    col += 0.5 * pow(col, vec3(2));
    return col;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord){

    vec3 currentColour = texture(iChannel2, vec3(1,1,1)).rgb;

    bool cubemapChangedFlag = texelFetch(iChannel1, ivec2(4.5, 4.5), 0).rgb != currentColour;
    bool resolutionChanged = texelFetch(iChannel0, ivec2(0.5, 2.5), 0).r > 0.0;
    bool run = iFrame == 0 || cubemapChangedFlag || resolutionChanged;

    //Cubemap load may take a while. Run code first frame and while last frame flag was 0
    if(run){

    vec4 col = vec4(0);

        //  Store an equirectangular projection of the environment map. Subsequent code will
        //  overwrite specific pixels to store the SPH matrices and state flags but this 
        //  should not be visible in the final redner.
        vec2 texCoord = fragCoord.xy / iResolution.xy;
        vec2 thetaphi = ((texCoord * 2.0) - vec2(1.0)) * vec2(PI, HALF_PI); 
        vec3 rayDir = vec3( cos(thetaphi.y) * cos(thetaphi.x), 
                           -sin(thetaphi.y), 
                            cos(thetaphi.y) * sin(thetaphi.x));

        col = vec4(getRadiance(rayDir), 1.0);
        //Ensure radiance is not 0
        col.x = max(col.x, 1e-5);
        col.y = max(col.y, 1e-5);
        col.z = max(col.z, 1e-5);

        //Coefficient values to accumulate
        vec3 L00 = vec3(0);
        vec3 L1_1 = vec3(0);
        vec3 L10 = vec3(0);
        vec3 L11 = vec3(0);

        vec3 L2_2 = vec3(0);
        vec3 L2_1 = vec3(0);
        vec3 L20 = vec3(0);
        vec3 L21 = vec3(0);
        vec3 L22 = vec3(0);

        //To make the sampling rate scalable and independent of the cubemap dimensions, we can 
        //sample a set number of equidistant directions on a sphere. While this is not doable 
        //for all number of directions, a good approximation is the Fibonacci spiral on a 
        //sphere.

        //From [4]
        //Golden angle in radians
        float phi = PI * (3.0 - sqrt(5.0));
        float pointCount;

        if(run){
            pointCount = 1024.0;
        }else{
            pointCount = 1.0;
            return;
        }

        for(float i = 0.0; i < pointCount; i++){

            float y = 1.0 - (i / pointCount) * 2.0;
            //Radius at y
            float radius = sqrt(1.0 - y * y);  

            //Golden angle increment
            float theta = phi * i;

            float x = cos(theta) * radius;
            float z = sin(theta) * radius;

            //Sample directiion
            vec3 dir = normalize(vec3(x, y, z));

            //Envronment map value in the direction (interpolated)
            vec3 radiance = getRadiance(dir);

            //Accumulate value weighted by spherical harmonic coefficient in the direction
            L00 += radiance * Y00;
            L1_1 += radiance * Y1n * dir.y;
            L10 += radiance * Y1n * dir.z;
            L11 += radiance * Y1n * dir.x;
            L2_2 += radiance * Y2n * dir.x * dir.y;
            L2_1 += radiance * Y2n * dir.y * dir.z;
            L20 += radiance * Y20 * (3.0 * pow(dir.z, 2.0) - 1.0);
            L21 += radiance * Y2n * dir.x * dir.z;
            L22 += radiance * Y22 * (pow(dir.x, 2.0) - pow(dir.y, 2.0));
        }

        //Scale the sum of coefficents on a sphere
        float factor = 4.0*PI / pointCount;

        L00 *= factor;
        L1_1 *= factor;
        L10 *= factor;
        L11 *= factor;
        L2_2 *= factor;
        L2_1 *= factor;
        L20 *= factor;
        L21 *= factor;
        L22 *= factor;

        //Write 4x4 matrix to bufferB
        //GLSL matrices are column major
        if(fragCoord.x < 3.0 && fragCoord.y < 4.0){

            int idxM = int(fragCoord.y-0.5);

            if(fragCoord.x == 0.5){
                mat4 redMatrix;
                redMatrix[0] = vec4(c1*L22.r, c1*L2_2.r, c1*L21.r, c2*L11.r);
                redMatrix[1] = vec4(c1*L2_2.r, -c1*L22.r, c1*L2_1.r, c2*L1_1.r);
                redMatrix[2] = vec4(c1*L21.r, c1*L2_1.r, c3*L20.r, c2*L10.r);
                redMatrix[3] = vec4(c2*L11.r, c2*L1_1.r, c2*L10.r, c4*L00.r-c5*L20.r);
                col = redMatrix[idxM];
            }

            if(fragCoord.x == 1.5){
                mat4 grnMatrix;
                grnMatrix[0] = vec4(c1*L22.g, c1*L2_2.g, c1*L21.g, c2*L11.g);
                grnMatrix[1] = vec4(c1*L2_2.g, -c1*L22.g, c1*L2_1.g, c2*L1_1.g);
                grnMatrix[2] = vec4(c1*L21.g, c1*L2_1.g, c3*L20.g, c2*L10.g);
                grnMatrix[3] = vec4(c2*L11.g, c2*L1_1.g, c2*L10.g, c4*L00.g-c5*L20.g);
                col = grnMatrix[idxM];
            }

            if(fragCoord.x == 2.5){
                mat4 bluMatrix;
                bluMatrix[0] = vec4(c1*L22.b, c1*L2_2.b, c1*L21.b, c2*L11.b);
                bluMatrix[1] = vec4(c1*L2_2.b, -c1*L22.b, c1*L2_1.b, c2*L1_1.b);
                bluMatrix[2] = vec4(c1*L21.b, c1*L2_1.b, c3*L20.b, c2*L10.b);
                bluMatrix[3] = vec4(c2*L11.b, c2*L1_1.b, c2*L10.b, c4*L00.b-c5*L20.b);
                col = bluMatrix[idxM];
            }
        }

                //Store a sample colour of the cubemap to detect load and change
        if(fragCoord.x == 4.5 && fragCoord.y == 4.5){
              col = vec4(texture(iChannel2, vec3(1,1,1)).rgb, 1.0);
        }

        fragColor = col;
    }else{
        //Reuse SH matrices
        fragColor = texture(iChannel1, fragCoord.xy/iResolution.xy);
    }
}

vec3 ACES(vec3 x) {
    float a = 2.51;
    float b = 0.03;
    float c = 2.1;
    float d = 0.7;
    float e = 0.12;
    return (x * (a * x + b)) / (x * (c * x + d) + e);
}

void mainImage(out vec4 fragColor, vec2 fragCoord) {
    // Concise recursion system borrowed from Poisson (starts in main in buffer A)
    vec4 col = texelFetch(iChannel0, ivec2(fragCoord), 0);
    col.rgb /= col.a;
    col.rgb = ACES(col.rgb);
    fragColor = vec4(pow(col.rgb, vec3(1.0/2.2)), 1);
}

struct material {
    vec3 col;
    float emission;
    float smoothness;
    float specularProb;
    float refractIndex;
    float opacity;
};

// Poisson's hash (https://www.shadertoy.com/view/dssXRj)
float seed;
vec2 hash22(vec2 p){
	vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973));
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.xx + p3.yz) * p3.zy);
}

float hash1() {
    return fract(sin(seed += 0.1) * 4568.7564);
}

vec2 hash2() {
    return vec2(hash1(), hash1());
}

vec3 hash3() {
    return vec3(hash1(), hash1(), hash1());
}

vec2 randomDir2D() {
    vec2 curr;
    while(true) {
        curr = hash2() * 2.0 - 1.0;
        if(length(curr) < 1.0){
            return curr;
        }
    }
}

vec3 randomDir() {
    vec3 d;
    while(true) {
        d = hash3() * 2.0 - 1.0;
        if(length(d) <= 1.0) return normalize(d);
    }
}

vec3 rotate2D(vec3 p, vec2 t){
    float stx = sin(t.x);
    float ctx = cos(t.x);
    float sty = sin(t.y);
    float cty = cos(t.y);
    mat3 xRotation;
    xRotation[0] = vec3(1, 0, 0);
    xRotation[1] = vec3(0, ctx, -stx);
    xRotation[2] = vec3(0, stx, ctx);

    mat3 yRotation;
    yRotation[0] = vec3(cty, 0, -sty);
    yRotation[1] = vec3(0, 1, 0);
    yRotation[2] = vec3(sty, 0, cty);
    return p*xRotation*yRotation;
}

void raytraceSphere(vec3 o, vec3 d, inout bool h, vec4 s, inout float t, inout vec3 n, in material inMat, inout material outMat) {
    vec3 oc = o - s.xyz;
    float a = dot(d, d);
    float b = 2.0 * dot(oc, d);
    float c = dot(oc, oc) - s.w * s.w;
    float disc = b * b - 4.0 * a * c;
    float currT = (-b - sqrt(disc))/(2.0 * a);
    if (disc > 0.0 && currT >= 0.0 && currT < t) {
        t = currT;
        h = true;
        n = normalize((o + d * t) - s.xyz);
        outMat = inMat;
    }
}

float raytraceScene(vec3 o, vec3 d, out bool h, out vec3 n, out material mat) {
    h = false;
    n = vec3(0);
    float t = 1000000.0;
    //raytraceSphere(o, d, h, vec4(1, -0.25, 0, 0.25), t, n, material(vec3(0, 0, 1), 0.5, 1.0, 1.0, 1.52, 10.0), mat);
    //raytraceSphere(o, d, h, vec4(0, 0, 0, 0.5), t, n, material(vec3(0, 1, 0), 0.5, 0.6, 1.0, 1.52, 10.0), mat);
    //raytraceSphere(o, d, h, vec4(-1, -0.175, 0, 0.325), t, n, material(vec3(1, 0, 0), 0.5, 1.0, 1.0, 1.52, 10.0), mat);
    raytraceSphere(o, d, h, vec4(0, -10000.25, 0, 10000), t, n, material(vec3(1), 0.5, 1.0, 0.1, 0.0, 0.0), mat);

    for (int i = -2; i <= 2; ++i) {
        raytraceSphere(o, d, h, vec4(-2, 0, i, 0.25), t, n, material(vec3(0.2, float(i + 2) / 4.0, 0.5), 0.5, 0.0, 0.0, 0.0, 0.0), mat);
        raytraceSphere(o, d, h, vec4(-1, 0, i, 0.25), t, n, material(vec3(0.4, float(i + 2) / 4.0, 0.5), 0.5, 0.8, 0.05, 0.0, 0.0), mat);
        raytraceSphere(o, d, h, vec4(0, 0, i, 0.25), t, n, material(vec3(0.6, float(i + 2) / 4.0, 0.5), 0.5, 1.0, 0.02, 0.0, 0.0), mat);
        raytraceSphere(o, d, h, vec4(1, 0, i, 0.25), t, n, material(vec3(0.8, float(i + 2) / 4.0, 0.5), 0.5, 1.0, 0.5, 0.0, 0.0), mat);
        raytraceSphere(o, d, h, vec4(2, 0, i, 0.25), t, n, material(vec3(1, float(i + 2) / 4.0, 0.5), 0.5, 1.0, 1.0, 1.52, 10.0), mat);
    }

    return t;
}

// Raytracing in One Weekend (https://raytracing.github.io/books/RayTracingInOneWeekend.html)
float schlick(float cosTheta, float refractRatio) {
    float r = (1.0 - refractRatio) / (1.0 + refractRatio);
    r = r * r;
    return r + (1.0 - r) * pow((1.0 - cosTheta), 5.0);
}

vec3 pathtrace(vec3 o, vec3 d) {
    vec3 col = vec3(1);
    float t;
    vec3 n;
    material mat;
    bool h = false;

    for (int i = 0; i < 12; ++i) {
        h = false;
        t = raytraceScene(o, d, h, n, mat);
        if (!h) {
            col *= pow(textureLod(iChannel1, o + d * 1600.0 + vec3(0, -50, 0), 0.0).rgb, vec3(4)) * 8.0;
            break;
        } else {
            float isSpecular = mat.specularProb > hash1() ? 1.0 : 0.0;

            vec3 diffuseD = normalize(randomDir() + n);
            vec3 reflectD = normalize(reflect(d, n));

            float cosTheta = min(dot(-d, n), 1.0);
            float sinTheta = sqrt(1.0 - cosTheta * cosTheta);
            float refractRatio = dot(d, n) >= 0.0 ? mat.refractIndex : 1.0 / mat.refractIndex;

            o = o + d * t + n * sign(dot(d, n)) * 0.01;

            if (mat.refractIndex > 1.0 && schlick(cosTheta, refractRatio) <= hash1() && refractRatio * sinTheta <= 1.0) {
                float inside = sign(dot(d, n));
                d = mix(randomDir(), refract(d, -n * inside, refractRatio), mat.smoothness * isSpecular);
                if (inside < 0.0) {
                    col *= mat.col * mat.emission;
                }
            } else {
                d = mix(diffuseD, reflectD, mat.smoothness * isSpecular);

                col *= mix(mat.col * mat.emission, vec3(1), isSpecular);
            }
        }
        if (mat.emission > 1.0) break;
    }

    return col;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ){
    seed = iTime + dot(sin(fragCoord), vec2(443.712, 983.234));
    seed += hash1() * 434.251;

    vec2 uv = ((fragCoord + hash2() - 0.5) - 0.5 * iResolution.xy) / iResolution.y;

    vec3 o = rotate2D(vec3(0, 0, -7), vec2(radians(20.0), radians(40.0)));
    vec3 d = rotate2D(normalize(vec3(uv, 1.75)), vec2(radians(20.0), radians(40.0)));
    vec3 focalPoint = o + d * 7.0;

    o += rotate2D(vec3(randomDir2D(), 0), vec2(radians(20.0), radians(40.0))) * 0.1;
    vec3 shiftedDir = normalize(focalPoint - o);

    vec3 col = pathtrace(o, shiftedDir);
    vec4 data = texelFetch(iChannel0, ivec2(fragCoord), 0);
    if(iMouse.z > 0.0){
        data *= 0.0;
    }
    data += vec4(col, 1);

    fragColor = data;
}

