void mainImage( out vec4 fragColor, in vec2 fragCoord ) {
    ivec2 f = ivec2(fragCoord);

    if (f.x > 0 || f.y > NUM_BONES) return;

    initAnimation(iTime);

    vec3 animPos = texelFetch(iChannel0, f, 0).xyz;
    animPos.y = max(animPos.y - planeY, 1.);

    vec3 startPos = vec3(animPos.x,-9,animPos.z);

    float t = mod(offsetTime(iTime), DURATION_TOTAL);
    vec3 pos = animPos;

    if (t < DURATION_START + DURATION_MORPH_ANIM) {
        float tm = t-(DURATION_START-DURATION_MORPH_STILL);
        if ( tm > 0.) {
            pos = mix(startPos, animPos, smoothstep(0.,1., tm / DURATION_MORPH));
        } else {
            pos = startPos;
        }

        if (f.y == HEAD) {
            pos.y = max(pos.y, 1.); 

            float tf = max(0., (t-DURATION_START*.5))*2.;
            float atm = clamp(1.-max(0.,tf/(DURATION_START+DURATION_MORPH_ANIM)), 0., 1.);
            float maxf = 50.f * atm*atm*atm*atm;
            float freq = min(10.,1.75/(.2+atm*atm));
            float h = maxf * abs(cos(freq*tf)); 
            pos.y += h;
        }
    } else if (t > DURATION_START + DURATION_ANIM - DURATION_MORPH_ANIM) {
        float tm = t-(DURATION_START + DURATION_ANIM - DURATION_MORPH_ANIM);
        if ( tm > 0.) {
            pos = mix(startPos, animPos, smoothstep(1.,0., tm / DURATION_MORPH));
        } else {
            pos = startPos;
        }

        if (f.y == HEAD) {
            pos.y = max(pos.y, 1.); 
            pos.xz += max(0.,tm) * vec2(3.5,30.);
        }
    } 


    pos = pos*.11;
    pos.z -= .5;

    fragColor = vec4(pos, 1.);
}

vec3 rotate(vec3 p, vec3 axis, float angle) {
    return mix(dot(p, axis) * axis, p, cos(angle)) + sin(angle) * cross(axis, p);
}

float getSpheresSDFUnique(vec3 p) {
    vec3 voxelPos = worldToVoxel(p.xyzz).xyz;
    ivec3 basePos = ivec3(floor(voxelPos));

    vec4 distances = vec4(FLOAT_INF);
    uvec4 indices = uvec4(uint(-1));

    float shapeD = 9999.0;
    for(int z = -1; z <= 1; z++) {     
        for(int y = -1; y <= 1; y++) {   
            for(int x = -1; x <= 1; x++) {
                ivec3 sampleCoord = basePos + ivec3(x, y, z);

                uvec4 fetchedClosest = fetchClosest3D(vec3(sampleCoord), iChannel1);
                for (int j = 0; j < 2; j++) {
                    uint index = fetchedClosest[j];
                    if(index == uint(-1)) { continue; }
                    if (index == uint(-1) || any(equal(indices, uvec4(index)))) {
                        continue;
                    } 

                    vec4 e = texelFetch(iChannel0, ivec2(index, 0), 0);
                    float dist = length(e.xyz - p) - e.w;

                    if (dist < distances[0]) {
                        distances = vec4(dist, distances.xyz);
                        indices = uvec4(index, indices.xyz);
                    } else if (dist < distances[1]) {
                        distances = vec4(distances.x, dist, distances.yz); 
                        indices = uvec4(indices.x, index, indices.yz);
                    } else if (dist < distances[2]) {
                        distances = vec4(distances.xy, dist, distances.z); 
                    } else if (dist < distances[3]) {
                        distances = vec4(distances.xyz, dist);             
                    }
              }
            }
        }
    }

    for(int i = 0; i < 4; i++) {
    shapeD = smin(distances[i], shapeD, 0.05 - smoothstep(0.0, 1.0, sin((iTime + 1.0) * 0.5)) * 0.009);
    }

    return shapeD;
}


float getSpheresSDF(vec3 p) {
    vec3 voxelPos = worldToVoxel(p.xyzz).xyz;
    ivec3 basePos = ivec3(floor(voxelPos));

    float shapeD = 9999.0;
    for(int z = -1; z <= 1; z++) {     
        for(int y = -1; y <= 1; y++) {   
            for(int x = -1; x <= 1; x++) {
                ivec3 sampleCoord = basePos + ivec3(x, y, z);

                uvec4 fetchedClosest = fetchClosest3D(vec3(sampleCoord), iChannel1);
                for (int j = 0; j < 2; j++) {
                    uint sphereIdx = fetchedClosest[j];
                    if(sphereIdx == uint(-1)) { continue; }

                    vec4 e = texelFetch(iChannel0, ivec2(sphereIdx, 0), 0);
                    e.w += pow(1.0 - e.w, 8.0) * 0.005;
                    float nd = length(e.xyz - p) - e.w;
                    shapeD = smin(nd, shapeD, 0.0125 - smoothstep(0.0, 1.0, sin((iTime + 1.0) * 0.5)) * 0.009);
              }
            }
        }
    }



    return shapeD;
}


float raymarchMap(vec3 ro, vec3 rd, bool groundTruth) {
    float t = 0.0;
    for(int i = 0; i < 32; i++) {
        vec3 p = ro + rd * t;

        float shapeD = !groundTruth ? 1e4 : scene(p) + 0.015;

        if(!groundTruth) {
            shapeD = min(getSpheresSDF(p), shapeD);
        }

        if(shapeD < 0.005) 
            return t;

        t += shapeD;

        if(t > 6.0) 
            break;  
    }
    return t;
}

vec3 getNormal(vec3 p) {
	float d = scene(p);
    vec2 e = vec2(.01, 0);

    vec3 n = d - vec3(
        scene(p-e.xyy),
        scene(p-e.yxy),
        scene(p-e.yyx));

    return normalize(n);
}

vec3 getSpheresNormal(vec3 p) {
	float d = getSpheresSDF(p);
    vec2 e = vec2(.01, 0);

    vec3 n = d - vec3(
        getSpheresSDF(p-e.xyy),
        getSpheresSDF(p-e.yxy),
        getSpheresSDF(p-e.yyx));

    return normalize(n);
}

vec3 shade( in vec3 p, in vec3 n, in vec3 ro, in vec3 rd, vec3 lp) {		
	float latt = pow(length(lp - p) * 2.0, 2.5) * 2.25;
    vec3 ld = normalize(vec3(2.0));
	vec3 diff = vec3(0.2,.5,1.) * (max(dot(n, ld),0.) ) ;
    vec3 col =  diff * 0.5;
	float trans =  pow( clamp( dot(-rd, -ld+n), 0., 1.), 1.) + 1.0;
	col += vec3(1.0,.2,.35) * (trans / latt );
    col += vec3(specular(p, rd, n, lp)) * 0.1;
    col += smoothstep(1., 0.6, dot(-rd, n)) * 0.1;

	return col;
}



void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    vec2 uv = fragCoord / iResolution.xy * 2.0 - 1.0;


    vec2 center   = vec2(0.5, 0.0);
    vec2 uvLeft   = uv + center;
    vec2 uvRight  = uv - center;

    float aspect = iResolution.x / iResolution.y;
    uvLeft.x  *= aspect;
    uvRight.x *= aspect;

    bool isLeftSide = (fragCoord.x < 0.5 * iResolution.x);

    bool groundTruth = isLeftSide;

    vec2 uvCam = isLeftSide ? uvLeft : uvRight;
    vec2 mouse = (iMouse.xy - 0.5 * iResolution.xy) / iResolution.y;

    vec3 rd = normalize(vec3(uvCam, -1.5));
    vec3 ro = vec3(0.0, 0.0, 2.0);

    float yrot = 0.0;
    float zrot =  sin(iTime * 2.0) * 0.25;
    if (iMouse.z > 0.0) {
        yrot += -4.0 * mouse.y;
        zrot = 4.0 * mouse.x;
    }
    rd = rotate(rd, vec3(1, 0, 0), yrot);
    ro = rotate(ro, vec3(1, 0, 0), yrot);
    rd = rotate(rd, vec3(0, 1, 0), zrot);
    ro = rotate(ro, vec3(0, 1, 0), zrot);


    float t = raymarchMap(ro, rd, groundTruth);

    if(t > 6.0) {
        fragColor = vec4(0.5, 0.5, 1.0, 1.0) * pow(length(uvCam), 0.33) * 0.5 * (hash(uvCam) * 0.1 + 0.9);
        return;
    }

    vec3 p   = ro + rd * t;    
    //vec3 nor =  isLeftSide ? getNormal(p) : getSpheresNormal(p);  
    vec3 nor =   getNormal(p);
    vec3 lp =  vec3(0.0, 0.095, 0.125);

    vec3 col = shade(p, nor, vec3(0.0), normalize(vec3(-1.5, uvCam)), lp);

    float rim = pow(clamp(1.0 - dot(nor, -rd), 0.0, 1.0), 3.0);
    col += vec3(0.5, 0.7, 1.0)*rim*0.25;

    fragColor = vec4(col, 1.0);
}

float getAvailableSpaceSDF(vec3 p, int currentIndex) {
    float shapeSDF = scene(p);

    uvec4 fetchedClosest = fetchClosest3D(worldToVoxel(p.xyzz).xyz, iChannel1);

    for(int i = 0; i < 4; i++) {
        uint sphereIdx = fetchedClosest[i];
        if(sphereIdx == uint(-1)) { continue; }
        vec4 circle = texelFetch(iChannel0, ivec2(sphereIdx, 0), 0);
        if(circle.w <= 0.0) continue;

        float currentCircleSDF = length(p - circle.xyz) - circle.w * 1.0;
        shapeSDF = max(-currentCircleSDF, shapeSDF);
    }


    for(int i = 0; i < (currentIndex % 4); i++) {
        vec4 circle = texelFetch(iChannel0, ivec2(i, 0), 0);
        if(circle.w <= 0.0) continue;

        float currentCircleSDF = length(p - circle.xyz) - circle.w * 1.0;

        shapeSDF = max(-currentCircleSDF, shapeSDF);
    }

    return shapeSDF;
}

vec4 gtSDG(vec3 pos) {
    float eps = 0.02;
    vec3 n;
    float d = scene(pos);
    n.x = scene(vec3(pos.x + eps, pos.y, pos.z)) - d;
    n.y = scene(vec3(pos.x, pos.y + eps, pos.z)) - d;
    n.z = scene(vec3(pos.x, pos.y, pos.z + eps)) - d;

    return vec4(n, d);
}

vec3 availableSpaceSDG(vec3 pos, int currentIndex) {
    float eps = 0.02;
    vec3 n;
    float d = getAvailableSpaceSDF(pos, currentIndex);
    n.x = getAvailableSpaceSDF(vec3(pos.x + eps, pos.y, pos.z), currentIndex) - d;
    n.y = getAvailableSpaceSDF(vec3(pos.x, pos.y + eps, pos.z), currentIndex) - d;
    n.z = getAvailableSpaceSDF(vec3(pos.x, pos.y, pos.z + eps), currentIndex) - d;

    return n;
}

vec3 snapToMedialAxis(vec3 candidate, int currentIndex) {
    vec3 pos = candidate;
    float s = 0.1;   
    float alpha = 0.1;  
    float beta = 0.5;    

    for(int iter = 0; iter < 32; iter++) {
        vec3 g = gtSDG(pos).xyz; //availableSpaceSDG(pos, currentIndex).xyz;
        float mg = length(g);        
        if(mg < 1e-4) break; 

        vec3 dir = g / mg;

        float currentSDF = getAvailableSpaceSDF(pos, currentIndex);        
        float stepSize = s;
        bool stepAccepted = false;

        while(stepSize > 1e-4) {
            vec3 newPos = pos - stepSize * dir;            
            float newSDF = getAvailableSpaceSDF(newPos, currentIndex);

            if(newSDF <= currentSDF - alpha * stepSize * mg) {
                pos = newPos;
                stepAccepted = true;
                break;
            }

            stepSize *= beta;
        }

        if(!stepAccepted) {
            break;
        }

        s = stepSize;
    }

    return pos;
}


void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord.xy / iResolution.xy) * 2.0 - 1.0;

    if(fragCoord.y > 0.5) {
        fragColor = vec4(0.0);
        return;
    }


    int circleIndex = int(fragCoord.x);

    if(circleIndex >= N_SPHERES) {
        fragColor = vec4(0.0);
        return;
    }

    vec4 oldData = texelFetch(iChannel0, ivec2(circleIndex, 0), 0);
    vec3 center = oldData.xyz;
    float radius = oldData.w;

    if(circleIndex > iFrame) {
        fragColor = oldData;
        return;
    }

    srand(ivec2(fragCoord), iFrame);
    if(circleIndex == iFrame && iFrame < N_SPHERES) {
        float bestScore = -1.0;
        vec3 bestPos = randomOnSphere() * frand();

        for(int c = 0; c < 16; c++) {
            vec3 candidate;
            float spaceSDF = 0.0;

            candidate = bestPos + randomOnSphere() * frand() * frand() * mix(0.05, 1.0, float(c) / 7.0);
            spaceSDF = getAvailableSpaceSDF(candidate, circleIndex);

            if(spaceSDF > 0.1) {
                vec3 g = availableSpaceSDG(candidate, circleIndex);
                candidate -= g * spaceSDF * 1.001;
            }

            float score = -spaceSDF;

            vec3 snapped = snapToMedialAxis(candidate, circleIndex);
            float snappedSpaceSDF = getAvailableSpaceSDF(snapped, circleIndex);
            float snappedScore = -snappedSpaceSDF;

            if(snappedSpaceSDF < 0.0 && snappedScore > score) {
                candidate = snapped;
                score = snappedScore;
            }


            if(score > bestScore) {
                bestScore = score;
                bestPos = candidate;
            }
        }

        if(bestScore > MIN_RADIUS) {
            center = bestPos;
            radius = max(bestScore, MIN_RADIUS);
        } else {
            center = vec3(0.0);
            radius = 0.0;
        }
    }
    fragColor = vec4(center, radius);
}

void fetchAndSortClosest3D(
    inout vec4 distances, 
    inout uvec4 indices,
    in vec3 samplePoint,
    in vec3 voxelCenter
) {
    uvec4 ids = fetchClosest3D(samplePoint, iChannel1);

    for (int i = 0; i < 4; i++) {
        sortClosest(distances, indices, ids[i], voxelCenter, iChannel0);
    }
}


float randomFloat(inout uint state) {
    state ^= state >> 16;
    state *= 0x7feb352dU;
    state ^= state >> 15;
    state *= 0x846ca68bU;
    state ^= state >> 16;
    return float(state) / 4294967296.0;
}

vec3 randomDir3D(inout uint state) {
    float z  = randomFloat(state) * 2.0 - 1.0;  // range [-1,1]
    float az = randomFloat(state) * PI2;
    float r  = sqrt(1.0 - z * z);
    float x  = r * cos(az);
    float y  = r * sin(az);
    return vec3(x, y, z);
}

uint rngSeed = 314159265u;
uint xorshift(in uint value) {
    value ^= value << 13;
    value ^= value >> 17;
    value ^= value << 5;
    return value;
}
uint nextUint() {
    rngSeed = xorshift(rngSeed);
    return rngSeed;
}
float nextFloat() {
    return float(nextUint()) / float(uint(-1));
}

uint murmur3( in uint u )
{
  u ^= ( u >> 16 ); u *= 0x85EBCA6Bu;
  u ^= ( u >> 13 ); u *= 0xC2B2AE35u;
  u ^= ( u >> 16 );

  return u;
}


void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    ivec2 fc = ivec2(fragCoord);
    ivec2 maxSize = ivec2(slicesPerRow * iResolution3D.x);
    if (any(greaterThanEqual(fc, maxSize))) {fragColor = vec4(0.0); return; }

    ivec3 cellCoord = from2D(fc, iResolution3D); 
    vec3 voxelCenter = vec3(cellCoord) + 0.5; 

    vec4 bestDistances = vec4(FLOAT_INF);
    uvec4 closestIndices = uvec4(uint(-1));

    if (iFrame == 0) {
        closestIndices = uvec4(nextUint(), nextUint(), nextUint(), nextUint()) % 63u;
    }

    uint seed = uint(iFrame) + uint(fragCoord.x) + uint(fragCoord.y);
    float rad = 3.0;

    fetchAndSortClosest3D(bestDistances, closestIndices, voxelCenter, voxelCenter);
    fetchAndSortClosest3D(bestDistances, closestIndices, voxelCenter + randomDir3D(seed) * rad, voxelCenter);
    fetchAndSortClosest3D(bestDistances, closestIndices, voxelCenter + randomDir3D(seed) * rad, voxelCenter);
    fetchAndSortClosest3D(bestDistances, closestIndices, voxelCenter + randomDir3D(seed) * rad, voxelCenter);
    fetchAndSortClosest3D(bestDistances, closestIndices, voxelCenter + randomDir3D(seed) * rad, voxelCenter);

    rngSeed = murmur3(uint(fragCoord.x)) ^ murmur3(floatBitsToUint(fragCoord.y)) ^ murmur3(floatBitsToUint(iTime));

    for (int i = 0; i < 16; i++) {
        sortClosest(bestDistances, closestIndices, nextUint() % PARTICLE_COUNT, voxelCenter, iChannel0);
    }


    fragColor = uintBitsToFloat(closestIndices);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    int j = int(fragCoord.x);
    vec4 circle = texelFetch(iChannel0, ivec2(j, 0), 0);
    float fun = smoothstep(0.0, 1.0, sin(iTime * 0.5));
    vec3 animation = vec3(sin(iTime + float(j) * 2.0), cos(iTime + float(j) * 3.0), cos(iTime * 2.0 + float(j) * 4.0)) * 0.3 * fun * smoothstep(8.0, 12.0, iTime);
    circle.xyz += animation;
    circle.w *= mix(1.1, 0.4, fun);
    fragColor = circle;
}

// Author : SÃ©bastien BÃ©rubÃ©
// Created : Dec 2014
// Modified : Feb 2016
//
// Ice raymarching experiment, built on top of primitives shader from Inigo Quilez : 
// https://www.shadertoy.com/view/Xds3zN
//
// You can play with the sliders : 1-Normal map scale
//                                 2-Isosurface thickness
//                                 3-Color / refraction normal / other debug stuff
//                                 4-Refraction index
//
// Notes:
// 
// - distance function map() works as usual, as all boolean operations and signed distance functions do.
// - sphereTracing() function was modified for volume raymarching (sign added, simple as that).
// - triplanar noise projection used for surface normal noise.
// - smooth subtraction was implemented to smooth out boolean shape.
// - "in scattering" is simply approximated with positive inner ice colors (the default color)
// - extinction coefficient is also roughly approximated both by negative inner ice color
//   and with traversal distance (WIP, I'll return to improve this once I better
//   understand scattering equations).
// - RAYMARCH_DFSS is slightly different from inigo's softshadow.
//   A "light cone width" value [0-1] is passed to the function in order to control softness.
//   I don't know how well it would perform in other scenarios, but it seems to do the trick
//   with limited samples in this case. I guess the principle is the same.
//
// License : Creative Commons Non-commercial (NC) license
//

//----------------------
// Constants 
const float GEO_MAX_DIST  = 1000.0;
const int MATERIALID_NONE      = 0;
const int MATERIALID_FLOOR     = 1;
const int MATERIALID_ICE_OUTER = 2;
const int MATERIALID_ICE_INNER = 3;
const int MATERIALID_SKY       = 4;

//----------------------
// Slider bound globals.
float ROUGHNESS      = 0.25; //sliderVal[0]
float ISOVALUE       = 0.03; //sliderVal[1]
float ICE_COLOR      = 0.00; //sliderVal[2]
float REFRACTION_IDX = 1.31; //sliderVal[3]

struct TraceData
{
    float rayLen;
    vec3  rayDir;
    vec3  normal;
    int   matID;
    vec3  matUVW;
    float alpha;
};

#define saturate(x) clamp(x,0.0,1.0)
vec3 normalMap(vec3 p, vec3 n);
TraceData TRACE_geometry(vec3 o, vec3 d);
TraceData TRACE_reflexion(vec3 o, vec3 d);
TraceData TRACE_translucentDensity(vec3 o, vec3 d);
TraceData TRACE_cheap(vec3 o, vec3 d);

float RAYMARCH_DFSS(vec3 ro, vec3 rd, float coneWidth);

vec4 MAT_apply(vec3 pos, TraceData traceData)
{
    vec3 L = normalize(vec3(-0.6,0.7,-0.5));
    vec4 col = vec4(traceData.alpha);

    if(traceData.matID==MATERIALID_NONE)
    {
        return vec4(0,0,0,1);
    }
    else if(traceData.matID==MATERIALID_ICE_INNER)
    {
        //NOTE : Coloring is not physically accurate.
        //       For this to be more accurate, 
        //       it should probably be computed like fog.
        //       (in scattering, out scattering / extinction coefficient?).
        vec3 cRed   = vec3( 0.70,-0.5,-0.60);
        vec3 cGreen = vec3(-0.50, 0.0,-0.5);
        vec3 cBlue  = vec3(-0.50,-0.5, 0.30);
        vec3 cGrey = vec3(-0.3); //Glass (~extinction coefficient, more or less)
        vec3 cWhite = vec3(1.0); //Ice (pseudo "in scattering")

        col.rgb = mix(cWhite ,cGrey, smoothstep(0.00,0.20,ICE_COLOR));
		col.rgb = mix(col.rgb,cBlue, smoothstep(0.20,0.40,ICE_COLOR));
        col.rgb = mix(col.rgb,cGreen,smoothstep(0.40,0.60,ICE_COLOR));
		col.rgb = mix(col.rgb,cRed , smoothstep(0.60,0.80,ICE_COLOR));    
    }
    else if(traceData.matID==MATERIALID_SKY)
    {
        col.rgb = vec3(0.6,0.7,0.85);
    }
    else if(traceData.matID==MATERIALID_FLOOR)
    {
        vec3 cDiff = pow(texture(iChannel1,traceData.matUVW.xz).rgb,vec3(1.2));
        float dfss = RAYMARCH_DFSS(pos, L, 0.07);
    	col.rgb = cDiff*(0.45+1.2*(dfss));
    }
    return col;
}

struct IceTracingData
{
    TraceData reflectTraceData;
	TraceData translucentTraceData;
    TraceData exitTraceData;
};

IceTracingData renderIce(TraceData iceSurface, vec3 ptIce, vec3 dir)
{
    IceTracingData iceData;

    vec3 normalDelta = normalMap(ptIce*ROUGHNESS,iceSurface.normal)*ROUGHNESS/10.;

    vec3 iceSurfaceNormal = normalize(iceSurface.normal+normalDelta); 
    vec3 refract_dir = refract(dir,iceSurfaceNormal,1.0/REFRACTION_IDX); //Ice refraction index = 1.31
    vec3 reflect_dir = reflect(dir,iceSurfaceNormal);

    //Trace reflection
    iceData.reflectTraceData = TRACE_reflexion(ptIce,reflect_dir);

    //Balance between refraction and reflection (not entirely physically accurate, Fresnel could be used here).
    float fReflectAlpha = 0.5*(1.0-abs(dot(normalize(dir),iceSurfaceNormal)));
    iceData.reflectTraceData.alpha = fReflectAlpha;
    vec3 ptReflect = ptIce+iceData.reflectTraceData.rayLen*reflect_dir;

    //Trace refraction
    iceData.translucentTraceData = TRACE_translucentDensity(ptIce,refract_dir);

    vec3 ptRefract = ptIce+iceData.translucentTraceData.rayLen*refract_dir;
    vec3 exitRefract_dir = refract(refract_dir,-iceData.translucentTraceData.normal,REFRACTION_IDX);

    //This value fades around total internal refraction angle threshold.
    if(length(exitRefract_dir)<=0.95)
    {
        //Total internal reflection (either refraction or reflexion, to keep things cheap).
        exitRefract_dir = reflect(refract_dir,-iceData.translucentTraceData.normal);
    }

    //Trace environment upon exit.
    iceData.exitTraceData = TRACE_cheap(ptRefract,exitRefract_dir);
    iceData.exitTraceData.matID = MATERIALID_FLOOR;

    return iceData;
}

vec3 main_render( vec3 o, vec3 dir, vec2 uv)
{ 
    vec3 pt = o;

    vec3 ptGeometry = vec3(0);
    vec3 ptReflect = vec3(0);

    TraceData geometryTraceData = TRACE_geometry(pt, dir);
    ptGeometry = o+geometryTraceData.rayLen*dir;

    IceTracingData iceData;
    iceData.translucentTraceData.rayLen = 0.0;
    if(geometryTraceData.matID == MATERIALID_ICE_OUTER && geometryTraceData.rayLen < GEO_MAX_DIST)
    {
        vec3 ptIce = ptGeometry;
        iceData = renderIce(geometryTraceData, ptIce, dir);
        geometryTraceData = iceData.exitTraceData;

        vec3 ptRefract = ptIce+iceData.translucentTraceData.rayLen*iceData.translucentTraceData.rayDir;
        ptReflect = ptIce+iceData.reflectTraceData.rayLen*iceData.reflectTraceData.rayDir;
        ptGeometry = ptRefract+geometryTraceData.rayLen*dir;

        //<Debug section, not mandatory>
        //[0.80-1.00] = Debug color range.
        if(ICE_COLOR>0.95) return iceData.exitTraceData.rayDir;
        if(ICE_COLOR>0.90) return max(iceData.exitTraceData.matUVW,vec3(0));
        if(ICE_COLOR>0.85) return iceData.translucentTraceData.rayLen*vec3(1);
        if(ICE_COLOR>0.80) return iceData.reflectTraceData.alpha*vec3(1);
        //</Debug section, not mandatory>
    }

    //cTerrain is either direct ray or refract ray.
    vec4 cTerrain  = MAT_apply(ptGeometry,geometryTraceData);
    vec4 cIceInner = MAT_apply(ptGeometry,iceData.translucentTraceData);
    vec4 cReflect  = MAT_apply(ptReflect,iceData.reflectTraceData);

    if(iceData.translucentTraceData.rayLen > 0.0 )
    {
        float fTrav = iceData.translucentTraceData.rayLen;
        vec3 cRefract = cTerrain.rgb;
        cRefract.rgb = mix(cRefract,cIceInner.rgb,0.3*fTrav+0.2*sqrt(fTrav*3.0));
        cRefract.rgb += fTrav*0.3;
        vec3 cIce = mix(cRefract,cReflect.rgb,iceData.reflectTraceData.alpha);
        return cIce;
	}
    return cTerrain.rgb;
}




struct DF_out
{
    float d;  //Distance to geometry
    int matID;//Geometry material ID
};


float sdPlane( vec3 p )
{
	return p.y;
}

float sdSphere( vec3 p, float s )
{
    return length(p)-s;
}

float sdBox( vec3 p, vec3 b )
{
  vec3 d = abs(p) - b;
  return min(max(d.x,max(d.y,d.z)),0.0) + length(max(d,0.0));
}

float udRoundBox( vec3 p, vec3 b, float r )
{
  return length(max(abs(p)-b,0.0))-r;
}

float sdTorus( vec3 p, vec2 t )
{
  return length( vec2(length(p.xz)-t.x,p.y) )-t.y;
}

float sdTriPrism( vec3 p, vec2 h )
{
    vec3 q = abs(p);
#if 0
    return max(q.z-h.y,max(q.x*0.866025+p.y*0.5,-p.y)-h.x*0.5);
#else
    float d1 = q.z-h.y;
    float d2 = max(q.x*0.866025+p.y*0.5,-p.y)-h.x*0.5;
    return length(max(vec2(d1,d2),0.0)) + min(max(d1,d2), 0.);
#endif
}

float sdCylinder( vec3 p, vec2 h )
{
  vec2 d = abs(vec2(length(p.xz),p.y)) - h;
  return min(max(d.x,d.y),0.0) + length(max(d,0.0));
}

float length2( vec2 p )
{
	return sqrt( p.x*p.x + p.y*p.y );
}

float length8( vec2 p )
{
	p = p*p; p = p*p; p = p*p;
	return pow( p.x + p.y, 1.0/8.0 );
}

float sdTorus88( vec3 p, vec2 t )
{
  vec2 q = vec2(length8(p.xz)-t.x,p.y);
  return length8(q)-t.y;
}


//----------------------------------------------------------------------

float opSmoothSubtract( float d1, float d2 )
{
    return length(vec2(max(d1,0.),min(d2,0.0)));
}

float opU( float d1, float d2 )
{
	return (d1<d2) ? d1 : d2;
}

vec3 opTwist( vec3 p )
{
    float  c = cos(10.0*p.y+10.0);
    float  s = sin(10.0*p.y+10.0);
    mat2   m = mat2(c,-s,s,c);
    return vec3(m*p.xz,p.y);
}

DF_out map( in vec3 pos )
{
    float dist = opU( sdPlane(     pos-vec3( -1.4) ),
	                sdSphere(    pos-vec3( 0.0,0.25, 0.0), 0.25 ) );
    dist = opU( dist, udRoundBox(  pos-vec3( 1.0,0.25, 1.0), vec3(0.15), 0.1 ) );
	dist = opU( dist, sdTorus(     pos-vec3( 0.0,0.25, 1.0), vec2(0.20,0.05) ) );
	dist = opU( dist, sdTriPrism(  pos-vec3(-1.0,0.25,-1.0), vec2(0.25,0.05) ) );
	dist = opU( dist, sdCylinder(  pos-vec3( 1.0,0.30,-1.0), vec2(0.10,0.20) ) );
	dist = opU( dist, sdTorus88(   pos-vec3(-1.0,0.25, 1.0), vec2(0.20,0.05) ) );
    dist = opU( dist, opSmoothSubtract(
	                      udRoundBox(  pos-vec3(-1.0,0.2, 0.0), vec3(0.15),0.05),
	                      sdSphere(    pos-vec3(-1.0,0.2, 0.0), 0.25)) );
    dist = opU( dist, sdBox(       pos-vec3( 0.0,0.20,-1.0), vec3(0.25)) );
	dist = opU( dist, 0.5*sdTorus( opTwist(pos-vec3( 1.0,0.25, 0.0)),vec2(0.15,0.02)) );

    DF_out outData;
    outData.d = dist-ISOVALUE;
    outData.matID = MATERIALID_ICE_OUTER;
    return outData;
}

vec3 gradient( in vec3 p )
{
	const float d = 0.001;
	vec3 grad = vec3(map(p+vec3(d,0,0)).d-map(p-vec3(d,0,0)).d,
                     map(p+vec3(0,d,0)).d-map(p-vec3(0,d,0)).d,
                     map(p+vec3(0,0,d)).d-map(p-vec3(0,0,d)).d);
	return grad;
}

vec2 sphereTracing( const vec3 o, const vec3 d, const float tmin, const float eps, const bool bInternal)
{
    //https://iquilezles.org/articles/raymarchingdf
    //http://mathinfo.univ-reims.fr/IMG/pdf/hart94sphere.pdf p.5-89
    //[modified for internal marching]
    float tmax = 10.0;
    float t = tmin;
    float dist = GEO_MAX_DIST;
    for( int i=0; i<50; i++ )
    {
        vec3 p = o+d*t;
	    dist = (bInternal?-1.:1.)*map(p).d;
        if( abs(dist)<eps || t>tmax )
            break;
        t += dist;
    }

    dist = (dist<tmax)?dist:GEO_MAX_DIST;
    return vec2( t, dist );
}

TraceData TRACE_getFront(const in TraceData tDataA, const in TraceData tDataB)
{
    if(tDataA.rayLen<tDataB.rayLen)
    {
        return tDataA;
    }
    else
    {
        return tDataB;
    }
}

float RAYCAST_floor(vec3 o, vec3 d)
{
    vec3 n = vec3(0,1,0);
    vec3 p = vec3(-0.1);
    float t = dot(p-o,n)/dot(d,n);
    return (t<0.0)?GEO_MAX_DIST:t;
}

//o=origin, d = direction
TraceData TRACE_cheap(vec3 o, vec3 d)
{
    TraceData floorData;
	floorData.rayLen  = RAYCAST_floor(o, d);
	floorData.rayDir  = d;
	floorData.normal  = vec3(0,1,0);
	floorData.matUVW  = o+d*floorData.rayLen;
	floorData.matID   = MATERIALID_FLOOR;
    floorData.alpha   = 1.0;

    TraceData skyData;
    skyData.rayLen  = 50.0;
    skyData.rayDir  = d;
	skyData.normal  = -d;
	skyData.matUVW  = d;
	skyData.matID   = MATERIALID_SKY;
    skyData.alpha   = 1.0;
    return TRACE_getFront(floorData,skyData);
}

TraceData TRACE_reflexion(vec3 o, vec3 d)
{
    return TRACE_cheap(o,d);
}

//o=origin, d = direction
TraceData TRACE_geometry(vec3 o, vec3 d)
{
    TraceData cheapTrace = TRACE_cheap(o,d);

    TraceData iceTrace;
    vec2 rayLen_geoDist = sphereTracing(o,d,0.1,0.0001,false);
    vec3 iceHitPosition = o+rayLen_geoDist.x*d;
    iceTrace.rayDir     = d;
    iceTrace.rayLen     = rayLen_geoDist.x;
    iceTrace.normal     = normalize(gradient(iceHitPosition));
    iceTrace.matUVW     = iceHitPosition;
    iceTrace.matID      = MATERIALID_ICE_OUTER;
    iceTrace.alpha      = 0.0;

    return TRACE_getFront(cheapTrace,iceTrace);
}

//o=origin, d = direction
TraceData TRACE_translucentDensity(vec3 o, vec3 d)
{
    TraceData innerIceTrace;

    vec2 rayLen_geoDist   = sphereTracing(o,d,0.01,0.001,true).xy;
    vec3 iceExitPosition  = o+rayLen_geoDist.x*d;
    innerIceTrace.rayDir  = d;
    innerIceTrace.rayLen  = rayLen_geoDist.x;
    innerIceTrace.normal  = normalize(gradient(iceExitPosition));
    innerIceTrace.matUVW  = iceExitPosition;
    innerIceTrace.matID   = MATERIALID_ICE_INNER;
    innerIceTrace.alpha   = rayLen_geoDist.x;
    return innerIceTrace;
}

#define saturate(x) clamp(x,0.0,1.0)
//o=origin, L = light direction
float RAYMARCH_DFSS( vec3 o, vec3 L, float coneWidth )
{
    //Variation of the Distance Field Soft Shadow from : https://www.shadertoy.com/view/Xds3zN
    //Initialize the minimum aperture (angle tan) allowable with this distance-field technique
    //(45deg: sin/cos = 1:1)
    float minAperture = 1.0; 
    float t = 0.0;
    float dist = GEO_MAX_DIST;
    for( int i=0; i<6; i++ )
    {
        vec3 p = o+L*t; //Sample position = ray origin + ray direction * travel distance
        float dist = map( p ).d;
        float curAperture = dist/t; //Aperture ~= cone angle tangent (sin=dist/cos=travelDist)
        minAperture = min(minAperture,curAperture);
        t += 0.03+dist; //0.03 : min step size.
    }

    //The cone width controls shadow transition. The narrower, the sharper the shadow.
    return saturate(minAperture/coneWidth); //Should never exceed [0-1]. 0 = shadow, 1 = fully lit.
}

vec3 smoothSampling(vec2 uv)
{
    const float T_RES = 64.0;
    vec2 x = fract(uv*T_RES+0.5);
    vec2 pc1 = uv-(x)/T_RES;
    //vec2 t = x * x * (3.0 - 2.0 * x);
    vec2 t = (6.*x*x-15.0*x+10.)*x*x*x; //ease function
    return textureLod(iChannel0,pc1+t/T_RES,0.0).xyz;
}

float triplanarSampling(vec3 p, vec3 n)
{
	float fTotal = abs(n.x)+abs(n.y)+abs(n.z);
	return  (abs(n.x)*smoothSampling(p.yz).x
            +abs(n.y)*smoothSampling(p.xz).x
            +abs(n.z)*smoothSampling(p.xy).x)/fTotal;
}

const mat2 m2 = mat2(0.90,0.44,-0.44,0.90);
float triplanarNoise(vec3 p, vec3 n)
{
    const float BUMP_MAP_UV_SCALE = 0.2;
    float fTotal = abs(n.x)+abs(n.y)+abs(n.z);
    float f1 = triplanarSampling(p*BUMP_MAP_UV_SCALE,n);
    p.xy = m2*p.xy;
    p.xz = m2*p.xz;
    p *= 2.1;
    float f2 = triplanarSampling(p*BUMP_MAP_UV_SCALE,n);
    p.yx = m2*p.yx;
    p.yz = m2*p.yz;
    p *= 2.3;
    float f3 = triplanarSampling(p*BUMP_MAP_UV_SCALE,n);
    return f1+0.5*f2+0.25*f3;
}

vec3 normalMap(vec3 p, vec3 n)
{
    float d = 0.005;
    float po = triplanarNoise(p,n);
	float px = triplanarNoise(p+vec3(d,0,0),n);
    float py = triplanarNoise(p+vec3(0,d,0),n);
	float pz = triplanarNoise(p+vec3(0,0,d),n);
    return normalize(vec3((px-po)/d,
                          (py-po)/d,
                          (pz-po)/d));
}

struct Cam
{
    vec3 R;//Right, 
    vec3 U;//Up,
    vec3 D;//Direction,
    vec3 o;//origin (pos)
};
Cam CAM_animate(vec2 uv)
{
    float PI = 3.14159;
	float rotX = 2.0*PI*(iMouse.x/iResolution.x+iTime*0.05);
    Cam cam;
    cam.o = vec3(cos(rotX),0.475,sin(rotX))*2.3;
    cam.D = normalize(vec3(0,-0.25,0)-cam.o);
    cam.R = normalize(cross(cam.D,vec3(0,1,0)));
    cam.U = cross(cam.R,cam.D);
    return cam;
}
vec3 CAM_getRay(Cam cam,vec2 uv)
{
    uv *= 2.0*iResolution.x/iResolution.y;;
    return normalize(uv.x*cam.R+uv.y*cam.U+cam.D*2.5);
}

vec4 processSliders(in vec2 fragCoord)
{
    vec4 sliderVal = texture(iChannel2,vec2(0,0));
	ROUGHNESS       = sliderVal[0]*4.0;
	ISOVALUE        = 0.005+sliderVal[1]*0.1;
	ICE_COLOR       = sliderVal[2];
	REFRACTION_IDX  = 1.0+sliderVal[3];

    if(length(fragCoord.xy-vec2(0,0))>1.)
    {
    	return texture(iChannel2,fragCoord.xy/iResolution.xy);
    }
    return vec4(0);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec4 cSlider = processSliders(fragCoord);
	vec2 uv = (fragCoord.xy-0.5*iResolution.xy) / iResolution.xx;

    Cam cam = CAM_animate(uv);
    vec3 d = CAM_getRay(cam,uv);
    vec3 c = main_render(cam.o, d, uv);

    //Vignetting
    float lensRadius = 0.65;
    uv /= lensRadius;
    float sin2 = uv.x*uv.x+uv.y*uv.y;
    float cos2 = 1.0-min(sin2*sin2,1.0);
    float cos4 = cos2*cos2;
    c *= cos4;

    //Gamma
    c = pow(c,vec3(0.4545)); //2.2 Gamma compensation

    //Apply slider overlay
    c = mix(c,cSlider.rgb,cSlider.a);

    fragColor = vec4(c,1.0);
}

//Buffer A : slider management (this is not required)

#define saturate(x) clamp(x,0.0,1.0)
vec4 sliderVal = vec4(0.25,0.22,0,0.31); //Default slider values [0-1]

void SLIDER_setValue(float idx, float val)
{
    if(idx<0.) return;
    else if(idx<0.25) sliderVal[0] = saturate(val);
	else if(idx<0.50) sliderVal[1] = saturate(val);
	else if(idx<0.75) sliderVal[2] = saturate(val);
	else if(idx<1.00) sliderVal[3] = saturate(val);
}

float SLIDER_getValue(float idx)
{
    if     (idx<0.25) return sliderVal[0];
    else if(idx<0.50) return sliderVal[1];
    else if(idx<0.75) return sliderVal[2];
    else if(idx<1.00) return sliderVal[3];
	else return 0.;
}

void SLIDER_init(vec2 mousePos, vec2 cMin, vec2 cMax )
{
    vec4 cPingPong = textureLod(iChannel0,vec2(0),0.0);
    if(length(cPingPong)>0.001)
        sliderVal = cPingPong;

    float width = cMax.x-cMin.x;
    float height = cMax.y-cMin.y;
    if(mousePos.x>cMin.x && mousePos.x<cMax.x &&
       mousePos.y>cMin.y && mousePos.y<cMax.y )
    {
        float t = (mousePos.y-cMin.y)/height;
        t = clamp(t/0.75-0.125,0.,1.); //25% top/bottom margins
		SLIDER_setValue((mousePos.x-cMin.x)/width, t);
    }
}

//Returns the distance from point "p" to a given line segment defined by 2 points [a,b]
float UTIL_distanceToLineSeg(vec2 p, vec2 a, vec2 b)
{
    //       p
    //      /
    //     /
    //    a--e-------b
    vec2 ap = p-a;
    vec2 ab = b-a;
    //Scalar projection of ap in the ab direction = dot(ap,ab)/|ab| : Amount of ap aligned towards ab
    //Divided by |ab| again, it becomes normalized along ab length : dot(ap,ab)/(|ab||ab|) = dot(ap,ab)/dot(ab,ab)
    //The clamp provides the line seg limits. e is therefore the "capped orthogogal projection", and length(p-e) is dist.
    vec2 e = a+clamp(dot(ap,ab)/dot(ab,ab),0.0,1.0)*ab;
    return length(p-e);
}

//uv = slider pixel in local space [0-1], t = slider value [0-1], ar = aspect ratio (w/h)
vec4 SLIDER_drawSingle(vec2 uv, float t, vec2 ar, bool bHighlighted)
{
    const vec3  ITEM_COLOR = vec3(1);
    const vec3  HIGHLIGHT_COLOR = vec3(0.2,0.7,0.8);
    const float RAD = 0.05;  //Cursor radius, in local space
    const float LW  = 0.030; //Line width
    float aa  = 14./iResolution.x; //antialiasing width (smooth transition)
    vec3 selectionColor = bHighlighted?HIGHLIGHT_COLOR:ITEM_COLOR;
    vec3 cheapGloss   = 0.8*selectionColor+0.2*smoothstep(-aa,aa,uv.y-t-0.01+0.01*sin(uv.x*12.));
    vec2 bottomCenter = vec2(0.5,0.0);
	vec2 topCenter    = vec2(0.5,1.0);
    vec2 cursorPos    = vec2(0.5,t);
    float distBar = UTIL_distanceToLineSeg(uv*ar, bottomCenter*ar, topCenter*ar);
    float distCur = length((uv-cursorPos)*ar)-RAD;
    float alphaBar = 1.0-smoothstep(2.0*LW-aa,2.0*LW+aa, distBar);
    float alphaCur = 1.0-smoothstep(2.0*LW-aa,2.0*LW+aa, distCur);
    vec4  colorBar = vec4(mix(   vec3(1),vec3(0),smoothstep(LW-aa,LW+aa, distBar)),alphaBar);
    vec4  colorCur = vec4(mix(cheapGloss,vec3(0),smoothstep(LW-aa,LW+aa, distCur)),alphaCur);
    return mix(colorBar,colorCur,colorCur.a);
}

#define withinUnitRect(a) (a.x>=0. && a.x<=1. && a.y>=0. && a.y<=1.0)
vec4 SLIDER_drawAll(vec2 uv, vec2 cMin, vec2 cMax, vec2 muv)
{
    float width = cMax.x-cMin.x;
    float height = cMax.y-cMin.y;
    vec2 ar = vec2(0.30,1.0);
    uv  = (uv -cMin)/vec2(width,height); //pixel Normalization
    muv = (muv-cMin)/vec2(width,height); //mouse Normalization
    if( withinUnitRect(uv) )
    {
        float t = SLIDER_getValue(uv.x);
		bool bHighlight = withinUnitRect(muv) && abs(floor(uv.x*4.0)-floor(muv.x*4.0))<0.01;
		uv.x = fract(uv.x*4.0); //repeat 4x
		uv.y = uv.y/0.75-0.125; //25% margins
        return SLIDER_drawSingle(uv,t,ar,bHighlight);
    }
    return vec4(0);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 cMinSliders = vec2(0.9,0.80);
    vec2 cMaxSliders = vec2(1.0,1.00);
    vec2 uvSliders = fragCoord.xy / iResolution.xy;
    vec2 mousePos = iMouse.xy / iResolution.xy;
    SLIDER_init(mousePos, cMinSliders, cMaxSliders);
    vec4 cSlider = SLIDER_drawAll(uvSliders,cMinSliders, cMaxSliders, mousePos);

    if(length(fragCoord.xy-vec2(0,0))<1.) 
        fragColor = sliderVal;
	else fragColor = cSlider;
}

// Ray Tracing - Primitives. Created by Reinder Nijhoff 2019
// The MIT License
// @reindernijhoff
//
// https://www.shadertoy.com/view/tl23Rm
//
// I wanted to create a reference shader similar to "Raymarching - Primitives" 
// (https://www.shadertoy.com/view/Xds3zN), but with ray-primitive intersection 
// routines instead of sdf routines.
// 
// As usual, I ended up mostly just copy-pasting code from Íñigo Quílez: 
// 
// https://iquilezles.org/articles/intersectors
// 
// Please let me know if there are other routines that I should add to this shader.
// 
// You can find all intersection routines in the Common tab. The routines have a similar 
// signature: a routine returns the distance to the first hit inside the 
// [distBound.x, distBound.y] interval and will set the normal if an intersection is found.
// If no intersection is found, the routine will return MAX_DIST.
//
// I made a simple ray tracer (Buffer A) to visualize a scene with all primitives.
//
// Use your mouse to change the camera viewpoint.
//

void mainImage( out vec4 fragColor, in vec2 fragCoord ) {
    vec4 data = texelFetch(iChannel0, ivec2(fragCoord), 0);
    vec3 col = data.rgb / data.w;

    // gamma correction
    col = max( vec3(0), col - 0.004);
    col = (col*(6.2*col + .5)) / (col*(6.2*col+1.7) + 0.06);

    // Output to screen
    fragColor = vec4(col,1.0);
}

// Ray Tracing - Primitives. Created by Reinder Nijhoff 2019
// The MIT License
// @reindernijhoff
//
// https://www.shadertoy.com/view/tl23Rm
//
// I wanted to create a reference shader similar to "Raymarching - Primitives" 
// (https://www.shadertoy.com/view/Xds3zN), but with ray-primitive intersection 
// routines instead of sdf routines.
// 
// As usual, I ended up mostly just copy-pasting code from Íñigo Quílez: 
// 
// https://iquilezles.org/articles/intersectors
// 
// Please let me know if there are other routines that I should add to this shader.
// 
// Sphere:          https://www.shadertoy.com/view/4d2XWV
// Box:             https://www.shadertoy.com/view/ld23DV
// Capped Cylinder: https://www.shadertoy.com/view/4lcSRn
// Torus:           https://www.shadertoy.com/view/4sBGDy
// Capsule:         https://www.shadertoy.com/view/Xt3SzX
// Capped Cone:     https://www.shadertoy.com/view/llcfRf
// Ellipsoid:       https://www.shadertoy.com/view/MlsSzn
// Rounded Cone:    https://www.shadertoy.com/view/MlKfzm
// Triangle:        https://www.shadertoy.com/view/MlGcDz
// Sphere4:         https://www.shadertoy.com/view/3tj3DW
// Goursat:         https://www.shadertoy.com/view/3lj3DW
// Rounded Box:     https://www.shadertoy.com/view/WlSXRW
//
// Disk:            https://www.shadertoy.com/view/lsfGDB
//

#define MAX_DIST 1e10
float dot2( in vec3 v ) { return dot(v,v); }

// Plane 
float iPlane( in vec3 ro, in vec3 rd, in vec2 distBound, inout vec3 normal,
              in vec3 planeNormal, in float planeDist) {
    float a = dot(rd, planeNormal);
    float d = -(dot(ro, planeNormal)+planeDist)/a;
    if (a > 0. || d < distBound.x || d > distBound.y) {
        return MAX_DIST;
    } else {
        normal = planeNormal;
    	return d;
    }
}

// Sphere:          https://www.shadertoy.com/view/4d2XWV
float iSphere( in vec3 ro, in vec3 rd, in vec2 distBound, inout vec3 normal,
               float sphereRadius ) {
    float b = dot(ro, rd);
    float c = dot(ro, ro) - sphereRadius*sphereRadius;
    float h = b*b - c;
    if (h < 0.) {
        return MAX_DIST;
    } else {
	    h = sqrt(h);
        float d1 = -b-h;
        float d2 = -b+h;
        if (d1 >= distBound.x && d1 <= distBound.y) {
            normal = normalize(ro + rd*d1);
            return d1;
        } else if (d2 >= distBound.x && d2 <= distBound.y) { 
            normal = normalize(ro + rd*d2);            
            return d2;
        } else {
            return MAX_DIST;
        }
    }
}

// Box:             https://www.shadertoy.com/view/ld23DV
float iBox( in vec3 ro, in vec3 rd, in vec2 distBound, inout vec3 normal, 
            in vec3 boxSize ) {
    vec3 m = sign(rd)/max(abs(rd), 1e-8);
    vec3 n = m*ro;
    vec3 k = abs(m)*boxSize;

    vec3 t1 = -n - k;
    vec3 t2 = -n + k;

	float tN = max( max( t1.x, t1.y ), t1.z );
	float tF = min( min( t2.x, t2.y ), t2.z );

    if (tN > tF || tF <= 0.) {
        return MAX_DIST;
    } else {
        if (tN >= distBound.x && tN <= distBound.y) {
        	normal = -sign(rd)*step(t1.yzx,t1.xyz)*step(t1.zxy,t1.xyz);
            return tN;
        } else if (tF >= distBound.x && tF <= distBound.y) { 
        	normal = -sign(rd)*step(t1.yzx,t1.xyz)*step(t1.zxy,t1.xyz);
            return tF;
        } else {
            return MAX_DIST;
        }
    }
}

// Capped Cylinder: https://www.shadertoy.com/view/4lcSRn
float iCylinder( in vec3 ro, in vec3 rd, in vec2 distBound, inout vec3 normal,
                 in vec3 pa, in vec3 pb, float ra ) {
    vec3 ca = pb-pa;
    vec3 oc = ro-pa;

    float caca = dot(ca,ca);
    float card = dot(ca,rd);
    float caoc = dot(ca,oc);

    float a = caca - card*card;
    float b = caca*dot( oc, rd) - caoc*card;
    float c = caca*dot( oc, oc) - caoc*caoc - ra*ra*caca;
    float h = b*b - a*c;

    if (h < 0.) return MAX_DIST;

    h = sqrt(h);
    float d = (-b-h)/a;

    float y = caoc + d*card;
    if (y > 0. && y < caca && d >= distBound.x && d <= distBound.y) {
        normal = (oc+d*rd-ca*y/caca)/ra;
        return d;
    }

    d = ((y < 0. ? 0. : caca) - caoc)/card;

    if( abs(b+a*d) < h && d >= distBound.x && d <= distBound.y) {
        normal = normalize(ca*sign(y)/caca);
        return d;
    } else {
        return MAX_DIST;
    }
}

// Torus:           https://www.shadertoy.com/view/4sBGDy
float iTorus( in vec3 ro, in vec3 rd, in vec2 distBound, inout vec3 normal,
              in vec2 torus ) {
    // bounding sphere
    vec3 tmpnormal;
    if (iSphere(ro, rd, distBound, tmpnormal, torus.y+torus.x) > distBound.y) {
        return MAX_DIST;
    }

    float po = 1.0;

	float Ra2 = torus.x*torus.x;
	float ra2 = torus.y*torus.y;

	float m = dot(ro,ro);
	float n = dot(ro,rd);

#if 1
	float k = (m + Ra2 - ra2)/2.0;
    float k3 = n;
	float k2 = n*n - Ra2*dot(rd.xy,rd.xy) + k;
    float k1 = n*k - Ra2*dot(rd.xy,ro.xy);
    float k0 = k*k - Ra2*dot(ro.xy,ro.xy);
#else
	float k = (m - Ra2 - ra2)/2.0;
	float k3 = n;
	float k2 = n*n + Ra2*rd.z*rd.z + k;
	float k1 = k*n + Ra2*ro.z*rd.z;
	float k0 = k*k + Ra2*ro.z*ro.z - Ra2*ra2;
#endif

#if 1
    // prevent |c1| from being too close to zero
    if (abs(k3*(k3*k3-k2)+k1) < 0.01) {
        po = -1.0;
        float tmp=k1; k1=k3; k3=tmp;
        k0 = 1.0/k0;
        k1 = k1*k0;
        k2 = k2*k0;
        k3 = k3*k0;
    }
#endif

    // reduced cubic
    float c2 = k2*2.0 - 3.0*k3*k3;
    float c1 = k3*(k3*k3-k2)+k1;
    float c0 = k3*(k3*(c2+2.0*k2)-8.0*k1)+4.0*k0;

    c2 /= 3.0;
    c1 *= 2.0;
    c0 /= 3.0;

    float Q = c2*c2 + c0;
    float R = c2*c2*c2 - 3.0*c2*c0 + c1*c1;

    float h = R*R - Q*Q*Q;
    float t = MAX_DIST;

    if (h>=0.0) {
        // 2 intersections
        h = sqrt(h);

        float v = sign(R+h)*pow(abs(R+h),1.0/3.0); // cube root
        float u = sign(R-h)*pow(abs(R-h),1.0/3.0); // cube root

        vec2 s = vec2( (v+u)+4.0*c2, (v-u)*sqrt(3.0));

        float y = sqrt(0.5*(length(s)+s.x));
        float x = 0.5*s.y/y;
        float r = 2.0*c1/(x*x+y*y);

        float t1 =  x - r - k3; t1 = (po<0.0)?2.0/t1:t1;
        float t2 = -x - r - k3; t2 = (po<0.0)?2.0/t2:t2;

        if (t1 >= distBound.x) t=t1;
        if (t2 >= distBound.x) t=min(t,t2);
	} else {
        // 4 intersections
        float sQ = sqrt(Q);
        float w = sQ*cos( acos(-R/(sQ*Q)) / 3.0 );

        float d2 = -(w+c2); if( d2<0.0 ) return MAX_DIST;
        float d1 = sqrt(d2);

        float h1 = sqrt(w - 2.0*c2 + c1/d1);
        float h2 = sqrt(w - 2.0*c2 - c1/d1);
        float t1 = -d1 - h1 - k3; t1 = (po<0.0)?2.0/t1:t1;
        float t2 = -d1 + h1 - k3; t2 = (po<0.0)?2.0/t2:t2;
        float t3 =  d1 - h2 - k3; t3 = (po<0.0)?2.0/t3:t3;
        float t4 =  d1 + h2 - k3; t4 = (po<0.0)?2.0/t4:t4;

        if (t1 >= distBound.x) t=t1;
        if (t2 >= distBound.x) t=min(t,t2);
        if (t3 >= distBound.x) t=min(t,t3);
        if (t4 >= distBound.x) t=min(t,t4);
    }

	if (t >= distBound.x && t <= distBound.y) {
        vec3 pos = ro + rd*t;
        normal = normalize( pos*(dot(pos,pos) - torus.y*torus.y - torus.x*torus.x*vec3(1,1,-1)));
        return t;
    } else {
        return MAX_DIST;
    }
}

// Capsule:         https://www.shadertoy.com/view/Xt3SzX
float iCapsule( in vec3 ro, in vec3 rd, in vec2 distBound, inout vec3 normal,
                in vec3 pa, in vec3 pb, in float r ) {
    vec3  ba = pb - pa;
    vec3  oa = ro - pa;

    float baba = dot(ba,ba);
    float bard = dot(ba,rd);
    float baoa = dot(ba,oa);
    float rdoa = dot(rd,oa);
    float oaoa = dot(oa,oa);

    float a = baba      - bard*bard;
    float b = baba*rdoa - baoa*bard;
    float c = baba*oaoa - baoa*baoa - r*r*baba;
    float h = b*b - a*c;
    if (h >= 0.) {
        float t = (-b-sqrt(h))/a;
        float d = MAX_DIST;

        float y = baoa + t*bard;

        // body
        if (y > 0. && y < baba) {
            d = t;
        } else {
            // caps
            vec3 oc = (y <= 0.) ? oa : ro - pb;
            b = dot(rd,oc);
            c = dot(oc,oc) - r*r;
            h = b*b - c;
            if( h>0.0 ) {
                d = -b - sqrt(h);
            }
        }
        if (d >= distBound.x && d <= distBound.y) {
            vec3  pa = ro + rd * d - pa;
            float h = clamp(dot(pa,ba)/dot(ba,ba),0.0,1.0);
            normal = (pa - h*ba)/r;
            return d;
        }
    }
    return MAX_DIST;
}

// Capped Cone:     https://www.shadertoy.com/view/llcfRf
float iCone( in vec3 ro, in vec3 rd, in vec2 distBound, inout vec3 normal,
             in vec3  pa, in vec3  pb, in float ra, in float rb ) {
    vec3  ba = pb - pa;
    vec3  oa = ro - pa;
    vec3  ob = ro - pb;

    float m0 = dot(ba,ba);
    float m1 = dot(oa,ba);
    float m2 = dot(ob,ba); 
    float m3 = dot(rd,ba);

    //caps
    if (m1 < 0.) { 
        if( dot2(oa*m3-rd*m1)<(ra*ra*m3*m3) ) {
            float d = -m1/m3;
            if (d >= distBound.x && d <= distBound.y) {
                normal = -ba*inversesqrt(m0);
                return d;
            }
        }
    }
    else if (m2 > 0.) { 
        if( dot2(ob*m3-rd*m2)<(rb*rb*m3*m3) ) {
            float d = -m2/m3;
            if (d >= distBound.x && d <= distBound.y) {
                normal = ba*inversesqrt(m0);
                return d;
            }
        }
    }

    // body
    float m4 = dot(rd,oa);
    float m5 = dot(oa,oa);
    float rr = ra - rb;
    float hy = m0 + rr*rr;

    float k2 = m0*m0    - m3*m3*hy;
    float k1 = m0*m0*m4 - m1*m3*hy + m0*ra*(rr*m3*1.0        );
    float k0 = m0*m0*m5 - m1*m1*hy + m0*ra*(rr*m1*2.0 - m0*ra);

    float h = k1*k1 - k2*k0;
    if( h < 0. ) return MAX_DIST;

    float t = (-k1-sqrt(h))/k2;

    float y = m1 + t*m3;
    if (y > 0. && y < m0 && t >= distBound.x && t <= distBound.y) {
        normal = normalize(m0*(m0*(oa+t*rd)+rr*ba*ra)-ba*hy*y);
        return t;
    } else {   
	    return MAX_DIST;
    }
}

// Ellipsoid:       https://www.shadertoy.com/view/MlsSzn
float iEllipsoid( in vec3 ro, in vec3 rd, in vec2 distBound, inout vec3 normal,
                  in vec3 rad ) {
    vec3 ocn = ro / rad;
    vec3 rdn = rd / rad;

    float a = dot( rdn, rdn );
	float b = dot( ocn, rdn );
	float c = dot( ocn, ocn );
	float h = b*b - a*(c-1.);

    if (h < 0.) {
        return MAX_DIST;
    }

	float d = (-b - sqrt(h))/a;

    if (d < distBound.x || d > distBound.y) {
        return MAX_DIST;
    } else {
        normal = normalize((ro + d*rd)/rad);
    	return d;
    }
}

// Rounded Cone:    https://www.shadertoy.com/view/MlKfzm
float iRoundedCone( in vec3 ro, in vec3 rd, in vec2 distBound, inout vec3 normal,
                    in vec3  pa, in vec3  pb, in float ra, in float rb ) {
    vec3  ba = pb - pa;
	vec3  oa = ro - pa;
	vec3  ob = ro - pb;
    float rr = ra - rb;
    float m0 = dot(ba,ba);
    float m1 = dot(ba,oa);
    float m2 = dot(ba,rd);
    float m3 = dot(rd,oa);
    float m5 = dot(oa,oa);
	float m6 = dot(ob,rd);
    float m7 = dot(ob,ob);

    float d2 = m0-rr*rr;

	float k2 = d2    - m2*m2;
    float k1 = d2*m3 - m1*m2 + m2*rr*ra;
    float k0 = d2*m5 - m1*m1 + m1*rr*ra*2. - m0*ra*ra;

	float h = k1*k1 - k0*k2;
    if (h < 0.0) {
        return MAX_DIST;
    }

    float t = (-sqrt(h)-k1)/k2;

    float y = m1 - ra*rr + t*m2;
    if (y>0.0 && y<d2) {
        if (t >= distBound.x && t <= distBound.y) {
        	normal = normalize( d2*(oa + t*rd)-ba*y );
            return t;
        } else {
            return MAX_DIST;
        }
    } else {
        float h1 = m3*m3 - m5 + ra*ra;
        float h2 = m6*m6 - m7 + rb*rb;

        if (max(h1,h2)<0.0) {
            return MAX_DIST;
        }

        vec3 n = vec3(0);
        float r = MAX_DIST;

        if (h1 > 0.) {        
            r = -m3 - sqrt( h1 );
            n = (oa+r*rd)/ra;
        }
        if (h2 > 0.) {
            t = -m6 - sqrt( h2 );
            if( t<r ) {
                n = (ob+t*rd)/rb;
                r = t;
            }
        }
        if (r >= distBound.x && r <= distBound.y) {
            normal = n;
            return r;
        } else {
            return MAX_DIST;
        }
    }
}

// Triangle:        https://www.shadertoy.com/view/MlGcDz
float iTriangle( in vec3 ro, in vec3 rd, in vec2 distBound, inout vec3 normal,
                 in vec3 v0, in vec3 v1, in vec3 v2 ) {
    vec3 v1v0 = v1 - v0;
    vec3 v2v0 = v2 - v0;
    vec3 rov0 = ro - v0;

    vec3  n = cross( v1v0, v2v0 );
    vec3  q = cross( rov0, rd );
    float d = 1.0/dot( rd, n );
    float u = d*dot( -q, v2v0 );
    float v = d*dot(  q, v1v0 );
    float t = d*dot( -n, rov0 );

    if( u<0. || v<0. || (u+v)>1. || t<distBound.x || t>distBound.y) {
        return MAX_DIST;
    } else {
        normal = normalize(-n);
        return t;
    }
}

// Sphere4:         https://www.shadertoy.com/view/3tj3DW
float iSphere4( in vec3 ro, in vec3 rd, in vec2 distBound, inout vec3 normal,
                in float ra ) {
    // -----------------------------
    // solve quartic equation
    // -----------------------------

    float r2 = ra*ra;

    vec3 d2 = rd*rd; vec3 d3 = d2*rd;
    vec3 o2 = ro*ro; vec3 o3 = o2*ro;

    float ka = 1.0/dot(d2,d2);

    float k0 = ka* dot(ro,d3);
    float k1 = ka* dot(o2,d2);
    float k2 = ka* dot(o3,rd);
    float k3 = ka*(dot(o2,o2) - r2*r2);

    // -----------------------------
    // solve cubic
    // -----------------------------

    float c0 = k1 - k0*k0;
    float c1 = k2 + 2.0*k0*(k0*k0 - (3.0/2.0)*k1);
    float c2 = k3 - 3.0*k0*(k0*(k0*k0 - 2.0*k1) + (4.0/3.0)*k2);

    float p = c0*c0*3.0 + c2;
    float q = c0*c0*c0 - c0*c2 + c1*c1;
    float h = q*q - p*p*p*(1.0/27.0);

    // -----------------------------
    // skip the case of 3 real solutions for the cubic, which involves 
    // 4 complex solutions for the quartic, since we know this objcet is 
    // convex
    // -----------------------------
    if (h<0.0) {
        return MAX_DIST;
    }

    // one real solution, two complex (conjugated)
    h = sqrt(h);

    float s = sign(q+h)*pow(abs(q+h),1.0/3.0); // cuberoot
    float t = sign(q-h)*pow(abs(q-h),1.0/3.0); // cuberoot

    vec2 v = vec2( (s+t)+c0*4.0, (s-t)*sqrt(3.0) )*0.5;

    // -----------------------------
    // the quartic will have two real solutions and two complex solutions.
    // we only want the real ones
    // -----------------------------

    float r = length(v);
	float d = -abs(v.y)/sqrt(r+v.x) - c1/r - k0;

    if (d >= distBound.x && d <= distBound.y) {
	    vec3 pos = ro + rd * d;
	    normal = normalize( pos*pos*pos );
	    return d;
    } else {
        return MAX_DIST;
    }
}

// Goursat:         https://www.shadertoy.com/view/3lj3DW
float cuberoot( float x ) { return sign(x)*pow(abs(x),1.0/3.0); }

float iGoursat( in vec3 ro, in vec3 rd, in vec2 distBound, inout vec3 normal,
                in float ra, float rb ) {
// hole: x4 + y4 + z4 - (r2^2)·(x2 + y2 + z2) + r1^4 = 0;
    float ra2 = ra*ra;
    float rb2 = rb*rb;

    vec3 rd2 = rd*rd; vec3 rd3 = rd2*rd;
    vec3 ro2 = ro*ro; vec3 ro3 = ro2*ro;

    float ka = 1.0/dot(rd2,rd2);

    float k3 = ka*(dot(ro ,rd3));
    float k2 = ka*(dot(ro2,rd2) - rb2/6.0);
    float k1 = ka*(dot(ro3,rd ) - rb2*dot(rd,ro)/2.0  );
    float k0 = ka*(dot(ro2,ro2) + ra2*ra2 - rb2*dot(ro,ro) );

    float c2 = k2 - k3*(k3);
    float c1 = k1 + k3*(2.0*k3*k3-3.0*k2);
    float c0 = k0 + k3*(k3*(c2+k2)*3.0-4.0*k1);

    c0 /= 3.0;

    float Q = c2*c2 + c0;
    float R = c2*c2*c2 - 3.0*c0*c2 + c1*c1;
    float h = R*R - Q*Q*Q;


    // 2 intersections
    if (h>0.0) {
        h = sqrt(h);

        float s = cuberoot( R + h );
        float u = cuberoot( R - h );

        float x = s+u+4.0*c2;
        float y = s-u;

        float k2 = x*x + y*y*3.0;

        float k = sqrt(k2);

		float d = -0.5*abs(y)*sqrt(6.0/(k+x)) 
                  -2.0*c1*(k+x)/(k2+x*k) 
                  -k3;

        if (d >= distBound.x && d <= distBound.y) {
            vec3 pos = ro + rd * d;
            normal = normalize( 4.0*pos*pos*pos - 2.0*pos*rb*rb );
            return d;
        } else {
            return MAX_DIST;
        }
    } else {	
        // 4 intersections
        float sQ = sqrt(Q);
        float z = c2 - 2.0*sQ*cos( acos(-R/(sQ*Q)) / 3.0 );

        float d1 = z   - 3.0*c2;
        float d2 = z*z - 3.0*c0;

        if (abs(d1)<1.0e-4) {  
            if( d2<0.0) return MAX_DIST;
            d2 = sqrt(d2);
        } else {
            if (d1<0.0) return MAX_DIST;
            d1 = sqrt( d1/2.0 );
            d2 = c1/d1;
        }

        //----------------------------------

        float h1 = sqrt(d1*d1 - z + d2);
        float h2 = sqrt(d1*d1 - z - d2);
        float t1 = -d1 - h1 - k3;
        float t2 = -d1 + h1 - k3;
        float t3 =  d1 - h2 - k3;
        float t4 =  d1 + h2 - k3;

        if (t2<0.0 && t4<0.0) return MAX_DIST;

        float result = 1e20;
             if (t1>0.0) result=t1;
        else if (t2>0.0) result=t2;
             if (t3>0.0) result=min(result,t3);
        else if (t4>0.0) result=min(result,t4);

        if (result >= distBound.x && result <= distBound.y) {
            vec3 pos = ro + rd * result;
            normal = normalize( 4.0*pos*pos*pos - 2.0*pos*rb*rb );
            return result;
        } else {
            return MAX_DIST;
        }
    }
}

// Rounded Box:     https://www.shadertoy.com/view/WlSXRW
float iRoundedBox(in vec3 ro, in vec3 rd, in vec2 distBound, inout vec3 normal,
   				  in vec3 size, in float rad ) {
	// bounding box
    vec3 m = 1.0/rd;
    vec3 n = m*ro;
    vec3 k = abs(m)*(size+rad);
    vec3 t1 = -n - k;
    vec3 t2 = -n + k;
	float tN = max( max( t1.x, t1.y ), t1.z );
	float tF = min( min( t2.x, t2.y ), t2.z );
    if (tN > tF || tF < 0.0) {
    	return MAX_DIST;
    }
    float t = (tN>=distBound.x&&tN<=distBound.y)?tN:
    		  (tF>=distBound.x&&tF<=distBound.y)?tF:MAX_DIST;

    // convert to first octant
    vec3 pos = ro+t*rd;
    vec3 s = sign(pos);
    vec3 ros = ro*s;
    vec3 rds = rd*s;
    pos *= s;

    // faces
    pos -= size;
    pos = max( pos.xyz, pos.yzx );
    if (min(min(pos.x,pos.y),pos.z)<0.0) {
        if (t >= distBound.x && t <= distBound.y) {
            vec3 p = ro + rd * t;
            normal = sign(p)*normalize(max(abs(p)-size,0.0));
            return t;
        }
    }

    // some precomputation
    vec3 oc = ros - size;
    vec3 dd = rds*rds;
	vec3 oo = oc*oc;
    vec3 od = oc*rds;
    float ra2 = rad*rad;

    t = MAX_DIST;        

    // corner
    {
    float b = od.x + od.y + od.z;
	float c = oo.x + oo.y + oo.z - ra2;
	float h = b*b - c;
	if (h > 0.0) t = -b-sqrt(h);
    }

    // edge X
    {
	float a = dd.y + dd.z;
	float b = od.y + od.z;
	float c = oo.y + oo.z - ra2;
	float h = b*b - a*c;
	if (h>0.0) {
	  h = (-b-sqrt(h))/a;
      if (h>=distBound.x && h<t && abs(ros.x+rds.x*h)<size.x ) t = h;
    }
	}
    // edge Y
    {
	float a = dd.z + dd.x;
	float b = od.z + od.x;
	float c = oo.z + oo.x - ra2;
	float h = b*b - a*c;
	if (h>0.0) {
	  h = (-b-sqrt(h))/a;
      if (h>=distBound.x && h<t && abs(ros.y+rds.y*h)<size.y) t = h;
    }
	}
    // edge Z
    {
	float a = dd.x + dd.y;
	float b = od.x + od.y;
	float c = oo.x + oo.y - ra2;
	float h = b*b - a*c;
	if (h>0.0) {
	  h = (-b-sqrt(h))/a;
      if (h>=distBound.x && h<t && abs(ros.z+rds.z*h)<size.z) t = h;
    }
	}

	if (t >= distBound.x && t <= distBound.y) {
        vec3 p = ro + rd * t;
        normal = sign(p)*normalize(max(abs(p)-size,1e-16));
        return t;
    } else {
        return MAX_DIST;
    };
}

// Ray Tracing - Primitives. Created by Reinder Nijhoff 2019
// @reindernijhoff
//
// https://www.shadertoy.com/view/tl23Rm
//
// I have combined different intersection routines in one shader (similar 
// to "Raymarching - Primitives": https://www.shadertoy.com/view/Xds3zN) and
// added a simple ray tracer to visualize a scene with all primitives.
//

#define PATH_LENGTH 12

//
// Hash functions by Nimitz:
// https://www.shadertoy.com/view/Xt3cDn
//

uint baseHash( uvec2 p ) {
    p = 1103515245U*((p >> 1U)^(p.yx));
    uint h32 = 1103515245U*((p.x)^(p.y>>3U));
    return h32^(h32 >> 16);
}

float hash1( inout float seed ) {
    uint n = baseHash(floatBitsToUint(vec2(seed+=.1,seed+=.1)));
    return float(n)/float(0xffffffffU);
}

vec2 hash2( inout float seed ) {
    uint n = baseHash(floatBitsToUint(vec2(seed+=.1,seed+=.1)));
    uvec2 rz = uvec2(n, n*48271U);
    return vec2(rz.xy & uvec2(0x7fffffffU))/float(0x7fffffff);
}

//
// Ray tracer helper functions
//

float FresnelSchlickRoughness( float cosTheta, float F0, float roughness ) {
    return F0 + (max((1. - roughness), F0) - F0) * pow(abs(1. - cosTheta), 5.0);
}

vec3 cosWeightedRandomHemisphereDirection( const vec3 n, inout float seed ) {
  	vec2 r = hash2(seed);
	vec3  uu = normalize(cross(n, abs(n.y) > .5 ? vec3(1.,0.,0.) : vec3(0.,1.,0.)));
	vec3  vv = cross(uu, n);
	float ra = sqrt(r.y);
	float rx = ra*cos(6.28318530718*r.x); 
	float ry = ra*sin(6.28318530718*r.x);
	float rz = sqrt(1.-r.y);
	vec3  rr = vec3(rx*uu + ry*vv + rz*n);
    return normalize(rr);
}

vec3 modifyDirectionWithRoughness( const vec3 normal, const vec3 n, const float roughness, inout float seed ) {
    vec2 r = hash2(seed);

	vec3  uu = normalize(cross(n, abs(n.y) > .5 ? vec3(1.,0.,0.) : vec3(0.,1.,0.)));
	vec3  vv = cross(uu, n);

    float a = roughness*roughness;

	float rz = sqrt(abs((1.0-r.y) / clamp(1.+(a - 1.)*r.y,.00001,1.)));
	float ra = sqrt(abs(1.-rz*rz));
	float rx = ra*cos(6.28318530718*r.x); 
	float ry = ra*sin(6.28318530718*r.x);
	vec3  rr = vec3(rx*uu + ry*vv + rz*n);

    vec3 ret = normalize(rr);
    return dot(ret,normal) > 0. ? ret : n;
}

vec2 randomInUnitDisk( inout float seed ) {
    vec2 h = hash2(seed) * vec2(1,6.28318530718);
    float phi = h.y;
    float r = sqrt(h.x);
	return r*vec2(sin(phi),cos(phi));
}

//
// Scene description
//

vec3 rotateY( const in vec3 p, const in float t ) {
    float co = cos(t);
    float si = sin(t);
    vec2 xz = mat2(co,si,-si,co)*p.xz;
    return vec3(xz.x, p.y, xz.y);
}

vec3 opU( vec3 d, float iResult, float mat ) {
	return (iResult < d.y) ? vec3(d.x, iResult, mat) : d;
}

float iMesh( in vec3 ro, in vec3 rd, in vec2 distBound, inout vec3 normal) {
	const vec3 tri0 = vec3(-2./3. * 0.43301270189, 0, 0);
	const vec3 tri1 = vec3( 1./3. * 0.43301270189, 0, .25);
	const vec3 tri2 = vec3( 1./3. * 0.43301270189, 0,-.25);
	const vec3 tri3 = vec3( 0, 0.41079191812, 0);

    vec2 d = distBound;
	d.y = min(d.y, iTriangle(ro, rd, d, normal, tri0, tri1, tri2));   
	d.y = min(d.y, iTriangle(ro, rd, d, normal, tri0, tri3, tri1));  
	d.y = min(d.y, iTriangle(ro, rd, d, normal, tri2, tri3, tri0));   
	d.y = min(d.y, iTriangle(ro, rd, d, normal, tri1, tri3, tri2));

    return d.y < distBound.y ? d.y : MAX_DIST;
}

vec3 worldhit( in vec3 ro, in vec3 rd, in vec2 dist, out vec3 normal ) {
    vec3 tmp0, tmp1, d = vec3(dist, 0.);

    d = opU(d, iPlane      (ro,                  rd, d.xy, normal, vec3(0,1,0), 0.), 1.);
    d = opU(d, iBox        (ro-vec3( 1,.250, 0), rd, d.xy, normal, vec3(.25)), 2.);
    d = opU(d, iSphere     (ro-vec3( 0,.250, 0), rd, d.xy, normal, .25), 3.);
    d = opU(d, iCylinder   (ro,                  rd, d.xy, normal, vec3(2.1,.1,-2), vec3(1.9,.5,-1.9), .08 ), 4.);
    d = opU(d, iCylinder   (ro-vec3( 1,.100,-2), rd, d.xy, normal, vec3(0,0,0), vec3(0,.4,0), .1 ), 5.);
    d = opU(d, iTorus      (ro-vec3( 0,.250, 1), rd, d.xy, normal, vec2(.2,.05)), 6.);
    d = opU(d, iCapsule    (ro-vec3( 1,.000,-1), rd, d.xy, normal, vec3(-.1,.1,-.1), vec3(.2,.4,.2), .1), 7.);
    d = opU(d, iCone       (ro-vec3( 2,.200, 0), rd, d.xy, normal, vec3(.1,0,0), vec3(-.1,.3,.1), .15, .05), 8.);
    d = opU(d, iRoundedBox (ro-vec3( 0,.250,-2), rd, d.xy, normal, vec3(.15,.125,.15), .045), 9.);
    d = opU(d, iGoursat    (ro-vec3( 1,.275, 1), rd, d.xy, normal, .16, .2), 10.);
    d = opU(d, iEllipsoid  (ro-vec3(-1,.300, 0), rd, d.xy, normal, vec3(.2,.25, .05)), 11.);
    d = opU(d, iRoundedCone(ro-vec3( 2,.200,-1), rd, d.xy, normal, vec3(.1,0,0), vec3(-.1,.3,.1), 0.15, 0.05), 12.);
    d = opU(d, iRoundedCone(ro-vec3(-1,.200,-2), rd, d.xy, normal, vec3(0,.3,0), vec3(0,0,0), .1, .2), 13.);
    d = opU(d, iMesh       (ro-vec3( 2,.090, 1), rd, d.xy, normal), 14.);
    d = opU(d, iSphere4    (ro-vec3(-1,.275,-1), rd, d.xy, normal, .225), 15.);

    tmp1 = opU(d, iBox     (rotateY(ro-vec3(0,.25,-1), 0.78539816339), rotateY(rd, 0.78539816339), d.xy, tmp0, vec3(.1,.2,.1)), 16.);
    if (tmp1.y < d.y) {
        d = tmp1;
        normal = rotateY(tmp0, -0.78539816339);
    }

    return d;
}

//
// Palette by Íñigo Quílez: 
// https://www.shadertoy.com/view/ll2GD3
//
vec3 pal(in float t, in vec3 a, in vec3 b, in vec3 c, in vec3 d) {
    return a + b*cos(6.28318530718*(c*t+d));
}

float checkerBoard( vec2 p ) {
   return mod(floor(p.x) + floor(p.y), 2.);
}

vec3 getSkyColor( vec3 rd ) {
    vec3 col = mix(vec3(1),vec3(.5,.7,1), .5+.5*rd.y);
    float sun = clamp(dot(normalize(vec3(-.4,.7,-.6)),rd), 0., 1.);
    col += vec3(1,.6,.1)*(pow(sun,4.) + 10.*pow(sun,32.));
    return col;
}

#define LAMBERTIAN 0.
#define METAL 1.
#define DIELECTRIC 2.

float gpuIndepentHash(float p) {
    p = fract(p * .1031);
    p *= p + 19.19;
    p *= p + p;
    return fract(p);
}

void getMaterialProperties(in vec3 pos, in float mat, 
                           out vec3 albedo, out float type, out float roughness) {
    albedo = pal(mat*.59996323+.5, vec3(.5),vec3(.5),vec3(1),vec3(0,.1,.2));

    if( mat < 1.5 ) {            
        albedo = vec3(.25 + .25*checkerBoard(pos.xz * 5.));
        roughness = .75 * albedo.x - .15;
        type = METAL;
    } else {
        type = floor(gpuIndepentHash(mat+.3) * 3.);
        roughness = (1.-type*.475) * gpuIndepentHash(mat);
    }
}

//
// Simple ray tracer
//

float schlick(float cosine, float r0) {
    return r0 + (1.-r0)*pow((1.-cosine),5.);
}
vec3 render( in vec3 ro, in vec3 rd, inout float seed ) {
    vec3 albedo, normal, col = vec3(1.); 
    float roughness, type;

    for (int i=0; i<PATH_LENGTH; ++i) {    
    	vec3 res = worldhit( ro, rd, vec2(.0001, 100), normal );
		if (res.z > 0.) {
			ro += rd * res.y;

            getMaterialProperties(ro, res.z, albedo, type, roughness);

            if (type < LAMBERTIAN+.5) { // Added/hacked a reflection term
                float F = FresnelSchlickRoughness(max(0.,-dot(normal, rd)), .04, roughness);
                if (F > hash1(seed)) {
                    rd = modifyDirectionWithRoughness(normal, reflect(rd,normal), roughness, seed);
                } else {
                    col *= albedo;
			        rd = cosWeightedRandomHemisphereDirection(normal, seed);
                }
            } else if (type < METAL+.5) {
                col *= albedo;
                rd = modifyDirectionWithRoughness(normal, reflect(rd,normal), roughness, seed);            
            } else { // DIELECTRIC
                vec3 normalOut, refracted;
                float ni_over_nt, cosine, reflectProb = 1.;
                if (dot(rd, normal) > 0.) {
                    normalOut = -normal;
            		ni_over_nt = 1.4;
                    cosine = dot(rd, normal);
                    cosine = sqrt(1.-(1.4*1.4)-(1.4*1.4)*cosine*cosine);
                } else {
                    normalOut = normal;
                    ni_over_nt = 1./1.4;
                    cosine = -dot(rd, normal);
                }

	            // Refract the ray.
	            refracted = refract(normalize(rd), normalOut, ni_over_nt);

        	    // Handle total internal reflection.
                if(refracted != vec3(0)) {
                	float r0 = (1.-ni_over_nt)/(1.+ni_over_nt);
	        		reflectProb = FresnelSchlickRoughness(cosine, r0*r0, roughness);
                }

                rd = hash1(seed) <= reflectProb ? reflect(rd,normalOut) : refracted;
                rd = modifyDirectionWithRoughness(-normalOut, rd, roughness, seed);            
            }
        } else {
            col *= getSkyColor(rd);
			return col;
        }
    }  
    return vec3(0);
}

mat3 setCamera( in vec3 ro, in vec3 ta, float cr ) {
	vec3 cw = normalize(ta-ro);
	vec3 cp = vec3(sin(cr), cos(cr),0.0);
	vec3 cu = normalize( cross(cw,cp) );
	vec3 cv =          ( cross(cu,cw) );
    return mat3( cu, cv, cw );
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ) {
    bool reset = iFrame == 0;

    vec2 mo = iMouse.xy == vec2(0) ? vec2(.125) : 
              abs(iMouse.xy)/iResolution.xy - .5;

    vec4 data = texelFetch(iChannel0, ivec2(0), 0);
    if (round(mo*iResolution.xy) != round(data.yz) || round(data.w) != round(iResolution.x)) {
        reset = true;
    }

    vec3 ro = vec3(.5+2.5*cos(1.5+6.*mo.x), 1.+2.*mo.y, -.5+2.5*sin(1.5+6.*mo.x));
    vec3 ta = vec3(.5, -.4, -.5);
    mat3 ca = setCamera(ro, ta, 0.);    
    vec3 normal;

    float fpd = data.x;
    if(all(equal(ivec2(fragCoord), ivec2(0)))) {
        // Calculate focus plane.
        float nfpd = worldhit(ro, normalize(vec3(.5,0,-.5)-ro), vec2(0, 100), normal).y;
		fragColor = vec4(nfpd, mo*iResolution.xy, iResolution.x);
    } else { 
        vec2 p = (-iResolution.xy + 2.*fragCoord - 1.)/iResolution.y;
        float seed = float(baseHash(floatBitsToUint(p - iTime)))/float(0xffffffffU);

        // AA
        p += 2.*hash2(seed)/iResolution.y;
        vec3 rd = ca * normalize( vec3(p.xy,1.6) );  

        // DOF
        vec3 fp = ro + rd * fpd;
        ro = ro + ca * vec3(randomInUnitDisk(seed), 0.)*.02;
        rd = normalize(fp - ro);

        vec3 col = render(ro, rd, seed);

        if (reset) {
           fragColor = vec4(col, 1);
        } else {
           fragColor = vec4(col, 1) + texelFetch(iChannel0, ivec2(fragCoord), 0);
        }
    }
}

