// Standard 2D rotation formula.
mat2 r2(in float a){ float c = cos(a), s = sin(a); return mat2(c, -s, s, c); }

// vec2 to float hash.
float hash21(vec2 p){

    float n = dot(p, vec2(7.163, 157.247)); 
    return fract(sin(n)*43758.5453);
}

// vec3 to float hash.
float hash31(vec3 p){

    float n = dot(p, vec3(13.163, 157.247, 7.951)); 
    return fract(sin(n)*43758.5453); 
