//get distance to nearest surface and atmosphere/surface color
vec4 colorDistanceField(vec3 point, inout float minDist)
{       
    float charDist 		= MAX_DIST;
    vec4 charfield		= characterField(point, charDist);

    vec3 mPoint = point - vec3(7.5, 0.0, 2.0);
    pMod2(mPoint.xz, vec2(15.0, 15.0));

    float hexaHeight 	= 3.0;
    float hexaDist		= fHexagonCircumcircle(mPoint, vec2(1.5, hexaHeight));
    float distPlane     = fPlane(plane, point);
    minDist             = min(minDist, distPlane);
    minDist				= min(minDist, charDist);
    minDist				= min(minDist, hexaDist);

    //blend colors
    vec4 color = vec4(0.0);
    color += groundColor * step(distPlane, minDist);
    color += groundColor * step(hexaDist, minDist);
    color += charfield * step(charDist, minDist);

    return color;
}

//get distance and color to nearest surface
float distanceField(vec3 point)
{
    float minDist = MAX_DIST;
    colorDistanceField(point, minDist);
    return minDist;
}

vec3 computeNormal(vec3 p, float roughness, out float ao)
{    
    vec3 normalWS = vec3(0.0);
    for(int i = min(0, iFrame); i < 4; i++)
    {
        vec3 e = 0.5773*(2.0*vec3((((i+3)>>1)&1),((i>>1)&1),(i&1))-1.0);
        uint unusedMatId;
        normalWS += e*distanceField(p + e * 0.001);
    }
    normalWS = normalize(normalWS);    
    vec3 deform = noise3(p*0.0002);

    ao = length(deform);
    deform = deform*2.0 - vec3(1.0);
    return normalize(normalWS + deform * roughness*0.0001);
}

vec3 computeSaberLightDir(vec3 point, StickmanData data, FieldData fieldData)
{
#if LIGHT_QUALITY
    float grad = 0.75;

    vec3 normalWS = vec3(0.0);
    for(int i = min(0, iFrame); i < 4; i++)
    {
        vec3 e = 0.5773*(2.0*vec3((((i+3)>>1)&1),((i>>1)&1),(i&1))-1.0);
        uint unusedMatId;
        vec3 p = point + e * grad;
        normalWS += e*fSaber(data.invStickmanRot*(p - data.stickmanPos), data, fieldData);
    }
    normalWS = -normalize(normalWS); 
    return normalWS;
#else
    vec3 s = (vec3(0., data.saberLen*2.0, 0.)*data.invSaberRot);
    vec3 a = data.stickmanPos + (data.bodyPos + data.saberPos*data.bodyDeform)*data.invStickmanRot;
    vec3 c = data.stickmanPos + (data.bodyPos + (s + data.saberPos)*data.bodyDeform)*data.invStickmanRot;
    return normalize(mix(a, c, 0.5) - point);
#endif
}

float distBetweenSabers(StickmanData first, StickmanData secnd, FieldData secndField)
{
    vec3 s = (vec3(0., first.saberLen*2.0, 0.)*first.invSaberRot);
    vec3 a = first.stickmanPos + (first.bodyPos + first.saberPos*first.bodyDeform)*first.invStickmanRot;
    vec3 c = first.stickmanPos + (first.bodyPos + (s + first.saberPos)*first.bodyDeform)*first.invStickmanRot;

    float sithDistLaser = 1000.0;
    for(float i = 0.; i <= 1.0; i += 1.0/32.0)
    {
        vec3 b = mix(a, c, i);
        vec3 stickmanDiff = secnd.invStickmanRot*(b - secnd.stickmanPos);        
    	sithDistLaser = min(sithDistLaser, fSaber(stickmanDiff, secnd, secndField)); 
    }

    return sithDistLaser;
}

vec3 doLighting(vec3 surfColor, vec3 surfPoint, vec3 surfNormal, vec3 lightColor, vec3 lightDir, float roughness)
{
    if(dot(surfColor, surfColor) <= 2.5)
    {             
        float lightingWrap = 0.5;
        float diff 		= dot(surfNormal, lightDir);
        diff			= clamp((diff + lightingWrap)/((1.0 + lightingWrap)*(1.0 + lightingWrap)), 0.0, 1.0);
        vec3 eyeDir 	= normalize(projectionCenter - surfPoint);
        vec3 halfVec 	= normalize(eyeDir + lightDir);
        float spec 		= clamp(dot(halfVec, surfNormal), 0.0, 1.0);
        spec 			= pow(spec, mix(128.0, 8.0, pow(roughness, 0.5))) * pow(diff, 1.0);
        surfColor 		= surfColor * diff * lightColor + lightColor * spec;
    }    
    return surfColor;
}

//raymarch and sample atmosphere color along the ray
vec4 rmAtmosphere(vec3 rayStart, vec3 rayDir, float minDist)
{
    float cloud = 0.0;
	float transmittance = 1.0;
    vec3 scatteredLight = vec3(0.0, 0.0, 0.0);

    float totalDist = minDist;
    float dist = 0.0;
    float dStep = 0.0;
    vec3 color = zero;
    float stepBias, jediDistLaser, sithDistLaser, strLaser;
    vec3 atmColor, surfColor, litColor;
    vec3 endPoint, sithStickmanDiff, jediStickmanDiff, normal;
    vec3 jediSaberLightDir, sithSaberLightDir;
    vec4 dfRes;   
    float roughness = .0;
    vec3 S, Sint;
    float saberOverlap;

    float distSab = distBetweenSabers(jediData, sithData, sithFieldData);
    //distSab = min(distSab, distBetweenSabers(sithData, jediData, jediFieldData));
    float contactLightPower = 1.0 + smoothstep(0.3, 0.15, distSab)*3.0;

    vec4 rmRes;

    for(int i = 0; i < MAX_STEPS; ++i)
    {   
        stepBias = max(MIN_STEP_BIAS, totalDist*2.0/MAX_DIST);//to avoid artefacts

        endPoint = rayStart + rayDir * totalDist; 
        jediStickmanDiff = jediData.invStickmanRot*(endPoint - jediData.stickmanPos);
        jediFieldData.fSaber = fSaber(jediStickmanDiff, jediData, jediFieldData);
        strLaser = 1.0 + smoothstep(jediData.saberLen*2., 0.0, fHandle(jediStickmanDiff, jediData, jediFieldData))*2.;
        jediDistLaser = (LASER_STR + strLaser)/pow(jediFieldData.fSaber, 2.0);  

#ifdef TWO_EGGS
        sithStickmanDiff = sithData.invStickmanRot*(endPoint - sithData.stickmanPos);
        sithFieldData.fSaber = fSaber(sithStickmanDiff, sithData, sithFieldData);
        strLaser = 1.0 + smoothstep(sithData.saberLen*2., 0.0, fHandle(sithStickmanDiff, sithData, sithFieldData))*2.;
        sithDistLaser = (LASER_STR + strLaser)/pow(sithFieldData.fSaber, 2.0);         

        saberOverlap = 1.0/pow(jediFieldData.fSaber*sithFieldData.fSaber, 1.5);
        jediDistLaser += saberOverlap;
        sithDistLaser += saberOverlap;
#endif

        jediSaberLightDir = computeSaberLightDir(endPoint, jediData, jediFieldData);
        sithSaberLightDir = computeSaberLightDir(endPoint, sithData, sithFieldData);

#if VOL_FOG
        vec3 atmSamplePos = endPoint + rayDir*dist*(s_pixelRand-0.5);
        cloud = atmThickness(atmSamplePos);

        S = jediDistLaser*jediData.laserLight*contactLightPower*
#if VOL_SHADOW            
            volumetricShadow(atmSamplePos, jediSaberLightDir)*
#endif            
            cloud * PHASE_FUNC; // incoming light
#ifdef TWO_EGGS
        S += sithDistLaser*sithData.laserLight*contactLightPower*
#if VOL_SHADOW            
            volumetricShadow(atmSamplePos, sithSaberLightDir)*
#endif            
            cloud * PHASE_FUNC; // incoming light        
#endif        

        Sint = (S - S * exp(-cloud * dStep)) / cloud; // integrate along the current step segment
        scatteredLight += transmittance * Sint; // accumulate and also take into account the transmittance from previous steps
		// Evaluate transmittance to view independentely
        transmittance *= exp(-cloud * dStep); 
        if(transmittance < 0.005) 
        {
            break;
        }
#endif              
        dist = MAX_DIST;
        dfRes = colorDistanceField(endPoint, dist);        
        dStep = dist * stepBias;        
        totalDist += dStep;  

        if(dist <= MIN_DIST)
        {                  
            float ao = 1.0;
            normal = computeNormal(endPoint, roughness, ao);
            //store final hit color
            surfColor = dfRes.xyz;
            roughness = dfRes.w;

            //do lighting            
            litColor = AMBIANT_LIGHT * surfColor;            
            //Don't do sunlight, night time looks better
            //litColor += doLighting(surfColor, endPoint, normal, sunLightColor, normalize(sunLightPos - endPoint), roughness);                                  

            litColor += doLighting(surfColor, endPoint, normal, 
                                   (jediData.laserLight*contactLightPower)*jediDistLaser*0.5,
                                   jediSaberLightDir, roughness);                        
#ifdef TWO_EGGS

            litColor += doLighting(surfColor, endPoint, normal, 
                                   (sithData.laserLight*contactLightPower)*sithDistLaser*0.5, 
                                   sithSaberLightDir, roughness);                        
#endif                                                

            color = surfColor*ao*0.01 + litColor;

            rmRes = vec4(color, totalDist);   
            break;
        }                

        //no surface hit, return sky + atmColor
        if(totalDist >= MAX_DIST || i >= MAX_STEPS - 1)
        {
            rmRes = vec4(color + skyColor, MAX_DIST + 0.01);
            break;
        }
    }    

    rmRes.xyz = mix(fogColor*0.8, rmRes.xyz, transmittance) + scatteredLight;
    return rmRes;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{      
    s_pixelRand = textureLod(iChannel0, fragCoord/vec2(1024.0), 0.0).r;
    s_pixelRand = fract(s_pixelRand + float(iFrame % 256)*1.618);
    s_time = iTime;// - iTimeDelta * s_pixelRand;

    vec2 mousePos = iMouse.xy / iResolution.xy * 2.0 - vec2(1.0);
    float day = 0.0;
    day = sign(day) * pow(abs(day), 2.0);
    dayProgress = abs(day);

    float sunsetFromNight = smoothstep(0.4, 0.5, dayProgress);
    float sunsetToDay = smoothstep(0.8, 0.5, dayProgress);
    vec3 sunsetColor = mix(mix(vec3(0.5, 0.0 ,0.0), vec3(1.0, 0.8, 0.3), sunsetFromNight),
                           mix(vec3(0.2, 0.2, 1.0), vec3(1.0, 0.8, 0.3), sunsetToDay), (sunsetFromNight + sunsetToDay)/2.0);
    float sunsetStr = sunsetFromNight*sunsetToDay;    

    sunLightPos = vec3(0.0, -1000.0, 0.0);
    mat3 sRotZ;
    rotationZ(day*PI, sRotZ);
    sunLightPos = sRotZ*sunLightPos;

    sunLightColor = mix(vec3(0.004, 0.004, 0.0065), vec3(0.8, 0.8, 0.7), dayProgress);    
    sunLightColor = mix(sunLightColor, sunsetColor, sunsetStr);

    vec2 uv = fragCoord.xy / iResolution.xy;    
    vec3 ro = vec3(0.0);

    float t = s_time * 1.1; 
    t += (cos(t*0.5))*0.2;

    float camT = t*0.5;
    float camRotY = (mousePos.x + camT*0.1)*PI*-2.0;
    float camY = (1.0 - cos(camT*0.5))*0.3;
    float camDist = 12.0 - sin(camT*0.5)*4.0;

    //animate before marching
    initStickman(jediData, true);
#ifdef TWO_EGGS    
    jediData.stickmanPos.x += 2.7;
    mat3 yRot;
    rotationY(-0.5*PI, yRot);    
    jediData.invStickmanRot = yRot*jediData.invStickmanRot;

    initStickman(sithData, false);    
    sithData.stickmanPos.x -= 2.7;
    rotationY(0.5*PI, yRot);
    sithData.invStickmanRot = yRot*sithData.invStickmanRot;
    animateSith(t, sithData);      
    computeFieldData(sithData, sithFieldData);
#endif    
    animateJedi(t, jediData);
    computeFieldData(jediData, jediFieldData);


    //////////////////

    //Do camera setup from mouse coord
    vec3 pCenter        = vec3(0.0, 0.2, 0.0);
    vec3 pOffset		= vec3(0.0, 0.0, 1.0);

    mat3 pRotY;
    rotationY(camRotY, pRotY);
    pOffset.y = camY;
    pOffset = pRotY*pOffset;    
    projectionCenter    = pCenter + pOffset*camDist;

    vec3 tmpCenter      = (projectionCenter + vec3(0.0, 0.0, .50));

    projectionCenter    = (projectionCenter);

    projectionForward   = normalize(-pOffset);
    projectionUp 		= vec3(0.0, 1.0, 0.0);
    projectionRight 	= cross(projectionUp, projectionForward);
    projectionUp 		= cross(projectionForward, projectionRight);      
    mousePos       = pixelToNormalizedspace(iMouse.xy);


    cameraOffset        = -projectionForward * FOCAL_LENGTH;

    vec2 rd = uv*2.0 - vec2(1.0);
    rd.y /= iResolution.x/iResolution.y;
    //setup ray
    vec3 rayPos                 = projectionCenter + cameraOffset;
    vec3 pointOnProjectionPlane = projectionCenter + projectionRight * rd.x + projectionUp * rd.y;
    vec3 rayDirection           = normalize(pointOnProjectionPlane - rayPos);

    float sun = pow(max(0.0, dot(rayDirection, normalize(sunLightPos))), 2.0);

    //sky and stars
    vec2 xzDir 		= normalize(rayDirection.xz);
    vec2 starsUv 	= vec2(atan(xzDir.x, xzDir.y), rayDirection.y);
    vec3 stars      = textureLod(iChannel0, starsUv * 0.1, 0.).xyz;
    stars           *= pow(dot(stars, stars)*0.5, 16.0) * 0.3;// smoothstep(2.1, 2.5, dot(stars, stars));
    stars = smoothstep(vec3(0.0), vec3(1.0), stars);
    float skyHeight = pow(max(0.0, rayDirection.y) * 2.0, 0.75);
    float starVis   = skyHeight * pow(1.0 - dayProgress, 2.0);
    stars = mix(zero, stars, pow(starVis, 6.0));

    vec3 lowColor = mix(vec3(0.01, 0.01, 0.05), vec3(0.85, 0.85, 1.0), dayProgress);
    lowColor = mix(lowColor, sunsetColor, sunsetStr + pow(sun, 5.0)*sunsetStr*2.0);
    vec3 upColor = mix(vec3(0.0005, 0.0005, 0.001), vec3(0.15, 0.15, 1.0), dayProgress);
    upColor = mix(upColor, sunsetColor, sunsetStr*0.5 + pow(sun, 5.0)*sunsetStr*2.0);

    skyColor = mix(lowColor, upColor, skyHeight);    

    float fogBlur = 0.5;
    fogColor = mix(mix(lowColor, upColor, max(0.0, skyHeight - fogBlur)),
                   mix(lowColor, upColor, min(1.0, skyHeight + fogBlur)),
                   0.5);

    //march ray
    vec4 rayMarchResult     = rmAtmosphere(rayPos, rayDirection, 0.0);    
    float dist              = rayMarchResult.w;
    vec4 surfaceColor       = vec4(rayMarchResult.xyz , 1.0);

    if(dist >= MAX_DIST)
    {
        surfaceColor.xyz += stars;
        surfaceColor.xyz = surfaceColor.xyz + sunLightColor*pow(sun, 80.0)*10.0;
    }    

    //convert to gamma space
    surfaceColor = pow( surfaceColor, vec4(1.0/2.2));
    fragColor = surfaceColor;
}

/*
 * Cube on Plane with Soft Shadows
 * 
 * This shader demonstrates ray marching techniques to render a cube on a checkerboard plane
 * with physically-based lighting and soft shadows. Key features include:
 * 
 * - Ray marching with signed distance functions (SDFs)
 * - Toggleable soft/hard shadows with configurable softness
 * - Physically-based lighting with proper light attenuation
 * - Blinn-Phong specular reflections
 * - Rotating light source that circles the scene
 * - ACES-inspired tone mapping for improved contrast
 * - Checkerboard floor pattern with proper shadowing
 * 
 * The shadow implementation uses ray marching from surface points toward the light source,
 * calculating penumbra based on the proximity of occluders to the shadow ray.
 * 
 * Controls:
 * - Modify USE_SOFT_SHADOWS to toggle between soft and hard shadows
 * - Adjust SHADOW_SOFTNESS to control the softness of shadow edges
 */

// --- Constants ---
const float PI = 3.14159265359;

// --- Ray Marching Constants ---
// Maximum number of steps to take when ray marching before giving up
const int MAX_MARCHING_STEPS = 255;
// Minimum distance to start ray marching from
const float MIN_DIST = 0.0;
// Maximum distance to consider when ray marching (beyond this is considered a miss)
const float MAX_DIST = 100.0;
// Precision threshold for considering a hit (when distance < PRECISION)
const float PRECISION = 0.001;
// Default background color for rays that don't hit any object
const vec3 COLOR_BACKGROUND = vec3(0.835, 1, 1);

// --- Shadow Settings ---
// Set to true for soft shadows, false for hard shadows
const bool USE_SOFT_SHADOWS = true;
// Controls the softness of shadows when USE_SOFT_SHADOWS is true
// Higher values = sharper shadows, lower values = softer shadows
const float SHADOW_SOFTNESS = 8.0;

// --- Signed Distance Functions (SDFs) ---
// SDF for a cube - returns the signed distance from point p to a cube
// Negative inside, positive outside, zero on the surface
// p: the point to calculate distance from
// center: the center position of the cube
// size: half the length of the cube's sides
float sdCube(vec3 p, vec3 center, float size) {
  // Offset p by the center of the cube
  vec3 q = abs(p - center) - vec3(size);
  // Distance to the closest point on the cube
  return length(max(q, 0.0)) + min(max(q.x, max(q.y, q.z)), 0.0);
}

// SDF for an infinite horizontal floor at y = -1
// p: the point to calculate distance from
float sdFloor(vec3 p) {
  float d = p.y + 1.; // +1 shifts the floor down to y = -1
  return d;
}

// --- Scene Composition Operations ---
// Union operation for combining two objects
// Takes two vec2 values where:
//   x component = signed distance
//   y component = material ID
// Returns the object with the smallest distance (closest to the ray)
vec2 opU(vec2 d1, vec2 d2) {
  return (d1.x < d2.x) ? d1 : d2; // the x-component is the signed distance value
}

// --- Scene Description ---
// Maps a 3D point to the closest object in the scene
// Returns vec2 where:
//   x component = signed distance to closest object
//   y component = material ID of closest object
vec2 map(vec3 p) {
  vec2 res = vec2(1e10, 0.); // Initialize with a very large distance and ID = 0
  vec2 flooring = vec2(sdFloor(p), 0.5); // Floor with ID = 0.5
  vec2 cube = vec2(sdCube(p, vec3(0, 0, 0), 1.0), 1.5); // Centered cube with ID = 1.5

  // Combine objects using union operation
  res = opU(res, flooring);
  res = opU(res, cube);
  return res; // the y-component is the ID of the object hit by the ray
}

// --- Ray Marching Implementation ---
// Marches a ray through the scene to find intersections
// ro: ray origin (camera position)
// rd: ray direction
// Returns vec2 where:
//   x component = distance traveled along ray until hit
//   y component = material ID of hit object
vec2 rayMarch(vec3 ro, vec3 rd) {
  float depth = MIN_DIST; // Start from minimum distance
  vec2 res = vec2(0.0);   // Initialize result (distance and ID)
  float id = 0.;          // Material ID of hit object

  // Main ray marching loop
  for(int i = 0; i < MAX_MARCHING_STEPS; i++) {
    vec3 p = ro + depth * rd; // Current position along ray
    res = map(p);             // Get distance to closest object and its ID
    depth += res.x;           // Move along ray by the safe distance
    id = res.y;               // Store the object ID

    // Exit conditions: hit something or went too far
    if(res.x < PRECISION || depth > MAX_DIST)
      break;
  }
  return vec2(depth, id);
}

// --- Normal Calculation ---
// Calculates the surface normal at point p using the gradient of the SDF
// This uses central differences to approximate the gradient
// p: the point to calculate normal at
// center: the center of the cube (parameter kept for consistency)
vec3 calcNormal(in vec3 p, in vec3 center) {
  const float eps = 0.0005; // Small epsilon for offset sampling
  const vec2 h = vec2(eps, 0.0);

  // Sample the distance field at 4 nearby points and calculate the gradient
  return normalize(vec3(
    map(p + h.xyy).x - map(p - h.xyy).x,
    map(p + h.yxy).x - map(p - h.yxy).x,
    map(p + h.yyx).x - map(p - h.yyx).x
  ));
}

// --- Shadow Calculation ---
// Calculates hard shadows (0 or 1)
// ro: ray origin (the point on the surface)
// rd: ray direction (direction to the light)
float hardShadow(vec3 ro, vec3 rd, float mint, float maxt) {
  for(float t = mint; t < maxt;) {
    vec3 p = ro + rd * t;
    float h = map(p).x;
    if(h < PRECISION)
      return 0.0; // In shadow
    t += h;
  }
  return 1.0; // Not in shadow
}

// --- Soft Shadow Calculation ---
// Calculates soft shadows with penumbra
// ro: ray origin (the point on the surface)
// rd: ray direction (direction to the light)
// k: controls the softness of the shadow (higher = sharper shadow edges)
float softShadow(vec3 ro, vec3 rd, float mint, float maxt, float k) {
  float res = 1.0;
  float t = mint;

  for(int i = 0; i < 64; i++) {
    if(t >= maxt) break;

    vec3 p = ro + rd * t;
    float h = map(p).x;

    if(h < PRECISION)
      return 0.0; // Complete shadow

    // This is the key part of soft shadows:
    // The ratio h/t represents the "angle" to the potential occluder
    // Smaller h/t means the ray passes closer to an object
    // k controls how quickly the shadow value drops off with angle
    res = min(res, k * h / t);

    t += h;
  }

  return res;
}

// --- Rendering Function ---
// Calculates the color for a ray based on intersection and lighting
// ro: ray origin (camera position)
// rd: ray direction
vec3 render(vec3 ro, vec3 rd) {
  vec3 col = COLOR_BACKGROUND; // Default to background color

  // Perform ray marching to find intersection
  vec2 res = rayMarch(ro, rd);
  float d = res.x; // Distance traveled along ray

  // If ray didn't hit anything (went beyond MAX_DIST), return background color
  if(d > MAX_DIST)
    return col;

  float id = res.y; // Material ID of hit object
  vec3 p = ro + rd * d; // Intersection point in 3D space

  // Get the center for normal calculation (only matters for cubes)
  vec3 center = vec3(0, 0, 0); // Cube center
  vec3 normal = calcNormal(p, center); // Surface normal at intersection

  // --- Lighting Calculation ---
  // Rotating point light source
  float lightAngle = iTime * 0.5; // Control rotation speed with the multiplier
  float lightRadius = 3.0; // Distance from origin
  float lightHeight = 3.0; // Height above the plane
  vec3 lightPosition = vec3(
    lightRadius * cos(lightAngle), // X position rotates with time
    lightHeight,                   // Fixed height
    lightRadius * sin(lightAngle)  // Z position rotates with time
  );
  vec3 lightDirection = normalize(lightPosition - p);

  // Calculate distance to light for attenuation
  float lightDistance = length(lightPosition - p);

  // Light attenuation (falloff with distance)
  // Using inverse square law: intensity ∝ 1/distance²
  float lightAttenuation = 1.0 / (1.0 + 0.1 * lightDistance + 0.01 * lightDistance * lightDistance);

  // Base ambient lighting (different for floor and cube)
  float ambient = 0.1;

  // Diffuse lighting (Lambert)
  float diffuse = max(dot(normal, lightDirection), 0.0);

  // Specular lighting (Blinn-Phong)
  vec3 viewDirection = normalize(ro - p);
  vec3 halfwayDirection = normalize(lightDirection + viewDirection);
  float specularPower = (id < 1.0) ? 32.0 : 16.0; // Higher for floor (more shiny)
  float specular = pow(max(dot(normal, halfwayDirection), 0.0), specularPower);

  // Shadow calculation
  // Offset the origin slightly to avoid self-shadowing
  vec3 shadowRayOrigin = p + normal * 0.01;

  // Calculate shadow (1.0 = fully lit, 0.0 = fully in shadow)
  float shadow;
  if (USE_SOFT_SHADOWS) {
    shadow = softShadow(shadowRayOrigin, lightDirection, 0.1, 10.0, SHADOW_SOFTNESS);
  } else {
    shadow = hardShadow(shadowRayOrigin, lightDirection, 0.1, 10.0);
  }

  // Material properties
  vec3 materialColor;
  float materialShininess;

  if(id < 1.) {
    // Floor with checkerboard pattern - increased contrast
    materialColor = vec3(0.95) * (0.3 + 0.7 * mod(floor(p.x) + floor(p.z), 2.0));
    materialShininess = 0.08; // Slightly increased specular for floor
  } else {
    // Cube with blue color
    materialColor = vec3(0.2, 0.4, 0.8);
    materialShininess = 0.6; // Higher specular for cube
  }

  // Combine lighting components
  vec3 ambientComponent = ambient * materialColor;
  vec3 diffuseComponent = diffuse * materialColor * lightAttenuation * shadow;
  vec3 specularComponent = specular * vec3(1.0) * materialShininess * lightAttenuation * shadow;

  // Final color
  col = ambientComponent + diffuseComponent + specularComponent;

  // Add a subtle environmental lighting
  col += COLOR_BACKGROUND * 0.02; // Reduced environmental contribution

  // Apply contrast enhancement
  col = pow(col, vec3(1.1)); // Increase contrast by applying a power function

  // Apply improved tone mapping (ACES-inspired)
  // This gives better contrast than the simple Reinhard operator
  const float tm_a = 2.51;
  const float tm_b = 0.03;
  const float tm_c = 2.43;
  const float tm_d = 0.59;
  const float tm_e = 0.14;
  col = (col * (tm_a * col + tm_b)) / (col * (tm_c * col + tm_d) + tm_e);

  // Gamma correction with slightly lower gamma for more contrast
  col = pow(col, vec3(1.0/2.1)); // Standard is 2.2, using 2.1 for slightly higher contrast

  return col;
}

// --- Main Entry Point ---
// ShaderToy entry point - called for each pixel
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  // Convert pixel coordinates to normalized device coordinates (-1 to 1)
  // Centered at origin and adjusted for aspect ratio
  vec2 uv = (fragCoord - .5 * iResolution.xy) / iResolution.y;

  // --- Camera Setup ---
  // Get normalized mouse position for rotation (default to 0.5 if mouse not clicked)
  float mouseX = iMouse.z > 0.0 ? iMouse.x / iResolution.x : 0.5;
  // Convert mouse position to rotation angle (full circle when dragging across screen)
  float rotationY = mouseX * 2.0 * PI;

  // Calculate camera position with rotation
  float camDist = 6.0;
  vec3 ro = vec3(
    camDist * sin(rotationY),
    2,
    camDist * cos(rotationY)
  );

  // Look at the center of the scene
  vec3 lookAt = vec3(0, -0.5, 0);
  vec3 forward = normalize(lookAt - ro);
  vec3 right = normalize(cross(vec3(0, 1, 0), forward));
  vec3 up = cross(forward, right);
  vec3 rd = normalize(forward + uv.x * right + uv.y * up);

  // Render the scene for this ray
  vec3 col = render(ro, rd);

  // Output final color to screen
  fragColor = vec4(col, 1.0);
}

// ========================
// Marching through volume
// ========================

#define DATA(lmn) texture(iChannel0, vcubeFromLMN(2, lmn)).st

vec2 getDataInterp(vec3 lmn) {
    vec3 flmn = floor(lmn);

    vec2 d000 = DATA( flmn );
    vec2 d001 = DATA( flmn + vec3(0.0, 0.0, 1.0) );
    vec2 d010 = DATA( flmn + vec3(0.0, 1.0, 0.0) );
    vec2 d011 = DATA( flmn + vec3(0.0, 1.0, 1.0) );
    vec2 d100 = DATA( flmn + vec3(1.0, 0.0, 0.0) );
    vec2 d101 = DATA( flmn + vec3(1.0, 0.0, 1.0) );
    vec2 d110 = DATA( flmn + vec3(1.0, 1.0, 0.0) );
    vec2 d111 = DATA( flmn + vec3(1.0, 1.0, 1.0) );

    vec3 t = lmn - flmn;
    return mix(
        mix(mix(d000, d100, t.x), mix(d010, d110, t.x), t.y),
        mix(mix(d001, d101, t.x), mix(d011, d111, t.x), t.y),
        t.z
    );
}

void readLMN(in vec3 lmn, out float density, out float lightAmount) {
    #ifdef SMOOTHING
    	vec2 data = getDataInterp(lmn);
    #else
    	vec2 data = DATA(lmn);
    #endif

    bool noLight = texelFetch(iChannel2, ivec2(KEY_S,0), 0).x > 0.5;
    lightAmount = noLight ? 1.0 : data.t;
    lightAmount = mix(lightAmount, 1.0, 0.025);

    // density = fDensity(iChannel1, lmn, iTime);
    density = data.s;
}

vec4 march(vec3 p, vec3 nv, vec2 fragCoord) {
    vec2 tRange;
    float didHitBox;
    boxClip(BOX_MIN, BOX_MAX, p, nv, tRange, didHitBox);
    tRange.s = max(0.0, tRange.s);

    vec4 color = vec4(0.0);
    if (didHitBox < 0.5) {
        return color;
    }

    bool noColor = texelFetch(iChannel2, ivec2(KEY_A,0), 0).x > 0.5;
	bool noDensity = texelFetch(iChannel2, ivec2(KEY_D,0), 0).x > 0.5;

    float t = tRange.s + min(tRange.t-tRange.s, RAY_STEP)*hash12(fragCoord);
    int i=0;
    for (; i<150; i++) { // Theoretical max steps: (BOX_MAX-BOX_MIN)*sqrt(3)/RAY_STEP
        if (t > tRange.t || color.a > QUIT_ALPHA) { break; }

        vec3 rayPos = p + t*nv;
        vec3 lmn = lmnFromWorldPos(rayPos);

        float density;
        float lightAmount;
        readLMN(lmn, density, lightAmount);

        vec3 cfrag = noColor ? vec3(1.0) : colormap(0.7*density+0.8);
        density = noDensity ? 0.1 : density;

        float calpha = density * MAX_ALPHA_PER_UNIT_DIST * RAY_STEP;
        vec4 ci = clamp( vec4(cfrag * lightAmount, 1.0)*calpha, 0.0, 1.0);
        color = blendOnto(color, ci);

        t += RAY_STEP;
    }

    float finalA = clamp(color.a/QUIT_ALPHA, 0.0, 1.0);
    color *= (finalA / (color.a + 1e-5));

    bool showSteps = texelFetch(iChannel2, ivec2(KEY_F,0), 0).x > 0.5;
    return showSteps ? vec4(vec3(float(i)/150.0), 1.0) : color;
}

// ================
// Final rendering
// ================

#define RES iResolution
#define TAN_HALF_FOVY 0.5773502691896257
#define VIGNETTE_INTENSITY 0.25

vec3 skybox(vec3 nvDir) {
    return ( mix(0.1, 0.2, smoothstep(-0.2,0.2, nvDir.y)) )*vec3(1.0);
}

vec3 nvCamDirFromClip(vec3 nvFw, vec2 clip) {
    vec3 nvRt = normalize(cross(nvFw, vec3(0.,1.,0.)));
    vec3 nvUp = cross(nvRt, nvFw);
    return normalize(TAN_HALF_FOVY*(clip.x*(RES.x/RES.y)*nvRt + clip.y*nvUp) + nvFw);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord / iResolution.xy;

    // Camera
    float isMousePressed = clamp(iMouse.z, 0.0, 1.0);
    vec2 mouseAng = mix(
        vec2(CAM_THETA, CAM_PHI),
        PI * vec2(4.0*iMouse.x, iMouse.y) / iResolution.xy,
        isMousePressed
    );

    vec3 camPos = 2.5 * SPHERICAL(mouseAng.x, mouseAng.y);
    vec3 lookTarget = vec3(0.0);

	vec3 nvCamFw = normalize(lookTarget - camPos);
    vec3 nvCamDir = nvCamDirFromClip(nvCamFw, uv*2. - 1.);

    // Render
    vec3 bgColor = skybox(nvCamDir);
    vec4 fgColor = march(camPos, nvCamDir, fragCoord);
    vec3 finalColor = blendOnto(fgColor, vec4(bgColor, 1.0)).rgb;

    // Vignette
    vec2 radv = vec2(0.5, 0.5) - uv;
    float dCorner = length(radv) / INV_SQRT_2;
    float vignetteFactor = 1.0 - mix(0.0, VIGNETTE_INTENSITY, smoothstep(0.4, 0.9, dCorner));

    fragColor = vec4(vignetteFactor * finalColor, 1.0);
}

