// ---------------------------------------------
// Distance field 
// ---------------------------------------------
float box( vec3 p, vec3 b )
{
    vec3 q = abs(p) - b;
    return length(max(q,0.0)) + min(max(q.x,max(q.y,q.z)),0.0);
}

float map(vec3 p) {

        float d = 99999.;

    #if SCENE == 0
        vec3 pp = p;
        p.xz = mod(p.zx,1.)-.5;
        d = min(d, length(p-vec3(0.,.4,0.))-.4);
        //d = min(d, sheep(p*8.)/8.);
        d = max(d, abs(pp.z)-5.);
        d = max(d, abs(pp.x)-3.);
    #endif

    #if SCENE == 1
        vec3 pp = p;
        p.xz = mod(p.zx,1.)-.5;
        //p.xz = rot(p.y*.5)*p.xz;
        d = min(d, box(p-vec3(0.,.4,0.),vec3(.4)));
        //d = min(d, sheep(p*8.)/8.);
        d = max(d, abs(pp.z)-5.);
        d = max(d, abs(pp.x)-3.);
    #endif

    #if SCENE == 2
    {
        vec3 ip = floor(p);
        vec3 fp = fract(p)-.5;

        vec3 id = hash3(ip+1000.);
        fp.y = p.y-.2;
        fp.xy = rot(id.x*PI*3.) * fp.xy;
        fp.xz = rot(id.y*PI*3.) * fp.xz;
        fp.yz = rot(id.z*PI*3.) * fp.yz;
        d = min(d, box(fp,vec3(.3)));
        d = max(d, abs(p.z)-5.);
        d = max(d, abs(p.x)-3.);

    }
    #endif

    #if !FURNACE_TEST
        d = min(d, p.y);
    #endif
    return d;
}









// ---------------------------------------------
// Ray tracing 
// ---------------------------------------------
float trace(vec3 ro, vec3 rd, vec2 nf) {
    float t = nf.x;
    for(int i=0; i<256; i++) {
        float d = map(ro+rd*t);
        if (t > nf.y || abs(d)<0.001) break;
        t += d;
    }

    return t;
}

vec3 normal(vec3 p, float t) {
    vec2 eps = vec2(0.0001,0.0);
    float d = map(p);
    vec3 n;
    n.x = d - map(p - eps.xyy);
    n.y = d - map(p - eps.yxy);
    n.z = d - map(p - eps.yyx);
    n = normalize(n);
    return n;
}

