#define sundir normalize( vec3(5.,1.,0.))


// ---------------------------------------------
// Material
// ---------------------------------------------
struct Material {
    vec3 albedo;
    float metallic;
    float roughness;
    vec3 emissive;
};
Material newMaterial() {
    Material mat;
    mat.albedo = vec3(1.);
    mat.metallic = 0.;
    mat.roughness = .1;
    mat.emissive = vec3(0.);

    return mat;
}
Material getMaterial(vec3 p, inout vec3 n) {

    Material mat = newMaterial();

    #if 1 // Random materials
        if (abs(map(p)-p.y) > 0.001) {
            vec3 rnd = hash3(floor(p+1000.));
            mat.roughness = rnd.y*rnd.y;
            mat.metallic = rnd.x;
            mat.albedo = hash3(floor(p))*.75;
            mat.emissive = mat.albedo*step(rnd.y,.02);
        } else {
            mat.metallic = 1.;
            mat.roughness = .5;
        }
    #else // Roughness/Metallic axis
        if (abs(map(p)-p.y) > 0.001) {
            mat.roughness = pow(floor(p.z+5.)/9.,1.)*.99+0.01;
            mat.metallic = saturate(floor(p.x+3.)/5.);
            mat.albedo = vec3(1.);
        } else {
            mat.metallic = 1.;
            mat.roughness = mod(floor(p.x)+floor(p.z),2.)*.25+.25;
        }
    #endif


    #if FURNACE_TEST // Set it in the common tab
        mat.albedo = vec3(1.);
        mat.roughness = pow(floor(p.z+5.)/9.,1.)*.99+0.01;
        mat.metallic = saturate(floor(p.x+3.)/5.);
        mat.emissive = vec3(0.);
    #endif

    return mat;
}



// ---------------------------------------------
// BRDF
// ---------------------------------------------
vec3 evalDisneyDiffuse(Material mat, float NoL, float NoV, float LoH, float roughness) {
    float FD90 = 0.5 + 2. * roughness * pow(LoH,2.);
    float a = F_Schlick(1.,FD90, NoL);
    float b = F_Schlick(1.,FD90, NoV);

    return mat.albedo * (a * b / PI);
}

vec3 evalDisneySpecular(Material mat, vec3 F, float NoH, float NoV, float NoL) {
    float roughness = pow(mat.roughness, 2.);
    float D = D_GTR(roughness, NoH,2.);
    float G = GeometryTerm(NoL, NoV, pow(0.5+mat.roughness*.5,2.));

    vec3 spec = D*F*G / (4. * NoL * NoV);

    return spec;
}

vec4 sampleDisneyBRDF(vec3 v, vec3 n, Material mat, inout vec3 l) {

    float roughness = pow(mat.roughness, 2.);

    // sample microfacet normal
    vec3 t,b;
    basis(n,t,b);
    vec3 V = toLocal(t,b,n,v);
    vec3 h = SampleGGXVNDF(V, roughness,roughness, frand(), frand());
    if (h.z < 0.0)
        h = -h;
    h = toWorld(t,b,n,h);

    // fresnel
    vec3 f0 = mix(vec3(0.04), mat.albedo, mat.metallic);
    vec3 F = F_Schlick(f0, dot(v,h));

    // lobe weight probability
    float diffW = (1.-mat.metallic);
    float specW = luma(F);
    float invW = 1./(diffW + specW);
    diffW *= invW;
    specW *= invW;


    vec4 brdf = vec4(0.);
    float rnd = frand();
    if (rnd < diffW) // diffuse
    {
        l = cosineSampleHemisphere(n);
        h = normalize(l+v);

        float NoL = dot(n,l);
        float NoV = dot(n,v);
        if ( NoL <= 0. || NoV <= 0. ) { return vec4(0.); }
        float LoH = dot(l,h);
        float pdf = NoL/PI;

        vec3 diff = evalDisneyDiffuse(mat, NoL, NoV, LoH, roughness) * (1.-F);
        brdf.rgb = diff * NoL;
        brdf.a = diffW * pdf;
    } 
    else // specular
    {
        l = reflect(-v,h);

        float NoL = dot(n,l);
        float NoV = dot(n,v);
        if ( NoL <= 0. || NoV <= 0. ) { return vec4(0.); }
        float NoH = min(dot(n,h),.99);
        float pdf = GGXVNDFPdf(NoH, NoV, roughness);

        vec3 spec = evalDisneySpecular(mat, F, NoH, NoV, NoL);
        brdf.rgb = spec * NoL;
        brdf.a = specW * pdf;
    }

    return brdf;
}


// ---------------------------------------------
// Pathtrace
// ---------------------------------------------
vec4 pathtrace(vec3 ro, vec3 rd) {

    float firstDepth = 0.;
    vec3 acc = vec3(0.);
    vec3 abso = vec3(1.);

    const int BOUNCE_COUNT = 6;
    for(int i=0; i<BOUNCE_COUNT; i++) {

        // raytrace
        float t = trace(ro,rd, vec2(0.01, 1000.));
        vec3 p = ro + rd * t;
        if (i == 0) firstDepth = t;

        // sky intersection ?
        if (t > 1000.) {
            acc += skyColor(rd, sundir) * abso;
            break;
        }

        // info at intersection point
        vec3 n = normal(p, t);
        vec3 v = -rd;
        Material mat = getMaterial(p,n);

        // sample BRDF
        vec3 outDir;
        vec4 brdf = sampleDisneyBRDF(v,n, mat, outDir);

        // add emissive part of the current material
        acc += mat.emissive * abso;

        // absorption (pdf are in brdf.a)
        if (brdf.a > 0.)
            abso *= brdf.rgb / brdf.a;

        // next direction
        ro = p+n*0.01;
        rd = outDir;
    }

    return vec4(acc, firstDepth);
}


// ---------------------------------------------
// Entrypoint
// ---------------------------------------------
void mainImage( out vec4 fragColor, in vec2 fragCoord ) {
    vec2 invRes = vec2(1.) / iResolution.xy;
    srand(ivec2(fragCoord), iFrame);

    // read data
    Data data = readData(iChannel1, invRes);
    if (iFrame == 0) data = initData();

    // setup ray
    vec2 uv = (fragCoord + vec2(frand(), frand())-.5) * invRes;
    vec3 ro = data.ro;
    vec2 v = uv*2.-1.;
    v.x *= iResolution.x * invRes.y;
    vec3 rd = lookat(data.ro, data.ta) * normalize(vec3(v,FOCAL_LENGTH));

    // pathtrace
    vec4 col = pathtrace(ro, rd);

    // fog
    col.rgb = mix(col.rgb, skyColor(rd,sundir), 1.-exp(-col.a*0.001));


    fragColor = vec4(min(col.rgb, 10.), col.a > 1000. ? -1. : col.a);
}

// ---------------------------------------------
// - Camera/data IO + Frames accumulation
//
//
// MODE 0 - Raw frame
// MODE 1 - Accumulate frames
// MODE 2 - Temporal reprojection
// ---------------------------------------------
#define MODE 1


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec3 seed = hash3(vec3(fragCoord.xy, float((iFrame+1) % 10000)));
    vec2 invRes = vec2(1.) / iResolution.xy;
    vec2 uv = (fragCoord + seed.xy-.5) * invRes;

    // read input buffer
    vec2 rawUv = fragCoord*invRes;
    vec4 rawCol = texture(iChannel1, rawUv);
    vec4 col = rawCol;

    // read data
    bool needRefresh = false;
    Data data = readData(iChannel0, invRes);
    if (iFrame == 0) data = initData();

    // camera
    if (iMouse.zw == data.oldMouse.zw) {
        data.theta += (data.oldMouse.x - iMouse.x)  * CAMERA_SENSITIVTY;
        data.phi += (data.oldMouse.y - iMouse.y)  * CAMERA_SENSITIVTY;
        if (texelFetch( iChannel2, ivec2(87,0), 0 ).x > 0.) { // w
            data.r *= 1.-CAMERA_SENSITIVTY;
            needRefresh = true;
        }
        if (texelFetch( iChannel2, ivec2(83,0), 0 ).x > 0.) { // s
            data.r *= 1.+CAMERA_SENSITIVTY;
            needRefresh = true;
        }
        if (texelFetch( iChannel2, ivec2(32,0), 0 ).x > 0.) { // space
            needRefresh = true;
        }
        if (iMouse.z > .5)
            needRefresh = true;
    }
    data.phi = clamp(data.phi, 0.01, 3.);

    data.ro = normalize(vec3(cos(data.theta), data.phi, sin(data.theta)))*data.r;
    data.ta = vec3(0.,0.5,0.);


    // MODE 1 - accumulate frame
    #if MODE == 1
    vec4 lastCol = texture(iChannel0, fragCoord*invRes);
    if (!needRefresh) {
        float w = 1. / (float(iFrame)-data.refreshTime + 1.);
        col = lastCol*(1.-w) + col * w;
    }
    else {
        data.refreshTime = float(iFrame);
    }
    #endif

    // MODE 2 - temporal reprojection
    #if MODE == 2
    if (col.a > 0.) {
        // reconstruct world space position
        vec3 ro = data.ro;
        vec2 v = uv*2.-1.;
        v.x *= iResolution.x * invRes.y;
        vec3 rd = lookat(data.ro, data.ta) * normalize(vec3(v,FOCAL_LENGTH));
        float t = rawCol.a;
        vec3 p = ro + rd * t;

        // reprojection
        mat3 oldCam = lookat(data.oldRo, data.oldTa);
        mat3x4 invOldCam = mat3x4( vec4( oldCam[0], -dot(oldCam[0],data.oldRo) ),
                                   vec4( oldCam[1], -dot(oldCam[1],data.oldRo) ),
                                   vec4( oldCam[2], -dot(oldCam[2],data.oldRo) ));
        vec4 wpos = vec4(p,1.0);
        vec3 cpos = wpos*invOldCam;
        vec2 npos = FOCAL_LENGTH*cpos.xy/cpos.z;
        vec2 spos = 0.5 + 0.5*npos*vec2(iResolution.y/iResolution.x,1.0) - (seed.xy-.5)*invRes;
        vec2 rpos = spos * iResolution.xy;
        vec4 lastCol = texture(iChannel0, spos);

        float w = .0;
        vec3 oldRd = lookat(data.oldRo, data.oldTa) * normalize(vec3(v,FOCAL_LENGTH));
        vec3 oldwp = data.oldRo + oldRd * lastCol.w;

        // depth rejection
        for(int x=-1; x<=1; x++){
            for(int y=-1; y<=1; y++){
                float lastT = texture(iChannel0, spos + vec2(x, y) * invRes).a;
                w = max(w, smoothstep(t*t*.005,0.,abs(t-lastT)));
            }
        }
        w -= 0.02;

        // color clamping
        #if 1
        const int kernelSize = 2;
        vec3 minCol = vec3(99999.);
        vec3 maxCol = vec3(0.);
        for(int x=-kernelSize; x<=kernelSize; x++){
            for(int y=-kernelSize; y<=kernelSize; y++){
                vec4 c = texture(iChannel1, spos + vec2(x, y) * invRes);
                c.rgb = RGBToYCoCg(c.rgb);
                minCol = min(minCol, c.rgb);
                maxCol = max(maxCol, c.rgb);
            }
        }
        lastCol.rgb = RGBToYCoCg(lastCol.rgb);
        lastCol.rgb = clamp(lastCol.rgb, minCol, maxCol);
        lastCol.rgb = YCoCgToRGB(lastCol.rgb);
        #endif

        //w = 0.99;
        if (rpos.x < 7. && rpos.y < 1.) w = 0.;
        if (abs(spos.x-.5) > .5) w = 0.;
        if (abs(spos.y-.5) > .5) w = 0.;

        if (iFrame > 1)
            col = mix(col, lastCol, saturate(w));
    }
    #endif


    // write data
    data.oldRo = data.ro;
    data.oldTa = data.oldTa;
    data.oldMouse = iMouse;
    if (fragCoord.y < 1.)
    col = writeData(col, fragCoord, data);

    // output pixel color
    fragColor = col;
}

#define INFINITY 9999999.0
#define PI 3.141592653589
#define NUM_SAMPLES 32
#define NUM_BOUNCES 3

float light_size;
float light_area;
//vec3 light_position = vec3(0, 0.97, 0);
vec3 light_position;
vec3 light_normal;
int seed;
vec4 light_albedo;
int flat_idx;



vec2
sample_disk(vec2 uv)
{
	float theta = 2.0 * 3.141592653589 * uv.x;
	float r = sqrt(uv.y);
	return vec2(cos(theta), sin(theta)) * r;
}

vec3
sample_cos_hemisphere(vec2 uv)
{
	vec2 disk = sample_disk(uv);
	return vec3(disk.x, sqrt(max(0.0, 1.0 - dot(disk, disk))), disk.y);
}

mat3
construct_ONB_frisvad(vec3 normal)
{
	mat3 ret;
	ret[1] = normal;
	if(normal.z < -0.999805696) {
		ret[0] = vec3(0.0, -1.0, 0.0);
		ret[2] = vec3(-1.0, 0.0, 0.0);
	}
	else {
		float a = 1.0 / (1.0 + normal.z);
		float b = -normal.x * normal.y * a;
		ret[0] = vec3(1.0 - normal.x * normal.x * a, b, -normal.x);
		ret[2] = vec3(b, 1.0 - normal.y * normal.y * a, -normal.y);
	}
	return ret;
}

void
encrypt_tea(inout uvec2 arg)
{
	uvec4 key = uvec4(0xa341316c, 0xc8013ea4, 0xad90777d, 0x7e95761e);
	uint v0 = arg[0], v1 = arg[1];
	uint sum = 0u;
	uint delta = 0x9e3779b9u;

	for(int i = 0; i < 32; i++) {
		sum += delta;
		v0 += ((v1 << 4) + key[0]) ^ (v1 + sum) ^ ((v1 >> 5) + key[1]);
		v1 += ((v0 << 4) + key[2]) ^ (v0 + sum) ^ ((v0 >> 5) + key[3]);
	}
	arg[0] = v0;
	arg[1] = v1;
}

vec2
get_random()
{
  	uvec2 arg = uvec2(flat_idx, seed++);
  	encrypt_tea(arg);
  	return fract(vec2(arg) / vec2(0xffffffffu));
}

struct Ray
{
	vec3 origin, dir;
};

struct AABB
{
	vec3 min_, max_;
};

mat4
rotate_y(float a)
{
	mat4 ret = mat4(1.0);
	ret[0][0] = ret[2][2] = cos(a);
	ret[0][2] = sin(a);
	ret[2][0] = -ret[0][2];
	return ret;
}

vec3
sample_light(vec2 rng)
{
	return light_position + vec3(rng.x - 0.5, 0, rng.y - 0.5) * light_size;
}

bool
intersect_aabb(in Ray ray, in AABB aabb, inout float t_min, inout float t_max)
{
	vec3 div = 1.0 / ray.dir;
	vec3 t_1 = (aabb.min_ - ray.origin) * div;
	vec3 t_2 = (aabb.max_ - ray.origin) * div;

	vec3 t_min2 = min(t_1, t_2);
	vec3 t_max2 = max(t_1, t_2);

	t_min = max(max(t_min2.x, t_min2.y), max(t_min2.z, t_min));
	t_max = min(min(t_max2.x, t_max2.y), min(t_max2.z, t_max));

	return t_min < t_max;
}

vec3
ray_at(in Ray ray, float t)
{
	return ray.origin + t * ray.dir;
}

float
intersect_plane(
	Ray ray,
    vec3 center,
    vec3 normal)
{
    float denom = dot(ray.dir, normal);
    float t = dot(center - ray.origin, normal) / denom;
	return t > 0.0 ? t : INFINITY;
}

float
intersect_box(Ray ray, out vec3 normal, vec3 size)
{
	float t_min = 0.0;
	float t_max = 999999999.0;
	if(intersect_aabb(ray, AABB(-size, size), t_min, t_max)) {
		vec3 p = ray_at(ray, t_min);
		p /= size;
		if(abs(p.x) > abs(p.y)) {
			if(abs(p.x) > abs(p.z)) {
				normal = vec3(p.x > 0.0 ? 1.0 : -1.0, 0, 0);
			}
			else {
				normal = vec3(0, 0, p.z > 0.0 ? 1.0 : -1.0);
			}
		}
		else if(abs(p.y) > abs(p.z)) {
			normal = vec3(0, p.y > 0.0 ? 1.0 : -1.0, 0);
		}
		else {
			normal = vec3(0, 0, p.z > 0.0 ? 1.0 : -1.0);
		}

		return t_min;
	}

	return INFINITY;
}

float
intersect_light(Ray ray)
{
	float t = intersect_plane(ray, light_position, light_normal);

	vec3 p = ray_at(ray, t);
	if(all(lessThan(abs(light_position - p).xz, vec2(light_size * 0.5)))) {
		return t;
	}

	return INFINITY;
}

float
intersect(Ray ray, inout vec3 p, inout vec3 normal, out vec4 albedo)
{
	float t_min = INFINITY;

	albedo = vec4(0.0);

	{
		float t = intersect_light(ray);
		if(t < t_min) {
			//albedo = vec3(100);
			albedo = light_albedo;
			//albedo = vec3(dot(ray.dir, light_normal) < 0.0 ? 1.0 : 0.0);
			normal = light_normal;
			t_min  = t;
			p = ray_at(ray, t);
		}
	}

	{
		vec3 normal_tmp;
		Ray ray_tmp = ray;
		//mat4 r = rotate_y(scene_time);
		mat4 r = rotate_y(0.3);
		ray_tmp.origin -= vec3(-0.35, -0.5, -0.35);
		ray_tmp.dir = vec3(r * vec4(ray_tmp.dir, 0));
		ray_tmp.origin = vec3(r * vec4(ray_tmp.origin, 1.0));
		float t = intersect_box(ray_tmp, normal_tmp, vec3(0.25, 0.5, 0.25));
		if(t < t_min) {
			t_min = t;
			p = ray_at(ray, t);
			albedo = vec4(0.7, 0.7, 0.7, 0);
			normal = vec3(transpose(r) * vec4(normal_tmp, 0.0));
		}
	}

	{
		vec3 normal_tmp;
		Ray ray_tmp = ray;
		ray_tmp.origin -= vec3(0.5, -0.75, 0.35);
		float t = intersect_box(ray_tmp, normal_tmp, vec3(0.25, 0.25, 0.25));
		if(t < t_min) {
			t_min = t;
			p = ray_at(ray, t);
			albedo = vec4(0.7, 0.7, 0.7, 0);
			normal = normal_tmp;
		}
	}

	// left
	{
		vec3 n = vec3(1, 0, 0);
		float t = intersect_plane(ray, vec3(-1, 0, 0), n);
		if(t < t_min) {
			vec3 p_tmp = ray_at(ray, t);
			if(all(lessThanEqual(p_tmp.yz, vec2(1))) && all(greaterThanEqual(p_tmp.yz,
							vec2(-1))))
			{
				normal = n;
				p = p_tmp;

				t_min = t;

				albedo = vec4(0.9, 0.1, 0.1, 0);
			}
		}
	}
	// right
	{
		vec3 n = vec3(-1, 0, 0);
		float t = intersect_plane(ray, vec3(1, 0, 0), n);
		if(t < t_min) {
			vec3 p_tmp = ray_at(ray, t);
			if(all(lessThanEqual(p_tmp.yz, vec2(1))) && all(greaterThanEqual(p_tmp.yz,
							vec2(-1))))
			{
				normal = n;
				p = p_tmp;

				t_min = t;

				albedo = vec4(0.1, 0.9, 0.1, 0);
			}
		}
	}
	// floor
	{
		vec3 n = vec3(0, 1, 0);
		float t = intersect_plane(ray, vec3(0, -1, 0), n);
		if(t < t_min) {
			vec3 p_tmp = ray_at(ray, t);
			if(all(lessThan(p_tmp.xz, vec2(1))) && all(greaterThan(p_tmp.xz,
							vec2(-1))))
			{
				normal = n;
				p = p_tmp;
				albedo = vec4(0.7, 0.7, 0.7, 0);

				t_min = t;
			}
		}
	}
	// ceiling
	{
		vec3 n = vec3(0, -1, 0);
		float t = intersect_plane(ray, vec3(0, 1, 0), n);
		if(t < t_min) {
			vec3 p_tmp = ray_at(ray, t);
			if(all(lessThan(p_tmp.xz, vec2(1))) && all(greaterThan(p_tmp.xz,
							vec2(-1))))
			{
				normal = n;
				p = p_tmp;
				albedo = vec4(0.7, 0.7, 0.7, 0);

				t_min = t;
			}
		}
	}
	// back wall
	{
		vec3 n = vec3(0, 0, 1);
		float t = intersect_plane(ray, vec3(0, 0, -1), n);
		if(t < t_min) {
			vec3 p_tmp = ray_at(ray, t);
			if(all(lessThan(p_tmp.xy, vec2(1))) && all(greaterThan(p_tmp.xy,
							vec2(-1))))
			{
				normal = n;
				p = p_tmp;
				albedo = vec4(0.7, 0.7, 0.7, 0);

				t_min = t;
			}
		}
	}


	normal = normalize(normal);

	return t_min;
}

bool
test_visibility(vec3 p1, vec3 p2)
{
	const float eps = 1e-5;

	Ray r = Ray(p1, normalize(p2 - p1));
	r.origin += eps * r.dir;

	vec3 n, p;
	vec4 a; // ignored
	float t_shadow = intersect(r, p, n, a);

	return t_shadow > distance(p1, p2) - 2.0 * eps;
}

vec3
pt_mis(Ray ray)
{
	vec3 contrib = vec3(0);
	vec3 tp = vec3(1.0);

	vec3 position, normal;
	vec4 albedo;
	float t = intersect(ray, position, normal, albedo);

	if(t == INFINITY)
		return vec3(0.0);

	if(albedo.a > 0.0) { /* hight light source */
		return albedo.rgb * albedo.a;
	}

	for(int i = 0; i < NUM_BOUNCES; i++) {
		mat3 onb = construct_ONB_frisvad(normal);

		{ /* NEE */
			vec3 pos_ls = sample_light(get_random());
			vec3 l_nee = pos_ls - position;
			float rr_nee = dot(l_nee, l_nee);
			l_nee /= sqrt(rr_nee);
			float G = max(0.0, dot(normal, l_nee)) * max(0.0, -dot(l_nee, light_normal)) / rr_nee;

			if(G > 0.0) {
				float light_pdf = 1.0 / (light_area * G);
				float brdf_pdf = 1.0 / PI;

				float w = light_pdf / (light_pdf + brdf_pdf);

				vec3 brdf = albedo.rgb / PI;

				if(test_visibility(position, pos_ls)) {
					vec3 Le = light_albedo.rgb * light_albedo.a;
					contrib += tp * (Le * w * brdf) / light_pdf;
				}
			}
		}

		{ /* brdf */
			vec3 dir = normalize(onb * sample_cos_hemisphere(get_random()));

			vec3 brdf = albedo.rgb / PI;

			Ray ray_next = Ray(position, dir);
			ray_next.origin += ray_next.dir * 1e-5;

			vec3 position_next, normal_next;
			vec4 albedo_next;
			float t = intersect(ray_next, position_next, normal_next, albedo_next);

			if(t == INFINITY)
				break;

			float brdf_pdf = 1.0 / PI;

			if(albedo_next.a > 0.0) { /* hit light_source */
				float G = max(0.0, dot(ray_next.dir, normal)) * max(0.0, -dot(ray_next.dir, normal_next)) / (t * t);
				if(G <= 0.0) /* hit back side of light source */
					break;

				float light_pdf = 1.0 / (light_area * G);

				float w = brdf_pdf / (light_pdf + brdf_pdf);

				vec3 Le = light_albedo.rgb * light_albedo.a;
				contrib += tp * (Le * w * brdf) / brdf_pdf;

				break;
			}

			tp *= brdf / brdf_pdf;

			position = position_next;
			normal = normal_next;
			albedo = albedo_next;
		}
	}

	return contrib;
}

void
mainImage(out vec4 fragColor, in vec2 fragCoord)
{
	light_size = 0.5;
	light_area = light_size * light_size;
	light_position = vec3(0.5 * sin(iTime), 0.90, 0.5 * cos(iTime));
	light_normal = vec3(0, -1, 0);
	seed = 0;
	light_albedo = vec4(1, 1, 1, 2.0 / (light_size * light_size));
	flat_idx = int(dot(gl_FragCoord.xy, vec2(1, 4096)));


	vec2 p = fragCoord.xy / vec2(iResolution) - vec2(0.5);
	float a = float(iResolution.x) / float(iResolution.y);
	if(a < 1.0)
		p.y /= a;
	else
		p.x *= a;

	vec3 cam_center = vec3(0, 0, 3.125);

	vec3 s = vec3(0);
	for(int i = 0; i < NUM_SAMPLES; i++) {
		Ray ray;
		ray.origin = cam_center;
		vec2 r = get_random();
		vec3 ray_dir = normalize(vec3(p + r.x * dFdx(p) + r.y * dFdy(p), -1));
		ray.dir = ray_dir;
		vec3 c = pt_mis(ray);
		s += c;
	}

	fragColor = vec4(pow(s / float(NUM_SAMPLES), vec3(1.0 / 2.2)), 1.0);
}

// Exponential smooth min from IQ
float smin( float a, float b, float k )
{
    k *= 1.0;
    float r = exp2(-a/k) + exp2(-b/k);
    return -k*log2(r);
}

// Signed distance to segment from IQ
float sdSegment( in vec2 p, in vec2 a, in vec2 b )
{
    vec2 pa = p-a, ba = b-a;
    float h = clamp( dot(pa,ba)/dot(ba,ba), 0.0, 1.0 );
    return length( pa - ba*h )+.1;
}

// Noise texture with higher-order interpolation
float smoothNoise(sampler2D t,vec2 uv)
{
    uv *= 256.;

    vec2 f = vec2(smoothstep(0., 1., fract(uv.x)),
                  smoothstep(0., 1., fract(uv.y)));

    float a = textureLod(t, (floor(uv) + vec2(0, 0) + .5) / 256., 0.).r;
    float b = textureLod(t, (floor(uv) + vec2(1, 0) + .5) / 256., 0.).r;
    float c = textureLod(t, (floor(uv) + vec2(0, 1) + .5) / 256., 0.).r;
    float d = textureLod(t, (floor(uv) + vec2(1, 1) + .5) / 256., 0.).r;

    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

// Heightmap for a single cell
float cellHeight(vec2 uv, vec2 cell, float scale)
{
    uv = fract(uv) * 2. - 1.;

    vec2 absUv = abs(uv);
    vec2 pointOnEdge = uv / max(absUv.x, absUv.y) + cell;

    float d = smin(sdSegment(absUv, vec2(1, 1), vec2( 1, -1)),
                   sdSegment(absUv, vec2(1, 1), vec2(-1,  1)), 1. / 16.);

    float d2 = pow(d, .6);

    float h = pow(smoothstep(.1, 1., d2), .6);

    h += smoothNoise(iChannel0, mix(uv, pointOnEdge / (5. * scale), .9) / 4.) *
                                      exp(-d * 8.) * pow(scale, .5) / 6.;

    return h / 12.;
}

// Heightmap for the whole surface
float surfaceHeight(vec2 uv, vec2 cell)
{
    uv *= .5;

    // Procedural quadtree-style subdivision
    float scale = 1.;
    vec2 offset = vec2(0);
    for(int i = 0; i < 2; ++i)
    {
        float a = textureLod(iChannel0, (floor(uv) + .5 + offset) / 8., 0.).r;
        if(a < .5)
            break;
        if(fract(uv.x * scale) > .5)
            offset.x += .5 / scale;
        if(fract(uv.y * scale)>.5)
            offset.y += .5 / scale;
        scale *= 2.;
    }

    cell += offset * scale * 2.;

    return cellHeight(uv * scale, cell, scale) / scale * 2.;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (fragCoord - iResolution.xy * 0.5) / iResolution.y * 2.0;
    vec2 uv2 = uv;

    // Rotation
    float a = .2 + iTime / 64.;
    uv *= mat2(cos(a), sin(a), -sin(a), cos(a));

    // Ray direction
    vec3 r = normalize(vec3(uv, -1));

    // Translation
    uv *= 2.;
    uv += iTime / 6.;

    vec2 cell = floor(uv * .5) * 2.;

    // Get surface normal from heightmap
    const float eps = 1. / 64.;
    float h0 = surfaceHeight(uv, cell);
    float h1 = surfaceHeight(uv + vec2(eps, 0.), cell);
    float h2 = surfaceHeight(uv + vec2(0., eps), cell);

    vec3 n = normalize(cross(vec3(vec2(eps, 0.), h1 - h0), vec3(vec2(0., eps), h2 - h0)));

    vec3 col = vec3(0);
    vec3 refl = reflect(r,n);

    // Specular highlights
    col += vec3(pow(max(0., dot(refl, normalize(vec3(1)))), 32.)) * 4. * vec3(1, 1, .75);
    col += vec3(pow(max(0., dot(refl, normalize(vec3(0, -.2, 1)))), 16.));
    col += vec3(pow(max(0., dot(refl, normalize(vec3(-1, 0, .5)))), 32.)) / 2. * vec3(1, .7, .7);

    // Environment light
    col += (cos(refl.x * 10.) * .5 + .5) / 32. * vec3(.75, .6, 1.);

    // Post-processing and output
    col *= 1. - smoothstep(0., 3., length(uv2));
    col += 1. / 210.;
    col *= 2.;
    col /= (col + 1.) * .85;

    fragColor = vec4(sqrt(max(col, 0.) * 1.05), 1.) +
                texelFetch(iChannel1, ivec2(fragCoord) & 1023,0).r / 256.;
}

/*

    Physically based rendering with direct and image based lighting.

    Always nice to see it be useful.
    Leave a comment if this was linked to from somewhere.

    Changing the cubemap in BufferB will propagate the new data to other tabs and trigger
    a re-render. Changing the resolution will use the existing data textures scaled to the
    new viewport. Because we use a texture atlas in BufferC, seam artifacts can appear.

    Edit 1: Added anisotropic BRDF and trick for IBL

    Edit 2: Added environment map filtering option ENV_FILTERING. Disabled by default.

    Edit 3: Fix missing /PI scaling for diffuse irradiance

    Edit 4: Some notes on spherical harmonics and changes to environment filtering

    Edit 5: Added a source discussing the details of spherical harmonics calculation

    Edit 6: Cleaned up specular sampling, corrected IBL calculation, added multiple scattering

    Based on:
    https://learnopengl.com/PBR/Theory
    https://google.github.io/filament/Filament.html
    https://cseweb.ucsd.edu/~ravir/papers/envmap/envmap.pdf

    https://www.shadertoy.com/view/ld3SRr
    https://www.shadertoy.com/view/ls3Szr
    https://www.shadertoy.com/view/lscBW4

    BufferA: Input and resolution change
    BufferB: Diffuse IBL with spherical harmonics
    BufferC: Specular IBL with prefiltered and BRDF integration maps

    BufferB also stores an equirectangular projection of the cubemap it loads. This is used
    as input for BufferC and also as the environment map for Image. This allows us to rerender
    the scene by changing just one iChannel input in BufferB.

    BufferC creates 5 prefiltered environment maps of decreasing resolution for various 
    roughness values. These are interpolated between to get the correct specular reflection
    on the spheres. BufferC also creates a two channel BRDF integration map needed for the 
    split-sum IBL.

*/

//  ----------------------- Uncomment to view buffer outputs -----------------------


// Use the matrices from BufferB to replace the environment map
//#define DISPLAY_DIFFUSE_SH


// The equirectangular projection of the cubemap from BufferB
//#define DISPLAY_ENVIRONMENT_MAP


// Prefiltered maps and BRDF integration map from BufferC
//#define DISPLAY_SPECULAR_MAPS


//  --------------------------------------------------------------------------------


// ----- Toggle two point lights
#define LIGHTS

// ----- Move lights
//#define ANIMATE_LIGHTS

// ----- Tone map spheres
#define TONEMAPPING

// Multiplied by strength later
const vec3 lightColour = vec3(1.0);

// Normal mapping using triplanar texture mapping of iChannel3
const vec3 DETAIL_SCALE = vec3(0.05);
const vec3 BLENDING_SHARPNESS = vec3(2.0);
const float DETAIL_HEIGHT = 0.05;

// ----- TODO: Physically based camera and light sources
// Shadertoy cubemaps are not HDR and diffuse irradiance can seem quite dull.
// We can artificially increase the strength of the image radiance in BufferB
const float AMBIENT_STRENGTH = 1.0;
const float EXPOSURE = 1.0;

const float SHADOW_SHARPNESS = 8.0;

// Raymaching of scene geometry
const float EPSILON = 1e-3;
const float MIN_DIST = 0.01;
const int MAX_STEPS = 128;
const float MAX_DIST = 100.0;

// Sphere size
float radius = 3.0;

// Sphere positioning in capped domain repetition
const float CELL = 10.0;
const float HALF_CELL = 0.5 * CELL;

//-------------------------- Camera ---------------------------

vec3 rayDirection(float fieldOfView, vec2 fragCoord) {
    vec2 xy = fragCoord - iResolution.xy / 2.0;
    float z = (0.5 * iResolution.y) / tan(radians(fieldOfView) / 2.0);
    return normalize(vec3(xy, -z));
}

// https://www.geertarien.com/blog/2017/07/30/breakdown-of-the-lookAt-function-in-OpenGL/
mat3 lookAt(vec3 camera, vec3 at, vec3 up){
  vec3 zaxis = normalize(at-camera);    
  vec3 xaxis = normalize(cross(zaxis, up));
  vec3 yaxis = cross(xaxis, zaxis);

  return mat3(xaxis, yaxis, -zaxis);
}


//-------------------------- Geometry -------------------------

float sphereSDF(vec3 p, float radius) {
    return length(p) - radius;
}

vec3 getLightPosition(int i){

    #ifdef ANIMATE_LIGHTS
        float offset = 2.8+0.45*iTime;
    #else
        float offset = 2.8;
    #endif

    if(i == 0){
        return vec3(30.0*cos(offset), 4.0, 30.0*sin(offset)); 
    }
    return vec3(-2.0*cos(2.0*offset), 12.0,  -2.0*sin(2.0*offset));
}

float getLightSDF(vec3 p){
    float d = MAX_DIST;
    d = min(MAX_DIST, sphereSDF(p-getLightPosition(0), 0.2));
    d = min(d, sphereSDF(p-getLightPosition(1), 0.2));
    return d;
}

float getSDF(vec3 p){

    vec3 l = vec3(1,0,1);
    return sphereSDF(p-CELL*clamp(round(p/CELL),-l,l), radius);
}

float distanceToScene(vec3 cameraPos, vec3 rayDir, float start, float end, bool scene) {

    float depth = start;

    float dist;

    for (int i = 0; i < MAX_STEPS; i++){

        if(scene){
            dist = getSDF(cameraPos + depth * rayDir);
        }else{
            dist = getLightSDF(cameraPos + depth * rayDir);
        }

        if (dist < EPSILON){ return depth; }

        depth += dist;

        if (depth >= end){ return end; }
    }

    return depth;
}

// Tetrahedral normal technique with a loop to avoid inlining getSDF()
// This should improve compilation times
// https://iquilezles.org/articles/normalsSDF
vec3 getNormal(vec3 p){
    vec3 n = vec3(0.0);
    int id;
    for(int i = ZERO; i < 4; i++){
        vec3 e = 0.5773*(2.0*vec3((((i+3)>>1)&1),((i>>1)&1),(i&1))-1.0);
        n += e*getSDF(p+e*EPSILON);
    }
    return normalize(n);
}

vec3 getTriplanar(vec3 position, vec3 normal){
    vec3 xaxis = texture(iChannel3, DETAIL_SCALE.x*(position.zy)).rgb;
    vec3 yaxis = texture(iChannel3, DETAIL_SCALE.y*(position.zx)).rgb;
    vec3 zaxis = texture(iChannel3, DETAIL_SCALE.z*(position.xy)).rgb;

    vec3 blending = abs(normal);
	blending = normalize(max(blending, 0.00001));
    blending = pow(blending, BLENDING_SHARPNESS);
	float b = (blending.x + blending.y + blending.z);
	blending /= b;

    return	xaxis * blending.x + 
       		yaxis * blending.y + 
        	zaxis * blending.z;
}


// Return the position of p extruded in the normal direction by normal map
vec3 getDetailExtrusion(vec3 p, vec3 normal, vec3 idx){
    float m = 0.0;
    if(idx.x == 0.0){
        m = 1.0;
    }
    if(idx.x == 1.0){
        m = 0.2;
    }
    float detail = m * DETAIL_HEIGHT*length(getTriplanar(12.0*p, normal));
    return p + detail * normal;
}

// Return the normal direction after applying a normal map
vec3 getDetailNormal(vec3 p, vec3 normal, vec3 idx){
    vec3 tangent;
    vec3 bitangent;
    // Construct orthogonal directions tangent and bitangent to sample detail gradient in
    pixarONB(normal, tangent, bitangent);

    tangent = normalize(tangent);
    bitangent = normalize(bitangent);

    float EPS = 1e-3;
    vec3 delTangent = 	getDetailExtrusion(p + tangent * EPS, normal, idx) - 
        				getDetailExtrusion(p - tangent * EPS, normal, idx);

    vec3 delBitangent = getDetailExtrusion(p + bitangent * EPS, normal, idx) - 
        				getDetailExtrusion(p - bitangent * EPS, normal, idx);

    return normalize(cross(delTangent, delBitangent));
}

//---------------------------- Material ----------------------------

// The domain is repeated and clamped. Store the cell a point is in to vary sphere materials
vec3 getIndex(vec3 p){
    return 1.0 + floor((p+HALF_CELL) / CELL);
}

// Base colour for dielectrics. This is overwritten for metals.
vec3 getAlbedo(vec3 p, vec3 normal, vec3 idx){

    // Have a smooth white dielectric sphere to demonstrate diffuse IBL
    if(idx.x == 2.0 && idx.z == 2.0){
        return vec3(1);
    }

    // Green corner sphere
    if(idx.x == 0.0 && idx.z == 0.0){
        return vec3(0.0625, 0.375, 0.0625);
    }

    // Diffuse colour for mixed sphere
    if(idx.x == 0.0 && idx.z == 1.0){
        return vec3(0.0125, 0.2625, 0.3125);
    }

    // Sky blue
    if(idx.x == 0.0 && idx.z == 2.0){
        return vec3(0.1125, 0.4125, 1.0);
    }

    // Striped
    if(idx.x == 2.0 && idx.z == 1.0){
        return mix(vec3(0.0625), vec3(1.0, 0.8125, 0.125), 
            smoothstep(0.0, 0.2, sin(5.8*p.y + 5.8*p.z)));
    }

    // Orange.
    return vec3(0.875, 0.125, 0.0);
}

// Metalness is binary
float getMetalness(vec3 p, vec3 normal, vec3 idx){
    if(idx.x == 0.0 && idx.z == 1.0){
        // Have one sphere mixing metal and dielectric based on texture
        return length(getTriplanar(12.0*p, normal)) > 0.4 ? 1.0 : 0.0;
    }else{
        // Middle row is metal
        return mod(idx.x, 2.0);
    }
}

float getRoughness(vec3 p, vec3 normal, float metalness, vec3 idx){
    float roughness = 0.0;
    if(idx.x == 0.0 && idx.z == 1.0){
        // Mixed sphere roughness depends on material
        roughness = metalness == 1.0 ?
            0.25*saturate(length(getTriplanar(1.0*p, normal)))
          : 0.5*length(getTriplanar(12.0*p, normal));
    }else if(idx.x == 1.0 && idx.z == 2.0){
        // Copper sphere roughness
        roughness = 0.3;
    }else{
        // Rougness gradient in z direction
        roughness = idx.z / 3.0;
    }

    // Stop roughness being 0 or 1
    return clamp(roughness, 0.05, 0.999);
}


//---------------------------- PBR ----------------------------

// Trowbridge-Reitz AKA GGX
float distribution(vec3 n, vec3 h, float roughness){
    float a_2 = roughness * roughness;
	return a_2/(PI * pow(pow(dot_c(n, h), 2.0) * (a_2 - 1.0) + 1.0, 2.0));
}

// Schlick-Beckmann
float geometry(float cosTheta, float k){
	return (cosTheta) / (cosTheta * (1.0 - k) + k);
}

float smiths(float NdotV, float NdotL, float roughness){
    float k = pow(roughness + 1.0, 2.0) / 8.0; 
	return geometry(NdotV, k) * geometry(NdotL, k);
}

// Anisotropic distribution and visibility functions from Filament
// GGX
float distributionAnisotropic(float NoH, vec3 h, vec3 t, vec3 b, float at, float ab) {
    float ToH = dot(t, h);
    float BoH = dot(b, h);
    float a2 = at * ab;
    vec3 v = vec3(ab * ToH, at * BoH, a2 * NoH);
    float v2 = dot(v, v);
    float w2 = a2 / v2;
    return a2 * w2 * w2 * (1.0 / PI);
}

// Smiths GGX correlated anisotropic
float smithsAnisotropic(float at, float ab, float ToV, float BoV,
                                       float ToL, float BoL, float NoV, float NoL) {
    float lambdaV = NoL * length(vec3(at * ToV, ab * BoV, NoV));
    float lambdaL = NoV * length(vec3(at * ToL, ab * BoL, NoL));
    float v = 0.5 / (lambdaV + lambdaL);
    return saturate(v);
}

// Fresnel-Schlick
vec3 fresnel(float cosTheta, vec3 F0){
    return F0 + (1.0 - F0) * pow(1.0 - cosTheta, 5.0);
} 

vec3 fresnelSchlickRoughness(float cosTheta, vec3 F0, float roughness){
    return F0 + (max(vec3(1.0-roughness), F0) - F0) * pow(1.0 - cosTheta, 5.0);
}

// Cook-Torrance BRDF
vec3 BRDF(vec3 p, vec3 n, vec3 viewDir, vec3 lightDir, vec3 albedo, float metalness, 
            float roughness, vec3 F0,
            vec3 tangent, vec3 bitangent, float anisotropy,
            vec3 energyCompensation){

    vec3 h = normalize(viewDir + lightDir);
    float cosTheta = dot_c(h, viewDir);

    // Lambertian diffuse reflectance
    vec3 diffuse = albedo / PI;

    // Normal distribution
    // What fraction of microfacets are aligned in the correct direction
    float D;

    // Fresnel term
    // How reflective are the microfacets viewed from the current angle
    vec3 F = fresnelSchlickRoughness(cosTheta, F0, roughness);

    // Geometry term
    // What fraction of the microfacets are lit and visible
    float G;

    // Visibility term. 
    // In Filament it combines the geometry term and the denominator
    float V;

    float NdotL = dot_c(lightDir, n);
    float NdotV = dot_c(viewDir, n);

    if(anisotropy == 0.0){

        D = distribution(n, h, roughness);
        G = smiths(NdotV, NdotL, roughness);
        V = G / max(0.0001, (4.0 * NdotV * NdotL));

    }else{

        float at = max(roughness * (1.0 + anisotropy), 0.001);
        float ab = max(roughness * (1.0 - anisotropy), 0.001);

        D = distributionAnisotropic(dot_c(n, h), h, tangent, bitangent, at, ab);

        V = smithsAnisotropic(at, ab, dot_c(tangent, viewDir), 
                                                     dot_c(bitangent, viewDir),
                                                     dot_c(tangent, lightDir), 
                                                     dot_c(bitangent, lightDir),
                                                     dot_c(n, viewDir), 
                                                     dot_c(n, lightDir));

    }

    // Specular reflectance
    vec3 specular = D * F * V;

    specular *= energyCompensation;

    // Combine diffuse and specular
    vec3 kD = (1.0 - F) * (1.0 - metalness);
    return kD * diffuse + specular;
}


//---------------------------- Shadows ----------------------------

// https://iquilezles.org/articles/rmshadows
float softShadow(vec3 pos, vec3 rayDir, float start, float end, float k ){
    float res = 1.0;
    float depth = start;
    for(int counter = ZERO; counter < MAX_STEPS; counter++){
        float dist = getSDF(pos + rayDir * depth);
        if( abs(dist) < EPSILON){ return 0.0; }       
        if( depth > end){ break; }
        res = min(res, k*dist/depth);
        depth += dist;
    }
    return res;
}


//------------------------------ IBL ------------------------------

// BufferB writes matrices of the spherical harmonics coefficients for red, green and blue.
// These can be used to get the channel value in a given direction
vec3 getSHIrradiance(vec3 normal){

    vec4 n = vec4(normal, 1.0);

    mat4 redMatrix = mat4(
        texelFetch(iChannel1, ivec2(0,0), 0),
        texelFetch(iChannel1, ivec2(0,1), 0),
        texelFetch(iChannel1, ivec2(0,2), 0),
        texelFetch(iChannel1, ivec2(0,3), 0));


    mat4 grnMatrix = mat4(
        texelFetch(iChannel1, ivec2(1,0), 0),
        texelFetch(iChannel1, ivec2(1,1), 0),
        texelFetch(iChannel1, ivec2(1,2), 0),
        texelFetch(iChannel1, ivec2(1,3), 0));


    mat4 bluMatrix = mat4(
        texelFetch(iChannel1, ivec2(2,0), 0),
        texelFetch(iChannel1, ivec2(2,1), 0),
        texelFetch(iChannel1, ivec2(2,2), 0),
        texelFetch(iChannel1, ivec2(2,3), 0));

    float r = dot(n, redMatrix * n);
    float g = dot(n, grnMatrix * n);
    float b = dot(n, bluMatrix * n);

    return vec3(r, g, b);
}

// Get the environment colour from the equirectangular projection of the cubemap from bufferB
// Clamp texture coordinates to reduce the seam artifact
vec3 getEnvironment(vec3 rayDir, vec2 scaleSize){
    vec2 texCoord = vec2((atan(rayDir.z, rayDir.x) / TWO_PI) + 0.5, acos(rayDir.y) / PI);
    texCoord.x = clamp(texCoord.x, 1.e-3, 0.999);
    texCoord *= scaleSize;
    return texture(iChannel1, texCoord).rgb;
}

// https://google.github.io/filament/Filament.md.html#lighting/imagebasedlights/anisotropy
vec3 getReflectedVector(vec3 v, vec3 n, vec3 t, vec3 b, float roughness, float anisotropy) {
    vec3  anisotropyDirection = anisotropy >= 0.0 ? b : t;
    vec3  anisotropicTangent  = cross(anisotropyDirection, -v);
    vec3  anisotropicNormal   = cross(anisotropicTangent, anisotropyDirection);
    vec3  bentNormal          = normalize(mix(n, anisotropicNormal, abs(anisotropy)));

    return reflect(v, bentNormal);
}

// Get two prefiltered roughness environment maps and linearly interpolate
// between them to get the roughness data needed.
vec3 getEnvironment(vec3 rayDir, float roughness, vec2 scaleSize){

    // There are 5 levels of roughness (0.0, 0.25, 0.5, 0.75, 1.0)
    float level1 = floor(1.0+(roughness) * 5.0);

    // Level 0 would give us the entire atlas
    level1 = max(1.0, level1);

    float level2 = level1 + 1.0;
    level2 = min(level2, 5.0);

    // The dimensions of the projection tile as a fraction of the viewport.
    float size1 = 1.0/pow(2.0, level1);
    float size2 = 1.0/pow(2.0, level2);

    // The offset in the x direction. y offset is always 0
    float offset1 = 0.0;
    float i;
    // The offset of the tile in the atlas is the sum of tiles before it (1/2 + 1/4 + ...)
    for(i = 1.0; i < level1; i++){
    	offset1 += 1.0/pow(2.0, i);
    }

    float offset2 = offset1 + 1.0/pow(2.0, i);

    vec2 texCoord1 = vec2((atan(rayDir.z, rayDir.x) / TWO_PI) + 0.5, acos(rayDir.y) / PI);

    vec2 texCoord2 = vec2((atan(rayDir.z, rayDir.x) / TWO_PI) + 0.5, acos(rayDir.y) / PI);

    float f = fract(roughness * 5.0);


    // Clamp texture coordinates to reduce the seam artifact. Depends on level.
    texCoord1.x = clamp(texCoord1.x, 0.0 + level1 * 0.005, 1.0 - level1 * 0.005);
    texCoord2.x = clamp(texCoord2.x, 0.0 + level2 * 0.005, 1.0 - level2 * 0.005);


    // Scale and offset to correct atlas tile
    texCoord1 = vec2(offset1, 0.0) + size1 * texCoord1;
    texCoord2 = vec2(offset2, 0.0) + size2 * texCoord2;

    // When changing to fullscreen, the atlas is not rerendered. 
    // Find the scaled relative coordinates
    texCoord1 *= scaleSize;
    texCoord2 *= scaleSize;

    return mix(texture(iChannel2, texCoord1).rgb, texture(iChannel2, texCoord2).rgb, f);
}

vec2 getBRDFIntegrationMap(vec2 coord, vec2 scaleSize){
    // Avoid reading outside the tile in the atlas
    coord = clamp(coord, 1e-5, 0.99);
    vec2 texCoord = vec2(coord.x/2.0, coord.y / 2.0 + 0.5);
    texCoord *= scaleSize;
    return texture(iChannel2, texCoord).rg;
}


//---------------------------- Lighting ----------------------------

vec3 getIrradiance(vec3 p, vec3 rayDir, vec3 geoNormal, vec3 idx, vec2 scaleSize){
    vec3 I = vec3(0);
    vec3 radiance = vec3(0);
    vec3 lightDir = vec3(0);
    vec3 vectorToLight = vec3(0);

    vec3 n = getDetailNormal(p, geoNormal, idx);
    vec3 albedo = getAlbedo(p, n, idx);
    float metalness = getMetalness(p, n, idx);
    float roughness = getRoughness(p, n, metalness, idx);

    // Index of refraction for common dielectrics. Corresponds to f0 4%
    float IOR = 1.5;

    // Reflectance of the surface when looking straight at it along the negative normal
    vec3 F0 = vec3(pow(IOR - 1.0, 2.0) / pow(IOR + 1.0, 2.0));

    float anisotropy = 0.0;

    // Metals tint specular reflections.
    // https://docs.unrealengine.com/en-US/RenderingAndGraphics/Materials/PhysicallyBased/index.html
    vec3 tintColour;
    if(idx.x == 1.0 && idx.z == 1.0){
        // Silver
        tintColour = vec3(0.972, 0.960, 0.915);
    }else if(idx.x == 1.0 && idx.z == 2.0){
        // Copper
        // Add darker circles
        float weight = length(getTriplanar(8.0*(p.xxx+p.yyy+p.zzz), geoNormal));
        tintColour = saturate(0.6 + max(0.2, weight)) * vec3(0.955, 0.637, 0.538);
        anisotropy = -0.5;
        // Remove normal mapping
        n = geoNormal;
    }else{
        // Gold
        // https://www.youtube.com/watch?v=j-A0mwsJRmk&ab_channel=ACMSIGGRAPH
        tintColour = vec3(1.022, 0.782, 0.344);
    }

    F0 = mix(F0, tintColour, metalness);

    vec2 envBRDF = getBRDFIntegrationMap(vec2(dot_c(n, -rayDir), roughness), scaleSize);
    // https://google.github.io/filament/Filament.html#materialsystem/improvingthebrdfs/energylossinspecularreflectance
    vec3 energyCompensation = 1.0 + F0 * (1.0 / envBRDF.y - 1.0);

    // Anisotropy directions
    vec3 tangent;
    vec3 bitangent;

    if(anisotropy != 0.0){

        //Normalise position
        vec3 pos = p - idx * vec3(CELL); 

        //Tangent and bitangent on a sphere have a nice solution given an orientation direction
        //https://computergraphics.stackexchange.com/questions/5498/compute-sphere-tangent-for-normal-mapping
        tangent = normalize(cross(vec3(1), pos));
        bitangent = normalize(cross(geoNormal, tangent));
    }

    // Find direct lighting for all sources

    #ifdef LIGHTS
    for(int i = ZERO; i < 2; i++){

        vec3 position = getLightPosition(i);
        vectorToLight = position-p;
        lightDir = normalize(vectorToLight);
        radiance = i == 0 ? 1.5 * lightColour : 1.0 * lightColour;

        float shadow = softShadow(p + n * EPSILON * 2.0, lightDir, MIN_DIST, length(vectorToLight), SHADOW_SHARPNESS);

        I +=  shadow 
            * BRDF(p, n, -rayDir, lightDir, albedo, metalness, roughness, F0, tangent, bitangent, anisotropy, energyCompensation) 
            * radiance 
            * dot_c(n, lightDir);
    }

    #endif

    // Find ambient diffuse IBL component

    vec3 F = fresnelSchlickRoughness(dot_c(n, -rayDir), F0, roughness);
	vec3 kD = (1.0 - F) * (1.0 - metalness);
	vec3 irradiance = AMBIENT_STRENGTH * getSHIrradiance(n);
	vec3 diffuse    = irradiance * albedo / PI;

    // Find ambient specular IBL component

    vec3 R;

    if(anisotropy == 0.0){
        R = reflect(rayDir, n);
    }else{      
        R = getReflectedVector(rayDir, n, tangent, bitangent, roughness, anisotropy);
    }

    vec3 prefilteredColor = getEnvironment(R, roughness, scaleSize);   
    vec3 specular = prefilteredColor * mix(envBRDF.xxx, envBRDF.yyy, F0);

    specular *= energyCompensation;

	vec3 ambient = kD * diffuse + specular;

    // Combine direct and IBL lighting
    return ambient + I;
}

// https://knarkowicz.wordpress.com/2016/01/06/aces-filmic-tone-mapping-curve/
vec3 ACESFilm(vec3 x){
    return clamp((x * (2.51 * x + 0.03)) / (x * (2.43 * x + 0.59) + 0.14), 0.0, 1.0);
}
void mainImage( out vec4 fragColor, in vec2 fragCoord ){

    // Read the size of the texture atlas and environment map
    vec2 atlasSize = texelFetch(iChannel2, ivec2(5.5), 0).rg;
    vec2 scaleSize = 1.0/(iResolution.xy/atlasSize);

    vec3 rayDir = rayDirection(60.0, fragCoord);

    //----------------- Define a camera -----------------

    vec3 cameraPos = texelFetch(iChannel0, ivec2(0.5, 1.5), 0).xyz;
    vec3 targetDir = -cameraPos;
    vec3 up = vec3(0.0, 1.0, 0.0);

    // Get the view matrix from the camera orientation
    mat3 viewMatrix = lookAt(cameraPos, targetDir, up);

    // Transform the ray to point in the correct direction
    rayDir = normalize(viewMatrix * rayDir);

    //---------------------------------------------------

    vec3 p;
    vec3 col;

    float distToLight = MAX_DIST;

    #ifdef LIGHTS
        distToLight = distanceToScene(cameraPos, rayDir, MIN_DIST, MAX_DIST, false);
    #endif
    float t = distanceToScene(cameraPos, rayDir, MIN_DIST, distToLight, true);

    if(t < MAX_DIST){
        p = cameraPos + rayDir * t;
        vec3 normal = getNormal(p);
        vec3 idx = getIndex(p);
        if(t == distToLight){
            col = lightColour;
        }else{
            col = EXPOSURE * getIrradiance(p, rayDir, normal, idx, scaleSize);
            #ifdef TONEMAPPING
                col = ACESFilm(col);
            #endif
        }
    } else {
        col = getEnvironment(rayDir, scaleSize);
        #ifdef DISPLAY_DIFFUSE_SH
            col = getSHIrradiance(rayDir);
        #endif
    }

    vec2 uv = fragCoord.xy/iResolution.xy;

    #ifdef DISPLAY_ENVIRONMENT_MAP
        col = texture(iChannel1, uv*scaleSize).rgb;
    #endif

    #ifdef DISPLAY_SPECULAR_MAPS
        col = texture(iChannel2, uv*scaleSize).rgb;
    #endif

    col = gamma(col);

    fragColor = vec4(col,1.0);
}

// Track mouse movement and resolution change between frames and set camera position.

#define CAMERA_DIST 20.0

void mainImage( out vec4 fragColor, in vec2 fragCoord ) {

    // Work with just the first four pixels.
    if((fragCoord.x == 0.5) && (fragCoord.y < 4.0)){

        vec4 oldData = texelFetch(iChannel0, ivec2(0.5), 0).xyzw;

        vec2 oldPolarAngles = oldData.xy;
        vec2 oldMouse = oldData.zw;

        vec2 polarAngles = vec2(0);
        vec2 mouse = iMouse.xy / iResolution.xy; 

        // Stop camera going directly above and below
        float angleEps = 0.01;

        float mouseDownLastFrame = texelFetch(iChannel0, ivec2(0.5, 3.5), 0).x;

        // If mouse button is down and was down last frame.
        if(iMouse.z > 0.0 && mouseDownLastFrame > 0.0){

            // Difference between mouse position last frame and now.
            vec2 mouseMove = mouse - oldMouse;
            polarAngles = oldPolarAngles + vec2(5.0, 3.0) * mouseMove;

        }else{
            polarAngles = oldPolarAngles;
        }

        polarAngles.x = modulo(polarAngles.x, 2.0 * PI - angleEps);
        polarAngles.y = min(PI - angleEps, max(angleEps, polarAngles.y));

        // Store mouse data in the first pixel of Buffer A.
        if(fragCoord == vec2(0.5, 0.5)){
            // Set value at first frames.
            if(iFrame < 10){
                polarAngles = vec2(PI / 4.0, 1.33);
                mouse = vec2(0);
            }
            fragColor = vec4(polarAngles, mouse);
        }

        // Store camera position in the second pixel of Buffer A.
        if(fragCoord == vec2(0.5, 1.5)){
            // Cartesian direction from polar coordinates.
            vec3 cameraPos = normalize(vec3(-cos(polarAngles.x) * sin(polarAngles.y), 
                                             cos(polarAngles.y), 
                                            -sin(polarAngles.x) * sin(polarAngles.y)));

            fragColor = vec4(CAMERA_DIST * cameraPos, 1.0);
        }

        // Store resolution change data in the third pixel of Buffer A.
        if(fragCoord == vec2(0.5, 2.5)){
            float resolutionChangeFlag = 0.0;
            // The resolution last frame.
            vec2 oldResolution = texelFetch(iChannel0, ivec2(0.5, 2.5), 0).yz;

            if(iResolution.xy != oldResolution){
            	resolutionChangeFlag = 1.0;
            }

        	fragColor = vec4(resolutionChangeFlag, iResolution.xy, 1.0);
        }

        // Store whether the mouse button is down in the fourth pixel of Buffer A
        if(fragCoord == vec2(0.5, 3.5)){
            if(iMouse.z > 0.0){
            	fragColor = vec4(vec3(1.0), 1.0);
            }else{
            	fragColor = vec4(vec3(0.0), 1.0);
            }
        }

    }
}

/*

    Diffuse IBL using spherical harmonics

    Read the environment map and calculate 9 spherical harmonics coefficients for each channel.
    The coefficients will describe the low frequency data of the environment. We can use them
    to construct a matrix which, when multiplied with a view vector, will give the data in 
    that direction. The low frequency data is similar to a convoluted irradiance map and is 
    used for diffuse image based lighting, which gives us the ambient colour for shading. 

    Based on:
    [1] https://cseweb.ucsd.edu/~ravir/papers/envmap/envmap.pdf
    [2] http://orlandoaguilar.github.io/sh/spherical/harmonics/irradiance/map/2017/02/12/SphericalHarmonics.html
    [3] https://metashapes.com/blog/realtime-image-based-lighting-using-spherical-harmonics/
    [4]	https://stackoverflow.com/questions/9600801/evenly-distributing-n-points-on-a-sphere/26127012#26127012
    [5] https://bduvenhage.me/geometry/2019/07/31/generating-equidistant-vectors.html
    [6] https://andrew-pham.blog/2019/08/26/spherical-harmonics/
    [7] http://www.cse.chalmers.se/~uffe/xjobb/Readings/GlobalIllumination/Spherical%20Harmonic%20Lighting%20-%20the%20gritty%20details.pdf

    This tab writes the matrix from equation 12 of [1] used in lighting calculations later.
    We also store an equirectangular projection of the environment map and track cubemap change.

    Notes:
    - Most implementations use coefficients instead of matrices. We are assuming that matrix 
      vector multiplication is more efficient on GPUs (also compacts the code)
    - Matrices need 16 * 3 floats for RGB whereas coefficients need 9 * 3
    - There is a proposed GLTF extension which would include SH coefficients
    - The matrices are symmetric, so column/row majority does not change the result

    - SH works well in environments where the light strength has a uniform distribution. In 
      scenes with a very strong light source (like the Sun in an HDR file) SH will produce 
      ringing. These artefacts are caused by the Gibbs phenomenon where the coefficents turn 
      negative. Visually this leads to dark rings and a bright spot opposite the strong light
      source. One fix is to use a windowing function but this increases the total brightness.
      Reading SH values from a lower MIP level (or convolved map) can blur the result and 
      reduce ringing (while also increasing total brightness). A pre-convolved 
      diffuse environment map can be used instead of SH.

      Alternatively spherical gaussians can be used instead of SH:
      https://therealmjp.github.io/posts/sg-series-part-5-approximating-radiance-and-irradiance-with-sgs/

*/

// Constants cn from equation 12 in [1]
const float c1 = 0.429043;
const float c2 = 0.511664;
const float c3 = 0.743125;
const float c4 = 0.886227;
const float c5 = 0.247708;

// First 9 spherical harmonics coefficients from equation 3 in [1]
const float Y00 = 0.282095;
const float Y1n = 0.488603; // 3 direction dependent values
const float Y2n = 1.092548; // 3 direction dependent values
const float Y20 = 0.315392;
const float Y22 = 0.546274;

vec3 getRadiance(vec3 dir){
    // Shadertoy textures are gamma corrected. Undo for lighting calculations.
    vec3 col = inv_gamma(texture(iChannel2, dir).rgb);
    // Add some bloom to the environment
    col += 0.5 * pow(col, vec3(2));
    return col;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord){

    vec3 currentColour = texture(iChannel2, vec3(1,1,1)).rgb;

    bool cubemapChangedFlag = texelFetch(iChannel1, ivec2(4.5, 4.5), 0).rgb != currentColour;
    //bool resolutionChanged = texelFetch(iChannel0, ivec2(0.5, 2.5), 0).r > 0.0;

    bool run = iFrame == 0 || cubemapChangedFlag;

    if(run){

        vec4 col = vec4(0);

        // Store an equirectangular projection of the environment map. Subsequent code will
        // overwrite specific pixels to store the SH matrices and state flags but this 
        // should not be visible in the final render.
        vec2 texCoord = fragCoord.xy / iResolution.xy;
        vec2 thetaphi = ((texCoord * 2.0) - vec2(1.0)) * vec2(PI, HALF_PI); 
        vec3 rayDir = vec3( cos(thetaphi.y) * cos(thetaphi.x), 
                           -sin(thetaphi.y), 
                            cos(thetaphi.y) * sin(thetaphi.x));

        col = vec4(getRadiance(rayDir), 1.0);
        // Ensure radiance is not 0
        col.x = max(col.x, 1e-5);
        col.y = max(col.y, 1e-5);
        col.z = max(col.z, 1e-5);


    //------------------------------------------------------------------------------------
    //----------------------------------- BUG? -------------------------------------------
    //------- It should be fragCoord.x < 3.0 because we write and read 3 matrices --------
    //------- But that will give the wrong result and I can't figure out why -------------
    //------------------------------------------------------------------------------------
    //------------------------------------------------------------------------------------

        if(fragCoord.x < 4.0 && fragCoord.y < 4.0){

            // Coefficient values to accumulate
            vec3 L00 = vec3(0);
            vec3 L1_1 = vec3(0);
            vec3 L10 = vec3(0);
            vec3 L11 = vec3(0);

            vec3 L2_2 = vec3(0);
            vec3 L2_1 = vec3(0);
            vec3 L20 = vec3(0);
            vec3 L21 = vec3(0);
            vec3 L22 = vec3(0);

            // To make the sampling rate scalable and independent of the cubemap dimensions, 
            // we can sample a set number of equidistant directions on a sphere. While this is 
            // not doable for all number of directions, a good approximation is the Fibonacci 
            // spiral on a sphere.

            // From [4]
            // Golden angle in radians
            float phi = PI * (3.0 - sqrt(5.0));

            // The loop should not run every frame but Windows FPS drops anyway. 
            // This seems to have fixed it
            float sampleCount;
            if(run){
                sampleCount = iResolution.x < 2000.0 ? SH_SAMPLE_COUNT : SH_LOW_SAMPLE_COUNT;
            }else{
                sampleCount = 1.0;
            }

            for(float i = float(ZERO); i < sampleCount; i++){

                float y = 1.0 - (i / sampleCount) * 2.0;
                // Radius at y
                float radius = sqrt(1.0 - y * y);  

                // Golden angle increment
                float theta = phi * i;

                float x = cos(theta) * radius;
                float z = sin(theta) * radius;

                // Sample direction
                vec3 dir = normalize(vec3(x, y, z));

                // Envronment map value in the direction (interpolated)
                vec3 radiance = getRadiance(dir);

                // Accumulate value weighted by spherical harmonic coefficient in the direction
                L00 += radiance * Y00;
                L1_1 += radiance * Y1n * dir.y;
                L10 += radiance * Y1n * dir.z;
                L11 += radiance * Y1n * dir.x;
                L2_2 += radiance * Y2n * dir.x * dir.y;
                L2_1 += radiance * Y2n * dir.y * dir.z;
                L20 += radiance * Y20 * (3.0 * pow(dir.z, 2.0) - 1.0);
                L21 += radiance * Y2n * dir.x * dir.z;
                L22 += radiance * Y22 * (pow(dir.x, 2.0) - pow(dir.y, 2.0));
            }

            // Scale the sum of coefficents on a sphere
            float factor = 4.0*PI / sampleCount;

            L00 *= factor;
            L1_1 *= factor;
            L10 *= factor;
            L11 *= factor;
            L2_2 *= factor;
            L2_1 *= factor;
            L20 *= factor;
            L21 *= factor;
            L22 *= factor;

            // Write three 4x4 matrices to bufferB
            // GLSL matrices are column major
            int idxM = int(fragCoord.y-0.5);

            if(fragCoord.x == 0.5){
                mat4 redMatrix;
                redMatrix[0] = vec4(c1*L22.r, c1*L2_2.r, c1*L21.r, c2*L11.r);
                redMatrix[1] = vec4(c1*L2_2.r, -c1*L22.r, c1*L2_1.r, c2*L1_1.r);
                redMatrix[2] = vec4(c1*L21.r, c1*L2_1.r, c3*L20.r, c2*L10.r);
                redMatrix[3] = vec4(c2*L11.r, c2*L1_1.r, c2*L10.r, c4*L00.r-c5*L20.r);
                col = redMatrix[idxM];
            }

            if(fragCoord.x == 1.5){
                mat4 grnMatrix;
                grnMatrix[0] = vec4(c1*L22.g, c1*L2_2.g, c1*L21.g, c2*L11.g);
                grnMatrix[1] = vec4(c1*L2_2.g, -c1*L22.g, c1*L2_1.g, c2*L1_1.g);
                grnMatrix[2] = vec4(c1*L21.g, c1*L2_1.g, c3*L20.g, c2*L10.g);
                grnMatrix[3] = vec4(c2*L11.g, c2*L1_1.g, c2*L10.g, c4*L00.g-c5*L20.g);
                col = grnMatrix[idxM];
            }

            if(fragCoord.x == 2.5){
                mat4 bluMatrix;
                bluMatrix[0] = vec4(c1*L22.b, c1*L2_2.b, c1*L21.b, c2*L11.b);
                bluMatrix[1] = vec4(c1*L2_2.b, -c1*L22.b, c1*L2_1.b, c2*L1_1.b);
                bluMatrix[2] = vec4(c1*L21.b, c1*L2_1.b, c3*L20.b, c2*L10.b);
                bluMatrix[3] = vec4(c2*L11.b, c2*L1_1.b, c2*L10.b, c4*L00.b-c5*L20.b);
                col = bluMatrix[idxM];
            }
        }

        // Store a sample colour of the cubemap to detect load and change
        if(fragCoord.x == 4.5 && fragCoord.y == 4.5){
              col = vec4(texture(iChannel2, vec3(1,1,1)).rgb, 1.0);
        }

        // Store the size of the render
        if(fragCoord.x == 5.5 && fragCoord.y == 5.5){
             col = vec4(iResolution.xy, 0.0, 1.0);
        }

        fragColor = col;
    }else{
        // Reuse data
        fragColor = texelFetch(iChannel1, ivec2(fragCoord.xy), 0);
    }
}

