vec3 disneySubSurfaceSample(out vec3 wi, const in vec3 wo, out float pdf, const in vec2 u, const in vec3 normal, const in MaterialInfo material) {

    cosineSample

    vec3 H = normalize(wo+wi);
    float NdotH = dot(normal,H);

