            isect = currentIsect;
            isect.material.albedo = vec3(1., 1., 1.);
            isect.material.emissive = vec3(0.);
        }
        currentIsect = intersectTriangle(ray, Triangle(v3, v2, v0));
        if (currentIsect.t > ray.tMin && currentIsect.t < isect.t) {
