        }
        currentIsect = intersectTriangle(ray, Triangle(v3, v2, v0));
        if (currentIsect.t > ray.tMin && currentIsect.t < isect.t) {
            isect = currentIsect;
            isect.material.albedo = vec3(0.7f, 0.1f, 0.1f);
            isect.material.emissive = vec3(0.);
        }
    }

    // right wall 
    {
        vec3 v0 = vec3( 12.5f, -12.6f, 25.0f);
        vec3 v1 = vec3( 12.5f, -12.6f, 15.0f);
        vec3 v2 = vec3( 12.5f,  12.6f, 15.0f);
        vec3 v3 = vec3( 12.5f,  12.6f, 25.0f);
        currentIsect = intersectTriangle(ray, Triangle(v0, v1, v2));
        if (currentIsect.t > ray.tMin && currentIsect.t < isect.t) {
            isect = currentIsect;
            isect.material.albedo = vec3(0.1f, 0.7f, 0.1f);
            isect.material.emissive = vec3(0.);
        }
        currentIsect = intersectTriangle(ray, Triangle(v3, v2, v0));
        if (currentIsect.t > ray.tMin && currentIsect.t < isect.t) {
            isect = currentIsect;
            isect.material.albedo = vec3(0.1f, 0.7f, 0.1f);
            isect.material.emissive = vec3(0.);
        }
    }


    return isect;

}

float fovToNearValue(float fovInEuler) {
    return 1. / tan(fovInEuler * 0.5f * PI / 180.f);        
}

vec4 miss() {
    return vec4(0.5f, 0.5f, 0.5f, 1.0f);
}

vec4 traceRay(Ray primaryRay, inout uint seed) {
    vec4 color = vec4(0.f, 0.f, 0.f, 1.f);
    vec3 lightIntensity = vec3(1.0f, 1.0f, 1.0f);
    Ray ray = primaryRay;

    for (int bounce = 0; bounce < BOUNCE_COUNT; ++bounce) {
        Intersection isect = intersect(ray);
        if (isect.t < ray.tMin || isect.t > ray.tMax) {
            if (bounce == 0)
                color = miss();
            break;
        }

        // light too weak, stop reflection
        if (lightIntensity.x < 0.001 && lightIntensity.y < 0.001 && lightIntensity.z < 0.001)
            break;

        // Create a secondary ray, bounced off of primary ray.
        ray.origin = ray.origin + isect.t * ray.direction + RAY_NORMAL_NUDGE * isect.normal;
        ray.direction = normalize(isect.normal + randomUnitVector(seed));

        color.xyz += isect.material.emissive * lightIntensity;
        lightIntensity *= isect.material.albedo;
    }

    return color;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // uv, in -1 ~ +1 on both axis
    vec2 uv = (fragCoord/iResolution.xy) * 2.f - 1.f;

    vec2 mouseUV = vec2(iMouse.x / iResolution.x, iMouse.y / iResolution.y);
    bool mouseDown = iMouse.z > 0.f;

    Camera camera;
    camera.pos = vec3(0.f, 0.0f, -5.f);
    camera.near = fovToNearValue(CAMERA_FOV);
    camera.aspectRatio = iResolution.x / iResolution.y;
    camera.samplePerPixel = CAMERA_SAMPLE_PER_PIXEL;
    camera.resolution = iResolution;

    uint seed = uint(uint(fragCoord.x) * uint(1973) + uint(fragCoord.y) * uint(9277) + uint(iFrame) * uint(26699)) | uint(1);

    vec4 color = vec4(0.);


#ifdef DEBUG_RAY_DIR
    Ray ray = raygen(uv, camera, seed);
    fragColor = vec4(ray.direction, 1.f);
#elif defined DEBUG_MOUSE
    fragColor = vec4(mouseUV, 0.f, 1.);
    if (mouseDown && uv.x < -0.9 && uv.y < -0.9f)
        fragColor = vec4(0.f, 0.f, 0.f, 1.f);
#elif defined DEBUG_RAND
    fragColor = vec4(randomUnitVector(seed), 1.f);
#else
    // Multisample (anti-aliasing)
    for (int s = 0; s < camera.samplePerPixel; ++s) {
        Ray ray = raygen(uv, camera, seed);
        color += traceRay(ray, seed) / float(camera.samplePerPixel);
    }

#ifdef TEMPORAL_ACCUM
    vec4 prev = texture(iChannel0, fragCoord / iResolution.xy);
    color = mix(prev, color, 1.0f / (float(iFrame) + 1.0f));
#endif

    fragColor = color;
#endif
}

// Fun with spherical lights, area shadows, occlusion and reflections.
// Sphere and trace functions by inigo quilez, https://iquilezles.org

#define BIAS 0.0001
#define PI 3.1415927
#define SEED 4.

float sphIntersect( in vec3 ro, in vec3 rd, in vec4 sph )
{
  vec3 oc = ro - sph.xyz;
  float b = dot( oc, rd );
  float c = dot( oc, oc ) - sph.w*sph.w;
  float h = b*b - c;
  if( h<0.0 ) return -1.0;
  return -b - sqrt( h );
}

float sphOcclusion( in vec3 pos, in vec3 nor, in vec4 sph )
{
    vec3  r = sph.xyz - pos;
    float l = length(r);
    float d = dot(nor,r);
    float res = d;

    if( d<sph.w ) res = pow(clamp((d+sph.w)/(2.0*sph.w),0.0,1.0),1.5)*sph.w;

    return clamp( res*(sph.w*sph.w)/(l*l*l), 0.0, 1.0 );

}

float sphAreaShadow( vec3 P, in vec4 L, vec4 sph )
{
  vec3 ld = L.xyz - P;
  vec3 oc = sph.xyz - P;
  float r = sph.w - BIAS;

  float d1 = sqrt(dot(ld, ld));
  float d2 = sqrt(dot(oc, oc));

  if (d1 - L.w / 2. < d2 - r) return 1.;

  float ls1 = L.w / d1;
  float ls2 = r / d2;

  float in1 = sqrt(1.0 - ls1 * ls1);
  float in2 = sqrt(1.0 - ls2 * ls2);

  if (in1 * d1 < in2 * d2) return 1.;

  vec3 v1 = ld / d1;
  vec3 v2 = oc / d2;
  float ilm = dot(v1, v2);

  if (ilm < in1 * in2 - ls1 * ls2) return 1.0;

  float g = length( cross(v1, v2) );

  float th = clamp((in2 - in1 * ilm) * (d1 / L.w) / g, -1.0, 1.0);
  float ph = clamp((in1 - in2 * ilm) * (d2 / r) / g, -1.0, 1.0);

  float sh = acos(th) - th * sqrt(1.0 - th * th) 
           + (acos(ph) - ph * sqrt(1.0 - ph * ph))
           * ilm * ls2 * ls2 / (ls1 * ls1);

  return 1.0 - sh / PI;
}


//-------------------------------------------------------------------------------------------
const int SPH = 27; //3x3x3

vec4 sphere[SPH];
vec4 L;

vec3 rand3( float x, float seed )
{ 
  float f = x+seed;
  return fract( PI*sin( vec3(f,f+5.33,f+7.7)) );
}

float areaShadow( in vec3 P )
{
  float s = 1.0;
  for( int i=0; i<SPH; i++ )
    s = min( s, sphAreaShadow(P, L, sphere[i] ) );
  return s;           
}

vec3 reflections( vec3 P, vec3 R, vec3 tint, int iid )
{
  float t = 1e20;

  vec3 s = vec3(R.y < 0. ? 1.-sqrt(-R.y/(P.y+1.)) : 1.); // P.y+1 floor pos
  for( int i=0; i<SPH; i++ )
  {    
    float h = sphIntersect( P, R, sphere[i] );
    if( h>0.0 && h<t )
    {
      s = i == iid ? tint * 2. : vec3(0.);
      t = h;
    }
  }     
  return max( vec3(0.), s);           
}

float occlusion( vec3 P, vec3 N )
{
  float s = 1.0;
  for( int i=0; i<SPH; i++ )
    s *= 1.0 - sphOcclusion( P, N, sphere[i] ); 
  return s;           
}

float sphLight( vec3 P, vec3 N, vec4 L)
{
  vec3 oc = L.xyz  - P;
  float dst = sqrt( dot( oc, oc ));
  vec3 dir = oc / dst;

  float c = dot( N, dir );
  float s = L.w  / dst;

  return max(0., c * s);
}

//-------------------------------------------------------------------------------------------

vec3 shade( vec3 I, vec3 P, vec3 N, float id, float iid )
{
  vec3 base = rand3( id, SEED );
  vec3 wash = mix( vec3(0.9), base, 0.4);
  vec3 hero = rand3( iid, SEED );

  vec3 ref = reflections( P, I - 2.*(dot(I,N))*N, hero, int(iid) );
  float occ = occlusion( P, N );
  float ocf = 1.-sqrt((0.5 + 0.5*-N.y)/(P.y+1.25))*.5; //floor occusion. 1.25 floor P.
  float fre = clamp( 1. + dot( I, N), 0., 1.); fre = (0.01+0.4*pow(fre,3.5));
  float lgh = sphLight( P, N, L) *  areaShadow( P );
  float inc = ( id == iid ? 1.0 : 0.0 );

  // Env light
  vec3 C = wash * occ * ocf * .2;

  // Sphere light
  C += ( inc + lgh * 1.3 ) * hero;

  // Reflections
  C = mix( C, ref, fre );

  return C;
}    

vec3 trace( vec3 E, vec3 I, vec3 C, float px, float iid )
{
  float t = 1e20;
  float id  = -1.0;
  vec4  obj = vec4(0.);
  for( int i=0; i<SPH; i++ )
  {
    vec4 sph = sphere[i];
    float h = sphIntersect( E, I, sph ); 
    if( h>0.0 && h<t ) 
    {
      t = h;
      obj = sph;
      id = float(i);
    }
  }

  if( id>-0.5 )
  {
    vec3 P = E + t*I;
    vec3 N = normalize(P-obj.xyz);
    C = shade( I, P, N, id, iid  );
  }

  return C;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 q = fragCoord.xy / iResolution.xy;
    vec2 p = (2.0*fragCoord.xy-iResolution.xy)/iResolution.y;
    vec2 m = step(0.0001,iMouse.z) * iMouse.xy/iResolution.xy;

    //-----------------------------------------------------

    float time = iTime;
    float an = 0.3*time - 7.0*m.x;
    float sec = mod(time,1.);

    float spI = floor(mod(time,float(SPH)));

    //-----------------------------------------------------
    for( int i=0; i<SPH; i++ )
    {
      float ra = 0.4;
      float id = float(i);
      sphere[i] = vec4( mod( id, 3.0) - 1.0,
                        mod( floor( id/3.0 ), 3.0 ) - .55,
                        floor( id/9.0 )-1.0, ra );

      if( i == int(spI) )
      {
        sphere[i].w += 0.025 * sin(sec*50.) / sqrt(sec) * ( 1.-sqrt(sec));
        L = sphere[i];
      }
    }

    //-----------------------------------------------------

    float fov = 1.8;
    vec3 E = vec3( 3.5*sin(an), 2.0, 3.5*cos(an));
    vec3 V = normalize( -E );
    vec3 uu = normalize( cross( V, vec3(0., 1., 0.)));
    vec3 vv = normalize( cross( uu, V));
    vec3 I = normalize( p.x*uu + p.y*vv + fov*V );

    float px = 1.0*(2.0/iResolution.y)*(1.0/fov);


    //-----------------------------------------------------

    vec3 C = vec3(1.);

    float tmin = 1e20;
    float t = -(1.0+E.y)/I.y;
    if( t>0.0 )
    {
        tmin = t;
        vec3 pos = E + t*I;
        vec3 nor = vec3(0.0,1.0,0.0);
        C = shade( I, pos, nor, -1.0, spI );
    }    

    C = trace( E, I, C, px, spI );

    // post
    C = pow( C, vec3(0.41545) );   
    C *= 0.5 + 0.5*pow(18.0*q.x*q.y*(1.0-q.x)*(1.0-q.y),0.12);

    fragColor = vec4( C, 1. );
}

vec2 mainSound( in int samp,float time)
{
	float sec = mod(time,1.);
    float ech = mod(time,.2);
    float sph = floor( mod(time,27.));
    float rnd = fract( 876.432 * sin( sph ) ) + 5.;
    float hum = sin(400.0*time) * sin(8.0*time) * 0.2;
    float bel = sin(rnd*340.0*sec)*exp(-4.0*sec)*exp(-4.0*ech)*.5;
    return vec2( hum + bel );
}

