float map(vec3 p)
{
    return distance(p, vec3(0,0,4)) - 1.0;
}

vec3 get_normal(vec3 p)
{
    vec2 e = vec2(1.0,-1.0)*0.5773*0.0005;
    return normalize(e.xyy*map(p + e.xyy) + 
					 e.yyx*map(p + e.yyx) + 
					 e.yxy*map(p + e.yxy) + 
					 e.xxx*map(p + e.xxx));
}

struct Ray
{
    vec3 origin;
    vec3 dir;
