Ray camera_ray(vec2 uv, float fov)
{
    uv = uv * 2.0 - 1.0;
    uv.x *= iResolution.x / iResolution.y;    
    uv *= tan(radians(fov) * 0.5);

    Ray ray;
    ray.origin = vec3(0);
    ray.dir = normalize(vec3(uv, 1));
    return ray;    
}


void trace_scene(inout Ray ray)
