void mainImage( out vec4 o, in vec2 vpos )
{
    vec2 uv = vpos/iResolution.xy;    
    Ray camera = camera_ray(uv, 40.0);

    trace_scene(camera);
    vec3 hit = camera.origin + camera.dir * camera.t;
    vec3 normal = get_normal(hit);

    o = texture(iChannel1, camera.dir);
    if(camera.t > 10.0 || dot(normal, camera.dir) > 0.0) return;

    uvec2 seed;
    seed = uvec2(texelFetch(iChannel0, ivec2(vpos) & 1023, 0).xy * exp2(32.0)); 

    if(uv.x > 0.5)
    {
        o.rgb = spherical_cap_new_vndf(normal, camera.dir, seed); 
    }
    else 
    {
        o.rgb = canonical_vndf_heitz(normal, camera.dir, seed); 
    }    

    o.rgb *= 30.0;
    o.rgb = o.rgb * ACESInputMat;
    o.rgb = RRTAndODTFit(o.rgb);
    o.rgb = o.rgb * ACESOutputMat;
    o.rgb = saturate(o.rgb);

    o.rgb = from_linear(o.rgb);    
}

#define PI   3.14159
#define TAU (PI * 2.0)
#define mad(a,b,c) ((a)*(b)+(c))


vec3 uniform_sample_sphere(vec2 u)
{
    vec3 dir;
    dir.x = cos(u.x * TAU);
    dir.y = sin(u.x * TAU);      
    dir.z = u.y * 2.0 - 1.0; 
    dir.xy *= sqrt(1.0 - dir.z * dir.z);
    return dir;
}

vec3 ray_cosine(vec2 u, vec3 n)
{
    return normalize(uniform_sample_sphere(u) + n);
}

vec3 ray_uniform(vec2 u, vec3 n)
{
    vec3 dir = uniform_sample_sphere(u);
    dir = dot(dir, n) < 0.0 ? -dir : dir;
    return normalize(dir + n * 0.01);
}

vec2 r2(in uint idx, in uvec2 useed)
{
    uvec2 phi = uvec2(3242174889u, 2447445413u);    
    uvec2 p = phi * idx + useed;  
    return vec2(p) * exp2(-32.0);  
}

float saturate(float x){return clamp(x, 0.0, 1.0);}
vec2 saturate(vec2 x){return clamp(x, 0.0, 1.0);}
vec3 saturate(vec3 x){return clamp(x, 0.0, 1.0);}
vec4 saturate(vec4 x){return clamp(x, 0.0, 1.0);}

float pow2(float x)
{
    return x * x;
}

vec3 to_linear(vec3 sRGB)
{
    bvec3 cutoff = lessThan(sRGB, vec3(0.04045));
    vec3 higher = pow((sRGB + vec3(0.055)) / vec3(1.055), vec3(2.4));
    vec3 lower = sRGB / vec3(12.92);

    return mix(higher, lower, cutoff);
}

//Linear to sRGB
vec3 from_linear(vec3 linearRGB)
{
    bvec3 cutoff = lessThan(linearRGB, vec3(0.0031308));
    vec3 higher = vec3(1.055) * pow(linearRGB, vec3(1.0 / 2.4)) - vec3(0.055);
    vec3 lower = linearRGB * vec3(12.92);

    return mix(higher, lower, cutoff);
}

