    return mat;
}

vec2 opU(vec2 d1, vec2 d2)
{
	return (d1.x < d2.x) ? d1 : d2;
}

vec2 map(vec3 p)
{
    vec2 res = vec2(1e20, 0);

    return res;
}

vec3 calcNormal( in vec3 pos )
{
    vec3 n = vec3(0.0);
    for( int i=ZERO; i<4; i++ )
    {
        vec3 e = 0.5773*(2.0*vec3((((i+3)>>1)&1),((i>>1)&1),(i&1))-1.0);
        n += e * abs(map(pos+0.0005*e).x);
    }
    return normalize(n);
}

bool marchHit(ray r, float tmin, float tmax, inout hitRecord rec)
{
    vec2 res = vec2(-1);

    float t = tmin;
    for(int i = 0; i < 256 && t < tmax; i++)
    {
        vec2 h = map(r.o + r.d * t);
        if(abs(h.x) < .0001 * t)
        { 
            rec.t = t;
            rec.p = r.o + r.d * t;
            rec.n = calcNormal(rec.p);
            rec.mat = DIFFUSE(vec3(1), 1.);
            return true;
        }
        t += h.x;
    }

    return false;
}

bool worldHit(ray r, float tmin, float tmax, out hitRecord rec)
{
    rec.t = tmax;

    bool hit = false;

    if(iBox(noTransform, vec3(1e3, .01, 1e3), r, tmin, rec.t, rec))

        hit = true,
        rec.mat = DIFFUSE(vec3(.5), 1.);

    if (iSphere(translate(vec3(0, 1, 0)), 1., r, tmin, rec.t, rec))

        hit = true,
        rec.mat = GLASS(vec3(1), 1.5, 0.);

    if (iSphere(translate(vec3(-4, 1, 0)), 1., r, tmin, rec.t, rec))

        hit = true,
        rec.mat = DIFFUSE(vec3(.4, .2, .1), 1.);

    if (iSphere(translate(vec3(4, 1, 0)), 1., r, tmin, rec.t, rec))

        hit = true, 
        rec.mat = METAL(vec3(.7, .6, .5), 0.);

    vec2 ro = r.o.xz, rd = r.d.xz, p = floor(ro), s = sign(rd), m,
         d = (p - ro + .5 + s * .5) / rd, cen;

    bool bhit = false;

    float t;
    if(box(translate(vec3(0, .2, 0)), vec3(12, .2, 12), r, tmin, rec.t, t))
    for(int i = ZERO; i < 40; i++)
    {
        for(int j = ZERO; j < 4; j++)
        {
            cen = p - vec2(j / 2, j % 2);

            if (all(lessThan(abs(cen), vec2(12))))
            {
                cen += .2 + .9 * hash2(cen);

                if (sqr(abs(abs(cen.x) - 2.) - 2.) + sqr(cen.y) > .8)
                if (iSphere(translate(vec3(cen.x, .2, cen.y)), .2, r, tmin, rec.t, rec))
                {
                    bhit = true;

                    vec4 ran = hash4(cen);

                    if(ran.w < .8)
                    {
                        if      (ran.w < .3) rec.mat = DIFFUSE(ran.xyz * ran.xyz * .9 + .1, 1.);
                        else if (ran.w < .5) rec.mat = METAL(.5 * ran.xyz + .5, .5 * hash(ran));
                        else                 rec.mat = GLASS(.5 * ran.xyz + .5, 1.5, 0.);
                    }

                    else rec.mat = LIGHT(4. * ran.xyz);
                }
            }
        }

        if(bhit)
        {
            hit = true;
            break;
        }

        m = step(d, d.yx);
        d += m / abs(rd);
        p += m * s;
    }

    //if(marchHit(r, tmin, rec.t, rec)) hit = true;

    return hit;
}

vec3 skyTexture(vec3 rd)
{
    if(SKYTYPE == 1) return (1. - vec3(.25, .15, 0) * (rd.y + 1.));
    if(SKYTYPE == 2) return .7 * texture(iChannel0, rd).xyz;

    return vec3(0);
}

vec3 sphericalDirection(float sinTheta, float cosTheta, float sinPhi, float cosPhi) {
    return vec3(sinTheta * cosPhi, sinTheta * sinPhi, cosTheta);
}

vec3 uniformSampleCone(float cosThetaMax, vec3 X, vec3 Y, vec3 Z)
{
    float cosTheta = mix(cosThetaMax, 1., rand);
    float sinTheta = sqrt(1. - cosTheta * cosTheta);
    float phi = rand * TAU;
    vec3 V = sphericalDirection(sinTheta, cosTheta, sin(phi), cos(phi));
    return V.x * X + V.y * Y + V.z * Z;
}

const float scale = 2.,

            r1  =   0.836,
            r2  =   3.210,
            r3  =   0.448,
            r4  = -11.500,
            r5  =   0.283,
            r6  = - 0.385,
            r7  =   0.505,
            r8  = - 0.532,
            r9  =   1.060,
            r10 = - 1.200,

            d1 = 0.1075,
            d2 = 0.0165,
            d3 = 0.1555,
            d4 = 0.0505,
            d5 = 0.1890,
            d6 = 0.0505,
            d7 = 0.2122,
            d8 = 0.0097,
            d9 = 0.1390,

            N1 = 1.64238,
            N2 = 1.62306,
            N3 = 1.57566,
            N4 = 1.67270,
            N5 = 1.64238,
            N6 = 1.64238,

            V1 = 48.0,
            V2 = 56.9,
            V3 = 41.2,
            V4 = 32.2,
            V5 = 48.0,
            V6 = 48.0,

            A  = .4444 * scale;

const float N = 1.4, AD = .6308 / N * scale, ID = .864,
            k1 = .19749, k2 = .61588, k3 = .20134;
float I;

struct lens
{
    // Radius, Thickness, IOR, Abbe number, Semi-Diameter
    float R, d, N, V, h;
};

const int numLenses = 10;
const lens[] lenses = lens[](lens(r1,  d1, N1, V1, .36),
                             lens(r2,  d2, 1., 0., .36),
                             lens(r3,  d3, N2, V2, .32),
                             lens(r4,  d4, N3, V3, .32),
                             lens(r5,  d5, 1., 0., .22),
                             lens(r6,  d6, N4, V1, .22),
                             lens(r7,  d7, N5, V1, .29),
                             lens(r8,  d8, 1., 0., .29),
                             lens(r9,  d9, N6, V1, .29),
                             lens(r10, 0., 1., 0., .29));

cam c;

bool iLens(float pos, float h, float R, ray r, float tmin, float tmax, inout hitRecord rec)
{
    vec3 oc = r.o - c.w * (R + pos) - c.o, p;

    float b = dot(oc, r.d),
          d = R * R - dot2(oc - b * r.d);

    if(d < 0.) return false;

    d = sqrt(d);

    float t = -b - d, s = -sign(R),
          zCap = sqrt(R * R - h * h);

    if(t > tmin && t < tmax && s * dot(p = oc + r.d * t, c.w) > zCap)
    {
        rec.t = t;
        rec.p = r.o + r.d * t;
        rec.n = p / abs(R);
        return true;
    }

    t = -b + d;

    if(t > tmin && t < tmax && s * dot(p = oc + r.d * t, c.w) > zCap)
    {
        rec.t = t;
        rec.p = r.o + r.d * t;
        rec.n = -p / abs(R);
        return true;
    }

	return false;
}

vec3 color(ray r)
{
    vec3 col = vec3(1), emitted = vec3(0);
    float pdf;
	hitRecord rec;

    #ifdef USE_LENS

    float zMax = 0.;
    float[numLenses] lensPos;
    lens L, l;

    for(int i = ZERO; i < numLenses; i++)
    {
        l = lenses[i];
        lensPos[i] = zMax;
        zMax += l.d * scale;
    }

    #ifdef DISPERSION
    float waveMix = halton(seed.w);
    #else
    float waveMix = .5;
    #endif

    l = lenses[numLenses - 1]; l.R *= scale; l.h *= scale;

    vec3 oc = c.o - c.w * (l.R - lensPos[numLenses - 1] - sign(l.R) * sqrt(l.R * l.R - l.h * l.h)) - r.o,
         Z = normalize(oc), X, Y;

    onb(Z, X, Y);

    float cosThetaMax = sqrt(max(0., 1. - l.h * l.h / dot2(oc)));

    r.d = uniformSampleCone(cosThetaMax, X, Y, Z);

    col *= /* TAU * (1. - cosThetaMax) */ dot(r.d, -c.w) / PI;

    float tmin = 1e-3 * scale;
    int lensID = numLenses;

    for (int i = ZERO; i < 20; i++)
    {
        lensID += int(sign(dot(r.d, c.w)));

        L = lenses[lensID];

        L.R *= scale;
        L.h *= scale;

        if(iLens(lensPos[lensID], L.h, L.R, r, tmin, 1e5, rec))
        {
            vec3  o = r.o - c.o - A * c.w;
            float t = -dot(c.w, o) / dot(r.d, c.w);

            if(t > 0. && t < rec.t)
            if(4. * dot2(o + r.d * t) > AD) return vec3(0);

            if(lensID > 0) l = lenses[lensID - 1];
            else           l = lens(0., 0., 1., 0., 0.);

            if(dot(r.d, c.w) < 0.)
            {
                lens temp = L;
                L = l; l = temp;
            }

            float n1 = L.N,
                  n2 = l.N,
                  IOR, F;

            float d = 550. / 4. / n1,
                  nCoat = sqrt(n1 * n2);

            #ifdef DISPERSION

            if(n1 > 1.) n1 -= (waveMix - .5) * (n1 - 1.) / L.V;
            if(n2 > 1.) n2 -= (waveMix - .5) * (n2 - 1.) / l.V;

            #endif

            IOR = n2 / n1;

            #ifdef ANTI_REFLECTION_COATING

            F = Reflectance(400. + 300. * waveMix, d, acos(dot(-r.d, rec.n)), n1, nCoat, n2);

            #else

            F = dielectricFresnel(abs(dot(r.d, rec.n)), IOR);

            #endif

            r = ray(rec.p, rand < F ? reflect(r.d, rec.n) : refract(r.d, rec.n, IOR));
        }
        else break;
    }

    if(lensID > -1) return vec3(0);
    #endif

    for (int i = ZERO; i < 10; i++)
    {
        if (worldHit(r, .01, 1e5, rec))
        {
            emitted += col * rec.mat.emission;

            if(luma(col) < 1e-6) break;

            ray scattered;
            scattered.o = rec.p;

            rec.eta = rec.mat.IOR;
            if(dot(rec.n, r.d) > 0.) rec.n = -rec.n;
            else rec.eta = 1. / rec.eta;
            vec3 BSDF = DisneySample(rec, -r.d, scattered.d, pdf);
            if(pdf > 0.) col *= BSDF / pdf;
            else break;

            r = scattered;

            #ifdef RUSSIAN_ROULETE
            float p = 1. - 1. / luma(col + 1.);
        	if (rand > p) break;
            col /= p;
            #endif
        }

        else
        {
            emitted += col * skyTexture(r.d);
            break;
    	}
    }

    #ifdef USE_LENS

        emitted *= 5. * N * N;
        #ifdef DISPERSION
        emitted *= 4. * max(1. - abs(4. * waveMix - vec3(3, 2, 1)), 0.);
        #endif

    #endif

    return emitted;
}

cam camera(vec3 ro, vec3 lp, vec3 vup, float vfov, float aperture, float d)
{
    cam c;

    float hh = tan(radians(vfov) / 2.) * d,
          hw = R.x / R.y * hh;

    c.rad = aperture / 2.;
    c.o = ro;
    c.w = normalize(ro - lp);
    c.u = normalize(cross(vup, c.w));
    c.v = cross(c.w, c.u);
    c.llc = c.o - hw * c.u - hh * c.v - d * c.w;
    c.hor = 2. * hw * c.u;
    c.ver = 2. * hh * c.v;

    d /= scale;
    I = scale * (d + k1) / (k2 * d - k3);

    return c;
}

ray getRay(cam c, vec2 uv)
{
    #ifdef USE_LENS
    uv -= .5;
    uv.x *= R.x / R.y;
    uv   *= .6 * ID * scale;

    return ray(c.o - uv.x * c.u - uv.y * c.v + c.w * I, c.w);

    #else
    vec2 rd = c.rad * ranDisk();

    c.o += c.u * rd.x + c.v * rd.y;

    return ray(c.o, normalize(c.llc + uv.x * c.hor + uv.y * c.ver - c.o));
    #endif
}

void mainImage(out vec4 O, vec2 I)
{
    O = vec4(0);

    if(iFrame < 2 && SKYTYPE > 1) return;

    seed = uvec4(I, iFrame, iTime);

    vec2 uv = (I + rand2 - .5) / R.xy;

    c = camera(vec3(13, 2, 3), vec3(0), vec3(0, 1, 0), 28., AD, 10.);

    vec3 col = deNaN(color(getRay(c, uv)));

    if(texelFetch(iChannel2, ivec2(32, 0), 0).x < .5) O = texelFetch(iChannel1, ivec2(I), 0);

    O += vec4(col, 1);
}

vec3 tex(vec2 p)
{
    vec4 O = texture(iChannel0, clamp(p, 0., 1.));
    return O.xyz / O.w;
}

void mainImage(out vec4 O, vec2 I)
{
    O = vec4(0);

    if(iFrame < 2 && SKYTYPE > 1) return;

    seed = uvec4(I, iFrame, iTime);

    // TO DO: Bloom and Halation

    if(texelFetch(iChannel2, ivec2(32, 0), 0).x < .5) O = texelFetch(iChannel1, ivec2(I), 0);

    O += vec4(tex(I / R.xy), 1);
}

const vec4  groundAlbedo         = vec4(0.3);
// Ray marching steps. More steps mean better accuracy but worse performance
const int TRANSMITTANCE_STEPS     = 128;
const int IN_SCATTERING_STEPS     = 128;

//-----------------------------------------------------------------------------
// Constants

// All parameters that depend on wavelength (vec4) are sampled at
// 630, 560, 490, 430 nanometers

const float g = 0.8;

const float groundRadius        = 6371.; // km
const float atmosphereThickness = 1e2;   // km
const float atmosphereRadius    = groundRadius + atmosphereThickness;
const vec3 viewPos = vec3(0, 6371.001, 0);
const vec3 sunDir = normalize(vec3(8, 0, -4));

const vec4 sun_spectral_irradiance = vec4(1.679, 1.828, 1.986, 1.307);
const vec4 molecular_scattering_coefficient_base = vec4(6.605e-3, 1.067e-2, 1.842e-2, 3.156e-2);
const vec4 ozone_absorption_cross_section = vec4(3.472e-25, 3.914e-25, 1.349e-25, 1.103e-26);

const float ozoneMean = 3e2;

const vec4 aerosol_absorption_cross_section = vec4(2.8722e-24, 4.6168e-24, 7.9706e-24, 1.3578e-23);
const vec4 aerosol_scattering_cross_section = vec4(1.5908e-22, 1.7711e-22, 2.0942e-22, 2.4033e-22);
const float aerosol_base_density = 1.3681e20;
const float aerosol_background_density = 2e6;
const float aerosol_height_scale = 0.73;

//-----------------------------------------------------------------------------

float iSphere(vec3 ro, vec3 rd, float rad)
{
    float b = dot(ro, rd),
          d = rad * rad - dot2(ro - b * rd);

    if (d < 0.) return -1.;

    d = sqrt(d);

    return d > -b ? -b + d : -b - d;
}

/*
 * Rayleigh phase function.
 */
float molecular_phase_function(float cosTheta)
{
    return .0596831 * (1. + cosTheta * cosTheta);
}

/*
 * Henyey-Greenstrein phase function.
 */
float aerosol_phase_function(float cosTheta)
{
    float gg  = g * g,
          den = 1. + gg + 2. * g * cosTheta;

    return INV4PI * (1. - gg) / den / sqrt(den);
}

/*
 * Return the molecular volume scattering coefficient (km^-1) for a given altitude
 * in kilometers.
 */
vec4 get_molecular_scattering_coefficient(float h)
{
    return molecular_scattering_coefficient_base * exp(-.07771971 * pow(h, 1.16364243));
}

/*
 * Return the molecular volume absorption coefficient (km^-1) for a given altitude
 * in kilometers.
 */
vec4 get_molecular_absorption_coefficient(float h)
{
    h += 1e-4; // Avoid division by 0
    float density = 3.78547397e20 / h * exp(-sqr(log(h) - 3.22261) * 5.55555555);
    return ozone_absorption_cross_section * ozoneMean * density;
}

float get_aerosol_density(float h)
{
    return aerosol_base_density * exp(-h / aerosol_height_scale) + aerosol_background_density;
}

/*
 * Get the collision coefficients (scattering and absorption) of the
 * atmospheric medium for a given point at an altitude h.
 */
void get_atmosphere_collision_coefficients(float h,
                                           out vec4 aerosol_absorption,
                                           out vec4 aerosol_scattering,
                                           out vec4 molecular_absorption,
                                           out vec4 molecular_scattering,
                                           out vec4 extinction)
{
    h = max(h, 0.); // In case height is negative

    float aerosol_density = get_aerosol_density(h);
    aerosol_absorption = aerosol_absorption_cross_section * aerosol_density;
    aerosol_scattering = aerosol_scattering_cross_section * aerosol_density;

    molecular_absorption = get_molecular_absorption_coefficient(h);
    molecular_scattering = get_molecular_scattering_coefficient(h);
    extinction = aerosol_absorption + aerosol_scattering + molecular_absorption + molecular_scattering;
}

vec2 rd2uv(vec3 rd)
{
    vec2 uv;

    vec3 ard = abs(rd);

    if(ard.x > ard.y && ard.x > ard.z)
    {
        uv = .5 * rd.yz / rd.x + .5;
        if(rd.x > 0.) uv.y++;
    }
    else if(ard.y > ard.z)
    {
        uv = .5 * rd.zx / rd.y + .5;
        uv.x += 1.;
        if(rd.y > 0.) uv.y++;
    }
    else
    {
        uv = .5 * rd.xy / rd.z + .5;
        uv.x += 2.;
        if(rd.z > 0.) uv.y++;
    }

    return uv / vec2(3, 2);
}

vec3 uv2rd(vec2 uv)
{
    uv *= vec2(3, 2);
    ivec2 i = ivec2(uv);

    uv = fract(uv) - .5;

    vec3 rd = normalize(vec3(uv, .5));

    if(i.y < 1) rd = -rd;

    return i.x < 1 ? rd.zxy : i.x < 2 ? rd.yzx : rd;
}

vec4 LUT(float cosTheta, float normalized_altitude)
{
    return texture(iChannel0, uv2rd(vec2(cosTheta * .5 + .5, normalized_altitude)));
}

void mainCubemap(out vec4 O, vec2 I, vec3 ro, vec3 rd)
{
    if (SKYTYPE < 2) return;

    if (iFrame > 1) { O = texture(iChannel0, rd); return; }

    if (iFrame > 0)
    {
        ro = viewPos;

        float tmax = iSphere(ro, rd, groundRadius);

        if (tmax < 0.) tmax = iSphere(ro, rd, atmosphereRadius);

        float cosTheta = dot(-rd, sunDir);

        float molecular_phase = molecular_phase_function(cosTheta);
        float aerosol_phase = aerosol_phase_function(cosTheta);

        float dt = tmax / float(IN_SCATTERING_STEPS);

        vec4 L = vec4(0),
             transmittance = vec4(1);

        vec3 pos = ro;

        for (int i = 0; i < IN_SCATTERING_STEPS; ++i)
        {
            float d = length(pos);
            vec3 zenith_dir = pos / d;
            float altitude = d - groundRadius;
            float normalized_altitude = altitude / atmosphereThickness;

            cosTheta = dot(zenith_dir, sunDir);

            vec4 aerosol_absorption, aerosol_scattering;
            vec4 molecular_absorption, molecular_scattering;
            vec4 extinction;
            get_atmosphere_collision_coefficients(
                altitude,
                aerosol_absorption, aerosol_scattering,
                molecular_absorption, molecular_scattering,
                extinction);

            vec4 transmittance_to_sun = LUT(cosTheta, normalized_altitude);

            // Solid angle subtended by the planet from a point at d distance
            // from the planet center.
            // 2nd order scattering from the ground
            vec4 L_ground = .5 * (1. - sqrt(max(1. - sqr(groundRadius / d), 0.))) * groundAlbedo * INVPI * LUT(cosTheta, 0.) * LUT(1., 0.) / LUT(1., normalized_altitude) * cosTheta;

            // Fit of Earth's multiple scattering coming from other points in the atmosphere
            vec4 L_ms = vec4(.00434, .00694, .01188, .02) / (1. + 5. * exp(-17.92 * cosTheta));

            vec4 ms = L_ms + L_ground;

            vec4 S = sun_spectral_irradiance *
                (molecular_scattering * (molecular_phase * transmittance_to_sun + ms) +
                 aerosol_scattering   * (aerosol_phase   * transmittance_to_sun + ms));

            vec4 step_transmittance = exp(-dt * extinction);

            // Energy-conserving analytical integration
            // "Physically Based Sky, Atmosphere and Cloud Rendering in Frostbite"
            // by Sébastien Hillaire

            L += transmittance * S * (1. - step_transmittance) / extinction;
            transmittance *= step_transmittance;

            pos += rd * dt;
        }

        O.xyz = mat4x3(137.672389239975, -8.632904716299537, -1.7181567391931372,
                       32.549094028629234, 91.29801417199785, -12.005406444382531,
                       -38.91428392614275, 34.31665471469816, 29.89044807197628,
                       8.572844237945445, -11.103384660054624, 117.47585277566478) * L;
        return;
    }

    I = rd2uv(rd);

    float cosTheta = I.x * 2. - 1.;

    ro = vec3(0, 0, groundRadius + atmosphereThickness * I.y);
    rd = vec3(-sqrt(1. - cosTheta * cosTheta), 0, cosTheta);

    float tmax = iSphere(ro, rd, groundRadius);
    if (tmax < 0.) tmax = iSphere(ro, rd, atmosphereRadius);

    float dt = tmax / float(TRANSMITTANCE_STEPS);

    O = vec4(0);

    for (int i = 0; i < TRANSMITTANCE_STEPS; i++)
    {
        vec4 aerosol_absorption, aerosol_scattering,
             molecular_absorption, molecular_scattering,
             extinction;

        get_atmosphere_collision_coefficients(
            length(ro) - groundRadius,
            aerosol_absorption, aerosol_scattering,
            molecular_absorption, molecular_scattering,
            extinction);

        O += extinction;

        ro += rd * dt;
    }

    O = exp(-O * dt);
}

vec3 tex(vec2 p)
{
    vec4 O = texture(iChannel0, p / R.xy);
    return flimTransform(O.xyz / O.w);
}

int poisson(float expMean)
{
    float p = 1.;
    int i = -1;
    while (p > expMean && i++ < 20) p *= rand;
    return i;
}

const float radius = .06,
            sigmaR = .024,
            blur   = .2;

void mainImage(out vec4 O, vec2 I)
{
    O = vec4(0);

    if(iFrame < 2 && SKYTYPE > 1) return;

    seed = uvec4(I, iFrame, iTime);

    if(texelFetch(iChannel2, ivec2(32, 0), 0).x < .5) O = texelFetch(iChannel1, ivec2(I), 0);

    float maxRadius = radius, mu, sigma;

    float ag = 1. / ceil(1. / radius);

    if (sigmaR > 0.)
    {
        sigma = log(sqr(sigmaR / radius) + 1.);
        mu = log(radius) - .5 * sigma;
        sigma = sqrt(sigma);
        maxRadius = exp(mu + 2. * sigma);
    }

    vec2 p = I + blur * gaussian2D() + rand2 - .5;

    vec3 col = vec3(0);

    ivec4 bound = ivec4((p - maxRadius) / ag, (p + maxRadius) / ag);

    bool covered = false;

    for (int x = bound.x; x <= bound.z && !covered; x++)
    for (int y = bound.y; y <= bound.w && !covered; y++)
    {
        vec2 pos = ag * vec2(x, y);

        vec3 expMean = exp(INVPI / (1. + sqr(sigmaR / radius)) * log(1. - tex(pos)));

        pos -= p;

        for (int i = 0; i < 3; i++)
        {
            if(col[i] > .5) continue;

            seed = uvec4(x, y, i, i);

            int nGrain = poisson(expMean[i]);

            for (int j = 0; j < nGrain; j++)
            {
                if (dot2(pos + ag * rand2) < sqr(sigmaR > 0. ? min(exp(mu + sigma * gaussian()), maxRadius) : radius))
                {
                    col[i]++;
                    break;
                }
            }
        }

        if (col == vec3(1)) covered = true;
    }

    if(texelFetch(iChannel2, ivec2(32, 0), 0).x < .5) O = texelFetch(iChannel1, ivec2(I), 0);

    O += vec4(col, 1);
}

