//	everything below here is based on iq's Raymarching - Primitives shader	
//	https://www.shadertoy.com/view/Xds3zN
//	
//--------------------------------------------------------------------------



// Created by inigo quilez - iq/2013
// License Creative Commons Attribution-NonCommercial-ShareAlike 3.0 Unported License.

// A list of usefull distance function to simple primitives, and an example on how to 
// do some interesting boolean operations, repetition and displacement.
//
// More info here: https://iquilezles.org/articles/distfunctions


vec2 map( in vec3 pos )
{
	vec2 sphere		= vec2( length( pos - spherePos ) - sphereRad, 2.0 );

	vec3 pa			= pos - tubeStart;
	vec3 ba			= tubeEnd - tubeStart;
	vec2 tube		= vec2( length( pa - ba * clamp( dot(pa,ba) / dot(ba,ba), 0.0, 1.0 ) ) - tubeRad, 2.0 );
	float bump		= 0.0;

	#ifndef DISABLE_NORMALS
	bump			= texture( iChannel0, pos.xz * 6.0 ).x * 0.002;
	#endif

	vec2 res		= vec2( pos.y + bump, 1.0 );
	res				= ( res.x < sphere.x ) ? res : sphere;
	res				= ( res.x < tube.x ) ? res : tube;

    return res;
}

vec2 castRay( in vec3 ro, in vec3 rd, in float maxd )
{
	float precis = 0.001;
    float h=precis*2.0;
    float t = 0.0;
    float m = -1.0;
    for( int i=0; i<60; i++ )
    {
        if( abs(h)<precis||t>maxd ) continue;//break;
        t += h;
	    vec2 res = map( ro+rd*t );
        h = res.x;
	    m = res.y;
    }

    if( t>maxd ) m=-1.0;
    return vec2( t, m );
}

vec3 calcNormal( in vec3 pos )
{
	vec3 eps = vec3( 0.001, 0.0, 0.0 );
	vec3 nor = vec3(
	    map(pos+eps.xyy).x - map(pos-eps.xyy).x,
	    map(pos+eps.yxy).x - map(pos-eps.yxy).x,
	    map(pos+eps.yyx).x - map(pos-eps.yyx).x );
	return normalize(nor);
}

vec3 render( in vec3 ro, in vec3 rd )
{ 
    vec3 col = vec3(0.0);
    vec2 res = castRay(ro,rd,20.0);
    if( res.y>-0.5 )
    {
		if( res.y == 2.0 )
			return vec3(1);

        vec3 pos = ro + res.x * rd;
        vec3 nor = calcNormal( pos );

		col = areaLights( pos, nor, rd );
	}
	return col;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
	vec2 q = fragCoord.xy/iResolution.xy;
    vec2 p = -1.0+2.0*q;
	p.x *= iResolution.x/iResolution.y;

	float time = 15.0 + iTime*0.1;
	vec3 ro = vec3(1.2*cos(time),0.3+0.2*cos(time),1.2*sin(time));
	vec3 ta = vec3(0,0,0);

	vec3 cw = normalize( ta-ro );
	vec3 cp = vec3( 0.0, 1.0, 0.0 );
	vec3 cu = normalize( cross(cw,cp) );
	vec3 cv = normalize( cross(cu,cw) );
	vec3 rd = normalize( p.x*cu + p.y*cv + 2.5*cw );

	updateLights();
    vec3 col = render( ro, rd );

	fragColor=vec4( col, 1.0 );
}

// the subsurface is non pbr at all

// top -> skin material with variable sss radius
// bottom -> leave material with variable sss radius

#define AA 3// antialiasing

// ray sphere intersection function
// thanks to iq: https://iquilezles.org/articles/intersectors/
float sphIntersect(vec3 ro, vec3 rd, vec3 ce, float ra) {
    vec3 oc = ro - ce;
    float b = dot(oc, rd);
    float c = dot(oc, oc) - ra*ra;
    float h = b*b - c;

    if(h<0.) return -1.;
    return -b - sqrt(h);
}

// intersection function
float intersect(vec3 ro, vec3 rd, float tmax, out vec3 on, out int oid) {
    float t = tmax;

    for (int i=0; i<10; i++) {
        vec3 ce = vec3((i%5)*2-4, i/5*2-1, 0); // sphere center
        float h = sphIntersect(ro, rd, ce, .95);
        if (h>0. && h<t) {
            on = normalize(ro-ce + rd*h); // normal
            oid = i;
            t = h;
        }
    }

    return t<tmax ? t : -1.;
}

// my subsurface scattering lighting model
// lambert + preintegrated sss + blinn ggx + shlick

// type -> type of diffusion model
// n -> normal
// l -> light direction
// rd -> ray direction
// kl -> light color
// kd -> diffuse color
// ks -> subsurface color
// ksr -> subsurface radius
// km -> roughness / microfacet amount
// kn -> refraction index
vec3 lighting(int type, vec3 n, vec3 l, vec3 rd, vec3 kl, vec3 kd, vec3 ks, vec3 ksr, float km, float kn) {
    float ndl = dot(n, l); // diffuse lambert / N⋅L
    float pndl = clamp( ndl, 0., 1.), // positive ndl
          nndl = clamp(-ndl, 0., 1.); // negative ndl

    // subsurface scattering
    vec3 sss;
    if (type==0) // exponential
        sss = .2 * pow(vec3(1.-pndl), 3./(ksr+.001)) * 
                   pow(vec3(1.-nndl), 3./(ksr+.001));
    else // gaussian         
        sss = .2 * exp(-3.*abs(ndl)/(ksr+.001));

    vec3 h = normalize(l - rd); // half vector
    float ndh = dot(n, h); // N⋅H

    // ggx / Trowbridge and Reitz specular model approximation
    float g = ndh*ndh * (km*km - 1.) + 1.;
    float ggx = km*km / (3.141592*g*g);

    // shlick approximation
    float fre = 1.+dot(rd, n); // fresnel
    // fresnel amount
    float f0 = (kn-1.)/(kn+1.);
          f0 = f0*f0;
    float kr = f0 + (1.-f0)*(1.-km)*(1.-km) * pow(fre, 5.); // reflectivity

    return kl*(pndl*(kd + kr*ggx) + kd*ks*ksr*sss); // diffuse + sss + specular
}

// rendering
vec3 render(vec3 ro, vec3 rd) {
    vec3 col = vec3(.5+.5*rd.y)*.025; // background

    vec3 n; int id;
    float t = intersect(ro, rd, 1e10, n, id);

    if (t>0.) {
        vec3 p = ro + rd*t; // hit point

        vec3 difCol;
        vec3 sssCol;
        vec3 sssRad;
        float sssDif;
        float rou;
        float ior;
        int type;

        int row = id/5;
        if (row==1) { // skin material
            difCol = vec3(.6,.45,.25);
            sssCol = vec3(.75);
            sssRad = float(id%5)/3.*vec3(1,.25,.04);
            rou = .1;
            ior = 1.5;
            type = 1;
        } else { // leave material
            difCol = vec3(.5,.6,.2);
            sssCol = vec3(.6);
            sssRad = float(id%5)/3.*vec3(.6,1,.06);
            rou = .1;
            ior = 1.5;
            type = 1;
        }

        col = lighting(type, n,          normalize(vec3(1,1,1)), rd,   vec3(1), difCol, sssCol, sssRad, rou, ior) + // key light
              lighting(type, n, normalize(vec3(-1,.4,.5)-.1*ro), rd, vec3(.25), difCol, sssCol, sssRad, rou, ior);  // rim light
    }

    return col;
}

// camera function
mat3 setCamera(vec3 ro, vec3 ta) {
    vec3 w = normalize(ta - ro); // forward vector
    vec3 u = normalize(cross(w, vec3(0,1,0))); // up vector
    vec3 v = cross(u, w); // side vector
    return mat3(u, v, w);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // normalized mouse coordinates
    vec2 mo = (iMouse.xy - .5*iResolution.xy)/iResolution.y;

    float an = .6*iTime + mo.x*3.141592; // camera xz rotation
    vec3 ro = 18.*vec3(sin(an),0,cos(an)); // ray origin
    vec3 ta = vec3(0); // target
    mat3 ca = setCamera(ro, ta); // camera matrix

    vec3 tot = vec3(0);
    for (int m=0; m<AA; m++)
    for (int n=0; n<AA; n++) {
        vec2 off = vec2(m,n) / float(AA) - .5; // AA offset
        vec2 p = (fragCoord+off - .5*iResolution.xy) / iResolution.y;

        vec3 rd = ca * normalize(vec3(p,3)); // ray direction
        vec3 col = render(ro, rd); // render

        col = 2.*col/(.8+2.5*col); // tonemapping
        col = pow(col, vec3(.4545)); // gamma correction

        tot += col;
    }
    tot /= float(AA*AA);

    // vignette
    vec2 q = fragCoord/iResolution.xy;
    tot *= .3+.7*pow(16. * q.x*q.y*(1.-q.x)*(1.-q.y), .1);

    // output
    fragColor = vec4(tot,1.0);
}


	const int max_iterations = 45;
	const float stop_threshold = 0.001;
	const float grad_step = 0.001;
	const float clip_far = 4.0;
	const float PI = 3.14159265359;

	const float furDepth = 0.5;
	const int furLayers = 50;
	const float rayStep = furDepth * 2.0 / float(furLayers);
	const float furThreshold = 0.4;
	const float uvScale = 0.5;

	float r = 1.;
	float rotation;
	float elevation;


	mat3 rotX(float g) {
		g = radians(g);
		vec2 a = vec2(cos(g), sin(g));
		return mat3(1.0, 0.0, 0.0,
					0.0, a.x, -a.y,
					0.0, a.y, a.x);
	}

	mat3 rotY(float g) {
		g = radians(g);
		vec2 a = vec2(cos(g), sin(g));
		return mat3(a.x, 0.0, a.y,
					0.0, 1.0, 0.0,
					-a.y, 0.0, a.x);
	}

	vec3 map(vec3 p) {
		p.y -= elevation;
		p *= rotY(rotation);
		float s = (length(p) - r) - 0.12 * sin(6. * p.x) * cos(6. * p.y)* sin(6. * p.z);
		return vec3(s * 0.5);	
	}


	vec2 cartesianToSpherical(vec3 p) {	
		float r = length(p);
		p = normalize(p);
		float t = (r - (1.0 - furDepth)) / furDepth;
		p.zyx *= rotX(rotation);
		vec2 uv = vec2(atan(p.y, p.x), acos(p.z));

		uv.y -= t * t * elevation;

		return uv;
	}

	float furDensity(vec3 pos) {
		vec2 uv = cartesianToSpherical(pos.xzy);	
		vec4 tex = textureLod(iChannel0, uv * uvScale, 0.0);

		float density = smoothstep(furThreshold, 1.0, tex.x);

		pos.y -= elevation;
		vec3 p = pos;
		p *= rotY(rotation);
		float r = length(pos) - 0.12 * sin(6. * p.x) * cos(6. * p.y)* sin(6. * p.z);;
		float t = (r - (1. - furDepth)) / furDepth;

		return density * (1. - t);

	}

	vec3 furNormal(vec3 pos, float density) {
    	float eps = 0.0001;
    	vec3 n;
    	n.x = furDensity( vec3(pos.x + eps, pos.y, pos.z)) - density;
    	n.y = furDensity( vec3(pos.x, pos.y + eps, pos.z)) - density;
    	n.z = furDensity( vec3(pos.x, pos.y, pos.z + eps)) - density;
    	return normalize(n);
	}


	vec3 furShade(vec3 pos, vec3 color, vec3 light, vec3 eye, float density) {

		vec3 v = normalize(light - pos);
		vec3 n = furNormal(pos, density);
		vec3 ev = normalize(pos - eye);
		vec3 h = reflect(ev, n);

		float diff = max(0.0, dot(v, n)) + 0.4;
		float spec = pow(max(0.0, dot(v, h)), 64.);

		float r = length(pos);
		float t = (r - (1.0 - furDepth)) / furDepth;
		t = clamp(t, 0.3, 1.);

		diff = mix(diff, 1., 0.5);

		return color * t * (diff + 1.9 * spec);
	}

	vec3 gradient( vec3 v ) {
		const vec3 delta = vec3( grad_step, 0.0, 0.0 );
		float va = map( v ).x;
		return normalize (
			vec3(
				map( v + delta.xyy).x - va,
				map( v + delta.yxy).x - va,
				map( v + delta.yyx).x - va			
			)
		);
	}

	vec3 ray_marching( vec3 origin, vec3 dir, float start, float end ) {

		float depth = start;
		vec3 salida = vec3(end);
		vec3 dist = vec3(0.1);

		for ( int i = 0; i < max_iterations; i++ ) 		{
			if ( dist.x < stop_threshold || depth > end ) break;
                dist = map( origin + dir * depth );
                depth += dist.x;
		}

		salida = vec3(depth, dist.y, dist.z);
		return salida;
	}

	vec3 shading( vec3 v, vec3 n, vec3 eye, vec3 lightMix) {

		vec3 final = vec3( 0.0 );
		vec3 ev = normalize( v - eye );
		vec3 ref_ev = reflect( ev, n );
		vec3 light_pos   = vec3(0.0, 2.0, -2.0);
		vec3 vl = normalize( light_pos - v );
		float diffuse  = max( 0.0, dot( vl, n ) );
		float specular = max( 0.0, dot( vl, ref_ev ) );
		specular = pow( specular, lightMix.x );
		final += vec3( 0.9 ) * ( diffuse * lightMix.y + specular * lightMix.z);	
		final += vec3(0.2);

		return final;
	}

	vec3 ray_dir( float fov, vec2 size, vec2 pos ) {
		vec2 xy = pos - size * 0.5;

		float cot_half_fov = tan(radians( 90.0 - fov * 0.5 ));	
		float z = size.y * 0.5 * cot_half_fov;

		return normalize( vec3( xy, z ) );
	}


	void mainImage( out vec4 fragColor, in vec2 fragCoord )
	{			
        rotation = 60. * (iTime);
        elevation = 0.25 * cos(iTime * 2.5);

		vec3 rd = ray_dir(60.0, iResolution.xy, fragCoord.xy );

		vec3 eye = vec3( .0, .0, -2.8 );

		vec3 lightMix = vec3(6., 0.45, 0.15);
		vec3 color = vec3(0.);

		vec3 data = ray_marching( eye, rd, 0.0, clip_far );
		if ( data.x < clip_far ) {

			vec3 pos = eye + rd * data.x;
			vec3 n = gradient( pos );

			vec3 lightColor =  shading( pos, n, eye, lightMix) * 2.0;			
			color = vec3(1.) * lightColor;

			vec4 c = vec4(0.0);

			for(int i=0; i<furLayers; i++) {
				vec4 sampleCol;
				sampleCol.a = furDensity(pos);
				if( c.a > 0.99 ) break;
				if (sampleCol.a > 0.) {
					sampleCol.rgb = sampleCol.a * furShade(pos, vec3(85., 72., 56) * lightColor / 255., vec3(0.0, 2.0, -2.0), eye, sampleCol.a);
					c = c + sampleCol * (1.0 - c.a);
				}
				pos += rd * rayStep;
			}

			color = c.xyz;
		}

		fragColor = vec4(2. * color, 1.0 );
	}

