    vec3 ta = vec3(0,0,0);

    // camera matrix
    vec3 ww = normalize( ta - ro );
    vec3 uu = normalize( cross(ww,up) );
    vec3 vv = normalize( cross(uu,ww) );

    // global normalize pixel coordinates
    vec2 gp = (2.0*fragCoord-iResolution.xy)/iResolution.y;

