        vec2 p = (2.0*(q+o)-res.xy)/res.y;
        #else    
        vec2 p = (2.0*q-res.xy)/res.y;
        #endif

        // ray direction
        vec3 rd = normalize( p.x*uu + p.y*vv + 1.5*ww );

        // background
	    vec3 col = vec3(0.07) * (1.0-0.3*length(gp));
