        // from back to front
        vec3 ray_col = col;

        #ifdef TEST_BOUNDS
        int i = 0, j = 0;
        #else
        for(int i = iv_len-1; i>=0; i--) // loop over intervals
        #endif
        {
        #ifndef TEST_BOUNDS
            for(int j = 2-1; j>=0; j--)  // loop over bounds inside interval
        #endif
            {
                float t, objid;
                vec3 nor;
                if(j == 0)
                {
                    t = ivd[i].t0;
                    nor = ivd[i].n0;
                    objid = ivd[i].m0;
                }
                else
                {
                    t = ivd[i].t1;
                    nor = ivd[i].n1;
                    objid = ivd[i].m1;
                }

                if( t > 0.0 )
                {
                    // surface intersection point
                    vec3  pos = ro + t*rd;
                    //if (isnan(length(nor))) continue;
                    if (dot(nor,rd) > 0.0) nor = -nor;
                    //nor = normalize(nor);

                    // material
                    vec3 mate = vec3(0.); // undefined
                    //if( objid == OBJ_BG )
