        }
        // gamma
        ray_col = rgb2srgb(ray_col);

	    tot += ray_col;
    #if AA>1
    }
    tot /= float(AA*AA);
    #endif

    // dither to remove banding in the background
    tot += fract(sin(fragCoord.x*vec3(13,17,11)+fragCoord.y*vec3(1,7,5))*158.391832)/255.0;

    fragColor = vec4( tot, 1.0 );
