                    2.950  // 折射率 （铁）
        )
    )
);

float seed; // 随机数种子

// 用随机数种子产生归一化的随机数
float rand13(vec3 x) {
    uvec3 p = floatBitsToUint(x);
    p = 1103515245U * ((p.xyz >> 1U) ^ (p.yzx));
    uint h32 = 1103515245U * ((p.x ^ p.z) ^ (p.y >> 3U));
    uint n = h32 ^ (h32 >> 16U);
    return float(n) * (1.0 / float(0xffffffffU));
}

float rand11() {
    uvec2 n = floatBitsToUint(seed++) * uvec2(1597334673U, 3812015801U);
    uint q = (n.x ^ n.y) * 1597334673U;
    return float(q) * (1.0 / float(0xffffffffU));
}

vec2  rand21() {
    uvec2 n = floatBitsToUint(seed++) * uvec2(1597334673U, 3812015801U);
    n = (n.x ^ n.y) * uvec2(1597334673U, 3812015801U);
    return vec2(n) * (1.0 / float(0xffffffffU));
}

// 光子在射线所在的位置
vec3 at(ray r, float t) {
    return r.origin + t * r.direction;
}

// 单位圆内随机取一点
vec2 random_in_unit_disk() {
    vec2 r = rand21() * vec2(1.0, TAU);
    return sqrt(r.x) * vec2(sin(r.y), cos(r.y));
}

// 从摄像机获取光线
ray get_ray(camera c, vec2 uv, vec3 color) {
    // 根据 VFOV 和显示画布长宽比计算传感器长宽
    float theta = radians(c.vfov);
    float half_height = tan(theta * 0.5);
    float half_width = c.aspect * half_height;

    // 以目标位置到摄像机位置为 Z 轴正方向
    vec3 z = normalize(c.lookfrom - c.lookat);
    // 计算出摄像机传感器的 XY 轴正方向
    vec3 x = normalize(cross(c.vup, z));
    vec3 y = cross(z, x);

    vec3 hwfx = half_width  * c.focus * x;
    vec3 hhfy = half_height * c.focus * y;

    vec3 lower_left_corner = c.lookfrom - hwfx - hhfy - c.focus * z;

    vec3 horizontal = 2.0 * hwfx;
    vec3 vertical   = 2.0 * hhfy;

    // 模拟光进入镜头光圈
    float lens_radius = c.aperture * 0.5;
    vec2 rud = lens_radius * random_in_unit_disk();
    vec3 offset = x * rud.x + y * rud.y;

    // 计算光线起点和方向
    vec3 ro = c.lookfrom + offset;
    vec3 po = lower_left_corner + uv.x * horizontal
                                + uv.y * vertical;
    vec3 rd = normalize(po - ro);

    return ray(ro, rd, color);
}

// 从欧拉角计算旋转矩阵
mat3 angle(vec3 a) {
    vec3 s = sin(a), c = cos(a);
    return mat3(vec3( c.z,  s.z,    0),
                vec3(-s.z,  c.z,    0),
                vec3(   0,    0,    1)) *
           mat3(vec3( c.y,    0, -s.y),
                vec3(   0,    1,    0),
                vec3( s.y,    0,  c.y)) *
           mat3(vec3(   1,    0,    0),
                vec3(   0,  c.x,  s.x),
                vec3(   0, -s.x,  c.x));
}

// 计算有向距离 (物体内部距离为负)
float signed_distance(object obj, vec3 pos) {
    vec3 position = obj.trs.position;
    vec3 rotation = obj.trs.rotation;
    vec3 scale    = obj.trs.scale;

    vec3 p = pos - position;

    // 会重复的将欧拉角转换成旋转矩阵，实际上只用在第一次计算就行了
    // 也有可能被编译器优化掉了
    p *= angle(radians(rotation));

    switch(obj.shape) {
        case SHAPE_SPHERE:
            return sd_sphere(p, scale.x);
        case SHAPE_BOX:
            return sd_box(p, scale);
        case SHAPE_CYLINDER:
            return sd_cylinder(p, scale.xy);
        default:
            return sd_sphere(p, scale.x);
    }
}

// 找到最近的物体并计算距离
object nearest_object(vec3 p) {
    object o; o.dis = TMAX;
    for (int i = 0; i < map.length(); i++) {
        object oi = map[i];
        oi.dis = abs(signed_distance(oi, p));
        if (oi.dis < o.dis) o = oi;
    }
    return o;
}

// 计算物体法线 from https://iquilezles.org/articles/normalsSDF/
vec3 calc_normal(object obj, vec3 p) {
    vec2 e = vec2(1, -1) * 0.5773 * 0.0005;
    return normalize( e.xyy*signed_distance(obj, p + e.xyy) + 
                      e.yyx*signed_distance(obj, p + e.yyx) + 
                      e.yxy*signed_distance(obj, p + e.yxy) + 
                      e.xxx*signed_distance(obj, p + e.xxx) );
}

// 构建正交基旋转矩阵 from https://graphics.pixar.com/library/OrthonormalB/paper.pdf
mat3 TBN(vec3 N) {
    float s = N.z >= 0.0 ? 1.0 : -1.0;
    float a = -1.0 / (s + N.z);
    float b = N.x * N.y * a;
    vec3  T = vec3(1.0 + s * N.x * N.x * a, s * b, -s * N.x);
    vec3  B = vec3(b, s + N.y * N.y * a, -N.y);

    return mat3(T, B, N);
}

// 使用光线步进 (Ray March) 检测第一个交点
record raycast(ray r) {
    record rec; float t = TMIN;
    for(uint i = 0U; i < MAX_RAYMARCH && t < TMAX && !rec.hit; i++) {
        rec.pos = at(r, t);
        rec.obj = nearest_object(rec.pos);
        rec.hit = rec.obj.dis < PRECISION;
        t      += rec.obj.dis;
    }
    return rec;
}

// 采样立方体贴图
vec4 mix_cube_lod(samplerCube sharp, samplerCube blur, vec3 dir, float lod) {
    return mix(textureLod(sharp, dir, lod), textureLod(blur, dir, lod), lod);
}

// 采样天空
vec3 sky(ray r, float brightness, float lod) {
    vec4 ibl = mix_cube_lod(iChannel2, iChannel3, r.direction, lod); // 天空盒 IBL 照明
    return pow(ibl.rgb * ibl.a * brightness, vec3(gamma)); // gamma 矫正
}

// 菲涅尔反射近似值
float fresnel_schlick(float cosine, float F0) {
    return mix(pow(abs(1.0 - cosine), 5.0), 1.0, F0);
}

// 用粗糙度计算菲涅尔
float fresnel_schlick(float cosine, float F0, float roughness) {
    return mix(fresnel_schlick(cosine, F0), F0, roughness);
}

// 在切线空间半球采样
vec3 hemispheric_sampling() {
    vec2 r = rand21() * vec2(1.0, TAU);

    vec2  v = vec2(cos(r.y), sin(r.y));
    float z = sqrt(r.x);
    vec2 xy = sqrt(1.0 - r.x) * v; 

    return vec3(xy, z);
}

// 用粗糙度在切线空间半球采样
vec3 hemispheric_sampling(float roughness) {
    vec2 r = rand21() * vec2(1.0, TAU);

    float shiny = pow(roughness, 5.0); // 光感越大高光越锐利
    // ToDo: 除零怎么办 ????!!
    r.x = shiny < 0.000001 ? 1.0 : (1.0 - r.x) / (1.0 + (shiny - 1.0) * r.x);

    vec2  v = vec2(cos(r.y), sin(r.y));
    float z = sqrt(r.x);
    vec2 xy = sqrt(1.0 - r.x) * v;

    return vec3(xy, z);
}

// 应用 PBR 材质
ray BSDF(ray r, record rec) {
    // 材质参数
    vec3  albedo       = rec.obj.mtl.albedo;
    float roughness    = rec.obj.mtl.roughness;
    float metallic     = rec.obj.mtl.metallic;
    float transmission = rec.obj.mtl.transmission;
    vec3  normal       = rec.obj.mtl.normal;
    float ior          = rec.obj.mtl.ior;

    normal = TBN(rec.normal) * normal; // 将切线空间法线转换到世界空间
    float outer = -sign(dot(normal, r.direction)); // 光正在从外面穿入物体表面

    // 光线和物体表面参数
    vec3 I  =  r.direction;
    vec3 V  = -r.direction;
    vec3 N  =  normal *= outer; // 如果处于 SDF 物体内部就反过来
    vec3 C  =  r.color;
    vec3 L;

    N = TBN(N) * hemispheric_sampling(roughness); // 用粗糙度半球采样
    float NoV = dot(N, V);

    float eta = outer > 0.0 ? ENV_IOR / ior : ior / ENV_IOR; // 计算折射率之比
    float k   = 1.0 - eta * eta * (1.0 - NoV * NoV); // 小于 0 为全反射
    float F0  = (eta - 1.0) / (eta + 1.0); F0 *= 3.0*F0; // 让透明材质的反射更明显一些
    float F   = fresnel_schlick(NoV, F0, roughness); // 菲涅尔

    vec2 rand2 = rand21(); // 取两个随机数
    if (rand2.y < F + metallic || k < 0.0) {
            L = I + 2.0 * NoV * N; // 包含镜面反射、菲涅尔反射、全反射
            // 下面可以提高帧数，但是会导致透明材质发黑，需要优化
            C *= float(dot(L, normal) > 0.0); // 如果光穿入或穿出表面就直接吸收掉
    } else {
        if (rand2.x < transmission) {
            L = eta * I - (sqrt(k)- eta * NoV) * N; // 斯涅尔折射
        } else {
            L = TBN(normal) * hemispheric_sampling(); // 漫反射
        }
    }


    C *= albedo;

    // 更新光的方向和颜色
    r.color     = C;
    r.direction = L;

    return r;
}

// RGB 亮度
float brightness(vec3 rgb) {
    return dot(rgb, vec3(0.299, 0.587, 0.114));
}

// 光线追踪
ray raytrace(ray r) {
    for (uint i = 0U; i < MAX_RAYTRACE; i++) {
        // 俄罗斯轮盘赌概率，防止光线过分的反复反射
        float inv_pdf = exp(float(i) / light_quality);
        float roulette_prob = 1.0 - (1.0 / inv_pdf);

        // 光线被毙掉就不用继续了
        if (rand11() < roulette_prob) { // discard;
            r.color *= roulette_prob;
            break;
        }

        // 能量守恒
        r.color *= inv_pdf;

        // 与地图求交
        record rec = raycast(r);

        // 没击中物体就肯定击中天空
        if (!rec.hit) {
            r.color *= sign(float(i)); // 纯黑色背景
            r.color *= sky(r, 2.0, 1.0 - 1.0 / (1.0 + 0.1 * float(i)));
            break;
        }

        // 计算法线
        rec.normal = calc_normal(rec.obj, rec.pos);

        // 更新光子的位置
        r.origin = rec.pos;

        // 应用 PBR 材质更新光线
        r = BSDF(r, rec);

        // 处理自发光
        float intensity = brightness(r.color);
        r.color *= rec.obj.mtl.emission;
        float visible   = brightness(r.color);

        // 光太暗或者击中光源
        if (intensity < visible || visible < VISIBILITY) break;
    }

    return r;
}

// Paniq's ACES fitted from https://github.com/TheRealMJP/BakingLab/blob/master/BakingLab/ACES.hlsl
vec3 ACESFitted(vec3 color) {
	// ODT_SAT => XYZ => D60_2_D65 => sRGB
    color *= mat3(
        0.59719, 0.35458, 0.04823,
        0.07600, 0.90834, 0.01566,
        0.02840, 0.13383, 0.83777
    );
    // Apply RRT and ODT
    vec3 a = color * (color + 0.0245786) - 0.000090537;
    vec3 b = color * (0.983729 * color + 0.4329510) + 0.238081;
    color  = a / b;
	// Back to color space
    color *= mat3(
         1.60475, -0.53108, -0.07367,
        -0.10208,  1.10813, -0.00605,
        -0.00327, -0.07276,  1.07602
    );
    // Clamp to [0, 1]
    return clamp(color, 0.0, 1.0);
}

// 片段着色器程序入口
vec4 fragment(vec2 uv, vec2 SCREEN_PIXEL_SIZE) {
    // 计算摄像机方位和视线
    vec3  lookfrom  = load(POSITION).xyz;
    vec2  rotation  = load(ROTATION).xy;
    vec3  direction = CameraRotation(rotation) * vec3(0, 0, -1);
    vec3  lookat    = lookfrom + direction;
    float aspect    = SCREEN_PIXEL_SIZE.y / SCREEN_PIXEL_SIZE.x;;

    // 初始化摄像机
    camera cam;
    cam.lookfrom = lookfrom;
    cam.lookat   = lookat;
    cam.aspect   = aspect;
    cam.vfov     = camera_vfov;
    cam.vup      = vec3(0, 1, 0);
    cam.focus    = camera_focus;
    cam.aperture = camera_aperture;

    // 用 UV 和时间初始化随机数发生器种子
    seed = rand13(vec3(uv, iTime*iTimeDelta));

    // 超采样
    uv += rand21() * SCREEN_PIXEL_SIZE;

    // 对每个光子经过的表面采样一次
    ray r = get_ray(cam, uv, vec3(1));

    // 处理颜色
    vec3 color = raytrace(r).color;

    // 色调映射
    color *= camera_exposure;
    color  = ACESFitted(color);

    // 伽马矫正
    color = pow(color, vec3(1.0 / gamma));

    return vec4(color, brightness(r.color));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 SCREEN_PIXEL_SIZE = 1.0 / iResolution.xy;
    vec2 uv = fragCoord * SCREEN_PIXEL_SIZE;

    fragColor = fragment(uv, SCREEN_PIXEL_SIZE); // 获取片元颜色

    if (bool(load(MOVING).x)) return; // 如果正在移动就不积累上一帧

    fragColor += texture(iChannel0, uv); // 积累帧进行降噪
}

#define PI 3.14159265358979
#define MARCH_SCALE 1.0


vec4 background(vec3 rd)
{
  float t = 1.0 - abs(rd.z);
  return mix(vec4(0.5, 0.5, 0.5, 1.0), vec4(0.5, 0.5, 0.8, 1.0), 1.0-t*t);
}

struct marchResult
{
  vec3 pos;
  vec3 norm;
  float inBounds;
  float depth;
  vec4 color;
};

struct transparentMarchResult
{
  float opacity;
  vec4 color;
};

struct OrbLightDescription
{
    vec3 pos;
    float Radius;
    vec3 color;
};

vec3 GetLightColor(int lightIndex)
{
    switch(lightIndex)
    {
        case 0: return vec3(1, 0.0, 1.0);
        case 1: return vec3(0, 1.0, 0.0);
    }
    return vec3(0, 0.0, 1.0);
}

OrbLightDescription GetLight(int lightIndex)
{
    const float lightMultiplier = 17.0f;
    float theta = iTime * 0.7 + float(lightIndex) * PI * 2.0 / float(3);
    float radius = 28.5f;

    OrbLightDescription orbLight;
    orbLight.pos = vec3(radius * cos(theta), radius * sin(theta), 16.0 + sin(theta * 2.0) * 2.5);
    orbLight.color = GetLightColor(lightIndex) * lightMultiplier;
    orbLight.Radius = 0.8f;

    return orbLight;
}

// --------------------------------------------//
//               Noise Functions
// --------------------------------------------//
// Taken from Inigo Quilez's Rainforest ShaderToy:
// https://www.shadertoy.com/view/4ttSWf
float hash1( float n )
{
    return fract( n*17.0*fract( n*0.3183099 ) );
}

// Taken from Inigo Quilez's Rainforest ShaderToy:
// https://www.shadertoy.com/view/4ttSWf
float noise( in vec3 x )
{
    vec3 p = floor(x);
    vec3 w = fract(x);

    vec3 u = w*w*w*(w*(w*6.0-15.0)+10.0);

    float n = p.x + 317.0*p.y + 157.0*p.z;

    float a = hash1(n+0.0);
    float b = hash1(n+1.0);
    float c = hash1(n+317.0);
    float d = hash1(n+318.0);
    float e = hash1(n+157.0);
	float f = hash1(n+158.0);
    float g = hash1(n+474.0);
    float h = hash1(n+475.0);

    float k0 =   a;
    float k1 =   b - a;
    float k2 =   c - a;
    float k3 =   e - a;
    float k4 =   a - b - c + d;
    float k5 =   a - c - e + g;
    float k6 =   a - b - e + f;
    float k7 = - a + b + c - d + e - f - g + h;

    return -1.0+2.0*(k0 + k1*u.x + k2*u.y + k3*u.z + k4*u.x*u.y + k5*u.y*u.z + k6*u.z*u.x + k7*u.x*u.y*u.z);
}

const mat3 m3  = mat3( 0.00,  0.80,  0.60,
                      -0.80,  0.36, -0.48,
                      -0.60, -0.48,  0.64 );

// Taken from Inigo Quilez's Rainforest ShaderToy:
// https://www.shadertoy.com/view/4ttSWf
float fbm_4( in vec3 x )
{
    float f = 2.0;
    float s = 0.5;
    float a = 0.0;
    float b = 0.5;
    for( int i=min(0, iFrame); i<4; i++ )
    {
        float n = noise(x);
        a += b*n;
        b *= s;
        x = f*m3*x;
    }
	return a;
}

// Taken from https://iquilezles.org/articles/distfunctions
float sdSphere( vec3 p, float s )
{
  return length(p)-s;
}

// Taken from https://iquilezles.org/articles/distfunctions
float sdPlane( vec3 p )
{
	return p.z;
}

float SmoothUnion( float d1, float d2, float k ) 
{
    float h = clamp( 0.5 + 0.5*(d2-d1)/k, 0.0, 1.0 );
    return mix( d2, d1, h ) - k*h*(1.0-h); 
}

float QueryVolumetricDistanceField(vec3 ro)
{
  vec3 fbmCoord = (ro + 2.0 * vec3(iTime, 0.0, iTime)) / 1.5f;
  float sdfValue = sdSphere(ro - vec3(-8.0, 2.0 + 20.0 * sin(iTime), -1), 5.6);
  sdfValue = SmoothUnion(sdfValue,sdSphere(ro - vec3(8.0, 8.0 + 12.0 * cos(iTime), 3), 5.6), 3.0f);
  sdfValue = SmoothUnion(sdfValue, sdSphere(ro - vec3(5.0 * sin(iTime), 3.0, 0), 8.0), 3.0) + 7.0 * fbm_4(fbmCoord / 3.2);
  sdfValue = SmoothUnion(sdfValue, sdPlane(ro + vec3(0, 0.4, 0)), 22.0);
  return sdfValue;
}

// 18 ops + mod
marchResult traceToOpaque(vec3 ro, vec3 rd)
{
  float d = -ro.z / rd.z;
  ro += d*rd;
  float tileIdx = mod(floor(ro.x * 0.2) + floor(ro.y * 0.2), 2.0);

  marchResult result;
  result.inBounds = step(0.0, d);
  result.pos = ro;
  result.norm = vec3(0.0, 0.0, 1.0);
  result.color = vec4(vec3(0.2 + 0.6*tileIdx), 1.0);
  result.depth = d;
  return result;
}

// 400 ops, 54 calls to QueryVField
// ~40,000 ops
marchResult marchToTransparent(vec3 ro, vec3 rd)
{
  int i = 0;
  float d = 0.0;
  float depth = 0.0;
  for (; i < 50; ++i)
  {
    d = QueryVolumetricDistanceField(ro);
    ro += 1.0*d*rd;
    depth += d;
    if (d < 0.1)
    {
      break;
    }
  }
  marchResult result;
  result.pos = ro;
  bool inBounds = i < 50 || dot(ro, ro) < 1e4;
  result.inBounds = inBounds ? 1.0 : 0.0;
  if (inBounds)
  {
    result.color = vec4(1, 1, 1, 1);
    d = QueryVolumetricDistanceField(ro);
    result.norm.x = QueryVolumetricDistanceField(ro + vec3(0.001, 0.0, 0.0)) - d;
    result.norm.y = QueryVolumetricDistanceField(ro + vec3(0.0, 0.001, 0.0)) - d;
    result.norm.z = QueryVolumetricDistanceField(ro + vec3(0.0, 0.0, 0.001)) - d;
    result.norm = normalize(result.norm);
    result.depth = depth;
  }
  return result;
}

// 700 ops
float fogDensity(in vec3 pos)
{
  //return QueryVolumetricDistanceField(pos) < 0.0 ? 1.0 : 0.0;
  return clamp(-QueryVolumetricDistanceField(pos), 0.0, 0.5);
}

// 10 ops
float massTransparency(float mass)
{
  return pow(0.9, mass*10.0);
}

// 10 ops
float massOpacity(float mass)
{
  return 1.0 - pow(0.9, mass * 5.0);
}

// 20 calls to volume field
// 14,000 ops
float fastOpacityIntegral(vec3 ro, vec3 re)
{
  float intervalLength = length(ro-re);
  vec3 rd = (re-ro) / intervalLength;
  float stepLength = max(0.5, intervalLength / 20.0);
  float totalMass = 0.0;
  float d = 0.0;
  vec3 pos = ro;

  do
  {
    float depth = QueryVolumetricDistanceField(pos);
    if (depth > 2.0) break;
    float thisStepLength = max(stepLength, depth);
    //return massOpacity(clamp(-depth, 0.0, 5.0));
    totalMass += thisStepLength * clamp(-depth, 0.0, 5.0);
    d += thisStepLength;
    pos += thisStepLength*rd;
  } while (false && d < intervalLength && totalMass < 4.0);
  return massOpacity(totalMass);
}

// (intervalLength/stepLength) calls to fogDensity, 700 ops per
// up to 100ish in the far corners:
// 100,000 ops
float fastOpacityIntegral2(vec3 ro, vec3 re)
{
  float totalMass = 0.0;
  const float stepLength = 1.0;
  float fogDepth = max(0.0, QueryVolumetricDistanceField(ro));
  // approximate integral as (distance into fog) * (fog density)
  return fogDepth * clamp(fogDepth, 0.0, 1.0);
  float intervalLength = length(ro-re);
  vec3 rd = normalize(re-ro);
  vec3 pos = ro;
  for (int i = 0; i < int(floor(intervalLength / stepLength)); ++i)
  {
    totalMass += stepLength * fogDensity(pos);
    pos += rd*stepLength;
    //if (totalMass > -10.0) break;
  }
  return massOpacity(totalMass);
}

// 38 ops, 1 squaredSphereChordLength call, 1 massOpacity call
// 63 ops
float fastOpacityIntegral3(vec3 ro, vec3 re)
{
  float totalMass = 0.0;
  float intervalLength = length(ro-re);
  vec3 rd = (re-ro) / intervalLength;
  vec3 pos = 0.5 * (ro+re);
  // this is some bullshit
  // just pretend the fog is a big sphere and calculate (squared) distance through it

  //totalMass = 0.0002 * intervalLength * squaredSphereChordLength(vec3(0.5, 0.5, 0.6)*pos - vec3(0,0,5), rd, 10.0);
  return massOpacity(totalMass);
}

// 4 + 3*(3 + 10 + 11 + 8) ops
// 100 ops, 3 calls to fastOpacityIntegral2
// 300,000 ops
vec4 calcLight(vec3 pos, vec3 norm)
{
  vec4 ambientLight = 0.3*vec4(1,1,1,0);
  vec4 color = vec4(0,0,0,1);
  for (int i = 0; i < 3; ++i)
    {
      OrbLightDescription light = GetLight(i);
      vec3 toLight = light.pos - pos;
      float dist = length(toLight);
      float cosAngle = max(0.0, dot(toLight, norm)) / dist;
      // use the more accurate opacity integral for the lighting that gets calculated once per pixel
      color.rgb += light.color * cosAngle * 1.0/dist * (1.0 - fastOpacityIntegral(pos, light.pos));
      //color.rgb += (cosAngle * 1.0/dist) * light.color;
    }
    return color + ambientLight;
}

// 100 ops, 3 calls to fastOpacityIntegral3
vec4 calcLight(vec3 pos)
{
  vec4 ambientLight = 0.3*vec4(1,1,1,0);
  vec4 color = vec4(0,0,0,1);
  for (int i = 0; i < 3; ++i)
    {
      OrbLightDescription light = GetLight(i);
      vec3 toLight = light.pos - pos;
      float dist = length(toLight);
      // this gets integrated over again anyway so who gives a shit
      //color.rgb += light.color * 1.0/dist * (1.0 - fastOpacityIntegral3(light.pos, pos));
      color.rgb += light.color * 1.0/dist * (1.0 - fastOpacityIntegral(pos, light.pos));
      //color.rgb += light.color * 1.0/dist;
    }
    return color + ambientLight;
}

// 1000 ops, 100 calls to fogDensity, 100 calls to massOpacity, 100 calls to calcLight
// 75,000 ops, 100 calls to calcLight(vec3)
transparentMarchResult marchThroughTransparent(vec3 ro, vec3 rd, float maxDepth, vec3 backgroundColor)
{
  vec3 color = vec3(0);
  vec3 fogBaseColor = vec3(0.8);
  float densityIntegral = 0.0;
  //vec3 color = backgroundColor;
  const float stepLength = 0.25;
  float previousDensity = 0.0;
  float density = 0.0;
  float totalTransparency = 1.0;
  vec3 pos = ro;
  float maxStepsFloat = min(100.0, maxDepth / stepLength);
  int maxSteps = int(maxStepsFloat);
  float finalStep = min(stepLength, maxDepth - float(maxSteps)*stepLength);
  for (int i = 0; i < maxSteps; ++i)
  {
    // could improve this by detecting when we're outside the fog
    pos += stepLength*rd;
    density = fogDensity(pos);
    //float intervalMass = 0.5*stepLength*(previousDensity + density);
    float intervalMass = 2.0*stepLength*(density);
    //float intervalOpacity = massOpacity(intervalMass);
    float intervalTransparency = massTransparency(intervalMass);
    float prevTransparency = totalTransparency;
    totalTransparency *= intervalTransparency;
    float intervalWeight = prevTransparency - totalTransparency;
    vec3 intervalColor = fogBaseColor * calcLight(pos).rgb;
    color += intervalColor * intervalWeight;

    densityIntegral += intervalMass;
    previousDensity = density;
  }
  pos += finalStep*rd;
  density = fogDensity(pos);
  //float intervalMass = 0.5*stepLength*(previousDensity + density);
  float intervalMass = 2.0*finalStep*(density);
  //float intervalOpacity = massOpacity(intervalMass);
  float intervalTransparency = massTransparency(intervalMass);
  float prevTransparency = totalTransparency;
  totalTransparency *= intervalTransparency;
  float intervalWeight = prevTransparency - totalTransparency;
  vec3 intervalColor = fogBaseColor * calcLight(pos).rgb;
  color += intervalColor * intervalWeight;

  densityIntegral += intervalMass;
  previousDensity = density;
  //color = mix(color, intervalColor, intervalOpacity);
  //color = vec3(abs(pos.z));
  //color = vec3(float(maxSteps) / 10.0);

  transparentMarchResult result;
  result.opacity = 1.0 - totalTransparency;
  result.color = vec4(color + backgroundColor*totalTransparency, 1);
  // result.emission = vec4(0,0,0,0);
  return result;
}

// called once per pixel = 810,000 times
// some ops, one call to traceToOpaque, one call to calcLight(vec3, vec3), one call to marchToTransparent,
// one call to marchThroughTransparent
// 810k * (18 + 1 calcLight(vec3, vec3) + 40k + 75k + 100 calcLight(vec3))
// 92G + 810k calcLight(vec3, vec3) + 81M calcLight(vec3)
// i forgot that FMAs are a thing while calculating this fffffffuuuuuuuuuuuuuuuuuuuuuuuuuu
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from -1 to 1)
    vec2 uv = (2.0 * fragCoord - iResolution.xy) /iResolution.x;

    vec3 cameraPos = vec3(-70.0 * cos(0.5), 70.0*sin(0.5), 35.0);
    vec3 cameraDirection = -normalize(cameraPos);
    float nearPlane = 1.5;
    vec3 cameraUp = vec3(0.0, 0.0, 1.0);
    cameraUp = cameraUp - dot(cameraUp, cameraDirection) * cameraDirection;
    vec3 cameraRight = cross(cameraDirection, cameraUp);
    vec3 rd = normalize(nearPlane*cameraDirection + uv.x*cameraRight + uv.y*cameraUp);

    // draw background
    fragColor = background(rd);

    // draw floor
    marchResult floorRes = traceToOpaque(cameraPos, rd);
    vec4 light = calcLight(floorRes.pos, floorRes.norm);
    fragColor = mix(fragColor, floorRes.color * light, floorRes.inBounds);


    // raymarch volumetric
    marchResult marchRes = marchToTransparent(cameraPos, rd);
    float maxDepth = floorRes.inBounds == 1.0 ? floorRes.depth - marchRes.depth : 100.0f;
    transparentMarchResult transRes = marchThroughTransparent(marchRes.pos, rd, maxDepth, fragColor.rgb);
    fragColor = transRes.color;

    //fragColor.rgb = vec3(fastOpacityIntegral(floorRes.pos, cameraPos));
    //fragColor.rgb = vec3(-QueryVolumetricDistanceField(floorRes.pos));


    //light = calcLight(marchRes.pos, marchRes.norm);
    //surfColor *= light;
    //surfColor.rgb = 0.5 + 0.5*marchRes.norm;
    //fragColor = mix(fragColor, surfColor, transRes.opacity);
    //fragColor.rgb = vec3(10.0 / maxDepth);
    fragColor.rgb = pow(fragColor.rgb, vec3(1.0/2.2));
    fragColor.a = 1.0;
}

/**
 * -----------------------------------------------------------
 * - SDF Outline Comparison
 * - Created by Steven Sell (ssell) / 2017
 * - License Creative Commons Attribution-NonCommercial-ShareAlike 3.0 Unported License.
 * - https://www.shadertoy.com/view/4lfyR2
 * -----------------------------------------------------------
 * 
 * Comparison of four different approaches for SDF outlining.
 * Use the mouse to drag the screen dividers.
 *
 *     Upper Left:  SDF Near-Miss
 *     Upper Right: SDF Offset Differences
 *     Lower Left:  Edge Detection
 *     Lower Right: Surface ID Differences
 *
 * -----------------------------------------------------------
 * - SDF Near-Miss
 * - Outline_NearMiss()
 * -----------------------------------------------------------
 * 
 * The outline is calculated based off of near-misses during raymarching,
 * where the ray comes within a threshold of the scene geometry but does
 * not make a direct hit.
 *
 * The outline/border thickness is calculated in world-units and thus will
 * vary in size based on depth. 
 *
 * This approach does not produce internal outlines, but that may be desireable.
 *
 * Pros:
 *
 *     - Cheap, minor modification to raymarching loop to keep track of nearest passes.
 *     - No additional scene sampling.
 *     - Only approach with smooth external outline edges.
 *
 * Cons:
 *
 *     - Have to modify raymarch routine.
 *     - Only approach without internal edge outlining.
 *     - Jagged internal outline.
 *
 * -----------------------------------------------------------
 * - SDF Offset Differences
 * - Outline_OffsetDifference()
 * -----------------------------------------------------------
 *
 * Calculates the difference between a raymarch sample and two offset samples.
 * If the difference in depth between the samples is within a threshold, then
 * it is part of an outline.
 *
 * This approach requires an additional two samples of the scene, which may
 * be expensive depending on the shader. It is also has controls for outline 
 * appearance in both UV-space (pixel may be used, but UV produces a smoother 
 * result) and world-space.
 *
 * Pros:
 *
 *     - Partial internal edge outlining.
 *     - Some internal outline edges are smooth.
 *     - Requires no modification of existing raymarch routine.
 *
 * Cons:
 *
 *     - Potentially trickier to calibrate for a given scene
 *     - Requires two additional scene marches.
 *
 * -----------------------------------------------------------
 * - SDF Edge Detection
 * - Outline_EdgeDetection()
 * -----------------------------------------------------------
 *
 * Detects SDF edges by keeping track of previous SDF values. If the ray
 * is moving away from a surface and it passed within a threshold of that
 * surface, then it is an outline.
 *
 * The controls for this outline are solely in world-space units (edge threshold).
 *
 * Both this approach and Offset Difference produce a partial internal outlining
 * that give a stroke/pen appearance that may be desired.
 *
 * Pros:
 *
 *     - Partial internal edge outlining.
 *     - Cheap, no additional samples or calculations outside of the march.
 *
 * Cons:
 *
 *     - Have to modify raymarch routine.
 *     - Jagged outline.
 *
 * -----------------------------------------------------------
 * - Surface ID Difference
 * - Outline_SurfaceIDDifference()
 * -----------------------------------------------------------
 *
 * The only approach that is not based on SDF values but instead on surface/material IDs. 
 * While defining the scene, must provide each surface/subset with a unique ID. During
 * the outlining, offsets into the scene are sampled. If the offsets have different IDs
 * then an outline edge is found.
 *
 * While this does not require modification to the raymarch itself, and the outline 
 * calculation is similar to SDF Offset Differences, it does potentially require a lot
 * of changes to the scene definition. But if you are already defining your scene with
 * material/surface IDs then no work may need to be done.
 *
 * Pros:
 *
 *     - Nearly full control over edge definitions.
 *     - Provides full external and internal outlining.
 *
 * Cons:
 *
 *     - Have to manually define surfaces.
 *     - Jagged edges.
 * 
 * -----------------------------------------------------------
 * - References
 * -----------------------------------------------------------
 * 
 * While I know that these different approaches are used in other ShaderToys,
 * the only one that was directly referenced/sourced was:
 *
 *     'Bender' - iq
 *      https://www.shadertoy.com/view/4slSWf
 *
 *      I initially thought that 'SDF Offset Differences' was being used in this shader,
 *      but after experimentation I saw it was completely different approach which
 *      is  called 'Surface ID Differences' in this shader for lack of a proper name.
 */

#define NearClip          0.0
#define Epsilon           0.01
#define FarClip           10.0
#define MaxSteps          100
#define PI                3.14159265
#define NearMissThreshold 0.045     // Used in SDF Near-Miss. World-Space.
#define EdgeThresold      0.03      // Used in SDF Edge Detection. World-Space.
#define UVOffset          0.003     // Used in SDF Offset Differences and Surface ID Differences. UV-Space.

      vec3 CamOrigin       = vec3(0.0);
const vec3 CamLookAt       = vec3(0.0, 1.05, 0.0);
const vec3 BackgroundColor = vec3(0.0, 0.335, 0.582);
const vec3 SunDir          = normalize(vec3(0.5, 2.5, 1.25));
const vec3 SunColor        = vec3(1.0, 1.0, 0.7);
const vec3 SkyDir          = normalize(vec3(0.0, 1.0, 0.0));
const vec3 SkyColor        = vec3(0.0, 0.0, 1.0);
const vec3 AmbDir          = normalize(SunDir * vec3(-1.0, 0.0, -1.0));
const vec3 AmbColor        = vec3(1.0, 1.0, 1.0);

//------------------------------------------------------------------------------------------
// Ray / Camera
//------------------------------------------------------------------------------------------

struct Ray
{
	vec3 o;
    vec3 d;
};

Ray Ray_LookAt(in vec2 uv, in vec3 o, in vec3 d)
{
    vec3 forward = normalize(d - o);
    vec3 right   = normalize(cross(forward, vec3(0.0, 1.0, 0.0)));
    vec3 up      = normalize(cross(right, forward));

    uv    = (uv * 2.0) - 1.0;
    uv.x *= (iResolution.x / iResolution.y);

    Ray ray;
    ray.o = o;
    ray.d = normalize((uv.x * right) + (uv.y * up) + (forward * 2.0));

    return ray;
}

//------------------------------------------------------------------------
// Scene
//------------------------------------------------------------------------

vec3  RotX(in vec3 p, float a)        { float s = sin(a); float c = cos(a); return vec3(p.x, (c * p.y) - (s * p.z), (s * p.y) + (c * p.z)); }
vec3  Repeat(vec3 p, vec3 c)          { return mod(p, c) - (0.5 * c); }
float smin(float a, float b, float k) { float h = clamp(0.5 + 0.5 * (b - a) / k, 0.0, 1.0); return mix(b, a, h) - k*h*(1.0 - h); }
float Box(vec3 p, vec3 b)             { vec3 d = abs(p) - b; return min(max(d.x,max(d.y,d.z)),0.0) + length(max(d,0.0)); }
float Sphere(vec3 p, float r)         { return length(p) - r; }
float Cylinder(vec3 p, vec2 h)        { vec2 d = abs(vec2(length(p.xz),p.y)) - h; return min(max(d.x,d.y),0.0) + length(max(d,0.0)); }
vec2  U(vec2 a, vec2 b)               { return (a.x < b.x) ? a : b; }
vec2  S(vec2 d2, vec2  d1 )           { return (-d1.x>d2.x)?-d1:d2; }

/**
 * Returns (SDF value, Surface ID)
 */
vec2 ShaderBall(vec3 pos)
{
    vec3 spos = pos - vec3(0.0, 1.5, 0.0);

    vec2 ts   = vec2(max(Sphere(spos, 1.0), -Sphere(spos, 0.8)), 9.0);                // Hollow top sphere
    vec2 tsi  = vec2(Sphere(spos, 0.725), 2.0);                                       // Inner sphere core
    vec2 tsc  = vec2(Sphere(spos - vec3(0.0, 0.4, 0.8), 0.55), 3.0);                  // Cut into side of top sphere
    vec2 rc   = vec2(Box(RotX(spos, PI * 0.15), vec3(2.0, 0.05, 2.0)), 4.0);          // Ring cut into top sphere

    vec2 st   = vec2(Cylinder(pos - vec3(0.0, 0.1, 0.0), vec2(mix(0.8, 0.3, clamp(pos.y - 0.125, 0.0, 1.0)), 0.2)), 5.0);  // Stand wide base      
    vec2 stc  = vec2(Cylinder(Repeat(pos, vec3(0.5, 0.0, 0.5)), vec2(0.125, 1.0)), 6.0);                                   // Stand ridge cuts
    vec2 stm  = vec2(Cylinder(pos - vec3(0.0, 0.35, 0.0), vec2(0.5, 0.35)), 5.0); // Thinner stand middle

    st   = S(st, stc);
    st.x = smin(st.x, stm.x, 0.2);                         

    vec2 b    = vec2(Cylinder(pos - vec3(0.0, 0.025, 0.0), vec2(1.0, 0.025)), 8.0);    // Base

    vec2 result = S(ts, tsc);
         result = S(result, rc);
         result = U(result, tsi);
         result = U(result, st);
         result = U(result, b);

    return result;
}

