float material;
float glow;
vec3 mouse;

// fractal brownian motion https://thebookofshaders.com/13/
vec3 fbm (vec3 p)
{
    vec3 result = vec3(.0);
    float a = .5;
    for (float i = 0.; i < 3.; ++i) {
        p.y += iTime*.005/a;
        result += sin(texture(iChannel1, p/a).xyz*6.28)*a;
        a /= 2.;
    }
    return result;
}

// signed distance function
float map(vec3 p)
{
    float dist = 100.;
    float shape = 100.;
    vec3 pp = p;
    float c;

    // sphere
    dist = length(p)-1.;

    // droplets
    c = pModPolar(p.xz, 8.);
    vec3 rng = hash31(c);
    p.x -= 1.-.5;
    rng.x += sign(p.x)*.5;
    p.x = abs(p.x)-.2;
    p.y *= -1.;
    float time = iTime * .2 + rng.x;
    float anim = fract(time);
    float index = floor(time);
    float wave = sin(anim*3.14);
    float h = .7+.3*pow(wave, 4.);
    float s = .03-.03*(1.-wave);
    shape = sdSegment(p, h, s);
    dist = smin(dist, shape, .2);
    shape = length(p-vec3(0,pow(anim, 10.)*200.+h,0))-.05;
    dist = smin(dist, shape, .3*pow(anim,0.5));

    // sphere mouse interaction
    dist = smin(dist, length(pp+mouse)-.1, .6);

    // surface details
    vec3 seed = pp*.1;
    vec3 noise = fbm(seed);
    dist -= noise.x*.01;

    return dist * .5;
}

void coloring (inout vec3 color, in vec3 pos, in vec3 normal, in vec3 ray, in vec2 uv, in float shade)
{
    // Inigo Quilez color palette
    // https://iquilezles.org/www/articles/palettes/palettes.htm
    vec3 tint = 1.5+.5*cos(vec3(1,.3,6)*6.283+iTime*.2+uv.y*3.);

    // lighting
    color = tint * pow(dot(normal, vec3(0,-1,0))*.5+.5, 10.);
    vec3 rf = reflect(ray, normal);
    float top = dot(rf, vec3(0,1,0))*.4+.5;
    float glow = dot(normal, ray)*.7+.5;
    color += vec3(0.7,.2,0.7)*pow(clamp(top,0.,1.), 1.5); // edit sphere color
    color += vec3(4,1,1)*pow(glow, 2.);
    color *= pow(shade,.5);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (fragCoord-iResolution.xy/2.)/iResolution.y;

    // background
    vec3 color = vec3(.2)*smoothstep(2.,.5,length(uv));

    // coordinates
    vec3 pos = vec3(0,0,3);
    vec3 at = vec3(0);
    pos.zy *= rot(sin(iTime*.2)*.1);
    vec3 ray = lookAt(pos, at, uv, 1.);

    // mouse interaction
    if (iMouse.z > 0.5) {
        vec2 uvm = (iMouse.xy-iResolution.xy/2.)/iResolution.y;
        mouse = vectorAt(pos, at, uvm*2., -1.) * -1.;
    }
    else mouse = vec3(0);

    // noise
    //vec3 blue = texture(iChannel0, fragCoord/1024.).xyz;
    //vec3 white = hash33(vec3(fragCoord, iFrame));

    // materialing
    material = 0.;
    glow = 0.;
    float maxDist = 4.;

    // raymarch
    const float count = 50.;
    float steps = 0.;
    float total = 0.;
    for (steps = count; steps > 0.; --steps) {
        float dist = map(pos);
        if (dist < total/iResolution.y || total > maxDist) break;
        dist *= 0.9+0.1;
        ray += total*.002;
        pos += ray * dist;
        total += dist;
    }

    // NuSan https://www.shadertoy.com/view/3sBGzV
    vec2 noff = vec2(.001,0);
    vec3 normal = normalize(map(pos)-vec3(map(pos-noff.xyy), map(pos-noff.yxy), map(pos-noff.yyx)));

    // coloring
    float shade = steps/count;
    if (shade > .001 && total < maxDist) {
        coloring(color, pos, normal, ray, uv, shade);
    }

    fragColor = vec4(color, 1);
}

#define repeat(p,r) (mod(p,r)-r/2.)
mat2 rot(float a) { return mat2(cos(a),-sin(a),sin(a),cos(a)); }
vec3 lookAt (vec3 from, vec3 at, vec2 uv, float fov)
{
  vec3 z = normalize(at-from);
  vec3 x = normalize(cross(z, vec3(0,1,0)));
  vec3 y = normalize(cross(x, z));
  return normalize(z * fov + uv.x * x + uv.y * y);
}
vec3 vectorAt (vec3 from, vec3 at, vec2 uv, float fov)
{
  vec3 z = normalize(at-from);
  vec3 x = normalize(cross(z, vec3(0,1,0)));
  vec3 y = normalize(cross(x, z));
  return (z * fov + uv.x * x + uv.y * y);
}
// Mercury
// https://mercury.sexy/hg_sdf/
float pModPolar(inout vec2 p, float repetitions) {
	float angle = 6.28/repetitions;
	float a = atan(p.y, p.x) + angle/2.;
	float r = length(p);
	float c = floor(a/angle);
	a = mod(a,angle) - angle/2.;
	p = vec2(cos(a), sin(a))*r;
	// For an odd number of repetitions, fix cell index of the cell in -x direction
	// (cell index would be e.g. -5 and 5 in the two halves of the cell):
	if (abs(c) >= (repetitions/2.)) c = abs(c);
	return c;
}

// Inigo Quilez
// https://iquilezles.org/articles/distfunctions/
float sdBox( vec3 p, vec3 b )
{
  vec3 q = abs(p) - b;
  return length(max(q,0.0)) + min(max(q.x,max(q.y,q.z)),0.0);
}
float sdTorus( vec3 p, vec2 t )
{
  vec2 q = vec2(length(p.xz)-t.x,p.y);
  return length(q)-t.y;
}
float sdSegment( vec3 p, float h, float r )
{
  p.y -= clamp( p.y, 0.0, h );
  return length( p ) - r;
}
float sdLink( vec3 p, float le, float r1, float r2 )
{
  vec3 q = vec3( p.x, max(abs(p.y)-le,0.0), p.z );
  return length(vec2(length(q.xy)-r1,q.z)) - r2;
}
float sdCappedTorus(in vec3 p, in vec2 sc, in float ra, in float rb)
{
  p.x = abs(p.x);
  float k = (sc.y*p.x>sc.x*p.y) ? dot(p.xy,sc) : length(p.xy);
  return sqrt( dot(p,p) + ra*ra - 2.0*ra*k ) - rb;
}
float smin( float d1, float d2, float k ) {
    float h = clamp( 0.5 + 0.5*(d2-d1)/k, 0.0, 1.0 );
    return mix( d2, d1, h ) - k*h*(1.0-h); }


// blackle
// https://suricrasia.online/demoscene/functions/
vec3 erot(vec3 p, vec3 ax, float ro) {
  return mix(dot(ax, p)*ax, p, cos(ro)) + cross(ax,p)*sin(ro);
}
vec3 rndrot(vec3 p, vec4 rnd) {
  return erot(p, normalize(tan(rnd.xyz)), rnd.w*3.1415);
}

// Dave Hoskins
// https://www.shadertoy.com/view/4djSRW
float hash11(float p)
{
    p = fract(p * .1031);
    p *= p + 33.33;
    p *= p + p;
    return fract(p);
}
vec3 hash31(float p)
{
   vec3 p3 = fract(vec3(p) * vec3(.1031, .1030, .0973));
   p3 += dot(p3, p3.yzx+33.33);
   return fract((p3.xxy+p3.yzz)*p3.zyx); 
}
vec3 hash33(vec3 p3) {
	p3 = fract(p3 * vec3(.1031, .1030, .0973));
    p3 += dot(p3, p3.yxz+33.33);
    return fract((p3.xxy + p3.yxx)*p3.zyx);
}
vec4 hash41(float p)
{
	vec4 p4 = fract(vec4(p) * vec4(.1031, .1030, .0973, .1099));
    p4 += dot(p4, p4.wzxy+33.33);
    return fract((p4.xxyz+p4.yzzw)*p4.zywx);

}

// Temporal Anti Aliasing from:
// https://www.elopezr.com/temporal-aa-and-the-quest-for-the-holy-trail/

// but only the color clamping...

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord.xy / iResolution.xy;
    vec3 color = texture(iChannel0, uv).rgb;
    vec3 temporal = texture(iChannel1, uv).rgb;
    vec3 minColor = vec3(9999.), maxColor = vec3(-9999.);
    for(int x = -1; x <= 1; ++x){
        for(int y = -1; y <= 1; ++y){
            vec3 c = texture(iChannel0, uv + vec2(x, y) / iResolution.xy).rgb;
            minColor = min(minColor, c);
            maxColor = max(maxColor, c);
        }
    }
    temporal = clamp(temporal, minColor, maxColor);
    fragColor.rgb = mix(color, temporal, 0.9);
    fragColor.a = 1.0;
}

float SphereDist(vec3 ro, vec3 rd, vec3 center, float r) {
    vec3 oc = center - ro;
    float lenOC = length(oc);
    if (lenOC < r) {
        return -1.; // ro is inside the sphere.
    }
    float lenProjedOC = dot(oc, rd);
    if (lenProjedOC < 0.) {
        return -1.;
    }
    vec3 projedOC = rd * lenProjedOC;
    vec3 perpendicular = oc - projedOC;
    float lenPerpendicular = length(perpendicular);
    if (lenPerpendicular > r) {
        return -1.;
    }
    float dist = lenProjedOC - sqrt(r*r - lenPerpendicular * lenPerpendicular);
    return dist;
}

vec3 SphereNormal(vec3 p, vec3 center) {
    return normalize(p - center);
}

vec3 SphereTangent(vec3 pos, vec3 normal) {
    vec3 posOffseted = pos;
    posOffseted.y += 1.;
    float D = - dot(normal, pos);
    float distToPlane = dot(normal, posOffseted) + D;
    vec3 proj = posOffseted - normal * distToPlane;
    vec3 tangent = normalize(proj - pos);
    return tangent;
}

vec3 ViewDir(vec2 fragCoord, float fov) {
    vec2 xy = fragCoord - iResolution.xy * .5;
    float z = iResolution.y * .5 / tan(radians(fov * .5));
    return normalize(vec3(xy, -z));
}

mat3 ViewToWorldMat(vec3 ro, vec3 target, vec3 up) {
    vec3 front = normalize(target - ro);
    vec3 right = normalize(cross(front, up));
    up = cross(right, front);
    return mat3(right, up, -front);
}

vec3 ShiftTangent(vec3 tangent, vec3 normal, float shift) {
    vec3 shiftedTangent = tangent + normal * shift;
    return normalize(shiftedTangent);
}

const int SHIFT_KEY = 16;

void mainImage( out vec4 fragColor, in vec2 fragCoord ) {
    vec3 col = vec3(0.);

    vec3 ro = vec3(0., 1.5, 4.1);
    // turing camera aroung when shift is pressing.
    {

        if (texelFetch( iChannel1, ivec2(SHIFT_KEY,0), 0 ).x > 0.) {
            ro = vec3(4.1*cos(iTime), 1.5, 4.1*sin(iTime));
        }        
    }
    vec3 rd = ViewDir(fragCoord, 45.);
    mat3 invViewMat = ViewToWorldMat(ro, vec3(0.,0.,0.), vec3(0.,1.,0.));
    rd = invViewMat * rd;

    vec4 sphere = vec4(vec3(0., 0., 0.), 1.);

    float dist = SphereDist(ro, rd, sphere.xyz, sphere.w);

    if (dist > 0.) {
        vec3 lightColor = vec3(1.,1.,1.);
        vec3 albedo = vec3(1.,.2,.2);
        vec3 specColor = vec3(1.,1.,1.);
        vec3 lightDir = normalize(vec3(0.,.5,1.));
        vec3 pos = ro + rd * dist;
        vec3 normal = SphereNormal(pos, sphere.xyz);
        float nl = dot(normal, lightDir);
        vec3 viewDir = -rd;
        vec3 halfDir = normalize(viewDir + lightDir);

#if 0
        // Blinn-Phong specular highlight
        float nh = dot(normal, halfDir);
        float spec = pow(nh, 400.);        
        col += nl * lightColor * albedo + nl * specColor * spec;
#else
        // anisotropic highlighting
        // http://web.engr.oregonstate.edu/~mjb/cs519/Projects/Papers/HairRendering.pdf

        vec3 tangent = SphereTangent(pos, normal);
        float shift = texelFetch(iChannel0, ivec2(0), 0).r;

        shift = shift * 2. - 1.;
        tangent = ShiftTangent(tangent, normal, shift);

        float dotTH = dot(tangent, halfDir);
        float sinTH = sqrt(1. - dotTH * dotTH);
        float dirAtten = smoothstep(-1., 0., dotTH);

        // Kajiya-Kay Model
        col += nl * lightColor * albedo + step(0., nl) * dirAtten * specColor * pow(sinTH, 400.);
#endif
    }

    // GUI
    vec2 uv = (fragCoord - .5) / iResolution.xy;
    vec4 gui = texture(iChannel0, uv);
    col = mix(col, gui.rgb, gui.a);
    fragColor = vec4(col,1.0);
}

