//------------------------------------------------------------------

vec3 hexagon_pattern( vec2 p ) 
{
	vec2 q = vec2( p.x*2.0*0.5773503, p.y + p.x*0.5773503 );

	vec2 pi = floor(q);
	vec2 pf = fract(q);

	float v = mod(pi.x + pi.y, 3.0);

	float ca = step(1.0,v);
	float cb = step(2.0,v);
	vec2  ma = step(pf.xy,pf.yx);

	return vec3( pi + ca - cb*ma, dot( ma, 1.0-pf.yx + ca*(pf.x+pf.y-1.0) + cb*(pf.yx-2.0*pf.xy) ) );
}

//------------------------------------------------------------------

const vec2 torus = vec2(0.5,0.2);

#define NumTiles 3

//------------------------------------------------------------------

float map( in vec3 p )
{
    // torus
    float d = length( vec2(length(p.xz)-torus.x,p.y) )-torus.y;

    // displace torus
    vec2 uv = vec2(atan(p.z,p.x),atan(length(p.xz)-torus.x,p.y) )*vec2(3.0*sqrt(3.0),2.0)/3.14159;
    uv = uv*float(NumTiles) + vec2(0.0,0.5*iTime);
    vec3 h = hexagon_pattern( uv );
    float f = mod(h.x+2.0*h.y,3.0)/2.0;
    d += f*0.04;

    return d;
}

vec2 castRay( in vec3 ro, in vec3 rd )
{
    // plane
    float tmax = (-torus.y-ro.y)/rd.y;

    // torus
    float t = 0.7;
    float m = 2.0;
    for( int i=0; i<256; i++ )
    {
	    float precis = 0.0004*t;
	    float res = map( ro+rd*t );
        if( res<precis || t>tmax ) break;
        t += res*0.25;
    }

    if( t>tmax ) { t=tmax; m=1.0; }
    return vec2( t, m );
}

float calcSoftshadow( in vec3 ro, in vec3 rd )
{
	float res = 1.0;
    float t = 0.02;
    for( int i=0; i<128; i++ )
    {
		float h = map( ro + rd*t )*0.2;
        res = min( res,24.0*h/t );
        t += clamp( h, 0.005, 0.02 );
        if( res<0.001 || t>0.8 ) break;
    }
    return smoothstep( 0.0, 1.0, res );
}

vec3 calcNormal( in vec3 pos )
{
    vec2 e = vec2(1.0,-1.0)*0.5773*0.0005;
    return normalize( e.xyy*map( pos + e.xyy ) + 
					  e.yyx*map( pos + e.yyx ) + 
					  e.yxy*map( pos + e.yxy ) + 
					  e.xxx*map( pos + e.xxx ) );
}

vec3 render( in vec3 ro, in vec3 rd )
{ 
    vec2  res = castRay(ro,rd);
    float t   = res.x;
    vec3  pos = ro + t*rd;
    vec3  nor = vec3(0.0,1.0,0.0);
    float occ = 1.0;
    float ks  = 0.0;
    vec3  col = vec3(0.0,0.0,0.0);

    // material        
    if( res.y<1.5 )
    {
        // texture
        vec3 te = texture(iChannel0,pos.xz*0.5).xyz;
        col = 0.02 + te*0.2;
        ks = te.x;
        // fake occlusion
        occ = smoothstep(0.06,0.4, abs(length(pos.xz)-torus.x) );
    }
    else
    {
        nor = calcNormal( pos );
        occ = 0.5+0.5*nor.y;

        vec2 uv = vec2( atan(pos.z,pos.x), atan(length(pos.xz)-torus.x,pos.y) )*
                  vec2(3.0*sqrt(3.0), 2.0)/3.14159;
        uv = uv*float(NumTiles) + vec2(0.0,0.5*iTime);
        vec3 h = hexagon_pattern( uv );
        float f = mod(h.x+2.0*h.y,3.0)/2.0;

        // cell color
        col = vec3(1.0-f);
        float hh = abs(sin(10.0*mod(h.x+h.y*2.0,24.0)));
        if( f<0.1 ) col = 0.12+0.12*cos(hh+vec3(0.0,2.0,2.0));

        // cell borders
        col *= 0.7+h.z;

        // texture
        vec3 te = texture( iChannel0, 0.2*uv ).xyz;
        col *= 0.08+0.72*te;
        ks = te.x;
    }

    // lighting
    vec3  lig = normalize( vec3(0.4, 0.5, -0.6) );
    vec3  hal = normalize( lig-rd );
    float amb = clamp( 0.5+0.5*nor.y, 0.0, 1.0 );
    float dif = clamp( dot( nor, lig ), 0.0, 1.0 );
    float bac = clamp( dot( nor, normalize(vec3(-lig.x,0.0,-lig.z))), 0.0, 1.0 )*clamp( 1.0-pos.y,0.0,1.0);

    //if( dif>0.0001 )
    //dif *= calcSoftshadow( pos, lig );

    float spe = pow( clamp( dot( nor, hal ), 0.0, 1.0 ),32.0)*
                dif *
                (0.04 + 0.96*pow( clamp(1.0+dot(hal,rd),0.0,1.0), 5.0 ));

    vec3 lin = vec3(0.0);
    lin += 3.00*dif*vec3(1.10,0.90,0.60);
    lin += 0.40*amb*vec3(0.30,0.60,1.50)*occ;
    lin += 0.30*bac*vec3(0.40,0.30,0.25)*occ;
    col = col*lin;
    col += 5.00*spe*vec3(1.15,0.90,0.70)*ks*ks*4.0;

	return col;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 mo = iMouse.xy/iResolution.xy;


    // camera	
    vec3 ro = vec3( 1.1*cos(0.05*iTime + 6.0*mo.x), 0.9, 1.1*sin(0.05*iTime + 6.0*mo.x) );
    vec3 ta = vec3( 0.0, -0.2, 0.0 );
    // camera-to-world transformation
    vec3 cw = normalize(ta-ro);
    vec3 cu = normalize( cross(cw,vec3(0.0, 1.0,0.0)) );
    vec3 cv = normalize( cross(cu,cw) );

    vec3 tot = vec3(0.0);
	#if AA>1
    for( int m=0; m<AA; m++ )
    for( int n=0; n<AA; n++ )
    {
        // pixel coordinates
        vec2 o = vec2(float(m),float(n)) / float(AA) - 0.5;
        vec2 p = (-iResolution.xy + 2.0*(fragCoord+o))/iResolution.y;
		#else    
        vec2 p = (-iResolution.xy + 2.0*fragCoord)/iResolution.y;
		#endif

        // ray direction
        vec3 rd = normalize( p.x*cu + p.y*cv + 2.0*cw );

        // render	
        vec3 col = render( ro, rd );

		// gamma
        col = pow( col, vec3(0.4545) );

        tot += col;
	#if AA>1
    }
    tot /= float(AA*AA);
	#endif
/*
    // color grading
    tot = 1.25*pow(tot,vec3(0.65,0.9,1.0) );

    // vignetting    
    vec2 q = fragCoord/iResolution.xy;
    tot *= 0.3 + 0.7*pow(16.0*q.x*q.y*(1.0-q.x)*(1.0-q.y),0.25);*/

    fragColor = vec4( tot, 1.0 );
}

#define LIGHT vec3(00,000,8000)
#define IOR 2.407 //index of refraction: 2.407 violet, 2.42 yellow (standard), 2.451 red
#define IOR2 (IOR + .0044)
#define DISPERSION 30.0
#define D DISPERSION
#define BRIGHT 10.0
const float PI = (355./113.);
const vec2 u = vec2(.1,0);

float hash(float n) {return fract(n*fract(n*.133929));}

vec2 rotate(vec2 p, float a) {return vec2 (cos(a)*p.x - sin(a)*p.y, sin(a)*p.x + cos(a)*p.y);}

float line_sdf(vec3 p, vec3 a, vec3 b)
{
    b-=a;
    p-=a;
    float angxy = -atan(b.y,b.x);
    p.xy = rotate(p.xy, angxy);
    b.xy = rotate(b.xy, angxy);
    float angxz = -atan(b.z,b.x);
    p.xz = rotate(p.xz, angxz);
    return length(p.yz);   
}

float dist (vec2 a, vec2 b)
{
    return (a.x-b.x)*(a.x-b.x)+(a.y-b.y)*(a.y-b.y);
}

//"pyramid" distance function (a cone with planar sides)
//the pyramid tip is (0,0,0), the pyramid shares its axis with the global x-axis
//p: point being sampled
//ang3: angle of p around the x-axis (0.0 - 1.0, precalculated)

//s: number of sides
//t: tilt angle (radians)
//o: offset of pyramid (offset along x-axis)
//r: rotation around x-axis (0.0 - 1.0)
//h: height (offset along surface normal)
float pyramid(vec3 p, float ang3, float s, float t, float o, float r, float h)
{
    ang3 = round((ang3+r)*s)/s-r;
    ang3 = ang3*PI*2.0;
    p.yz = rotate(p.yz,-ang3);
    p.x += o;
    p.xy = rotate(p.xy,t);
    return p.y-h;
}

float scene(vec3 p)
{
    if(length(p)>400.0)return length(p)-350.0;

    float ang3 = atan(p.z,p.y)/(PI*2.0);  //angle of p around x axis  0.0 - 1.0

    //make our diamond cuts out of six pyramids
    float t7 = pyramid(p,ang3,16.0,-PI/2.0,355.,0.0,0.0); //culet
    float t1 = pyramid(p,ang3,16.0,-(PI/2.0-.722),361.4,0.0,0.0); //lower girdle facets
    float t11 = pyramid(p,ang3,8.0,-(PI/2.0-.705),357.2,1.0/32.0,0.0); //pavilion main facets

    float t5 = pyramid(p,ang3,16.0,0.0,0.0,-1.0/32.0,290.0); //girdle

    float adjust_top = -10.0;

    float t2 = pyramid(p,ang3,16.0,PI/2.0-.71,-146.0+adjust_top,0.0,0.0); //upper girdle facets
    float t3 = pyramid(p,ang3,8.0,PI/2.0-.602,-100.85+adjust_top,1.0/32.0,0.0); //kite facets
    float t4 = pyramid(p,ang3,8.0,PI/2.0-.35,-41.85+adjust_top,-1.0/32.0,0.0); //star facets

    float t6 = pyramid(p,ang3,16.0,PI/2.0,15.0+adjust_top,0.0,0.0); //top

    return max(max(max(max(max(max(max(t1,t11),t2),t3),t4),t5),t6),t7); 
}

float calc(inout vec3 p, vec3 ps, inout vec3 norm) 
{
    float min_d = 100000.0;
    for(int i = 0; i < 80; i++)
    {
        float dist = scene(p);
        min_d = min(dist, min_d);
        p+=dist*ps;
        if(dist<.1)break;
    }
    if(min_d>.1)return 1000.0;
    norm = normalize(vec3(scene(p+u.xyy)-scene(p-u.xyy), scene(p+u.yxy)-scene(p-u.yxy), scene(p+u.yyx)-scene(p-u.yyx)));
    return min_d;
}

float light(vec3 p, vec3 ps, vec3 l)
{
        float ldist = line_sdf(l,p,p+ps);
        ldist = clamp((1.0-ldist/1000.0),0.0,1.0);
        return ldist*ldist*ldist*float(dot(ps,normalize(l-p))>0.0)*2.0;
}

vec3 cam(vec3 p)
{
    float s = sin(iTime*.1);
    s=mod(iTime*.1,2.0);
    s-=1.0;
    s = (1.0-pow(1.0-abs(s),6.0))*sign(s);
    s*=PI;
    s+=PI;
    p.xz = rotate(p.xz,-PI*.5+sin(iTime*.5)*PI*.25-s);
    p.xy = rotate(p.xy,-PI*.25+cos(iTime*.5)*PI*.15);
    return p;
}
vec3 icam(vec3 p)
{
    float s = sin(iTime*.1);
    s=mod(iTime*.1,2.0);
    s-=1.0;
    s = (1.0-pow(1.0-abs(s),6.0))*sign(s);
    s*=PI;
    s+=PI;
    p.xy = rotate(p.xy,PI*.25-cos(iTime*.5)*PI*.15);
    p.xz = rotate(p.xz,PI*.5-sin(iTime*.5)*PI*.25-iTime*.05+s);
    return p;
}
void mainImage( out vec4 F, in vec2 C )
{
    F = vec4(0);

    //lighting
    vec3 l=cam(LIGHT);


    //start marching
    vec3 p = cam(vec3(0,0,1200));
    vec3 ps = cam(normalize((vec3((C-iResolution.xy*.5)/iResolution.y,-1.2))));

    vec3 norm;
    float min_d = calc(p,ps,norm);

    if(min_d==1000.0||min_d > .1)
    {
        F=texture(iChannel0,icam(ps));
        return;
    } 

    //refract into diamond
    vec3 p3 = p;
    vec3 ps3 = normalize(refract(ps,norm,1.03/IOR));
    p3+=ps3*2500.0;
    ps3=-ps3;
    vec3 norm3;
    float min_d3 = calc(p3,ps3,norm3);

    vec3 p4 = p;
    vec3 ps4 = normalize(refract(ps,norm,1.03/IOR2));
    p4+=ps4*2500.0;
    ps4=-ps4;
    vec3 norm4;
    float min_d4 = calc(p4,ps4,norm4);
    float remaining_light = .8;

    //bounce around inside diamond
    for (int i = 0; i < 10; i++)
    {
        vec3 ps_old = ps3;
        ps3 = refract(-ps_old,-norm3,IOR/1.03);
        float r0 = (1.03-IOR)/(1.03+IOR);
        r0*=r0;

        vec3 pss_old = ps4;
        ps4 = refract(-pss_old,-norm3,IOR2/1.03);
        float r00 = (1.03-IOR2)/(1.03+IOR2);
        r00*=r00;

        if((ps3!=vec3(0))) //check for total internal reflection
        {
            float refract_amount = 1.0-(r0+(1.0-r0)*pow((1.0-dot(-ps_old,norm3)),5.0)); //Fresnel transmittance using Schlick's approximation
                                                                                        //taken directly from here: https://en.wikipedia.org/wiki/Schlick%27s_approximation
            float rrr = texture(iChannel0,icam(normalize(ps3+(ps4-ps3)*D)),4.).b;       //taken directly from here: https://en.wikipedia.org/wiki/Schlick%27s_approximation
            float ggg = texture(iChannel0,icam(normalize(ps3+(ps4-ps3)*D*.5)),4.).b;    //taken directly from here: https://en.wikipedia.org/wiki/Schlick%27s_approximation
            float bbb = texture(iChannel0,icam(normalize(ps3)),4.).b;  
            F.r+=pow(rrr,2.2)*refract_amount*remaining_light;
            F.g+=pow(ggg,2.2)*refract_amount*remaining_light;
            F.b+=pow(bbb,2.2)*refract_amount*remaining_light;
            F.r+=BRIGHT*light(p3,normalize(ps3+(ps4-ps3)*D),l)*refract_amount*remaining_light;
            F.g+=BRIGHT*light(p3,normalize(ps3+(ps4-ps3)*D*.5),l)*refract_amount*remaining_light;
            F.b+=BRIGHT*light(p3,normalize(ps3),l)*refract_amount*remaining_light;
            remaining_light-=refract_amount*remaining_light;
            if(remaining_light<0.1)break;       
        }

        ps3=normalize(reflect(-ps_old,-norm3));
        p3+=ps3*2500.0;
        ps3=-ps3;

        ps4=normalize(reflect(-pss_old,-norm3));
        p4+=ps4*2500.0;
        ps4=-ps4;

        min_d3 = calc(p3,ps3,norm3);
        if(min_d3>.1)break;

        min_d4 = calc(p4,ps4,norm4);

    }
    F.r+=pow(texture(iChannel0,icam(normalize(ps3+(ps4-ps3)*D)),4.).r,2.2)*remaining_light;
    F.g+=pow(texture(iChannel0,icam(normalize(ps3+(ps4-ps3)*D*.5)),4.).g,2.2)*remaining_light;
    F.b+=pow(texture(iChannel0,icam(normalize(ps3)),4.).b,2.2)*remaining_light;
    F.r+=BRIGHT*light(p3,normalize(ps3+(ps4-ps3)*D),l)*remaining_light;
    F.g+=BRIGHT*light(p3,normalize(ps3+(ps4-ps3)*D*.5),l)*remaining_light;
    F.b+=BRIGHT*light(p3,normalize(ps3),l)*remaining_light;


    //reflection
    vec3 p2 = p;
    vec3 ps2 = normalize(reflect(ps,norm));
    F*=.7; //~70% transmittance
    //reflected texture
    if(min_d <=.1) F+=pow(texture(iChannel0,icam(ps2)),vec4(2.2))*.2; //~30% reflectance

    //reflected specular
    float ldist = line_sdf(l,p2,p2+ps2);
    ldist = clamp((1.0-ldist/500.0),0.0,1.0);
    F += BRIGHT*.1*ldist*ldist*ldist*ldist*float(dot(ps2,l-p2)>0.0);

    //srgb
    F=pow(F,vec4(1./2.2));
}

// Just a pbr shader to test materials.

// aces tonemapper
vec3 ACES(vec3 x) {
    float a = 2.51;
    float b =  .03;
    float c = 2.43;
    float d =  .59;
    float e =  .14;
    return (x*(a*x+b))/(x*(c*x+d)+e);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // normalized pixel coordinates
    vec2 p = fragCoord/iResolution.xy;

    float w = texture(iChannel0, p).w; // numbers of renders

    // base texture with chromatic aberration
    vec2 off = (p-.5)*.00; // CA offset
    vec3 col = vec3(texture(iChannel0, p+off).r,
                    texture(iChannel0, p    ).g,
                    texture(iChannel0, p-off).b)/w;

    col = pow(col, vec3(.4545)); // gamma correction
    col = ACES(col); // tonemapping

    // color grading
    col = col*col*(3.-2.*col); // contrast
    col = 1.85*col/(1.+col); // highlighs rollof

    // vignette
    col *= .5+.5*pow(16. * p.x*p.y*(1.-p.x)*(1.-p.y), .1);

    // output
    fragColor = vec4(col,1.);
}

#define SKY_BOX 0

// vec2 to float hash
float hash(vec2 x) {
	float n = dot(x,vec2(127.1,311.7));
	return fract(sin(n)*4568.7564);
}

float seed; // randoms seed

// float hash
float hash(void) {return fract(sin(seed+=.1)*4568.7564);}

// normalized 3d vector
vec3 uniformVector() {
    float a = hash()*6.2831853;
    float x = hash()*2.-1.;
    float z = hash();

	return pow(z,1./3.)*vec3(sqrt(1.-x*x)*vec2(sin(a),cos(a)),x);
}

// random 3d vector
vec3 randomVector() {
    float a = hash()*6.2831853;
    float x = hash()*2.-1.;
    float z = hash();
    float w = sqrt(hash());

	return w*pow(z,1./3.) * vec3(sqrt(1.-x*x)*vec2(sin(a),cos(a)),x);
}

// cosine distribued diffuse brdf
// thanks to fizzer: http://www.amietia.com/lambertnotangent.html
vec3 cosineDirection(vec3 n) {
    float u = hash();
    float v = hash();

    float a = 6.283185*v;
    float b = u*2.-1.;
    vec3 rr = vec3(sqrt(1.-b*b)*vec2(cos(a),sin(a)),b);

    return normalize(n + rr);
}

// ray ellipsoid intersection function
// thanks to iq: https://iquilezles.org/articles/intersectors/
// sph[0] is the center of the ellipsoid and sph[1] is the size
vec4 elliIntersect(vec3 ro, vec3 rd, mat2x3 sph) {
    vec3 oc = ro - sph[0];
    vec3 r2 = sph[1]*sph[1];

    float a = dot(rd, rd/r2);
	float b = dot(oc, rd/r2);
	float c = dot(oc, oc/r2);
	float h = b*b - a*(c-1.); // discriminant

	if (h<0.) return vec4(-1);
    h = sqrt(h);
    float t = (-b-h) / a;
    vec3 n = normalize((oc + rd*t) / r2); // normal

    return vec4(t, n);
}

// ellipsoids
#define NUM_SPHERES 11
mat2x3 spheres[NUM_SPHERES];

// intersection function
float intersect(vec3 ro, vec3 rd, float tmax, out vec3 on, out float oid) {
    float t = tmax; // final distance

    for (int i=0; i<NUM_SPHERES; i++) {
        mat2x3 sph = spheres[i]; // current ellipsoid        
        vec4 tn = elliIntersect(ro, rd, sph); // distance and normal

        if (tn.x>0. && tn.x<t) {
            on = tn.yzw;
            oid = float(1 + i); // ellipsoid id
            t = tn.x;
        }
    }

    // plane
    float h = (-.5-ro.y)/rd.y;
    if (h>0. && h<t) {
        on = vec3(0,1,0);
        oid = 0.;
        t = h;
    }

    // output
    return t<tmax ? t : -1.;
}

// 2d texture function
// thanks to this great tutorial of the art of code:
// https://www.youtube.com/watch?v=VaYyPTw0V84
vec3 tex3D(sampler2D tex, vec3 p, vec3 n) {
    vec3 xy = texture(tex, p.xy).rgb;
    vec3 xz = texture(tex, p.xz).rgb;
    vec3 yz = texture(tex, p.yz).rgb;

    vec3 m = abs(n);
    return yz*m.x + xz*m.y + xy*m.z;
}

// texture bump mapping, thanks to Shane
// bf is the bump factor
vec3 texBump(sampler2D tex, vec3 p, vec3 n, float bf) {
    const vec2 e = vec2(.0001, 0); // epsilon

    // normal of the texture
    mat3 m = mat3(tex3D(tex, p - e.xyy, n),
                  tex3D(tex, p - e.yxy, n),
                  tex3D(tex, p - e.yyx, n));

    vec3 g = vec3(.299, .587, .114)*m; // luma
    g = (g - dot(tex3D(tex,  p , n), vec3(.299, .587, .114)))/e.x; 
    g -= n*dot(n, g);

    return g*bf;
}

vec3 skybox(vec3 rd) {
    #if SKY_BOX==0
    return pow(textureLod(iChannel1, rd, 0.).rgb, vec3(2.2));
    #else
    vec3 col = .3*mix(vec3(.4,.7,1), .5*vec3(.1,.3,.6), .5+.5*rd.y);
    col += 6.*step(.98,dot(rd, vec3(.57735)));
    return col;
    #endif
}

// rendering
vec3 render(vec3 ro, vec3 rd) {
    vec3 col = vec3(1); // final color

    for (int i=0; i<8; i++) { // 8 bounces of GI
        vec3 n; float id; // normal and id
        float t = intersect(ro, rd, 1e10, n, id); // distance

        // background
        if (t<0.) return col*skybox(rd);
        vec3 p = ro + rd*t;
        float fre = 1.+dot(rd, n); // fresnel

        if (id<.5) { // wood material
            vec3 bmp = texBump(iChannel3, p*.5, n, .0025);
            n = normalize(n + bmp);

            ro = p + n*.0001;

            float rou = .1; // roughness
            float ks = .1+.9*pow(fre, 5.)*(1.-rou); // reflectivity

            if (ks>hash()) { // rough reflection
                rd = normalize(reflect(rd, n) + rou*randomVector());
            } else { // diffuse
                col *= pow(tex3D(iChannel3, p*.5, n), vec3(1.5));
                rd = cosineDirection(n);
            }
        } else if (id<1.5) { // light
            return col*5.;
        } else if (id<2.5) { // orange plastic
            ro = p + n*.0001;

            float ks = .05+.95*pow(fre, 5.); // reflectivity
            if (ks>hash()) { // reflection
                rd = reflect(rd, n);
            } else { // diffuse
                col *= vec3(.9,.3,.1);
                rd = cosineDirection(n);
            }
        } else if (id<3.5) { // green plastic
            vec3 bmp = texBump(iChannel2, p*2., n, .04);
            n = normalize(n + bmp);

            ro = p + n*.0001;

            float rou = .6; // roughness
            float ks = .1+.9*pow(fre, 5.)*(1.-rou); // reflectivity

            if (ks>hash()) { // rough reflection
                rd = normalize(reflect(rd, n) + rou*randomVector());
            } else { // diffuse
                col *= vec3(.2,.6,.1);
                rd = cosineDirection(n);
            }
        } else if (id<4.5) { // rough metal
            vec3 bmp = texBump(iChannel3, p*.5, n, .003);
            n = normalize(n + bmp);

            col *= .9;
            ro = p + n*.0001;
            rd = reflect(rd, n);
        } else if (id<5.5) { // gold
            vec3 bmp = texBump(iChannel2, p*2., n, -.04);
            n = normalize(n + bmp);

            col *= vec3(.9,.7,.3);
            ro = p + n*.0001;
            rd = reflect(rd, n);
        } else if (id<6.5) { // light
            return col*5.;
        } else if (id<7.5) { // abstract (purple and gold)
            vec3 bmp = texBump(iChannel2, p*2., n, .1);
            n = normalize(n + bmp);

            ro = p + n*.0001;

            float h = tex3D(iChannel2, p*2., n).r;
            if (h<.6) { // diffuse
                col *= vec3(.3,.1,.9);
                rd = cosineDirection(n);
            } else { // gold
                col *= vec3(.9,.6,.3);
                rd = reflect(rd, n);
            }
        } else if (id<8.5) { // anisotropic metal (sort of)
            vec3 bmp = texBump(iChannel3, p, n, .0);
            n = normalize(n + bmp);

            vec3 rou = vec3(.4,1,.4); // roughness

            col *= vec3(.1,.3,.9);
            ro = p + n*.0001;
            rd = normalize(reflect(rd, n) + rou*randomVector());
        } else if (id<9.5) { // absorption
            float ior = 1.5; // refraction index

            // fresnel bias
            float f0 = (1.-ior)/(1.+ior);
            f0 = f0*f0;
            float ks = f0 + (1.-f0)*pow(fre, 5.); // reflectivity

            float s = -sign(fre-1.); // inside or outside

            if (ks>hash()) { // reflection
                ro = p+n*.0001;
                rd = reflect(rd, n);
            } else { // transmission
                if (s>0.) col *= exp(-.2*t*vec3(1,2,3)); // absorption
                ro = p - n*.001;
                rd = refract(rd, n, s<0. ? ior : 1./ior);
            }
        } else if (id<10.5) { // normal glass
            float ior = 1.5; // refraction index

            // fresnel bias
            float f0 = (1.-ior)/(1.+ior);
            f0 = f0*f0;
            float ks = f0 + (1.-f0)*pow(fre, 5.); // reflectivity

            float s = -sign(fre-1.); // inside or outside

            if (ks>hash()) { // reflection
                ro = p+n*.0001;
                rd = reflect(rd, n);
            } else { // transmission
                ro = p - n*.001;
                rd = refract(rd, n, s<0. ? ior : 1./ior);
            }
        } else if (id<11.5) { // emerald with gold
            vec3 bmp = texBump(iChannel2, p*2., n, .07);
            n = normalize(n + bmp);

            float h = tex3D(iChannel2, p*2., n).r;
            if (h<.65) { // emerald
                float ior = 2.4; // refraction index

                // fresnel bias
                float f0 = (1.-ior)/(1.+ior);
                f0 = f0*f0;
                float ks = f0 + (1.-f0)*pow(fre, 5.); // reflectivity

                float s = -sign(fre-1.); // inside or outside

                if (ks>hash()) { // reflection
                    ro = p+n*.0001;
                    rd = reflect(rd, n);
                } else { // transmission
                    if (s>0.) col *= exp(-.5*t*vec3(3,.2,2.5)); // absorption
                    ro = p - n*.001;
                    rd = refract(rd, n, s<0. ? ior : 1./ior);
                }
            } else { // gold
                col *= vec3(.9,.6,.3);
                ro = p + n*.0001;
                rd = reflect(rd, n);
            }
        }
    }

    // return black
    return vec3(0);
}

// camera function
mat3 setCamera(vec3 ro, vec3 ta) {
    vec3 w = normalize(ta - ro); // forward vector
    vec3 u = normalize(cross(w, vec3(0,1,0))); // side vector
    vec3 v = cross(u, w); // up vector
    return mat3(u, v, w);
}

#define SPP 5 // samples per pixel

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // setup scene
    spheres[0] = mat2x3(-1.5,1.5,.5,.25,.25,.25);
    spheres[1] = mat2x3(-1.5,0,0,.4,.5,.4);
    spheres[2] = mat2x3(0,0,0,.4,.5,.4);
    spheres[3] = mat2x3(1.5,0,0,.4,.5,.4);
    spheres[4] = mat2x3(1.5,0,1.5,.4,.5,.4);
    spheres[5] = mat2x3(1.5,1.5,-.5,.25,.25,.25);
    spheres[6] = mat2x3(-1.5,0,1.5,.4,.5,.4);
    spheres[7] = mat2x3(0,0,1.5,.4,.5,.4);
    spheres[8] = mat2x3(0,0,-1.5,.4,.5,.4);
    spheres[9] = mat2x3(1.5,0,-1.5,.4,.5,.4);
    spheres[10] = mat2x3(-1.5,0,-1.5,.4,.5,.4);

    // normalized mouse coordinates
    vec2 mo = (iMouse.xy - .5*iResolution.xy) / iResolution.y;

    vec3 tot = vec3(0); // accumulated color
    for (int i=0; i<SPP; i++) {
        // init randoms seed
        seed = float(i)+iTime + hash(fragCoord/iResolution.xy);

        vec2 off = vec2(hash(), hash()) - .5; // AA offset
        // pixel coordinates centered at the origin
        vec2 p = (fragCoord+off - .5*iResolution.xy) / iResolution.y;

        float an = -mo.x*6.283185-1.5; // camera xz rotation
        vec3 ro = 4.5*vec3(sin(an),.3+.7*mo.y,cos(an)); // ray origin
        vec3 ta = vec3(0); // target
        mat3 ca = setCamera(ro, ta); // camera matrix
        vec3 rd = ca * normalize(vec3(p,1.5)); // ray direction

        // depth of field

        vec3 tn; float tid; // temporary variables
        float t = intersect(ro, ca[2], 1e10, tn, tid); // focus distane
        vec3 fp = ro + rd*t; // focus plane

        // distribution on a disk
        float w = sqrt(hash()); // vector length
        float a = hash()*6.283185; // angle

        ro += .03 * w*(ca[0]*sin(a) + ca[1]*cos(a)); // blur
        rd = normalize(fp - ro);

        vec3 col = render(ro, rd); // render
        tot += col;
    }
    tot /= float(SPP);    

    // blend with the previous frame
    vec4 data = texelFetch(iChannel0, ivec2(fragCoord), 0);
    fragColor = vec4(tot,1) + data*step(iMouse.z,0.);
}

