float dot2( in vec2 v ) { return dot(v,v); }
vec4 sdJoint3DSphere( in vec3 p, in float l, in float a, in float w)
{

    // if perfectly straight
    if( abs(a)<0.001 ) return vec4( length(p-vec3(0,clamp(p.y,0.0,l),0))-w, p );

    // parameters
    vec2  sc = vec2(sin(a),cos(a));
    float ra = 0.5*l/a;

    // recenter
    p.x -= ra;

    // reflect
    vec2 q = p.xy - 2.0*sc*max(0.0,dot(sc,p.xy));

    float u = abs(ra)-length(q);
    float d2 = (q.y<0.0) ? dot2( q+vec2(ra,0.0) ) : u*u;
    float s = sign(a);
    return vec4( sqrt(d2+p.z*p.z)-w,
                 (p.y>0.0) ? s*u : s*sign(-p.x)*(q.x+ra),
                 (p.y>0.0) ? atan(s*p.y,-s*p.x)*ra : (s*p.x<0.0)?p.y:l-p.y,
                 p.z );
}

vec4 sdJoint3DFlat( in vec3 p, in float l, in float a, in float w)
{

    // if perfectly straight
    if( abs(a)<0.001 )
    {
        vec3 q = p; q.y -= 0.5*l;
        q = abs(q) - vec3(w,l*0.5,w);
        return vec4(min(max(q.x,max(q.y,q.z)),0.0) + length(max(q,0.0)),p);
    }

    // parameters
    vec2  sc = vec2(sin(a),cos(a));
    float ra = 0.5*l/a;

    // recenter
    p.x -= ra;

    // reflect
    vec2 q = p.xy - 2.0*sc*max(0.0,dot(sc,p.xy));

	// distance
    float u = abs(ra)-length(q);
    float d = max(length( vec2(q.x+ra-clamp(q.x+ra,-w,w), q.y) )*sign(-q.y),abs(u) - w);

    // parametrization (optional)
    float s = sign(a);
    float v = ra*atan(s*p.y,-s*p.x);
    u = u*s;

    // square profile
    q = vec2(d,abs(p.z)-w);

    d = min(max(q.x,q.y),0.0) + length(max(q,0.0));


    return vec4( d, u, v, p.z );
}


vec4 map( in vec3 pos )
{
    float an = 1.3*sin(iTime*1.1+3.0);
    float le = 0.8;
    float wi = 0.2;

    vec4 d1 = sdJoint3DSphere(pos-vec3(0.0,0.0, 0.4), le, an, wi );
    vec4 d2 = sdJoint3DFlat(  pos-vec3(0.0,0.0,-0.4), le, an, wi );

    return (d1.x<d2.x) ? d1 : d2;
}

// https://iquilezles.org/articles/normalsSDF
vec3 calcNormal( in vec3 pos )
{
    vec2 e = vec2(1.0,-1.0)*0.5773;
    const float eps = 0.0005;
    return normalize( e.xyy*map( pos + e.xyy*eps ).x + 
					  e.yyx*map( pos + e.yyx*eps ).x + 
					  e.yxy*map( pos + e.yxy*eps ).x + 
					  e.xxx*map( pos + e.xxx*eps ).x );
}

float hash(vec3 p)  // replace this by something better
{
    p  = fract( p*0.3183099+.1 );
	p *= 17.0;
    return fract( p.x*p.y*p.z*(p.x+p.y+p.z) );
}

float noise( in vec3 x )
{
    vec3 i = floor(x);
    vec3 f = fract(x);
    f = f*f*(3.0-2.0*f);
    return mix(mix(mix( hash(i+vec3(0,0,0)), 
                        hash(i+vec3(1,0,0)),f.x),
                   mix( hash(i+vec3(0,1,0)), 
                        hash(i+vec3(1,1,0)),f.x),f.y),
               mix(mix( hash(i+vec3(0,0,1)), 
                        hash(i+vec3(1,0,1)),f.x),
                   mix( hash(i+vec3(0,1,1)), 
                        hash(i+vec3(1,1,1)),f.x),f.y),f.z);
}

float fbm( in vec3 p )
{

    p *= 16.0;
	const mat3 m = mat3( 0.00,  0.80,  0.60,
    	                -0.80,  0.36, -0.48,
        	            -0.60, -0.48,  0.64 )*2.0;
    float f = 0.0;
    f += 0.500*noise( p ); p = m*p;
    f += 0.250*noise( p ); p = m*p;
    f += 0.125*noise( p ); p = m*p;
    return f;
}

#if HW_PERFORMANCE==0
#define AA 1
#else
#define AA 3
#endif

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
     // camera movement	
	float an = 0.6 + 0.1*iTime;
	vec3 ro = vec3( 1.4*sin(an), 0.2, 1.4*cos(an) );
    vec3 ta = vec3( 0.0, 0.2, 0.0 );
    // camera matrix
    vec3 ww = normalize( ta - ro );
    vec3 uu = normalize( cross(ww,vec3(0.0,1.0,0.0) ) );
    vec3 vv =          ( cross(uu,ww));

    // render
    vec3 tot = vec3(0.0);

    #if AA>1
    for( int m=0; m<AA; m++ )
    for( int n=0; n<AA; n++ )
    {
        // pixel coordinates
        vec2 o = vec2(float(m),float(n)) / float(AA) - 0.5;
        vec2 p = (-iResolution.xy + 2.0*(fragCoord+o))/iResolution.y;
        #else    
        vec2 p = (-iResolution.xy + 2.0*fragCoord)/iResolution.y;
        #endif

	    // create view ray
        vec3 rd = normalize( p.x*uu + p.y*vv + 1.8*ww );

        // raymarch
        const float tmax = 5.0;
        float t = 0.0;
        vec3 uvw = vec3(0.0);
        for( int i=0; i<256; i++ )
        {
            vec3 pos = ro + t*rd;

            vec4 h = map(pos);
            if( h.x<0.0001 || t>tmax )
            {
                uvw = h.yzw;
                break;
            }
            t += h.x;
        }


        // shading/lighting	
        vec3 col = vec3(0.0);
        if( t<tmax )
        {
            vec3 pos = ro + t*rd;
            vec3 nor = calcNormal(pos);
            vec3 lig = normalize(vec3(0.8,0.5,0.4));
            float dif = clamp( dot(nor,lig), 0.0, 1.0 );
            float amb = 0.5 + 0.5*dot(nor,vec3(0.0,1.0,0.0));
            col = vec3(0.2,0.3,0.4)*amb + vec3(0.8,0.7,0.5)*dif;
            col *= fbm( uvw*2.0 );
            col *= 1.75;
        }

        // gamma        
        col = sqrt( col );
	    tot += col;
    #if AA>1
    }
    tot /= float(AA*AA);
    #endif

	fragColor = vec4( tot, 1.0 );
}

#define MAX_DIST 100.
#define SURF_DIST .001
#define EPS .0001
#define PI 3.14
#define PI2 6.28
#define saturate(a) clamp(a,0.,1.)
#define S(a,b,t) smoothstep(a,b,t)
#define TS(a,b,c,d,t) smoothstep(a,b,t) * smoothstep(d,c,t)
#define REP(p,r) mod(p,r) - r * .5  

#define MAT_BALL 1.
#define MAT_FLOOR 2.
#define MAT_WALL 3.

#define CT iTime * .22 + .22
// #define CP vec3(0.5,0.5,0.5),vec3(0.5,0.5,0.5),vec3(1.0,1.0,1.0),vec3(0.0,0.33,0.67)
#define CP vec3(1.,1.,1.),vec3(2., .8, .4),vec3(.8,1.0,2.0),vec3(.52,0.,.2)

// ref: https://www.shadertoy.com/view/ll2GD3
vec3 palette( in float t, in vec3 a, in vec3 b, in vec3 c, in vec3 d ) {
    return a + b*cos( 6.283185*(c*t+d) );
}

vec3 getLightColor() {
    return palette(CT, CP * .98) * 1.;
}

vec3 getBallBaseColor() {
    return palette(CT, CP * 1.01) * .35;
}

vec3 getBallEmissionColor() {
    return palette(CT, CP * 1.02) * .5;
}

float rand(vec2 co){
    return fract(sin(dot(co, vec2(12.9898, 78.233))) * 43758.5453);
}

mat2 rot(float a) {
    float s = sin(a), c = cos(a);
    return mat2(c, -s, s, c);
}

float sdSphere(vec3 p, float s) {
    return length(p) - s;
}

float sdPlane( vec3 p, vec3 n, float h ) {
  return dot(p,n) + h;
}

float opUnion(float d1, float d2) {
    return min(d1, d2);
}

vec2 opUnion2(vec2 a, vec2 b) {
	return a.x < b.x ? a : b;
}

float opSmooth(float d1, float d2, float k)
{
    float h = clamp(.5 + .5 *(d2 - d1) / k, 0., 1.);
    return mix(d2, d1, h) - k * h * (1. - h);
}

