float hash12(vec2 p)
{
	uvec2 q = uvec2(ivec2(p)) * uvec2(1597334673U, 3812015801U);
	uint n = (q.x ^ q.y) * 1597334673U;
	return float(n) * (1. / float(0xffffffffU));
}

mat3 rotY(float a)
{
	return mat3(cos(a), 0., sin(a),
                	0., 1., 	0.,
               -sin(a), 0., cos(a));
}

mat3 rotX(float a)
{
	return mat3(1., 	0., 	 0.,
                0., cos(a), -sin(a),
                0., sin(a),  cos(a));
}

vec3 rotateYX(vec3 a, vec2 rot)
{
	return rotX(rot.y) * rotY(rot.x) * a;
}

mat3 getCameraMatrix(vec3 origin, vec3 target)
{
    vec3 lookAt = normalize(target - origin);
    vec3 right = normalize(cross(lookAt, vec3(0., 1., 0.)));
    vec3 up = normalize(cross(right, lookAt));
    return mat3(right, up, lookAt);
}

Ray getCameraRay(vec2 uv)
{
    vec3 origin = cameraPosition;
    vec3 target = vec3(0., 1., 0.);
    mat3 camera = getCameraMatrix(origin, target);
    vec3 direction = normalize(camera * vec3(uv, 2.5));
    return Ray(origin, direction);
}

/**
* Creative Commons CC0 1.0 Universal (CC-0)
*
* A small experimental follow up to my area lights shader (https://www.shadertoy.com/view/3dsBD4)
* with a textured rectangular area light. The diffuse component of the light is based on the 5 sample
* solid angle technique from the frostbite engine[1], and the specular technique is based on the most
* representative point method from unreal engine[2]. For specular, a point on the rectangular light source
* is calculated using the reflection vector originating from the shaded point. That point on the rectangle
* is the new light vector using which normal pbr shading calculations are done. 
*
* [1] Real Shading in Unreal Engine 4 -
* (https://cdn2.unrealengine.com/Resources/files/2013SiggraphPresentationsNotes-26915738.pdf)
* [2] Moving Frostbite to Physically Based Rendering 3.0 -
* (https://seblagarde.files.wordpress.com/2015/07/course_notes_moving_frostbite_to_pbr_v32.pdf)
*
*/

Rect rect;

vec2 sdUnion(vec2 a, vec2 b)
{
 	return a.x < b.x ? a : b;  
}

void initRect(vec2 rot)
{
    rect.up = rotateYX(vec3(0., 1., 0.), rot);
    rect.right = rotateYX(vec3(1., 0., 0.), rot);;
    rect.front = normalize(cross(rect.right, rect.up));
    rect.halfSize = vec2(5., 3.);

    rect.center = vec3(0., 5., 0.);

    rect.a = rect.center + rect.halfSize.x * rect.right + rect.halfSize.y * rect.up;
    rect.b = rect.center - rect.halfSize.x * rect.right + rect.halfSize.y * rect.up;
    rect.c = rect.center - rect.halfSize.x * rect.right - rect.halfSize.y * rect.up;
    rect.d = rect.center + rect.halfSize.x * rect.right - rect.halfSize.y * rect.up;
}

float sdPlane(vec3 pos, float height)
{
	float plane = pos.y - height;
#ifdef FLOOR_DISPLACEMENT
    return plane - textureLod(iChannel0, pos.xz * .02, 0.).r * .01;   
#else
    return plane;
#endif
}

float sdPlaneNoDisplacement(vec3 pos, float height)
{
	return pos.y - height;
}

float sdRect(vec3 p, vec3 a, vec3 b, vec3 c, vec3 d)
{
    vec3 ba = b - a; vec3 pa = p - a;
    vec3 cb = c - b; vec3 pb = p - b;
    vec3 dc = d - c; vec3 pc = p - c;
    vec3 ad = a - d; vec3 pd = p - d;
    vec3 nor = cross(ba, ad);

    return sqrt(
        (sign(dot(cross(ba, nor), pa)) +
         sign(dot(cross(cb, nor), pb)) +
         sign(dot(cross(dc, nor), pc)) +
         sign(dot(cross(ad, nor), pd)) < 3.)

        ?

        min(min(min(
		dot2(ba * clamp(dot(ba, pa) / dot2(ba), 0., 1.) - pa),
		dot2(cb * clamp(dot(cb, pb) / dot2(cb), 0., 1.) - pb)),
		dot2(dc * clamp(dot(dc, pc) / dot2(dc), 0., 1.) - pc)),
		dot2(ad * clamp(dot(ad, pd) / dot2(ad), 0., 1.) - pd))

        :

        dot(nor, pa) * dot(nor, pa) / dot2(nor) 
    );
}

vec2 sdScene(vec3 pos)
{
	vec2 result = vec2(sdPlaneNoDisplacement(pos, -.75), 2.);

    result = sdUnion(result, vec2(sdRect(pos, rect.a, rect.b, rect.c, rect.d), 0.));

    return result;
}

vec2 sdSceneNormal(vec3 pos)
{
	return vec2(sdPlane(pos, -.75), 1.);
}

vec3 calculateNormal(vec3 pos)
{
	vec2 eps = vec2(EPS, 0.);
    return normalize(vec3(sdSceneNormal(pos + eps.xyy).x, 
                          sdSceneNormal(pos + eps.yxy).x, 
                          sdSceneNormal(pos + eps.yyx).x) 
                     - sdSceneNormal(pos).x);
}

vec2 rayMarch(Ray ray)
{
	float dist = 0.;
    vec2 result = vec2(-1.);
    for(int i = 0; i < 128; ++i)
    {  
        result = sdScene(ray.origin + ray.direction * dist);
        if (result.x < EPS * dist || dist >= cameraFar) break;
        dist += result.x;
    }

    if (dist >= cameraFar) result.y = -1.;
    return vec2(dist, result.y);
}

float ndfTrowbridgeReitzRect(float NdotH, float alpha, float alphaPrime)
{
    float alpha2 = alpha * alpha;
    float alpha4 = alpha2 * alpha2;
    float alphaPrime3 = alphaPrime * alphaPrime * alphaPrime;
    float NdotH2 = NdotH * NdotH;

    return 
        			 	(alpha2 * alphaPrime3)
    	/ /*-------------------------------------------------*/
        	  	(pow(NdotH2 * (alpha2 - 1.) + 1., 2.));      
}

// Schlick-Beckmann GGX approximation used for smith's method
float geometrySchlickGGX(float NdotX, float k)
{
    return 
        					NdotX
    	/ /*----------------------------------------*/
    	  	  max(NdotX * (1. - k) + k, SMOL_EPS);
}

float geometrySmith(float NdotV, float NdotL, float roughness)
{
 	float roughnessplusone = roughness + 1.;
    float k = roughnessplusone * roughnessplusone / 8.;

    return geometrySchlickGGX(NdotV, k) * geometrySchlickGGX(NdotL, k);
}

// Schlick's approximation for Fresnel equation
vec3 fresnelSchlick(vec3 F0, float dotProd)
{
    return F0 + (1. - F0) * pow(1. - dotProd, 5.);
}

float rectSolidAngle(vec3 p, vec3 p0, vec3 p1, vec3 p2, vec3 p3)
{
    vec3 v0 = p0 - p;
    vec3 v1 = p1 - p;
    vec3 v2 = p2 - p;
    vec3 v3 = p3 - p;

    vec3 n0 = normalize(cross(v0, v1));
    vec3 n1 = normalize(cross(v1, v2));
    vec3 n2 = normalize(cross(v2, v3));
    vec3 n3 = normalize(cross(v3, v0));

    float g0 = acos(dot(-n0, n1));
	float g1 = acos(dot(-n1, n2));
	float g2 = acos(dot(-n2, n3));
	float g3 = acos(dot(-n3, n0));

    return g0 + g1 + g2 + g3 - TWO_PI;
}

vec3 rayPlaneIntersect(Ray ray)
{
   return ray.origin + ray.direction * (dot(rect.front, rect.center - ray.origin)
                                      / dot(rect.front, ray.direction));
}

vec4 rectLight(vec3 p, vec3 n, vec3 v, vec3 r, float NdotV, float roughness,
              vec3 f0, out vec3 fresnel, out vec3 diffCol, out vec3 specCol)
{

    vec4 result = vec4(0.);
    // ensure the points are wound counter-clockwise (only debug)
    float windingCheck = dot(cross(rect.right, rect.up), rect.center - p);
    if (windingCheck > 0.)
		return result;

    float solidAngle = rectSolidAngle(p, rect.a, rect.b, rect.c, rect.d);

    // diffuse
    result.w = solidAngle * .2 * (
        saturate(dot(normalize(rect.a - p), n)) +
        saturate(dot(normalize(rect.b - p), n)) +
        saturate(dot(normalize(rect.c - p), n)) +
        saturate(dot(normalize(rect.d - p), n)) +
        saturate(dot(normalize(rect.center - p), n)));   

    Ray rectRay = Ray(p, r);

    // calculate point on the rectangle surface/edge based on the ray originating from the shaded point
    vec3 planePointCenter = rayPlaneIntersect(rectRay) - rect.center;
    vec2 planePointProj = vec2(dot(planePointCenter, rect.right), 
                               dot(planePointCenter, rect.up));
    //vec2 c = min(abs(planePointProj), rect.halfSize) * sign(planePointProj);
    vec2 c = clamp(planePointProj, -rect.halfSize, rect.halfSize);
    vec3 L = rect.center + rect.right * c.x + rect.up * c.y;
#ifdef LIGHT_TEXTURE
    // calculate light uv
    vec3 L0 = L - rect.c;
    vec2 luv = vec2(dot(rect.right, L0), dot(rect.up, L0)) / (rect.halfSize * 2.);
#endif
    L -= p;

    vec3 l = normalize(L);
    vec3 h = normalize(l + v);
    float lightDist = length(L);

    float NdotH = max(0., dot(n, h));
    float VdotH = dot(v, h);

    float alpha = roughness * roughness;
    float alphaPrime = saturate(alpha + (RECT_LIGHT_RADIUS / (2. * lightDist)));

#ifdef LIGHT_TEXTURE
    // calculate approx light diffuse and specular colors (super experimental :p) 
    diffCol = pow(textureLod(iChannel1, luv, pow(exp(lightDist + .5), 2.)).rgb, vec3(2.2));
    specCol = pow(textureLod(iChannel1, luv, exp(lightDist * alpha + .5) + 1.).rgb, vec3(2.2));
#endif

    result.xyz += geometrySmith(NdotV, result.w, roughness) 
        * ndfTrowbridgeReitzRect(NdotH, alpha, alphaPrime)
        * fresnelSchlick(f0, VdotH);

    return result;
}


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 blueNoise = texelFetch(iChannel1,
						(iFrame * ivec2(113, 127)) & 63, 0).rg;
    vec2 uv = (2. * (fragCoord + blueNoise) - iResolution.xy) / iResolution.y;
    vec2 m = iMouse.xy / iResolution.y;
    float t = iTime * .5;

    vec3 col = vec3(0.);

    vec2 rot = m * TWO_PI;    
    initRect(rot);

    Ray ray = getCameraRay(uv);
    vec2 marchResult = rayMarch(ray);
    vec3 position = ray.origin + ray.direction * marchResult.x;
    vec3 normal = calculateNormal(position);
    vec3 viewDirection = -ray.direction;
    vec3 reflectDirection = reflect(ray.direction, normal);

    float NdotV = max(dot(normal, viewDirection), 0.);

    vec3 rectFresnel = vec3(0.);
	vec3 rLightDiff = vec3(0.); // light diffuse color
    vec3 rLightSpec = vec3(0.); // light specular color
    float rectRoughness = .08;
    float rectMetalness = .25;
	if (marchResult.y > -1.)
    {
		if (marchResult.y > 1.)
        {
            vec3 albedo = pow(textureLod(iChannel0, position.xz * .04, 0.).rgb, vec3(2.2));
#ifdef FLOOR_ROUGHNESS
            rectRoughness += albedo.r * .64;
#endif
            vec3 F0 = mix(vec3(.05), vec3(1.), rectMetalness);
            vec4 rLight = rectLight(position, normal, viewDirection,
					reflectDirection, NdotV, rectRoughness, F0, rectFresnel, rLightDiff, rLightSpec);
            vec3 kD = 1. - rectFresnel;
            kD *= 1. - rectMetalness;
#ifdef LIGHT_TEXTURE
        	col += (albedo * kD * rLightDiff + rLight.xyz * rLightSpec) * rLight.w * 
                RECT_LIGHT_INTENSITY;
#else
            col += (albedo * kD * PI_INV + rLight.xyz) * rLight.w * 
                RECT_LIGHT_INTENSITY * RECT_LIGHT_COLOR;
#endif
        }
        else
        {
#ifdef LIGHT_TEXTURE
            vec3 rectOrigin = position - rect.c;
        	vec2 rectUv = vec2(dot(rect.right, rectOrigin), dot(rect.up, rectOrigin)) / (rect.halfSize * 2.);
            col += pow(textureLod(iChannel1, rectUv, 0.).rgb, vec3(2.2)) * RECT_LIGHT_INTENSITY;
#else
            col += RECT_LIGHT_COLOR * RECT_LIGHT_INTENSITY;
#endif
        }
    }

    col = mix(col, vec3(.005, .0003, .0002), // brown-ish fog color
               		clamp(1. - exp(-marchResult.x * .08), 0., 1.));


    fragColor = vec4(col, 1.);
}

/**
* Creative Commons CC0 1.0 Universal (CC-0)
*
* A basic TAA implementation based on the variance clipping technique by Marco Salvi (Nvidia).
*
*/

const ivec2 offsets[8u] = ivec2[]
(
    ivec2(-1,-1), ivec2(-1, 1), 
	ivec2(1, -1), ivec2(1, 1), 
	ivec2(1, 0),  ivec2(0, -1), 
	ivec2(0, 1),  ivec2(-1, 0)
);

const float gaussian[8u] = float[]
(
    .0625, .0625,
    .0625, .0625,
    .125,  .125,
    .125,  .125
);

vec3 RGBToYCoCg(vec3 RGB)
{
    float Y = dot(RGB, vec3(1, 2,  1))  * .25;
    float Co= dot(RGB, vec3(2, 0, -2))  * .25 + (.5 * 256./255.);
    float Cg= dot(RGB, vec3(-1, 2, -1)) * .25 + (.5 * 256./255.);
    return vec3(Y, Co, Cg) * (1. / (1. + Y)); // tonemap
}

vec3 YCoCgToRGB(vec3 YCoCg)
{
    YCoCg *= 1. / (1. - YCoCg.x); // tonemap
	float Y= YCoCg.x;
	float Co= YCoCg.y - (.5 * 256. / 255.);
	float Cg= YCoCg.z - (.5 * 256. / 255.);
	float R= Y + Co - Cg;
	float G= Y + Cg;
	float B= Y - Co - Cg;
	return vec3(R, G, B);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord / iResolution.xy;
    vec3 currentBuffer = RGBToYCoCg(textureLod(iChannel0, uv, 0.).rgb);
    vec3 historyBuffer = RGBToYCoCg(textureLod(iChannel1, uv, 0.).rgb);

    vec3 mean = currentBuffer;
    vec3 variance = currentBuffer * currentBuffer;
    vec3 filtered = currentBuffer * .25;

    // Marco Salvi's Implementation (by Chris Wyman)
    for(int i = 0; i < 8; i++)
    {
        vec3 neighborTexel = RGBToYCoCg(texelFetch(iChannel0, ivec2(fragCoord.xy) + offsets[i], 0).rgb);
        mean += neighborTexel;
        variance += neighborTexel * neighborTexel;
        filtered += neighborTexel * gaussian[i];
    }

    mean /= 9.;
    variance /= 9.;
    const float stDevMultiplier = 1.5;
	vec3 sigma = sqrt(abs(variance - mean * mean));
	vec3 colorMin = min(filtered, mean - stDevMultiplier * sigma);
	vec3 colorMax = max(filtered, mean + stDevMultiplier * sigma);

    historyBuffer = clamp(historyBuffer, colorMin, colorMax);

    vec3 outColor = mix(historyBuffer, filtered, .05);

	fragColor = vec4(YCoCgToRGB(outColor), 1.);
}

// Tiny Planet: Vulcan
// by Morgan McGuire @CasualEffects
//
// Texturing inspired by Paul Malin https://www.shadertoy.com/view/ldBfDR
//
// I intentionally left the aliasing on the bright locations in...
// it looks like heat distortion.

const bool autoRotate = true;

/////////////////////////////////////////////////////////////////////////
// Morgan's standard Shadertoy helpers
#define Vector2      vec2
#define Point2       vec2
#define Point3       vec3
#define Vector3      vec3
#define Color3       vec3
#define Radiance3    vec3
#define Irradiance3  vec3
#define Power3       vec3
#define Biradiance3  vec3

const float pi          = 3.1415926535;
const float degrees     = pi / 180.0;
const float inf         = 1.0 / 1e-10;

float square(float x) { return x * x; }
float pow3(float x) { return x * square(x); }
vec3 square(vec3 x) { return x * x; }
vec3 pow3(vec3 x) { return x * square(x); }
float pow4(float x) { return square(square(x)); }
float pow5(float x) { return x * square(square(x)); }
float pow8(float x) { return square(pow4(x)); }
float infIfNegative(float x) { return (x >= 0.0) ? x : inf; }

struct Ray { Point3 origin; Vector3 direction; };	
struct Material { Color3 color; float metal; float smoothness; };
struct Surfel { Point3 position; Vector3 normal; Material material; };
struct Sphere { Point3 center; float radius; Material material; };

/** Analytic ray-sphere intersection. */
bool intersectSphere(Point3 C, float r, Ray R, inout float nearDistance, inout float farDistance) { Point3 P = R.origin; Vector3 w = R.direction; Vector3 v = P - C; float b = 2.0 * dot(w, v); float c = dot(v, v) - square(r); float d = square(b) - 4.0 * c; if (d < 0.0) { return false; } float dsqrt = sqrt(d); float t0 = infIfNegative((-b - dsqrt) * 0.5); float t1 = infIfNegative((-b + dsqrt) * 0.5); nearDistance = min(t0, t1); farDistance  = max(t0, t1); return (nearDistance < inf); }

///////////////////////////////////////////////////////////////////////////////////
// The following are from https://www.shadertoy.com/view/4dS3Wd
float hash(float n) { return fract(sin(n) * 1e4); }
float hash(vec2 p) { return fract(1e4 * sin(17.0 * p.x + p.y * 0.1) * (0.1 + abs(sin(p.y * 13.0 + p.x)))); }
float noise(float x) { float i = floor(x); float f = fract(x); float u = f * f * (3.0 - 2.0 * f); return mix(hash(i), hash(i + 1.0), u); }
float noise(vec2 x) { vec2 i = floor(x); vec2 f = fract(x); float a = hash(i); float b = hash(i + vec2(1.0, 0.0)); float c = hash(i + vec2(0.0, 1.0)); float d = hash(i + vec2(1.0, 1.0)); vec2 u = f * f * (3.0 - 2.0 * f); return mix(a, b, u.x) + (c - a) * u.y * (1.0 - u.x) + (d - b) * u.x * u.y; }
float noise(vec3 x) { const vec3 step = vec3(110, 241, 171); vec3 i = floor(x); vec3 f = fract(x); float n = dot(i, step); vec3 u = f * f * (3.0 - 2.0 * f); return mix(mix(mix( hash(n + dot(step, vec3(0, 0, 0))), hash(n + dot(step, vec3(1, 0, 0))), u.x), mix( hash(n + dot(step, vec3(0, 1, 0))), hash(n + dot(step, vec3(1, 1, 0))), u.x), u.y), mix(mix( hash(n + dot(step, vec3(0, 0, 1))), hash(n + dot(step, vec3(1, 0, 1))), u.x), mix( hash(n + dot(step, vec3(0, 1, 1))), hash(n + dot(step, vec3(1, 1, 1))), u.x), u.y), u.z); }

#define DEFINE_FBM(name, OCTAVES) float name(vec3 x) { float v = 0.0; float a = 0.5; vec3 shift = vec3(100); for (int i = 0; i < OCTAVES; ++i) { v += a * noise(x); x = x * 2.0 + shift; a *= 0.5; } return v; }
DEFINE_FBM(fbm3, 3)
DEFINE_FBM(fbm5, 5)
DEFINE_FBM(fbm6, 6)

///////////////////////////////////////////////////////////////////////////////////

// The red channel defines the height, but all channels
// are used for color.
#define elevationMap iChannel0
#define colorMap iChannel1

const float       verticalFieldOfView = 25.0 * degrees;

// Directional light source
const Vector3     w_i             = Vector3(1.0, 1.0, -0.8) / 1.6248076;
const Biradiance3 B_i             = Biradiance3(4);

const Point3      planetCenter    = Point3(0);

// Including mountains
const float       planetMaxRadius = 1.0;
const float       maxMountain = 0.13;


const float planetMinRadius = planetMaxRadius - maxMountain;

mat3 planetRotation;

/** Returns color, coverage under world-space point wsPoint.
    e is the relative height of the surface. 
    k is the relative height of the ray
*/
Color3 samplePlanet(Point3 osPosition, out float e, out float k) {
	Point3 s = normalize(osPosition);    

    // Cylindrical map coords
    Point2 cylCoord = vec2(atan(s.z, -s.x) / pi, s.y * 0.5 + 0.5);

    // Length of osPosition = elevation
    float sampleElevation  = length(osPosition);//dot(osPosition, s);

    // Relative height of the sample point [0, 1]
    k = (sampleElevation - planetMinRadius) * (1.0 / maxMountain);

    // Use explicit MIPs, since derivatives
    // will be random based on the ray marching
    float lod = (iResolution.x > 800.0) ? 1.0 : 2.0;

    // Relative height of the surface [0, 1]
    e = mix(textureLod(elevationMap, cylCoord, lod).r, textureLod(elevationMap, s.xz, lod).r, abs(s.y));
    e = square((e - 0.2) / 0.8) * 0.5;

    // Soften glow at high elevations, using the mip chain
    // (also blurs 
    lod += k * 6.0;

    // Planar map for poles mixed into cylindrical map
    Color3 material = mix(textureLod(colorMap, cylCoord * vec2(2.0, 2.0), lod).rgb,
                          textureLod(colorMap, s.xz, lod).rgb, abs(s.y));

    // Increase contrast
    material = pow3(material);


    // Object space height of the surface
    float surfaceElevation = mix(planetMinRadius, planetMaxRadius, e);

    return material;
}


/** Relative to mountain range */
float elevation(Point3 osPoint) {
    float e, k;
    samplePlanet(osPoint, e, k);
    return e;
}


void mainImage(out vec4 fragColor, in vec2 fragCoord) {
	// Rotate over time
	float yaw   = -((iMouse.x / iResolution.x) * 2.5 - 1.25) + (autoRotate ? -iTime * 0.02 : 0.0);
	float pitch = ((iMouse.y > 0.0 ? iMouse.y : iResolution.y * 0.3) / iResolution.y) * 2.5 - 1.25;
 	planetRotation = 
    	mat3(cos(yaw), 0, -sin(yaw), 0, 1, 0, sin(yaw), 0, cos(yaw)) *
    	mat3(1, 0, 0, 0, cos(pitch), sin(pitch), 0, -sin(pitch), cos(pitch));


    Vector2 invResolution = 1.0 / iResolution.xy;

	// Outgoing light
	Radiance3 L_o;

	Surfel surfel;	

	Ray eyeRay = Ray(Point3(0.0, 0.0, 5.0), normalize(Vector3(fragCoord.xy - iResolution.xy / 2.0, iResolution.y / (-2.0 * tan(verticalFieldOfView / 2.0)))));

    Point3 hitPoint;    
    float minDistanceToPlanet, maxDistanceToPlanet;

    bool hitBounds = intersectSphere(planetCenter, planetMaxRadius, eyeRay, minDistanceToPlanet, maxDistanceToPlanet);

    // Stars
    L_o = vec3(1) * max(0.0, hash(fragCoord * 0.5 + 10.0) - 0.999) / 0.0001 +
        pow5(fbm3(fragCoord.xyy * -0.007 + iTime * 0.1)) * square(texture(iChannel1, fragCoord * invResolution.x).rbr) * max(0.0, hash(fragCoord * 0.1) - 0.99) / 0.0003;

    // Background wash gradient
    float gradCoord = (fragCoord.x + fragCoord.y) * (invResolution.x * 0.5);
    L_o += mix(Color3(0.025, 0, 0.02), Color3(0.11, 0.06, 0.0), gradCoord) * 1.5 *
         (0.15 + smoothstep(0.0, 1.0, 2.5 * abs(gradCoord - 0.4)));

    // Background glow ("atmosphere")
    L_o += Color3(0.6, 0.06, 0.01) * (17.0 * pow8(max(0.0, 1.0 - length((fragCoord - iResolution.xy * 0.5) * invResolution.y))));

    // Sun
    Point2 sunCoord = vec2(-0.7, -0.5) + (fragCoord - iResolution.xy * 0.5) * invResolution.y;
    float sunDist = max(0.0,  1.0 - length(sunCoord));
    L_o += Color3(15, 9, 6) * (pow(sunDist, 12.0) * (1.0 + 0.25 * noise(sin(iTime * 0.1) + iTime * 0.1 + 20.0 * atan(sunCoord.x, -sunCoord.y))));


    if (hitBounds) {
        Color3 glow = Color3(0);
        // Planet surface + atmospherics

        // March to surface
        const int NUM_STEPS = 250;

        // Total traversal should be either 25% of the thickness of the planet,
        // the distance between total, or the max mountain height
        float dt = (maxDistanceToPlanet - minDistanceToPlanet) / float(NUM_STEPS);
        Color3 material = Color3(0);
        Vector3 wsNormal = Vector3(0);
        Color3 p;
        float coverage = 0.0;
        float e = 1.0, k = 0.0;

        // Take the ray to the planet's object space
        eyeRay.origin = (eyeRay.origin - planetCenter) * planetRotation;
        eyeRay.direction = eyeRay.direction * planetRotation;

        Point3 X;
        for (int i = 0; (i < NUM_STEPS) && (coverage < 1.0); ++i) {
            // Point on the ray in object space
            X = eyeRay.origin + eyeRay.direction * (dt * float(i) + minDistanceToPlanet);

            // color, coverage
	        p = samplePlanet(X, e, k);
            if (e > k) {
                // Hit the surface
                material = p;
                coverage = 1.0;

                // Surface emission
	            glow += pow(p, p * 2.5 + 7.0) * 3e3;
            } else {
                // Passing through atmosphere above lava; accumulate glow
	            glow += pow(p, p + 7.0) * square(square(1.0 - k)) * 25.0;
            }
        }

        // Planetary sphere normal
        Vector3 sphereNormal = normalize(planetRotation * X);

        // Surface normal
        const float eps = 0.01;
        wsNormal = planetRotation *
            normalize(Vector3(elevation(X + Vector3(eps, 0, 0)), 
                              elevation(X + Vector3(0, eps, 0)), 
                              elevation(X + Vector3(0, 0, eps))) - 
                              e);


        wsNormal = normalize(mix(wsNormal, sphereNormal, 0.95));

        // Lighting and compositing
        L_o =  mix(L_o, material * 
                   // Sun
                   (max(dot(wsNormal, w_i) + 0.1, 0.0) * B_i + 


                    // Rim light
                    square(max(0.8 - sphereNormal.z, 0.0)) * Color3(2.0, 1.5, 0.5)), coverage);
        L_o += glow;


        if (false && coverage > 0.0) {
            // Show normals
	      //  L_o = wsNormal * 0.5 + 0.5;
          //  L_o = max(0.0, dot(wsNormal, w_i)) * vec3(1);
        }
    }

	fragColor.xyz = sqrt(L_o);
    fragColor.a   = 1.0;//maxDistanceToPlanet;

}

// Cubemap Car Paint
