float normalDistributionGGXSphere(float NdotH, float alpha, float alphaPrime)
{
    float alpha2 = alpha * alpha;
    float alphaPrime2 = alphaPrime * alphaPrime;
    float NdotH2 = NdotH * NdotH;

    return 
        			 (alpha2 * alphaPrime2)
    	/ /*----------------------------------------*/
        	  pow(NdotH2 * (alpha2 - 1.) + 1., 2.);      
}

float normalDistributionGGXLine(float NdotH, float alpha, float alphaPrime)
{
    float alpha2 = alpha * alpha;
    float alphaPrime2 = alphaPrime * alphaPrime;
    float NdotH2 = NdotH * NdotH;

    return 
        			 (alpha2 * alphaPrime)
    	/ /*----------------------------------------*/
        	  pow(NdotH2 * (alpha2 - 1.) + 1., 2.);      
}

float normalDistributionGGXRect(float NdotH, float alpha, float alphaPrime)
{
    float alpha2 = alpha * alpha;
    float alpha4 = alpha2 * alpha2;
    float alphaPrime3 = alphaPrime * alphaPrime * alphaPrime;
    float NdotH2 = NdotH * NdotH;

    return 
        			 	(alpha2 * alphaPrime3)
    	/ /*-------------------------------------------------*/
        	  	(pow(NdotH2 * (alpha2 - 1.) + 1., 2.));      
}

// Schlick-Beckmann GGX approximation used for smith's method
float geometrySchlickGGX(float NdotX, float k)
{
    return 
        					NdotX
    	/ /*----------------------------------------*/
    	  	  max(NdotX * (1. - k) + k, SMOL_EPS);
}

float geometrySmith(float NdotV, float NdotL, float roughness)
{
 	float roughnessplusone = roughness + 1.;
    float k = roughnessplusone * roughnessplusone / 8.;

    return geometrySchlickGGX(NdotV, k) * geometrySchlickGGX(NdotL, k);
}

// Schlick's approximation for Fresnel equation
vec3 fresnelSchlick(vec3 F0, float dotProd)
{
    return F0 + (1. - F0) * pow(1. - dotProd, 5.);
}

vec3 Irradiance_SphericalHarmonics(const vec3 n) {
    // Irradiance from "Ditch River" IBL (http://www.hdrlabs.com/sibl/archive.html)
    // Generated using google filament cmgen tool
    return max(
          vec3( .754554516862612,  .748542953903366,  .790921515418539)
        + vec3(-.083856548007422,  .092533500963210,  .322764661032516) * (n.y)
        + vec3( .308152705331738,  .366796330467391,  .466698181299906) * (n.z)
        + vec3(-.188884931542396, -.277402551592231, -.377844212327557) * (n.x)
        , 0.0);
}

vec2 PrefilteredDFG_Karis(float roughness, float NoV) {
    // Karis 2014, "Physically Based Material on Mobile"
    // https://www.unrealengine.com/en-US/blog/physically-based-shading-on-mobile
    const vec4 c0 = vec4(-1., -.0275,  -.572,  .022);
    const vec4 c1 = vec4( 1.,  .0425,  1.040, -.040);

    vec4 r = roughness * c0 + c1;
    float a004 = min(r.x * r.x, exp2(-9.28 * NoV)) * r.x + r.y;

    return vec2(-1.04, 1.04) * a004 + r.zw;
}

vec4 sphereLight(vec3 p, vec3 n, vec3 v, vec3 r, vec3 f0, float NdotV, float roughness,
                 float metalness, out vec3 fresnel, out float attenuation)
{
    vec3 L = (SPHERE_LIGHT_POS - p);
    vec3 centerToRay = dot(L, r) * r - L;
    vec3 closestPoint = L + centerToRay * saturate(SPHERE_LIGHT_RADIUS
								/ length(centerToRay));
    vec3 l = normalize(closestPoint);
    vec3 h = normalize(v + l);
    float lightDist = length(closestPoint);

    float NdotL = max(dot(n, l), 0.);
    float NdotH = max(dot(n, h), 0.);
    float VdotH = max(dot(h, v), 0.);

    attenuation = pow(saturate(1. - pow(lightDist / SPHERE_LIGHT_VOLUME_RADIUS, 4.)), 2.)  
            					/ (lightDist * lightDist + 1.);

	attenuation *= softShadow(Ray(p + n * EPS, l));

    float alpha = roughness * roughness;
    float alphaPrime = saturate(alpha + (SPHERE_LIGHT_RADIUS / (2. * lightDist)));

    fresnel = fresnelSchlick(f0, VdotH);
    vec3 specular = normalDistributionGGXSphere(NdotH, alpha, alphaPrime)
        * geometrySmith(NdotV, NdotL, roughness)
        * fresnel;

 	return vec4(specular, NdotL);   
}

vec4 lineLight(vec3 p, vec3 n, vec3 v, vec3 r, vec3 f0, float NdotV, float roughness,
                 float metalness, out vec3 fresnel, out float attenuation)
{
    vec4 result = vec4(0.);
    vec3 l0 = lineStart - p, l1 = lineEnd - p;
    float lengthL0 = length(l0), lengthL1 = length(l1);
    float NdotL0 = dot(n, l0) / (2. * lengthL0);
    float NdotL1 = dot(n, l1) / (2. * lengthL1);
    result.w = (2. * saturate(NdotL0 + NdotL1)) / 
        	 (lengthL0 * lengthL1 + dot(l0, l1) + 2.); // NdotL

    vec3 ld = l1 - l0;
    float RdotL0 = dot(r, l0);
    float RdotLd = dot(r, ld);
    float L0dotLd = dot(l0, ld);
    float distLd = length(ld);

    float t = (RdotL0 * RdotLd - L0dotLd ) / (distLd * distLd - RdotLd * RdotLd);

    // point on the line
    vec3 closestPoint = l0 + ld * saturate(t);
    // point on the tube based on its radius
    vec3 centerToRay = dot(closestPoint, r) * r - closestPoint;
    closestPoint = closestPoint + centerToRay * saturate(LINE_LIGHT_RADIUS 
						/ length(centerToRay));
    vec3 l = normalize(closestPoint);
    vec3 h = normalize(v + l);
    float lightDist = length(closestPoint);

    float NdotH = max(dot(n, h), 0.);
    float VdotH = dot(h, v);

    float denom = lightDist / LINE_LIGHT_VOLUME_RADIUS;
    attenuation = 1. / (denom * denom + 1.);

	attenuation *= softShadow(Ray(p + n * EPS, normalize(l0 + ld * .5)));

    float alpha = roughness * roughness;
    float alphaPrime = saturate(alpha + (LINE_LIGHT_RADIUS / (2. * lightDist)));

    fresnel = fresnelSchlick(f0, VdotH);
    result.xyz = normalDistributionGGXLine(NdotH, alpha, alphaPrime)
        * geometrySmith(NdotV, result.w, roughness)
        * fresnel;

    return result;
}

vec3 rayPlaneIntersect(Ray ray)
{
   return ray.origin + ray.direction * (dot(rect.front, rect.center - ray.origin)
										/ dot(rect.front, ray.direction));
}

vec4 rectLight(vec3 p, vec3 n, vec3 v, vec3 r, vec3 f0, float NdotV, float roughness,
                 float metalness, out vec3 fresnel, out float attenuation)
{
 	vec4 result = vec4(0.);

    // facing side check
    float windingCheck = dot(cross(rect.right, rect.up), rect.center - p);
    if (windingCheck > 0.)
        return result;

    vec3 v0 = rect.a - p;
    vec3 v1 = rect.b - p;
    vec3 v2 = rect.c - p;
    vec3 v3 = rect.d - p;

    float solidAngle = rectSolidAngle(p, v0, v1, v2, v3);

    // diffuse
    result.w = solidAngle * .2 * (
        saturate(dot(normalize(v0), n)) +
        saturate(dot(normalize(v1), n)) +
        saturate(dot(normalize(v2), n)) +
        saturate(dot(normalize(v3), n)) +
        saturate(dot(normalize(rect.center - p), n)));    

    attenuation = softShadow(Ray(p + n * EPS, normalize(rect.center)));

    // specular
	Ray rectRay = Ray(p, r);
    vec3 planePointCenter = rayPlaneIntersect(rectRay) - rect.center;
    // project point on the plane on which the rectangle lies
    vec2 planePointProj = vec2(dot(planePointCenter, rect.right), 
                               dot(planePointCenter, rect.up));
    // translate the point to the top-right quadrant of the rectangle, project it on
    // the rectangle or its edge and translate back using sign of the original point.
    vec2 c = min(abs(planePointProj), rect.halfSize) * sign(planePointProj);
    vec3 L = rect.center + rect.right * c.x + rect.up * c.y - p;

    vec3 l = normalize(L);
    vec3 h = normalize(v + l);
    float lightDist = length(L);

    float NdotH = max(dot(n, h), 0.);
    float VdotH = dot(h, v);

    float alpha = roughness * roughness;
    float alphaPrime = saturate(alpha + (RECT_LIGHT_RADIUS / (2. * lightDist)));

    fresnel = fresnelSchlick(f0, VdotH);
    result.xyz = normalDistributionGGXRect(NdotH, alpha, alphaPrime)
        * geometrySmith(NdotV, result.w, roughness)
        * fresnel;

    return result;
}

vec3 renderScene(Ray ray)
{
    // update line light position & rotation
    //float t = iTime * .25;
    vec3 lineRotation = vec3(2., 0., 0.) * rotZ(T);
    vec3 linePosition = vec3(6. * sin(T), 3., 5.);
    lineStart = linePosition - lineRotation;
    lineEnd = linePosition + lineRotation;

	initRect(rect, T);

    vec3 col = vec3(0.);
    vec2 marchResult = rayMarch(ray);
    vec3 position = ray.origin + ray.direction * marchResult.x;
    vec3 normal = calculateNormal(position);
    vec3 viewDirection = -ray.direction;
    vec3 reflectDirection = reflect(ray.direction, normal);

    float NdotV = max(dot(normal, viewDirection), 0.);

    vec3 albedo = SPHERE_ALBEDO;

    float roughness = fract(marchResult.y), metalness = .88;
    vec3 reflectance = SILVER_F0;  

    if (marchResult.y > -1.)
    {
        if (marchResult.y > 2.)
        {
            albedo = pow(textureLod(iChannel0, position.xz * .18, 0.).rgb, vec3(2.2));
#ifdef FLOOR_ROUGHNESS
            roughness = albedo.r * .5;
#else
            roughness = .05;
#endif
            metalness = .05;
            reflectance = PLASTIC_F0;
        }
        else if (marchResult.y < .5)
            return LIGHT_COLOR * RECT_LIGHT_INTENSITY;

        vec3 F0 = mix(reflectance, albedo, metalness);

        vec3 sphereLightFresnel = vec3(0.);
        float sphereLightAttenuation = 1.;
        vec4 sphereLightDiffSpec = sphereLight(position, normal, viewDirection, 
				reflectDirection, F0, NdotV, roughness, metalness, sphereLightFresnel, 
				sphereLightAttenuation);
        vec3 sphereLightKd = 1. - sphereLightFresnel;
    	sphereLightKd *= 1. - metalness;

        vec3 lineLightFresnel = vec3(0.);
        float lineLightAttenuation = 1.;
        vec4 lineLightDiffSpec = lineLight(position, normal, viewDirection, 
				reflectDirection, F0, NdotV, roughness, metalness, lineLightFresnel, 
				lineLightAttenuation);
        vec3 lineLightKd = 1. - lineLightFresnel;
        lineLightKd *= 1. - metalness;

        vec3 rectLightFresnel = vec3(0.);
        float rectLightAttenuation = 1.;
        vec4 rectLightDiffSpec = rectLight(position, normal, viewDirection, 
				reflectDirection, F0, NdotV, roughness, metalness, rectLightFresnel, 
				rectLightAttenuation);
		vec3 rectLightKd = 1. - rectLightFresnel;
        rectLightKd *= 1. - metalness;

        col += (sphereLightKd * PI_INV * albedo + sphereLightDiffSpec.xyz)
            * SPHERE_LIGHT_INTENSITY * sphereLightDiffSpec.w * sphereLightAttenuation;

        col += (lineLightKd * PI_INV * albedo + lineLightDiffSpec.xyz)
            * LINE_LIGHT_INTENSITY * lineLightDiffSpec.w * lineLightAttenuation;

        col += (rectLightKd * PI_INV * albedo + rectLightDiffSpec.xyz)
            * RECT_LIGHT_INTENSITY * rectLightDiffSpec.w * rectLightAttenuation;

        col += albedo * .025; // global ambient

        // calculate glossy reflection + ibl
        float glossiness = roughness * roughness;
        vec3 indirectSpecular = vec3(.1125, .1875, .25) + reflectDirection.y * .35;
        Ray reflectRay = Ray(position, vec3(0.));
        for (int i = 0; i < REFLECTION_STEPS; ++i)
        {
			float percentage = float(i) / float(REFLECTION_STEPS);
            vec3 delta = rotateAround(vec3(0., 1., 0.), reflectDirection, 
                                      TWO_PI * percentage);
			reflectRay.direction = normalize(delta * glossiness + reflectDirection);
        	vec2 indirectMarchResult = rayMarchNoLights(reflectRay);

            if (floor(indirectMarchResult.y) == 3.)
            {
                vec3 indirectPosition = position + indirectMarchResult.x
                    	* reflectRay.direction;
                indirectSpecular += textureLod(iChannel0, indirectPosition.xz * .18, 0.).rgb;
            }  
            else if(floor(indirectMarchResult.y) == 1.)
                indirectSpecular += SPHERE_ALBEDO;

        }

        indirectSpecular /= float(REFLECTION_STEPS);

        vec2 dfg = PrefilteredDFG_Karis(roughness, NdotV);
        vec3 specularColor = F0 * dfg.x + dfg.y;
        vec3 ibl = indirectSpecular * specularColor
            + Irradiance_SphericalHarmonics(normal) * PI_INV * albedo;

        col += ibl * .84;
        col *= LIGHT_COLOR;
    }   

    // fog
    return mix(col, vec3(.01, .006, .004), // brown-ish fog color
               		clamp(1. - exp(-marchResult.x * .08), 0., 1.));
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 blueNoise = texelFetch(iChannel1,
						(iFrame * ivec2(113, 127)) & 63, 0).rg;
    vec2 uv = (2. * (fragCoord + blueNoise) - iResolution.xy) / iResolution.y;
    vec2 st = fragCoord / iResolution.xy;

    Ray ray = getCameraRay(uv);

    vec3 col = renderScene(ray);

    fragColor = vec4(col, 1.);
}

/**
* Creative Commons CC0 1.0 Universal (CC-0)
*
* A basic TAA implementation based on the variance clipping technique by Marco Salvi (Nvidia).
*
*/

const ivec2 offsets[8u] = ivec2[]
(
    ivec2(-1,-1), ivec2(-1, 1), 
	ivec2(1, -1), ivec2(1, 1), 
	ivec2(1, 0),  ivec2(0, -1), 
	ivec2(0, 1),  ivec2(-1, 0)
);

const float gaussian[8u] = float[]
(
    .0625, .0625,
    .0625, .0625,
    .125,  .125,
    .125,  .125
);

vec3 RGBToYCoCg(vec3 RGB)
{
    float Y = dot(RGB, vec3(1, 2,  1))  * .25;
    float Co= dot(RGB, vec3(2, 0, -2))  * .25 + (.5 * 256./255.);
    float Cg= dot(RGB, vec3(-1, 2, -1)) * .25 + (.5 * 256./255.);
    return vec3(Y, Co, Cg) * (1. / (1. + Y)); // tonemap
}

vec3 YCoCgToRGB(vec3 YCoCg)
{
    YCoCg *= 1. / (1. - YCoCg.x); // tonemap
	float Y= YCoCg.x;
	float Co= YCoCg.y - (.5 * 256. / 255.);
	float Cg= YCoCg.z - (.5 * 256. / 255.);
	float R= Y + Co - Cg;
	float G= Y + Cg;
	float B= Y - Co - Cg;
	return vec3(R, G, B);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord / iResolution.xy;
    vec3 currentBuffer = RGBToYCoCg(textureLod(iChannel0, uv, 0.).rgb);
    vec3 historyBuffer = RGBToYCoCg(textureLod(iChannel1, uv, 0.).rgb);

    vec3 mean = currentBuffer;
    vec3 variance = currentBuffer * currentBuffer;
    vec3 filtered = currentBuffer * .25;

    // Marco Salvi's Implementation (by Chris Wyman)
    for(int i = 0; i < 8; i++)
    {
        vec3 neighborTexel = RGBToYCoCg(texelFetch(iChannel0, ivec2(fragCoord.xy) + offsets[i], 0).rgb);
        mean += neighborTexel;
        variance += neighborTexel * neighborTexel;
        filtered += neighborTexel * gaussian[i];
    }

    mean /= 9.;
    variance /= 9.;
    const float stDevMultiplier = 1.5;
	vec3 sigma = sqrt(abs(variance - mean * mean));
	vec3 colorMin = min(filtered, mean - stDevMultiplier * sigma);
	vec3 colorMax = max(filtered, mean + stDevMultiplier * sigma);

    historyBuffer = clamp(historyBuffer, colorMin, colorMax);

    vec3 outColor = mix(historyBuffer, filtered, .05);

	fragColor = vec4(YCoCgToRGB(outColor), 1.);
}

// Perlin sin sphere
// By Paulo Falcao
//
// Inspired on https://x.com/andrewray/status/1791630436789355001
// 
// Made in Material Maker ( https://www.materialmaker.org/material?id=987 )
//
// Generated shader revised for shadertoy
//

vec3 rand33(vec3 p) {
	p = vec3(dot(p, vec3(127.1, 311.7, 74.7)), dot(p, vec3(269.5, 183.3, 246.1)), dot(p, vec3(113.5, 271.9, 124.6)));
	return -1. + 2. * fract(sin(p) * 43758.545);
}

float tex3d_fbm_perlin_nowrap(vec3 coord, vec3 size) {
	vec3 t,
	     o = floor(coord) + size,
	     f = fract(coord),
	     v000 = normalize(rand33(o) - vec3(.5)),
	     v001 = normalize(rand33(o + vec3(0, 0, 1)) - vec3(.5)),
	     v010 = normalize(rand33(o + vec3(0, 1, 0)) - vec3(.5)),
	     v011 = normalize(rand33(o + vec3(0, 1, 1)) - vec3(.5)),
	     v100 = normalize(rand33(o + vec3(1, 0, 0)) - vec3(.5)),
	     v101 = normalize(rand33(o + vec3(1, 0, 1)) - vec3(.5)),
	     v110 = normalize(rand33(o + vec3(1, 1, 0)) - vec3(.5)),
	     v111 = normalize(rand33(o + vec3(1)) - vec3(.5));
	float p000 = dot(v000, f),
	      p001 = dot(v001, f - vec3(0, 0, 1)),
	      p010 = dot(v010, f - vec3(0, 1, 0)),
	      p011 = dot(v011, f - vec3(0, 1, 1)),
	      p100 = dot(v100, f - vec3(1, 0, 0)),
	      p101 = dot(v101, f - vec3(1, 0, 1)),
	      p110 = dot(v110, f - vec3(1, 1, 0)),
	      p111 = dot(v111, f - vec3(1));
	t = f * f * f * (f * (f * 6. - 15.) + 10.);
	return .5 + mix(mix(mix(p000, p100, t.x), mix(p010, p110, t.x), t.y), mix(mix(p001, p101, t.x), mix(p011, p111, t.x), t.y), t.z);
}

float fbm3d_perlin_nowrap(vec3 coord) {
	vec3 size = vec3(.5);
	float normalize_factor = 0.,
	      value = 0.,
	      scale = 1.;
	for (int i = 0; i < 1; i++) {
		value += tex3d_fbm_perlin_nowrap(coord * size, size) * scale;
		normalize_factor += scale;
		size *= 2.;
		scale *= 1.2;
	}

	return value / normalize_factor;
}

vec3 MFSDF_Obj_Maker_rotate3d(vec3 p, vec3 a) {
	float c = cos(a.x),
	      s = sin(a.x);
	vec3 rv;
	rv.x = p.x;
	rv.y = p.y * c + p.z * s;
	rv.z = -p.y * s + p.z * c;
	c = cos(a.y);
	s = sin(a.y);
	p.x = rv.x * c + rv.z * s;
	p.y = rv.y;
	p.z = -rv.x * s + rv.z * c;
	c = cos(a.z);
	s = sin(a.z);
	rv.x = p.x * c + p.y * s;
	rv.y = -p.x * s + p.y * c;
	rv.z = p.z;
	return rv;
}

vec2 Simple360HDR_equirectangularMap(vec3 dir) { return vec2(atan(dir.y, dir.x), acos(dir.z)) / vec2(6.28319, 3.1415926); }

float Simple360HDR_hash12(vec2 p) {
	vec3 p3 = fract(p.xyx * .1031);
	p3 += dot(p3, p3.yzx + 33.33);
	return fract((p3.x + p3.y) * p3.z);
}

float Simple360HDR_noise(vec2 v) {
	vec2 v1 = floor(v),
	     v2 = smoothstep(0., 1., fract(v));
	return mix(mix(Simple360HDR_hash12(v1), Simple360HDR_hash12(v1 + vec2(0, 1)), v2.y), mix(Simple360HDR_hash12(v1 + vec2(1, 0)), Simple360HDR_hash12(v1 + vec2(1)), v2.y), v2.x);
}

float Simple360HDR_noiseOct(vec2 p) {
    return Simple360HDR_noise(p) * .5 + Simple360HDR_noise(p * 2. + 13.) * .25 + Simple360HDR_noise(p * 4. + 23.) * .15 + Simple360HDR_noise(p * 8. + 33.) * .1 + Simple360HDR_noise(p * 16. + 43.) * .05;
}

vec3 Simple360HDR_skyColor(vec3 p) {
	vec3 v = (Simple360HDR_noiseOct(p.xz * .1) - .5) * vec3(1);
	float d = length(p);
	return mix(vec3(.15, .3, .6) + v, vec3(.2, .5, 1) + v * 12. / max(d, 20.), clamp(d * .1, 0., 1.));
}

vec3 Simple360HDR_floorColor(vec3 p) {
    return (Simple360HDR_noiseOct(p.xz * .1) * .5 + .25) * vec3(.7, .5, .4);
}

vec3 Simple360HDR_renderHDR360(vec3 rd) {
	vec3 p, c;
	if (rd.y > 0.) {
		p = rd * 5. / rd.y;
		c = Simple360HDR_skyColor(p);
	}
	else {
		p = rd * -10. / rd.y;
		c = mix(Simple360HDR_floorColor(p), vec3(.5, .7, 1), clamp(1. - sqrt(-rd.y) * 3., 0., 1.));
	}

	float ds = clamp(dot(vec3(-.57735, .57735, -.57735), rd), 0., 1.);
	vec3 sunc = (ds > .9997 ? vec3(2) : vec3(0)) + pow(ds, 512.) * 4. + pow(ds, 128.) * vec3(.5) + pow(ds, 4.) * vec3(.5);
	if (rd.y > 0.) c += vec3(.3) * pow(1. - abs(rd.y), 3.) * .7;
	return c + sunc;
}

vec3 Simple360HDR_make360hdri(vec2 p) {
	vec2 thetaphi = (p * 2. - vec2(1)) * vec2(3.1415926, 1.5708);
	return Simple360HDR_renderHDR360(vec3(cos(thetaphi.y) * cos(thetaphi.x), sin(thetaphi.y), cos(thetaphi.y) * sin(thetaphi.x)));
}

float o7714_input_sdf(vec3 p) { return length(p) - 1.6; }

vec3 o7714_input_tex3d(vec4 p) { return sin(vec3(fbm3d_perlin_nowrap(p.xyz)) * 68.442 - iTime * 5.) * .868; }

vec3 normal_o7714(vec3 p) {
	return normalize(p);
}

vec4 distortHeighByNormal_o7714(vec3 uv) {
	float d = o7714_input_sdf(uv);
	if (d <= .081) {
		vec3 n = normal_o7714(uv),
		     s = o7714_input_tex3d(vec4(uv - d * n, 0));
		return vec4(s, o7714_input_sdf(uv - n * s * .071));
	}

	return vec4(vec3(0), d);
}

vec3 o7710_input_BaseColor_tex3d(vec4 p) {
	vec4 o7714_0_d = distortHeighByNormal_o7714((p).xyz);
	o7714_0_d.w /= 1.98882;
	return vec3(o7714_0_d.xyz * .882 + vec3(.636));
}

float o7710_input_sdf3d(vec3 p) {
	vec4 o7714_0_d = distortHeighByNormal_o7714((p).xyz);
	o7714_0_d.w /= 1.98882;
	return o7714_0_d.w;
}

vec4 PBRObjectMaker_o7710(vec4 uv) {
	uv.xyz = MFSDF_Obj_Maker_rotate3d(uv.xyz, vec3(iTime * 9., iTime * 5., iTime * 7.) * .01745329) ;
	float sdf = o7710_input_sdf3d(uv.xyz) ;
	if (uv.w > .5) return vec4(vec3(1) * clamp(o7710_input_BaseColor_tex3d(vec4(uv.xyz, 1)), vec3(0), vec3(1)), sdf);
	else return vec4(vec3(0), sdf);
}

vec4 o7702_input_mfsdf(vec4 p) { return PBRObjectMaker_o7710(p); }

vec3 o7702_input_hdri(vec2 uv) { return Simple360HDR_make360hdri(vec2((uv).x, -(uv).y + 1.)); }

vec3 normal_o7702(vec3 p) {
	const vec3 e = vec3(.001, -.001, 0);
	float v1 = o7702_input_mfsdf(vec4(p + e.xyy, 0)).w,
	      v2 = o7702_input_mfsdf(vec4(p + e.yyx, 0)).w,
	      v3 = o7702_input_mfsdf(vec4(p + e.yxy, 0)).w,
	      v4 = o7702_input_mfsdf(vec4(p + e.xxx, 0)).w;
	return normalize(vec3(v4 + v1 - v3 - v2, v3 + v4 - v1 - v2, v2 + v4 - v3 - v1));
}

void march_o7702(inout float d, inout vec3 p, float dS, vec3 ro, vec3 rd) {
	for (int i = 0; i < 500; i++) {
		p = ro + rd * d;
		dS = o7702_input_mfsdf(vec4(p, 0)).w;
		d += dS;
		if (d > 50. || abs(dS) < 1e-4) break;
	}
}


vec3 raymarch_o7702(vec2 uv) {
	float objMetallic,
	      d = 0.,
	      dS = 0.;
	uv -= .5;
	vec3 objColor,
	     color = vec3(0),
	     cam = vec3(sin(iTime * .2) * 5., sin(iTime * .13) + 2., 5),
	     ray = normalize(vec3(0) - cam),
	     cX = normalize(cross(vec3(0, 1, 0), ray)),
	     rd = normalize(ray * 1.5 + cX * uv.x + normalize(cross(cX, ray)) * uv.y),
	     ro = cam,
	     p = vec3(0);
	march_o7702(d, p, dS, ro, rd);
	objColor = o7702_input_mfsdf(vec4(p, 1)).xyz;
	objMetallic = 0.9;
	if (d < 50.) {
		vec3 ref, objColorRef,
		     n = normal_o7702(p);
		ref = normalize(reflect(rd, -n));
		objColorRef = o7702_input_hdri(Simple360HDR_equirectangularMap(ref.xzy)).xyz;
		color = mix(color, objColorRef,mix(vec3(1), objColor, objMetallic));
	}
	else color = o7702_input_hdri(Simple360HDR_equirectangularMap(rd.xzy)).xyz;

	return pow(color, vec3(.71429));
}

void mainImage(out vec4 fragColor, vec2 fragCoord) {
	float minSize = min(iResolution.x, iResolution.y);
	fragColor = vec4(raymarch_o7702(vec2(0, 1) + vec2(1, -1) * (fragCoord - .5 * (iResolution.xy - vec2(minSize))) / minSize), 1);
}

