#define LOD 0                // Compatible with MIPmapping and compression ! 
#define TILE 8               // Size of tiles in min/max acceleration structure
#define TILE2 4              // Size of tiles2 in upper level
#define Ntile  (256/TILE)    // number of tiles
#define Ntile2 (Ntile/TILE2) // number of tiles2 

int CAPS=0;     // === fonts & message from https://www.shadertoy.com/results?query=message
#define low CAPS=32;
#define caps CAPS=0;
#define spc  U.x-=.5;
#define char(c) T+= U.x<.0||U.x>1.||U.y<0.||U.y>1. ?vec4(0): textureGrad( iChannel3, U/16. + fract( vec2(c, 15-(c)/16) / 16.), dFdx(U/16.),dFdy(U/16.) )
#define initMsg vec4 T = vec4(0);
#define endMsg  return length(T.yz)==0. ? 0. : T.x;
#define C(c) spc char(64+CAPS+c);

float message(vec2 U) { // --- display waiting message "Click URL to load geometry"
    initMsg
    C(3) low C(12)C(9)C(3)C(11) spc caps C(21)C(18)C(12) spc low C(20)C(15) spc
    C(12)C(15)C(1)C(4) spc C(7)C(5)C(15)C(13)C(5)C(20)C(18)C(25)
    endMsg
}

void mainImage( out vec4 O, vec2 U )
{
    vec2 R = iResolution.xy; // === initialization
    if ( iFrame<1 || texelFetch(iChannel0,ivec2(0),0).a == 0. ) { // structure not yet computed
        if ( iChannelResolution[1].x <1. ) {          // geom image loaded not yet loaded
            O.rgb = vec3( message((U/R.y-vec2(0,.2))*8.) ); // display load message
        } else {                             // init min/max acceleration structure
            U -= .5; O-=O;
            if (max(U.x/2.,U.y) <= float(Ntile) ) {
                float s = mod(U.x,2.)<1. ? 1. : -1.; // compute min on even pixels and max on odd pixels
                vec3 M = vec3(1e5);
                for(int y = 0; y < TILE; y++)
                    for(int x = 0; x < TILE; x++)
                        M = min(M, s* texelFetch(iChannel1,ivec2(U.x/2.,U.y)*TILE+ivec2(x,y), 0).xyz) ;
                    O.xyz = s*M; O.w = 1.;
            } else {
                U.y -= float(Ntile+1);
                if (U.y>=0. && max(U.x/2.,U.y) <= float(Ntile2+1) ) {
                float s = mod(U.x,2.)<1. ? 1. : -1.; // compute min on even pixels and max on odd pixels
                vec3 M = vec3(1e5);
                for(int y = 0; y < TILE*TILE2; y++)
                    for(int x = 0; x < TILE*TILE2; x++)
                        M = min(M, s* texelFetch(iChannel1,ivec2(U.x/2.,U.y)*TILE*TILE2+ivec2(x,y), 0).xyz) ;
                    O.xyz = s*M; O.w = 1.;                    
        }}}
        return;
    }

    O = texelFetch(iChannel0,ivec2(U), 0);          // restore struct + prev image 
    if (max(U.x/2.,U.y) <= float(Ntile) ) return;   // preserve minmax struct. Ok, should be in another buffer :-)
    if (max(U.x/2.,U.y-float(Ntile+1)) <= float(Ntile2) ) return;

    // === display geometry image as slice of voxels (cumulated in time).
    // indeed, we could now do it in Image buffer.

    U *= 256./R.y; U.x -= float(2*Ntile);
    if (max(U.x/1.2,U.y)>256.) return;              // image is clamped anyway

    float eps = 2.*exp2(float(LOD)) / 256.,         // / 4. to see vertices
          //z = fract(iTime);
            z = fract(float(iFrame<<LOD)/256./1.2);
    O-=O;
    for (z=1.+eps; z>=-eps; z-=eps) 
    {
        vec3 P = vec3( U/257., z*1.2-.1 );          // target voxel center
        P.xz = .5 + ( P.xz-.5) * mat2(cos( 6.28*iMouse.x/R.x + vec4(0,33,11,0))); // scene rotation with mouse
        P.yz = .5 + ( P.yz-.5) * mat2(cos(-3.14*iMouse.y/R.y + vec4(0,33,11,0))); // rot from https://www.shadertoy.com/view/XlsyWX
        if ( min(P.x,min(P.y,P.z))<-eps ||  max(P.x,max(P.y,P.z))>1.+eps ) continue; // scene BBox

        for(int t2y = 0; t2y < Ntile2; t2y++)
            for(int t2x = 0; t2x < Ntile2; t2x++) 
            {
                vec3 m = texelFetch(iChannel0,ivec2(2*t2x  ,t2y+Ntile+1), 0).xyz - P,
                     M = texelFetch(iChannel0,ivec2(2*t2x+1,t2y+Ntile+1), 0).xyz - P;
                if ( max(m.x,max(m.y,m.z)) <= eps && min(M.x,min(M.y,M.z)) >= -eps ) { // tile2 contains a visible tile

                    for(int ty = 0; ty < TILE2; ty++)
                        for(int tx = 0; tx < TILE2; tx++) 
                        {
                            m = texelFetch(iChannel0,ivec2(2*(t2x*TILE2+tx)  ,t2y*TILE2+ty), 0).xyz - P,
                            M = texelFetch(iChannel0,ivec2(2*(t2x*TILE2+tx)+1,t2y*TILE2+ty), 0).xyz - P;              
                            if ( max(m.x,max(m.y,m.z)) <= eps && min(M.x,min(M.y,M.z)) >= -eps ) { // tile contains a visible voxel
                                for(int y = 0; y < TILE>>LOD; y++)
                                    for(int x = 0; x < TILE>>LOD; x++) {
                                        vec3 T = texelFetch(iChannel1,(ivec2(t2x,t2y)*TILE2+ivec2(tx,ty))*(TILE>>LOD)+ivec2(x,y), LOD).xyz - P;
                                        if (abs(T.z)<eps && dot(T.xy,T.xy)<eps*eps) { O = vec4(z); return; }
                                    }
                                //tx=ty=999; // stop ray. wrong: could be the eps-neighbor, and not even monotonous anyway.
                            }
                        }
                }
            }
    }
}

