float obj(vec3 pos){
    pos -= vec3(0.,0.13,0.);
    float  n = noise(pos);
    // float res =  length(max(abs(pos)-vec3(0.8,0.4,0.4)-n,0.0))-0.1;

    float res = length(pos)-(1.- 0.3*n);
    return res;
}

//raymarching step I
//find object
float disobj(vec3 pointpos,vec3 dir){
    float dd = 1.;
    float d = 0.;
    for(int i = 0;i<30;++i){
      vec3 sphere = pointpos + dd*dir;
          d = obj(sphere);
      dd += d;
      if(d<0.02)break;
    }
    return dd;
}

