float objdetal(in vec3 p) {
  	float res = 0.;
    vec3 c = p;
  	for (int i = 0; i < 10; ++i) {
        p =1.7*abs(p)/dot(p,p) -0.8;
        //p.yz= csqr(p.yz);
        p=p.zxy;
        res += exp(-20. * abs(dot(p,c)));        
  }
  return res/2.;
}
