vec4 background(in vec3 pos, in vec3 n,in vec3 lightDir ) {
    vec3 n0=n;
    const vec3 P=vec3(30000);//atmosphere thickness
    const float k=0.25;//mix


    const vec3 Mie=vec3(0.2);

    const vec3 Rayleigh=5.e10*pow(vec3(1./700.,1./520.,1./450.),vec3(4));

    const vec3 k0=mix(Rayleigh,Mie,k);

    const vec3 Q=k0/(P*P);//absorption
    const vec3 Sun=vec3(10,10,10);//sun color
    const vec3 g0=mix(Rayleigh*0.01,vec3(0.9),k);//single scatter
    n.y=max(n.y,1e-5);
    vec3 g=3./(8.*PI)*(1.+pow(dot(n,lightDir),2.))*(1.-g0*g0)/(2.+g0*g0)/pow(1.+g0*g0-2.*g0*dot(lightDir,n),vec3(1.5));
    vec3 t=Q*0.5*(P-pos.y)*(P-pos.y);
    vec3 c=Sun*g*(exp(-t/n.y)-exp(-t/lightDir.y))/(n.y-lightDir.y)*max(lightDir.y,0.);

    c+=exp(-t/n.y)*Sun*smoothstep(0.997,0.9975,dot(n0,lightDir));
	 return vec4(clamp(c,0.,50.),smoothstep(0.997,0.9975,dot(n0,lightDir)));
}

