    //Iterate through points
    for(int i; i<81;
    //Add projected, colored points to output
    O += (cos(a.y/.1+vec4(0,1,2,0))+1.)/length((I+I-r-r*b/(b.y+9.))/r.y-a*.4)/3e2)
        //2D point position (-4 to +4)
        a = vec2(i%9,i++/9)-4.,
        //Rotated position
