}

mat2 rot2d(float angle){
    float s = sin(angle);
    float c = cos(angle);
    return mat2(c, -s, s, c);
}

// Written by GLtracy

// ray marching const
const int max_iterations = 255;
const float stop_threshold = 0.001;
const float step_scale = 0.5;
const float grad_step = 0.1;
const float clip_far = 1000.0;

// math const
const float PI = 3.14159265359;
const float DEG_TO_RAD = PI / 180.0;

// math
mat2 rot2( float angle ) {
	float c = cos( angle );
	float s = sin( angle );

	return mat2(
		 c, s,
		-s, c
	);
}

// angle : pitch, yaw
mat3 rot3xy( vec2 angle ) {
	vec2 c = cos( angle );
	vec2 s = sin( angle );

	return mat3(
		c.y      ,  0.0, -s.y,
		s.y * s.x,  c.x,  c.y * s.x,
		s.y * c.x, -s.x,  c.y * c.x
	);
}

float smin( float a, float b, float r ) {
	float h = max( r-abs(a-b), 0.0 );
    return min( a, b ) - h*h*(0.25/max(r, 1e-3));
}

// distance function
float dist_sphere( vec3 v, float r ) {
    return length( v ) - r;
}

float dist_box( vec3 v, vec3 size, float r ) {
	return length( max( abs( v ) - size, 0.0 ) ) - r;
}

// distance in the world
float dist_field( vec3 v ) {
	// sphere
	float d0 = dist_sphere( v, 2.7 );
    float d1 = dist_box( v, vec3(2.0), 0.1 );

	return min(d0, d1);
}

// gradient in the world
vec3 gradient( vec3 v ) {
	const vec3 dx = vec3( grad_step, 0.0, 0.0 );
	const vec3 dy = vec3( 0.0, grad_step, 0.0 );
	const vec3 dz = vec3( 0.0, 0.0, grad_step );
	return normalize (
		vec3(
			dist_field( v + dx ) - dist_field( v - dx ),
			dist_field( v + dy ) - dist_field( v - dy ),
			dist_field( v + dz ) - dist_field( v - dz )			
		)
	);
}

// ray marching
float ray_marching( vec3 origin, vec3 dir, float start, float end ) {
	float depth = start;
	for ( int i = 0; i < max_iterations; i++ ) {
		float dist = dist_field( origin + dir * depth );
		if ( dist < stop_threshold ) {
			return depth;
		}
		depth += dist * step_scale;
		if ( depth >= end) {
			return end;
		}
	}
	return end;
}

// ray direction
vec3 ray_dir( float fov, vec2 size, vec2 pos ) {
	vec2 xy = pos - size * 0.5;

	float cot_half_fov = tan( ( 90.0 - fov * 0.5 ) * DEG_TO_RAD );	
	float z = size.y * 0.5 * cot_half_fov;

	return normalize( vec3( xy, -z ) );
}

// brdf
vec3 radiance(
	vec3 n,		// macro surface normal
	vec3 l,		// direction from vertex to light
	vec3 v,		// direction from vertex to view
	// matt
	float m,	// roughness
	vec3 cdiff,	// diffuse  reflectance
	vec3 cspec,	// specular reflectance : F0
	// light
	vec3 clight	// light intensity
) {
	// half vector
	vec3 h = normalize( l + v );

	// dot
	float dot_n_h = max( abs( dot( n, h ) ), 0.001 );
	float dot_n_v = max( abs( dot( n, v ) ), 0.001 );
	float dot_n_l = max( abs( dot( n, l ) ), 0.001 );
	float dot_h_v = max( abs( dot( h, v ) ), 0.001 ); // dot_h_v == dot_h_l

	// Geometric Term
#if 1
    // Cook-Torrance
    //          2 * ( N dot H )( N dot L )    2 * ( N dot H )( N dot V )
	// min( 1, ----------------------------, ---------------------------- )
	//                 ( H dot V )                   ( H dot V )
	float g = 2.0 * dot_n_h / dot_h_v;
	float G = min( min( dot_n_v, dot_n_l ) * g, 1.0 );
#else
    // Implicit
    float G = dot_n_l * dot_n_v;
#endif

    // Normal Distribution Function ( cancel 1 / pi )
#if 1
 	// Beckmann distribution
	//         ( N dot H )^2 - 1
	//  exp( ----------------------- )
	//         ( N dot H )^2 * m^2
	// --------------------------------
	//         ( N dot H )^4 * m^2
    float sq_nh   = dot_n_h * dot_n_h;
	float sq_nh_m = sq_nh * ( m * m );
	float D = exp( ( sq_nh - 1.0 ) / sq_nh_m ) / ( sq_nh * sq_nh_m );
#else
    // Blinn distribution
    float shininess = 2.0 / ( m * m ) - 2.0;
    float D = ( shininess + 2.0 ) / 2.0 * pow( dot_n_h, shininess );
#endif

	// Specular Fresnel Term : Schlick approximation
	// F0 + ( 1 - F0 ) * ( 1 - ( H dot V ) )^5
	vec3 Fspec = cspec + ( 1.0  - cspec ) * pow( 1.0 - dot_h_v, 5.0 );

	// Diffuse Fresnel Term : violates reciprocity...
	// F0 + ( 1 - F0 ) * ( 1 - ( N dot L ) )^5
	vec3 Fdiff = cspec + ( 1.0  - cspec ) * pow( 1.0 - dot_n_l, 5.0 );

	// Cook-Torrance BRDF
	//          D * F * G
	// ---------------------------
	//  4 * ( N dot V )( N dot L )
	vec3 brdf_spec = Fspec * D * G / ( dot_n_v * dot_n_l * 4.0 );

	// Lambertian BRDF ( cancel 1 / pi )
	vec3 brdf_diff = cdiff * ( 1.0 - Fdiff );

	// Punctual Light Source ( cancel pi )
	return ( brdf_spec + brdf_diff ) * clight * dot_n_l;	
}

// shading
vec3 shading( vec3 v, vec3 n, vec3 eye ) {
	// matt
	float roughness = 0.4;
	vec3 cdiff = vec3( 0.6 );
	vec3 cspec = vec3( 0.6 );

	vec3 ve = normalize( eye - v );

	vec3 final = vec3( 0.0 );	

	// light 0
	{
		vec3 light = vec3( 2.0, 5.0, 2.0 );
		vec3 clight = vec3( 0.4, 0.6, 0.8 );

		vec3 vl = normalize( light - v );

		final += radiance( n, vl, ve, roughness, cdiff, cspec, clight );
	}

	// light 1
	{
		vec3 light = vec3( -3.0, 7.0, -3.0 );
		vec3 clight = vec3( 0.8, 0.5, 0.3 );

		vec3 vl = normalize( light - v );

		final += radiance( n, vl, ve, roughness, cdiff, cspec, clight );
	}

	return final;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
	// default ray dir
	vec3 dir = ray_dir( 45.0, iResolution.xy, fragCoord.xy );

	// default ray origin
	vec3 eye = vec3( 0.0, 0.0, 10.0 );

	// rotate camera
	mat3 rot = rot3xy( vec2( -DEG_TO_RAD*30.0, iTime * 0.5 ) );
	dir = rot * dir;
	eye = rot * eye;

	// ray marching
	float depth = ray_marching( eye, dir, 0.0, clip_far );
	if ( depth >= clip_far ) {
		fragColor = vec4( 0.0, 0.0, 0.0, 1.0 );
        return;
	}

	// shading
	vec3 pos = eye + dir * depth;
	vec3 n = gradient( pos );
	fragColor = vec4( shading( pos, n, eye ), 1.0 );
}

#define MAX_DIST 500.0

#define INTEGRATE_UNBOUNDED_STUFF 1
// set to 0 to make the density of the glowy stuff 1/(distance^2)
// by default it's 1/distance, which means the total glow contribution grows with MAX_DIST
// I think it looks better with 1/distance
// but, hey, neither of these functions come from "physics"
// (or, if they do, it is only by coincidence)
//
// p.s. looks really nice when MAX_DIST is huge (thanks @CLPB for pointing this out)

const vec3 light = vec3(0.48, 0.64, -0.6);

vec3 ball1;
vec3 ball2;
vec3 ball3;

vec3 radii;

float sdf1(in vec3 pt) {
    return length(max(vec3(0.0), abs(pt - ball1) - 0.5 * radii.x)) - 0.25 * radii.x;
}

float sdf2(in vec3 pt) {
    vec2 tor = vec2(length(pt.xy - ball2.xy) - 0.75 * radii.y, pt.z);
    return length(tor) - 0.25* radii.y;
}

float sdf3(in vec3 pt) {
    return length(pt - ball3) - radii.z;
}

vec3 sdfs(in vec3 pt) {
    return vec3(sdf1(pt), sdf2(pt), sdf3(pt));
}

float sdf(in vec3 pt) {
    return min(sdf1(pt), min(sdf2(pt), sdf3(pt)));
}

float min_comp(in vec3 comps) {
    return min(comps.x, min(comps.y, comps.z));
}

vec3 sdf_grad(in vec3 pt) {
    float f = sdf(pt);
    const float h = 0.001;
    const float h_inv = 1000.0;

    return vec3(sdf(pt + vec3(h, 0.0, 0.0)) - f,
                sdf(pt + vec3(0.0, h, 0.0)) - f,
                sdf(pt + vec3(0.0, 0.0, h)) - f);
}

float raymarch(in vec3 orig, in vec3 dir, out vec3 integral) {
    integral = vec3(0.0);
    float curr = 0.0;
    const float step_ratio = 0.25;
    vec3 curr_sdf = sdfs(orig);
    float dist = step_ratio * min_comp(curr_sdf);
    vec3 next_sdf = sdfs(orig + dir * dist);
    // integral from 0 to d of 1/(a+bx) =
    // screw it, just average some things.
    integral = dist * (0.25 / curr_sdf + 1.0 / (curr_sdf + next_sdf) + 0.25 / next_sdf);
    float total_dist = dist;
    const vec3 thresh = vec3(0.004);
    for (int i = 0; i < 128; ++i) {
        curr_sdf = next_sdf;
        dist = step_ratio * min_comp(curr_sdf);
        total_dist += dist;
        next_sdf = sdfs(orig + total_dist * dir);
        vec3 mid = 0.5 * (curr_sdf + next_sdf);
#if INTEGRATE_UNBOUNDED_STUFF        
        integral += dist * (0.25 / max(thresh, curr_sdf) + 
                            0.5 / max(thresh, mid ) + 
                            0.25 / max(thresh, next_sdf));
#else
        integral += dist * (0.25 / max(thresh, curr_sdf * curr_sdf) + 
                            0.5 / max(thresh , mid * mid ) + 
                            0.25 / max(thresh, next_sdf * next_sdf));
#endif        
        if (min_comp(next_sdf) < 1.0e-3 || total_dist > MAX_DIST) {
            return total_dist;
        }
    }
    return total_dist;
}


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = (2.0 * fragCoord - iResolution.xy) / iResolution.y;

    vec3 orig = vec3(0.0, 0.1, -1.25);
    vec3 dir = normalize(vec3(uv, 1.0));

    mat3 tilt = mat3(1.0, 0.0, 0.0,
                0.0, 0.28, -0.96,
                0.0, 0.96, 0.28); 
    orig = tilt * orig;
    dir = tilt * dir;

    float theta = 0.6 * iTime;
    float ct = cos(theta);
    float st = sin(theta);

    float rad = 0.6;

    ball1 = rad * vec3(ct, st, 0.0);

    ct = cos(theta + 2.0 * 3.141592654 / 3.0);
    st = sin(theta + 2.0 * 3.141592654 / 3.0);
    ball2 = rad * vec3(ct, st, 0.0);

    ct = cos(theta - 2.0 * 3.141592654 / 3.0);
    st = sin(theta - 2.0 * 3.141592654 / 3.0);
    ball3 = rad * vec3(ct, st, 0.0);

    vec3 integral;

    radii = 0.3 + 0.2 * vec3(texture(iChannel0, vec2(0.0, 0.0)).r,
                             texture(iChannel0, vec2(0.5, 0.0)).r,
                             texture(iChannel0, vec2(1.0, 0.0)).r);

    float raydist = raymarch(orig, dir, integral);

#if INTEGRATE_UNBOUNDED_STUFF    
    vec3 col = smoothstep(0.15 * (1.0 *  radii), vec3(0.0), 0.45/(integral));
#else
    vec3 col = smoothstep(0.15 * (1.0 *  radii), vec3(0.0), 1.5/(integral));    
#endif    

    if (raydist < MAX_DIST) {
        vec3 pt = orig + raydist * dir;
        vec3 norm = normalize(sdf_grad(pt));
        vec3 bounce = normalize(reflect(dir, norm));
        col += 0.25 * smoothstep(0.95, 1.0, dot(bounce, light)) * vec3(0.9, 0.8, 1.0);
    }

    // Output to screen
    fragColor = vec4(col,1.0);
}

