    float theta = iTime * 3.141592 * 0.20;
    float x = 5.0 * cos(theta*0.5);
    float z = 5.0 * sin(theta*0.5);
    vec3 ro = vec3(0.5*x, 4.0, 5.3);

    vec3 ta = vec3(0.0, 0.25, 0.0);
    vec3 cw = normalize(ta - ro);
    vec3 cp = vec3(0.0, 1.0, 0.0);
    vec3 cu = normalize(cross(cw, cp));
    vec3 cv = normalize(cross(cu, cw));
    vec3 rd = normalize(p.x * cu + p.y * cv + 7.5 * cw);

    lightpos = vec3(1,0.7 + 0.2 * sin(theta*2.0),1); 

    vec3 col = vec3(0);
   	float t= castRay(ro, rd, 15.0,uv);    
	float depth = clamp(t/5.-1.3,0.,1.);
	if (t>15.) t=-1000000.;

	col+=0.3*scatter*vec3(1,0.8,0.6);


	fragColor = vec4(col,0.);
}

/*

Based on https://www.shadertoy.com/view/Xds3zN

A Fake Caustics Effect by Ray marched Invert ambient occlusion

*/

#define SAMPLES 32
#define MAXDEPTH 10

#if 1 
#define INVERSEAO 1      //0, 1 for ao or caustics
#define MINWEIGHTMODE 0  //0, 1, 2 for weaker, normal, stronger value
#define WEIGHTMODE 1     //0, 1 for normal, stronger value
#else
#define INVERSEAO 0
#define MINWEIGHTMODE 1
#define WEIGHTMODE 0
#endif


float sdPlane( vec3 p )
{
    return p.y;
}

float sdSphere( vec3 p, float s )
{
    return length(p)-s;
}

float sdBox( vec3 p, vec3 b )
{
    vec3 d = abs(p) - b;
    return min(max(d.x,max(d.y,d.z)),0.0) + length(max(d,0.0));
}

float sdEllipsoid( in vec3 p, in vec3 r )
{
    return (length( p/r ) - 1.0) * min(min(r.x,r.y),r.z);
}

float udRoundBox( vec3 p, vec3 b, float r )
{
    return length(max(abs(p)-b,0.0))-r;
}

float sdTorus( vec3 p, vec2 t )
{
    return length( vec2(length(p.xz)-t.x,p.y) )-t.y;
}

float sdHexPrism( vec3 p, vec2 h )
{
    vec3 q = abs(p);
#if 0
    return max(q.z-h.y,max((q.x*0.866025+q.y*0.5),q.y)-h.x);
#else
    float d1 = q.z-h.y;
    float d2 = max((q.x*0.866025+q.y*0.5),q.y)-h.x;
    return length(max(vec2(d1,d2),0.0)) + min(max(d1,d2), 0.);
#endif
}

float sdCapsule( vec3 p, vec3 a, vec3 b, float r )
{
    vec3 pa = p-a, ba = b-a;
    float h = clamp( dot(pa,ba)/dot(ba,ba), 0.0, 1.0 );
    return length( pa - ba*h ) - r;
}

float sdTriPrism( vec3 p, vec2 h )
{
    vec3 q = abs(p);
#if 0
    return max(q.z-h.y,max(q.x*0.866025+p.y*0.5,-p.y)-h.x*0.5);
#else
    float d1 = q.z-h.y;
    float d2 = max(q.x*0.866025+p.y*0.5,-p.y)-h.x*0.5;
    return length(max(vec2(d1,d2),0.0)) + min(max(d1,d2), 0.);
#endif
}

float sdCylinder( vec3 p, vec2 h )
{
  vec2 d = abs(vec2(length(p.xz),p.y)) - h;
  return min(max(d.x,d.y),0.0) + length(max(d,0.0));
}

float sdCone( in vec3 p, in vec3 c )
{
    vec2 q = vec2( length(p.xz), p.y );
    float d1 = -q.y-c.z;
    float d2 = max( dot(q,c.xy), q.y);
    return length(max(vec2(d1,d2),0.0)) + min(max(d1,d2), 0.);
}

float sdConeSection( in vec3 p, in float h, in float r1, in float r2 )
{
    float d1 = -p.y - h;
    float q = p.y - h;
    float si = 0.5*(r1-r2)/h;
    float d2 = max( sqrt( dot(p.xz,p.xz)*(1.0-si*si)) + q*si - r2, q );
    return length(max(vec2(d1,d2),0.0)) + min(max(d1,d2), 0.);
}

float sdPryamid4(vec3 p, vec3 h ) // h = { cos a, sin a, height }
{
    // Tetrahedron = Octahedron - Cube
    float box = sdBox( p - vec3(0,-2.0*h.z,0), vec3(2.0*h.z) );
    float d = 0.0;
    d = max( d, abs( dot(p, vec3( -h.x, h.y, 0 )) ));
    d = max( d, abs( dot(p, vec3(  h.x, h.y, 0 )) ));
    d = max( d, abs( dot(p, vec3(  0, h.y, h.x )) ));
    d = max( d, abs( dot(p, vec3(  0, h.y,-h.x )) ));
    float octa = d - h.z;
    return max(-box,octa); // Subtraction
}

float length2( vec2 p )
{
    return sqrt( p.x*p.x + p.y*p.y );
}

float length6( vec2 p )
{
    p = p*p*p; p = p*p;
    return pow( p.x + p.y, 1.0/6.0 );
}

float length8( vec2 p )
{
    p = p*p; p = p*p; p = p*p;
    return pow( p.x + p.y, 1.0/8.0 );
}

float sdTorus82( vec3 p, vec2 t )
{
    vec2 q = vec2(length2(p.xz)-t.x,p.y);
    return length8(q)-t.y;
}

float sdTorus88( vec3 p, vec2 t )
{
    vec2 q = vec2(length8(p.xz)-t.x,p.y);
    return length8(q)-t.y;
}

float sdCylinder6( vec3 p, vec2 h )
{
    return max( length6(p.xz)-h.x, abs(p.y)-h.y );
}

//------------------------------------------------------------------

float opS( float d1, float d2 )
{
    return max(-d2,d1);
}

vec2 opU( vec2 d1, vec2 d2 )
{
    return (d1.x<d2.x) ? d1 : d2;
}

vec3 opRep( vec3 p, vec3 c )
{
    return mod(p,c)-0.5*c;
}

vec3 opTwist( vec3 p )
{
    float  c = cos(10.0*p.y+10.0);
    float  s = sin(10.0*p.y+10.0);
    mat2   m = mat2(c,-s,s,c);
    return vec3(m*p.xz,p.y);
}

//------------------------------------------------------------------

float map( in vec3 pos )
{
    vec2 res = opU( vec2( sdPlane(     pos), 1.0 ),
                    vec2( sdSphere(    pos-vec3( 0.0,0.25, 0.0), 0.25 ), 46.9 ) );
    res = opU( res, vec2( sdBox(       pos-vec3( 1.0,0.25, 0.0), vec3(0.25) ), 3.0 ) );
    res = opU( res, vec2( udRoundBox(  pos-vec3( 1.0,0.25, 1.0), vec3(0.15), 0.1 ), 41.0 ) );
    res = opU( res, vec2( sdTorus(     pos-vec3( 0.0,0.25, 1.0), vec2(0.20,0.05) ), 25.0 ) );
    res = opU( res, vec2( sdCapsule(   pos,vec3(-1.3,0.10,-0.1), vec3(-0.8,0.50,0.2), 0.1  ), 31.9 ) );
    res = opU( res, vec2( sdTriPrism(  pos-vec3(-1.0,0.25,-1.0), vec2(0.25,0.05) ),43.5 ) );
    res = opU( res, vec2( sdCylinder(  pos-vec3( 1.0,0.30,-1.0), vec2(0.1,0.2) ), 8.0 ) );
    res = opU( res, vec2( sdCone(      pos-vec3( 0.0,0.50,-1.0), vec3(0.8,0.6,0.3) ), 55.0 ) );
    res = opU( res, vec2( sdTorus82(   pos-vec3( 0.0,0.25, 2.0), vec2(0.20,0.05) ),50.0 ) );
    res = opU( res, vec2( sdTorus88(   pos-vec3(-1.0,0.25, 2.0), vec2(0.20,0.05) ),43.0 ) );
    res = opU( res, vec2( sdCylinder6( pos-vec3( 1.0,0.30, 2.0), vec2(0.1,0.2) ), 12.0 ) );
    res = opU( res, vec2( sdHexPrism(  pos-vec3(-1.0,0.20, 1.0), vec2(0.25,0.05) ),17.0 ) );
    res = opU( res, vec2( sdPryamid4(  pos-vec3(-1.0,0.15,-2.0), vec3(0.8,0.6,0.25) ),37.0 ) );
    res = opU( res, vec2( opS( udRoundBox(  pos-vec3(-2.0,0.2, 1.0), vec3(0.15),0.05),
                               sdSphere(    pos-vec3(-2.0,0.2, 1.0), 0.25)), 13.0 ) );
    res = opU( res, vec2( opS( sdTorus82(  pos-vec3(-2.0,0.2, 0.0), vec2(0.20,0.1)),
                               sdCylinder(  opRep( vec3(atan(pos.x+2.0,pos.z)/6.2831, pos.y, 0.02+0.5*length(pos-vec3(-2.0,0.2, 0.0))), vec3(0.05,1.0,0.05)), vec2(0.02,0.6))), 51.0 ) );
    res = opU( res, vec2( 0.5*sdSphere(    pos-vec3(-2.0,0.25,-1.0), 0.2 ) + 0.03*sin(50.0*pos.x)*sin(50.0*pos.y)*sin(50.0*pos.z), 65.0 ) );
    res = opU( res, vec2( 0.5*sdTorus( opTwist(pos-vec3(-2.0,0.25, 2.0)),vec2(0.20,0.05)), 46.7 ) );
    res = opU( res, vec2( sdConeSection( pos-vec3( 0.0,0.35,-2.0), 0.15, 0.2, 0.1 ), 13.67 ) );
    res = opU( res, vec2( sdEllipsoid( pos-vec3( 1.0,0.35,-2.0), vec3(0.15, 0.2, 0.05) ), 43.17 ) );

    return res.x;
}

float castRay( in vec3 ro, in vec3 rd, float tmax)
{
    float tmin = 1.0;

    float t = tmin;
    float precis = 0.0005;
    for( int i=0; i<64; i++ )
    {
        float res = map( ro+rd*t );
        if( res<precis || t>tmax ) break;
        t += res;
    }
    return t;
}

float castRayAO( in vec3 ro, in vec3 rd)
{
    float tmin = 0.1;

    float t = tmin;
    float precis = 0.005;
    for( int i=0; i<MAXDEPTH; i++ )
    {
        float res = map( ro+rd*t );
        if( res<precis  ) 
        {
#if MINWEIGHTMODE>1
        return max(res, 0.0);
#elif MINWEIGHTMODE>0
        return 1. / max(t, 1.001);
#else
        return max(t, 0.0);
#endif
        }

        t += res;
    }
#if WEIGHTMODE>0
    return 1. / max(t, 0.001);
#else
    return 1. / max(t, 1.001);
#endif

}


vec3 calcNormal( in vec3 pos )
{
    vec2 e = vec2(1.0,-1.0)*0.0005;
    return normalize( e.xyy*map( pos + e.xyy ) +
                      e.yyx*map( pos + e.yyx ) +
                      e.yxy*map( pos + e.yxy ) +
                      e.xxx*map( pos + e.xxx ) );
}

#define PI 3.1415926535897932384626
float seed = 0.;
float rand() { return fract(sin(seed++)*43758.5453123); }

vec3 jitter(vec3 d, float phi, float sina, float cosa) {
    vec3 w = normalize(d), u = normalize(cross(w.yzx, w)), v = cross(w, u);
    return (u*cos(phi) + v*sin(phi)) * sina + w * cosa;
}

float calcAO( in vec3 pos, in vec3 nor )
{
    float ao = .0;
    for( int i=0; i<SAMPLES; i++ )
    {
        float r2 = rand();
        vec3 d = jitter(nor, 2.*PI*rand(), sqrt(r2), sqrt(1. - r2));

        ao += castRayAO(pos, d);
    }
    ao /= float(SAMPLES);
#if INVERSEAO > 0
    return clamp( ao, 0.0, 1.0 ); 
#else
    return clamp( 1. - ao, 0.0, 1.0 ); 
#endif
}

vec3 render( in vec3 ro, in vec3 rd )
{
    vec3 col = vec3(0.7, 0.9, 1.0) +rd.y*0.8;
    float t = castRay(ro,rd, 20.0);

    vec3 pos = ro + t*rd;
    vec3 nor = calcNormal( pos );

    float occ = calcAO( pos, nor );
    return vec3(occ, occ, occ);
}

mat3 setCamera( in vec3 ro, in vec3 ta, float cr )
{
    vec3 cw = normalize(ta-ro);
    vec3 cp = vec3(sin(cr), cos(cr),0.0);
    vec3 cu = normalize( cross(cw,cp) );
    vec3 cv = normalize( cross(cu,cw) );
    return mat3( cu, cv, cw );
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 mo = iMouse.xy/iResolution.xy;
    float time = 15.0 + iTime;

    vec2 p = (-iResolution.xy + 2.0*fragCoord)/iResolution.y;

    // camera    
    vec3 ro = vec3( -0.5+3.5*cos(0.1*time + 6.0*mo.x), 1.0 + 2.0*mo.y, 0.5 + 4.0*sin(0.1*time + 6.0*mo.x) );
    vec3 ta = vec3( -0.5, -0.4, 0.5 );

    // camera-to-world transformation
    mat3 ca = setCamera( ro, ta, 0.0 );
    // ray direction
    vec3 rd = ca * normalize( vec3(p.xy,2.0) );

     // render    
     fragColor.rgb = render( ro, rd );
}

const float pi = 3.14159265358979323;

float dot2( in vec3 v ) { return dot(v,v); }

// Originally from https://www.shadertoy.com/view/llcfRf
// Modified to remove the caps and return the whole intersection interval.
vec2 iCappedCone2( in vec3  ro, in vec3  rd, 
                  in vec3  pa, in vec3  pb, 
                  in float ra, in float rb )
{
    vec3  ba = pb - pa;
    vec3  oa = ro - pa;
    vec3  ob = ro - pb;

    float m0 = dot(ba,ba);
    float m1 = dot(oa,ba);
    float m3 = dot(rd,ba);

    // body
    float m4 = dot(rd,oa);
    float m5 = dot(oa,oa);
    float rr = ra - rb;
    float hy = m0 + rr*rr;

    float k2 = m0*m0    - m3*m3*hy;
    float k1 = m0*m0*m4 - m1*m3*hy + m0*ra*(rr*m3*1.0        );
    float k0 = m0*m0*m5 - m1*m1*hy + m0*ra*(rr*m1*2.0 - m0*ra);

    float h = k1*k1 - k2*k0;
    if( h<0.0 ) return vec2(-1.0);

    return ((vec2(-1, +1) * sqrt(h)) - k1) / k2;
}

// Originally from https://www.shadertoy.com/view/4lcSRn
// Modified to remove the caps and return the whole intersection interval.
vec2 iCylinder2( in vec3 ro, in vec3 rd, 
                in vec3 pa, in vec3 pb, in float ra ) // point a, point b, radius
{
    // center the cylinder, normalize axis
    vec3 cc = 0.5*(pa+pb);
    float ch = length(pb-pa);
    vec3 ca = (pb-pa)/ch;
    ch *= 0.5;

    vec3  oc = ro - cc;

    float card = dot(ca,rd);
    float caoc = dot(ca,oc);

    float a = 1.0 - card*card;
    float b = dot( oc, rd) - caoc*card;
    float c = dot( oc, oc) - caoc*caoc - ra*ra;
    float h = b*b - a*c;
    if( h<0.0 ) return vec2(-1.0);

    return ((vec2(-1, +1) * sqrt(h)) - b) / a;
}

float dofLine(vec3 c0, vec3 c1, float ra, vec3 p0, vec3 p1)
{
    float dlen = length(p1 - p0);
    vec3 dir = (p1 - p0) / dlen;

    // Test for intersection of the line segment with the cone of defocused rays.

    vec2 res = iCappedCone2(p0, dir, c0, c1, ra, 0.);

    if(res.y < 0. || res.x > dlen)
    {
        // To avoid rendering subpixel-sized lines which would end up being heavily under-sampled,
        // the center of the defocus cone is modelled as a thick cylinder.

        vec2 res2 = iCylinder2(p0, dir, c0, c1, 2e-3);

        if(res2.y > res2.x && res2.y > 0. && res2.x < dlen)
        {
            res.x = min(res.x, res2.x);
            res.y = max(res.y, res2.y);
        }

        if(res.y < 0. || res.x > dlen)
            return 0.;
    }

    vec3 q0 = p0 + dir * res.x;
    vec3 q1 = p0 + dir * res.y;

    // Contribution is modelled somewhat on the usual monte carlo raytracing.
    // This amounts to integrating coverage of a varying disc by a small point.
    // Function to integrate is: 1 / (pi * ((a * x + b) ^ 2))
    // Integral is: -1 / (pi * a * a * x + pi * a * b)

    vec3 cd = c1 - c0;
    float cl2 = ra / dot(cd, cd);

    float z0 = dot(q0 - c1, cd);
    float z1 = dot(q1 - c1, cd);

    float a = cl2 * (z1 - z0);
    float b = cl2 * z0;

    float i0 = pi * a * b;
    float i1 = pi * a * (a + b);

    i0 = 1e-4 / max(1e-10, abs(i0)) * sign(i0);
	i1 = 1e-4 / max(1e-10, abs(i1)) * sign(i1);

    return min(1., abs(i1 - i0));
}


float heightmap(vec2 uv)
{
    return (texture(iChannel0, uv.yx / 256.).r - .1) * 2.;
}

mat3 rotX(float a)
{
    return mat3(1., 0., 0., 0., cos(a), sin(a), 0., -sin(a), cos(a));
}

mat3 rotY(float a)
{
    return mat3(cos(a), 0., sin(a), 0., 1., 0., -sin(a), 0., cos(a));
}

mat3 rotZ(float a)
{
    return mat3(cos(a), sin(a), 0., -sin(a), cos(a), 0., 0., 0., 1.);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    float time = iTime;
    vec2 uv = fragCoord / iResolution.xy * 2. - 1.;
    uv.x *= iResolution.x / iResolution.y;

    vec3 ro = vec3(-0.2, 1., 0.);
    vec3 focus = ro + vec3(uv.xy, -3.5);

    float ra = .08;
    float t = iTime / 2.;

    mat3 m = rotX(.23);

    vec3 col = vec3(0.0);

    // Landscape.

    for(int y = -14; y < -1; ++y)
    {
        vec3 ps[4];
		for(int x = -6; x < 6; ++x)
        {            
            ps[1] = ps[0];
            ps[3] = ps[2];
            ps[0] = vec3(float(x + 0), 0, float(y + 0)) / 2.;
            ps[2] = vec3(float(x + 0), 0, float(y + 1)) / 2.;

            ps[0].y = heightmap(ps[0].xz + vec2(0., -floor(t))) + cos(iTime / 3.) * .1;
            ps[0].z += fract(t);
            ps[0] = m * ps[0];

            ps[2].y = heightmap(ps[2].xz + vec2(0., -floor(t))) + cos(iTime / 3.) * .1;
            ps[2].z += fract(t);
            ps[2] = m * ps[2];

            if(x > -6)
            {
                if(abs(x) > -y / 2)
                	continue;

                float f = 1. - smoothstep(2.8, 3.2,
                          abs(max(abs(ps[0].z + 3.), max(abs(ps[1].z + 3.),
                          max(abs(ps[2].z + 3.), abs(ps[3].z + 3.))))));

                if(f > 0.01)
                {
                    col += dofLine(ro, focus, ra, ps[0], ps[1]) * f * .5;
                    col += dofLine(ro, focus, ra, ps[1], ps[3]) * f * .5;
                }
            }
        }
    }

    // Dust particles.

    for(int i = 0; i < 32; ++i)
    {
        vec3 dotp = cos(vec3(19, 129, 99) * (float(i))) * vec3(2., 0.4, 5.) + vec3(0, 0.4, 0.);
        dotp.z += t;
        dotp.z = mod(dotp.z, 5.) - 6.;
        dotp = m * dotp;
        float f = 1. - smoothstep(1.5, 2., abs(dotp.z + 3.));
        if(f > 0.01)
        	col += dofLine(ro, focus, ra, dotp, dotp + 1e-4) * f * vec3(1,.8,.2);
    }


    col = pow(col + (1. - smoothstep(0., 3.8, length(uv))) * .1, vec3(1.8, 1.4, 1));

    fragColor.rgb = col * 2.;

    // Gamma correction

    fragColor.rgb = pow(min(fragColor.rgb, 1.), vec3(1. / 2.2)) +
        	texelFetch(iChannel1, ivec2(fragCoord) & 1023, 0).r / 100.;
    fragColor.a = 1.;
}

// more realistic color range
vec3 ACES(vec3 x) {
    float a = 2.51;
    float b =  .06;
    float c = 2.1;
    float d =  .7;
    float e =  .14;
    return (x*(a*x+b))/(x*(c*x+d)+e);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec4 data = texelFetch(iChannel0, ivec2(fragCoord), 0);
    vec3 col = data.rgb/data.w;

    col = pow(col,vec3(.4545)); // gamma correction
    col = ACES(col);

    // vignette
    vec2 p = fragCoord/iResolution.xy;
    col *= clamp(pow(100. * p.x*p.y*(1.-p.x)*(1.-p.y), .1), 0., 1.);
    // dithering
    col += fract(sin(fragCoord.x*vec3(13,1,11)+fragCoord.y*vec3(1,7,5))*158.391832)/255.;

    // output
    fragColor = vec4(col,1.0);
}

#define SAMPLES 4 // renders per frame

// ray indices
#define RED 0
#define GREEN 1
#define BLUE 2

float seed; // randoms seed

// hash functions by me
float hash1() {return fract(sin(seed+=.1)*4561.7564);}

vec2 hash2() {return fract(sin(seed+=.1)*vec2(8472.5636,9854.4213));}

vec3 hash3() {return fract(sin(seed+=.1)*vec3(7653.1285,6912.8512,5914.7134));}

// random normalized vector
vec3 uniformVector() {
    vec3 v = hash3()*2.-1.;
    return normalize(v);
}

// generate a value that depend on the ray index
float rayValues(int n, vec3 v) {
    return n==RED ? v.x : n==GREEN ? v.y : v.z;
}

// sphere intersection function
// thanks to iq: https://iquilezles.org/articles/intersectors/
float sphIntersect(vec3 ro, vec3 rd, vec3 ce, float ra, vec3 mat, int type,
                   float tmax, inout vec3 outn, inout vec3 outmat, inout int outtype) {
    vec3 oc = ro - ce;
    float b = dot(oc, rd);
    float c = dot(oc, oc) - ra*ra;
    float h = b*b - c;
    if (h<0.) return tmax;

    h = sqrt(h);
    float t1 = -b - h;
    float t2 = -b + h;
    float t = t1<.0001 ? t2 : t1;
    if (t>.0001 && t<tmax) {
        outn = (oc + rd*t)/ra;
        outmat = mat;
        outtype = type;
        return t;
    }
    return tmax;
}

// box intersection function
// thanks to iq: https://iquilezles.org/articles/intersectors/
float boxIntersect(vec3 ro, vec3 rd, vec3 ce, vec3 ra, vec3 mat, int type,
                   float tmax, inout vec3 outn, inout vec3 outmat, inout int outtype) {
    vec3 oc = ro - ce;

    vec3 m = 1./rd;
    vec3 n = -m*oc;
    vec3 k = abs(m)*ra;

    vec3 t1 = n - k;
    vec3 t2 = n + k;

	float tN = max(max(t1.x, t1.y), t1.z);
	float tF = min(min(t2.x, t2.y), t2.z);

	if(tN>tF || tF<0.) return tmax;

    float t = tN<.0001 ? tF : tN;
    if (t>.0001 && t<tmax) {
		outn = -sign(rd)*step(t1.yzx,t1.xyz)*step(t1.zxy,t1.xyz);
        outmat = mat;
        outtype = type;
	    return t;
    }
    return tmax;
}

// materials indices
#define LAMBERTIAN 0 // diffuse
#define DIELECTRIC 1 // transparent
#define EMISSIVE 2 // light

// n is the normal
// mat is the color of the object
// type is the type of material: lambertian, dielectric or emissive

float intersect(vec3 ro, vec3 rd, int ray, out vec3 n, out vec3 mat, out int type) {
    float t = 1e10;

    // inside: atmospheric volume
    t = sphIntersect(ro, rd, vec3(0,0,.1), .8-.1*hash1()*rayValues(ray, vec3(3,1,1)), vec3(1), LAMBERTIAN, t, n, mat, type);
    // outside: transparent sphere
    t = sphIntersect(ro, rd, vec3(0,0,.1), .8, vec3(1,.85,.7), DIELECTRIC, t, n, mat, type);

    // inside: atmospheric volume
    t = sphIntersect(ro, rd, vec3(0,0,-1.3), .5-.1*hash1()*rayValues(ray, vec3(2,1,1)), vec3(1), LAMBERTIAN, t, n, mat, type);
    // outside: transparent sphere
    t = sphIntersect(ro, rd, vec3(0,0,-1.3), .5, vec3(1,.85,.7), DIELECTRIC, t, n, mat, type);

    // floor
    t = boxIntersect(ro, rd, vec3(0,-.8,0), vec3(2,0,2), vec3(.3,.4,.5), LAMBERTIAN, t, n, mat, type);

    // light
    t = sphIntersect(ro, rd, vec3(0,1,-1.3), .3, vec3(16), EMISSIVE, t, n, mat, type);

    return t;
}

// diffuse BRDF
vec3 cosineDirection(vec3 n) {
  	vec2 r = hash2();

	vec3 u = normalize(cross(n, vec3(0,1,1)));
	vec3 v = cross(u, n);

	float ra = sqrt(r.y);
	float rx = ra*cos(2.*3.141592*r.x); 
	float ry = ra*sin(2.*3.141592*r.x);
	float rz = sqrt(1.-r.y);
	return normalize(rx*u + ry*v + rz*n);
}

// rendering function
vec3 render(vec3 ro, vec3 rd, int ray) {
    vec3 col = vec3(1);

    for (int i=0; i<12; i++) { // 24 ray bounces
        vec3 n, mat; int type;
        float t = intersect(ro, rd, ray, n, mat, type);
        if (t>=1e10) {
            if (i==0) return vec3(.5+.5*rd.y)*.01; // background
            return vec3(0);
        } else {
            vec3 p = ro + rd*t;
            ro = p;

            col *= mat; // multiply the color by the material albedo

            if (type==LAMBERTIAN) { // diffuse object
                rd = cosineDirection(n);
            } else if (type==DIELECTRIC) { // transparent object
                float fre = dot(rd, n); // fresnel
                float s = sign(fre);
                vec3 m = -n*s;// normal inside and outside
                float ior = 1.6; // refraction index
                float v = (.5-.5*s)/ior+ior*(.5+.5*s);
                // refracted ray + a bit of randomness for a better effect
                rd = normalize(refract(rd, m, v) + .6*uniformVector());
            } else if (type==EMISSIVE) {
                return col;
            }
        }
    }
    return vec3(0); // return black
}

// camera function
mat3 setCamera(vec3 ro, vec3 ta) {
	vec3 w = normalize(ta - ro);
	vec3 u = normalize(cross(w, vec3(0,1,0)));
	vec3 v = cross(u, w);
    return mat3(u, v, w);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec3 tot = vec3(0);
    for (int i=0; i<SAMPLES; i++) {
    seed = float(i)+iTime+dot(sin(fragCoord),vec2(443.712,983.234));

    vec2 of = hash2()-.2;
    vec2 p = (fragCoord+of - .5*iResolution.xy) / iResolution.y;
    vec2 m = (iMouse.xy - .5*iResolution.xy) / iResolution.y;

    float an = m.x*3.141592-1.8; // camera rotation
    vec3 ro = vec3(-4.*sin(an), m.y*3.+1., -4.*cos(an)); // ray origin
    vec3 ta = vec3(0); // target
    mat3 ca = setCamera(ro, ta); // camera matrix
    vec3 rd = ca * normalize(vec3(p,1.5)); // ray direction

    // 3 renders: red, green and blue
    vec3 col = vec3(render(ro, rd, RED).r,
                    render(ro, rd, GREEN).g,
                    render(ro, rd, BLUE).b);
    tot += col;
    }
    tot /= float(SAMPLES);

    // accumulate
    vec4 data = texelFetch(iChannel0, ivec2(fragCoord), 0);
    if (iMouse.z>0.) data*=0.;
    data += vec4(tot,1);

    // output
    fragColor = data;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord/iResolution.xy;

    vec4 w1_b1_w2_b2 = texture(iChannel1, uv);
    vec4 w3_b3_w4_b4 = texture(iChannel2, uv);
    vec4 w5_b5_w6_b6 = texture(iChannel3, uv);
    float t = getT(iTime);
    vec3 rgb = forwardPropagationPrediction(t, w1_b1_w2_b2, w3_b3_w4_b4, w5_b5_w6_b6);

    fragColor = vec4(rgb, 1.);
    // view weight layers un-comment
    // fragColor = w1_b1_w2_b2;
    // fragColor = w3_b3_w4_b4;
    // fragColor = w5_b5_w6_b6;
    vec2 mouseCoords = iMouse.xy/iResolution.xy;
    if ((mouseCoords.x > 0.001 && uv.x > mouseCoords.x) || (mouseCoords.x == 0. && uv.x > 0.5)) {
      fragColor = texture(iChannel0, uv);
    }

}

