// BRDF

// PBR specular from: https://learnopengl.com/#!PBR/Theory
float DistributionGGX(vec3 N, vec3 H, float a)
{
    float a2     = a*a;
    float NdotH  = max(dot(N, H), 0.0);
    float NdotH2 = NdotH*NdotH;

    float nom    = a2;
    float denom  = NdotH2 * (a2 - 1.0) + 1.0;
    denom        = max( denom * denom * tau/2., .00000001 );
    // ^HQ this max causes problems, too big and highlights can't be small and bright,
    // too small and apparently monte carlo blew up (though that could be amplifying other issues)
    // test with a dim light and a polished surface to see the clamping, even when very low

// n.b. this fix is why I had a bokeh-like fade, and why monte carlo tests were going weird on shiny surfaces    

    return nom / denom;
}

float GeometrySchlickGGX(float NdotV, float k)
{
    float nom   = NdotV;
    float denom = NdotV * (1.0 - k) + k;

    return nom / denom;
}

float GeometrySmith(vec3 N, vec3 V, vec3 L, float k)
{
    float NdotV = max(dot(N, V), 0.0);
    float NdotL = max(dot(N, L), 0.0);
    float ggx1 = GeometrySchlickGGX(NdotV, k);
    float ggx2 = GeometrySchlickGGX(NdotL, k);

    return ggx1 * ggx2;
}


// tangent and binormal are difference in pos for an infinitesimal step along u and v respectively
vec3 BRDF(
    vec3 pos,
    float depth,
    vec3 albedo,
    vec3 specCol,
    float roughness,
    vec3 n,
    vec3 i,
    vec3 l,
    vec3 lcol )
{
    float nDotL = max(0.,dot(n,l));
    vec3 diffuse = albedo*nDotL;

	// the maths says it needs this, but I don't really understand why
	diffuse /= (tau*.5);

    vec3 h = normalize(-i+l);

    float spec = DistributionGGX(n,h,roughness)
        		* GeometrySmith(n,-i,l,(roughness+1.)*(roughness+1.)/8.)
        		/ max( .0001, 4. * dot(n,-i) * dot(n,l) );

// this doesn't have a soft falloff - looks like it expects *lambertian    
// hmm... seems like the integral (For monte carlo/env map) includes this, but the brdf doesn't?
// BAH, MATHS!
spec *= nDotL;

    vec3 fresnel = mix( specCol, vec3(1), pow(1.-dot(n,-i),5.) );

    return mix( diffuse, vec3(spec), fresnel )*lcol;
}


vec3 mainImage2( in vec2 fragCoord )
{
    vec3 fragColour = vec3(0);

    // simple test scene: sphere/plane and light(s)
#if defined(PLANE)
	float zoom = 3.0;
    vec3 camp = vec3(1,1.5,-3);
    vec3 target = vec3(0,0,0);
#else    
	float zoom = 2.5;
    vec3 camp = vec3(0,1.5,-5)+.5*sin(iTime*vec3(1,1,0)/4.+vec2(tau*.25,0).xyy);
    vec3 target = vec3(0,0,0);
#endif
    if ( iMouse.z > .0 )
    {
        vec2 a = 2.*(iMouse.xy-iResolution.xy*.5)/iResolution.y;
        camp.yz = camp.yz*cos(a.y)+camp.zy*vec2(1,-1)*sin(a.y);
        camp.xz = camp.xz*cos(a.x)+camp.zx*vec2(1,-1)*sin(a.x);
    }

    vec3 ray = normalize(vec3( (fragCoord-iResolution.xy*.5)/iResolution.y, zoom ));
    vec3 pos = camp;
    vec3 camk = normalize( target - pos );
    vec3 cami = normalize( cross( vec3(0,1,0), camk ) );
    vec3 camj = cross( camk, cami );

    ray = ray.x*cami + ray.y*camj + ray.z*camk;

#if defined(PLANE)
    // intersect with plane
    vec4 plane = vec4(0,1,0,-.25); // n,n.p for any p in plane
    float t = (plane.w - dot(pos,plane.xyz)) / dot(ray,plane.xyz);
    if ( t <= 0. ) return fragColour;
    pos += t*ray;
	vec3 normal = plane.xyz;
    vec2 uv = (pos.xz-.5)/1.;
    vec3 tangent = vec3(1,0,0);
    vec3 binormal = vec3(0,0,1);
#else    
    // or, intersect with sphere
	vec4 sphere = vec4(0,0,0,.95); // centre,radius
	vec3 d = sphere.xyz-pos;
    vec3 p = ray*dot(ray,d); // vector from pos to closest point to centre
    float e = sphere.w*sphere.w - dot(p-d,p-d);
    if ( e < 0. ) return fragColour;
    pos += p - ray*sqrt(e);
	vec3 normal = normalize(pos - sphere.xyz);
//    vec2 uv = atan(pos.xy,-pos.zz)*7./6.283; // polar coords, to try to reduce distortion
    vec2 uv = pos.xy;
    vec3 tangent = vec3(1,0,abs(normal.x/normal.z));
    vec3 binormal = vec3(0,-1,abs(normal.y/normal.z));
#endif

    // add each light
    float a = iTime*6.283/20.;
    vec3 toLight = normalize(vec3(2,3,1));
    toLight.xz = toLight.xz*cos(a)+toLight.zx*vec2(1,-1)*sin(a);

    float depth;
    vec3 albedo;
    vec3 specCol;
    float roughness;
	SampleMaterialAndNormal( depth, albedo, specCol, roughness, normal, tangent, binormal, uv, pos );

    fragColour.rgb += BRDF( pos, depth, albedo, specCol, roughness, normal, ray, toLight, vec3(2) );

#if defined(PLANE)
  	fragColour.rgb += BRDF( pos, depth, albedo, specCol, roughness, normal, ray, normalize(vec3(-.2,1,.7)), vec3(.06,.05,.04) );
  	fragColour.rgb += BRDF( pos, depth, albedo, specCol, roughness, normal, ray, normalize(vec3(-.3,.5,1)), .5*vec3(.05,.2,.3) );
  	fragColour.rgb += BRDF( pos, depth, albedo, specCol, roughness, normal, ray, normalize(vec3(-.1,.5,1)), .5*vec3(.1) );
#else
  	fragColour.rgb += BRDF( pos, depth, albedo, specCol, roughness, normal, ray, normalize(vec3(.5,0,1)), vec3(.05,.2,.5) );
  	fragColour.rgb += BRDF( pos, depth, albedo, specCol, roughness, normal, ray, normalize(vec3(-.5,1,-1)), vec3(.05,.2,.3) );
  	fragColour.rgb += BRDF( pos, depth, albedo, specCol, roughness, normal, ray, normalize(vec3(.5,-.5,-1)), vec3(.1) );
#endif

    // exposure
    fragColour *= 2.;

    return fragColour;
}


void mainImage( out vec4 fragColour, in vec2 fragCoord )
{
    if ( true )
    {
        // rotated grid AA (hurts compile time but looks nice)
        fragColour.rgb = (
            clamp(mainImage2(fragCoord+vec2(-3,-1)/8.),0.,1.) +
            clamp(mainImage2(fragCoord+vec2(-1, 3)/8.),0.,1.) +
            clamp(mainImage2(fragCoord+vec2( 1,-3)/8.),0.,1.) +
            clamp(mainImage2(fragCoord+vec2( 3, 1)/8.),0.,1.)
            )/4.;
    }
    else
    {
    	fragColour.rgb = mainImage2(fragCoord);
    }

    fragColour.rgb = pow(fragColour.rgb,vec3(1./2.2));
    fragColour.a = 1.;
}

// Taken from Inigo Quilez's Rainforest ShaderToy:
// https://www.shadertoy.com/view/4ttSWf
float fbm_4( in vec3 x )
{
    float f = 2.0;
    float s = 0.5;
    float a = 0.0;
    float b = 0.5;
    for( int i=0; i<4; i++ )
    {
        float n = texture(iChannel0, x).r * 1.5;
        a += b*n;
        b *= s;
        x = f*m3*x;
    }
	return a;
}


float SDF(vec3 pos, float iTime)
{    
    vec3 fbmCoord = (pos + 2.0 * vec3(iTime * 6.0f, 0.0, iTime * 2.0)) / 150.0f;
    float sdfValue = sdSphere(pos, vec3(0.0, 5.0, 0), 5.0) + 10.0 * fbm_4(fbmCoord);
    sdfValue = sdSmoothUnion(sdfValue, sdPlane(pos), 35.0);
    return sdfValue;
}

vec3 SDFNormal(vec3 pos, float iTime) {
    vec2 e = vec2(SDF_NORMAL_DELTA, 0.0);
    return normalize(vec3(
        SDF(pos + e.xyy, iTime) - SDF(pos - e.xyy, iTime),
        SDF(pos + e.yxy, iTime) - SDF(pos - e.yxy, iTime),
        SDF(pos + e.yyx, iTime) - SDF(pos - e.yyx, iTime)
    ));
}

float FindVolumeBoundary(Ray ray, float maxT, float iTime, out vec3 normal)
{
    float t = 0.0f;
    float lastResult;
    for(int i = 0; i < MAX_STEPS_SDF; ++i)
    {
	    lastResult = SDF( ray.origin + ray.direction * t, iTime) * 1.5;
        if( lastResult < (SURFACE_DIST) || t > maxT ) break;
        t += lastResult;
    }

    if (t >= maxT || lastResult > SURFACE_DIST)
        return -1.0f;
    else
    {
        normal = SDFNormal(ray.origin + ray.direction * t, iTime);
        return t;
    }
}

float GetLightVisiblity(Ray ray, float maxT, float iTime)
{
    float t = 0.0f;
    float lightVisibility = 1.0f;
    float signedDistance = 0.0;
    for(int i = 0; i < MAX_STEPS_VOLUME_LIGHT; i++)
    {                       
        t += max(MARCH_STEP_SIZE_LIGHT, signedDistance);
        if(t > maxT || lightVisibility < ABSORPTION_CUTOFF) break;

        vec3 position = ray.origin + t * ray.direction;

        signedDistance = SDF(position, iTime);
        if(signedDistance < 0.0)
        {
            lightVisibility *= BeerLambert(ABSORPTION_COEFF * GetFogDensity(position, signedDistance), MARCH_STEP_SIZE_LIGHT);
        }
    }
    return lightVisibility;
}

Material GetMaterial(int materialID, vec3 position)
{
    Material mat;
    mat = materials[materialID];

    switch (materialID)
    {
        case MATERIAL_GROUND:
        {
            vec2 uv = position.xz / 30.0;
            uv = vec2(uv.x < 0.0 ? abs(uv.x) + 1.0 : uv.x, uv.y < 0.0 ? abs(uv.y) + 1.0 : uv.y);
            if((int(uv.x) % 2 == 0 && int(uv.y) % 2 == 0) || (int(uv.x) % 2 == 1 && int(uv.y) % 2 == 1))
            {
                mat.color = vec3(1, 1, 1) * 0.3;
            }
        }
        break;
    }

    return mat;    
}

void DepthCheck(
    inout float t,
    in float intersectionT, 
    in vec3 intersectionNormal,
    in int intersectionMaterialID,
    out vec3 normal,
    out int materialID
	)
{    
    if(intersectionT > EPSILON && intersectionT < t)
    {
		normal = intersectionNormal;
        materialID = intersectionMaterialID;
        t = intersectionT;
    }
}


float TraceOpaqueObjects(Ray ray, out int materialID, out vec3 normal)
{
    float t = LARGE_NUMBER;
    vec3 intersectionNormal = vec3(0, 0, 0);

    for (int i = 0; i < NUMBER_LIGHTS; ++i)
    {
        LightSource light = GetLight(i, iTime);

        DepthCheck(
        t, 
        SphereIntersection(ray, light.position, light.radius, intersectionNormal),
        intersectionNormal,
        MATERIAL_LIGHT + i,
        normal,
        materialID);
    }

    DepthCheck(
        t,
        PlaneIntersection(ray, vec3(0, 0, 0), vec3(0, 1, 0), intersectionNormal),
        intersectionNormal,
        MATERIAL_GROUND,
        normal,
        materialID);

    return t;
}


vec3 GammaCorrect(vec3 color) 
{
    return pow(color, vec3(1.0/2.2));
}

vec3 Render(Ray ray)
{
    vec3 normal;
    int materialID = MATERIAL_INVALID;
    float t = TraceOpaqueObjects(ray, materialID, normal);
    float depth = LARGE_NUMBER;

    if (materialID != MATERIAL_INVALID)
    {
        depth = t;
    }

    vec3 volumeNormal;
    float volumeDepth = FindVolumeBoundary(ray, depth, iTime, volumeNormal);
    float opaqueVisibility = 1.0f;
    vec3 volumeColor = vec3(0);
    if (volumeDepth > 0.0f)
    {
        opaqueVisibility = 1.0f;
        vec3 position = ray.origin + volumeDepth * ray.direction;
        vec3 materialColor = GetMaterial(MATERIAL_VOLUME, position).color;
        float distanceInVolume = 0.0f;
        float signedDistance = 0.0;
        for(int i = 0; i < MAX_STEPS_VOLUME; i++)
        {
            volumeDepth += max(MARCH_STEP_SIZE, signedDistance);
            if(volumeDepth > depth || opaqueVisibility < ABSORPTION_CUTOFF) break;

            position = ray.origin + volumeDepth * ray.direction;

            signedDistance = SDF(position, iTime);
            if(signedDistance < 0.0f)
            {
                distanceInVolume += MARCH_STEP_SIZE;
                float previousOpaqueVisiblity = opaqueVisibility;
                opaqueVisibility *= BeerLambert(ABSORPTION_COEFF * GetFogDensity(position, signedDistance), MARCH_STEP_SIZE);
                float absorptionFromMarch = previousOpaqueVisiblity - opaqueVisibility;

                for(int lightIndex = 0; lightIndex < NUMBER_LIGHTS; lightIndex++)
    			{
                    float lightVolumeDepth = 0.0f;
                    vec3 lightDirection = (GetLight(lightIndex, iTime).position - position);
                    float lightDistance = length(lightDirection);
                    lightDirection /= lightDistance;

                    vec3 lightColor = GetLight(lightIndex, iTime).color * AttenuateLight(lightDistance); 
                    if(IsColorInsignificant(lightColor)) continue;

                    Ray rayToLight = Ray(position, lightDirection);
                    float lightVisiblity = GetLightVisiblity(rayToLight, lightDistance, iTime); 
                    volumeColor += absorptionFromMarch * lightVisiblity * materialColor * lightColor;
                }
                volumeColor += absorptionFromMarch * materialColor * GetAmbientLight();
            }
        }
    }

    vec3 color = vec3(0);

    if (materialID != MATERIAL_INVALID && opaqueVisibility > ABSORPTION_CUTOFF)
    {
        vec3 position = ray.origin + t * ray.direction;
        Material material = GetMaterial(materialID, position);

        if((material.flags & MATERIAL_LIGHT_FLAG) != 0)
        {
            color = min(material.color, vec3(1.0));
        }       
        else
        {
            vec3 reflectionDirection = reflect( ray.direction, normal);
            CalculateLighting(position, normal, reflectionDirection, material, iTime, color);
        }
    }
    return color * opaqueVisibility + min(volumeColor, 1.0f);
}

CameraDescription Camera = CameraDescription(
    vec3(0, 3, 130),
    vec3(0, 3, 0),
    2.0,
    7.0
);

void mainImage(out vec4 fragColor, in vec2 fragCoord) 
{
    materials[MATERIAL_GROUND] = Material(vec3(1), 0);
    materials[MATERIAL_VOLUME] = Material(vec3(1,1,1) * 0.8, 0);
    for(int i = 0; i < NUMBER_LIGHTS; ++i)
    {
        LightSource light = GetLight(i, iTime);
        materials[MATERIAL_LIGHT + i] = Material(light.color, MATERIAL_LIGHT_FLAG);
    }

    vec2 uv = fragCoord.xy / iResolution.xy;
    float aspectRatio = iResolution.x /  iResolution.y; 
    float lensWidth = Camera.LensHeight * aspectRatio;

    vec3 NonNormalizedCameraView = Camera.LookAt - Camera.Position;
    float ViewLength = length(NonNormalizedCameraView);
    vec3 CameraView = NonNormalizedCameraView / ViewLength;

    mat3 viewMatrix = GetViewMatrix(iMouse, iResolution);
    CameraView = CameraView * viewMatrix;
    vec3 lensPoint = Camera.LookAt - CameraView * ViewLength;

    vec3 CameraRight = normalize(cross(CameraView, vec3(0, 1, 0)));    
    vec3 CameraUp = normalize(cross(CameraRight, CameraView));

    vec3 focalPoint = lensPoint - Camera.FocalDistance * CameraView;
    lensPoint += CameraRight * (uv.x * 2.0 - 1.0) * lensWidth / 2.0;
    lensPoint += CameraUp * (uv.y * 2.0 - 1.0) * Camera.LensHeight / 2.0;

    Ray ray;
    ray.origin = focalPoint;
    ray.direction = normalize(lensPoint - focalPoint);

    vec3 color = Render(ray);
    fragColor = vec4( GammaCorrect(clamp(color, 0.0, 1.0)), 1.0 );
}

#define PI 3.14159265359
#define EPSILON 1e-6
#define SDF_NORMAL_DELTA 1e-3
#define LARGE_NUMBER 1e20
#define MATERIAL_GROUND 0
#define MATERIAL_VOLUME 1
#define MATERIAL_LIGHT 2
#define MATERIAL_INVALID -1
#define MATERIAL_LIGHT_FLAG 1
#define NUMBER_LIGHTS 3
#define NUMBER_MATERIALS NUMBER_LIGHTS+2

// Play around with these
#define AMBIENT_LIGHT_STRENGTH 0.0
#define LIGHT_ATTENUATION_FACTOR 2.0f
#define LIGHT_INTENSITY_MULTIPLIER 20.0f
#define MAX_STEPS_SDF 40
#define SURFACE_DIST 0.2
#define MAX_STEPS_VOLUME 40
#define ABSORPTION_CUTOFF 0.04
#define ABSORPTION_COEFF 0.4
#define MAX_FOG_DENSITY 1.0
#define MAX_STEPS_VOLUME_LIGHT 6
#define MARCH_SIZE_MULTIPLIER 1.0
#define MARCH_STEP_SIZE 0.5 * MARCH_SIZE_MULTIPLIER
#define MARCH_STEP_SIZE_LIGHT 0.65 * MARCH_SIZE_MULTIPLIER

struct CameraDescription
{
    vec3 Position;
    vec3 LookAt;    

    float LensHeight;
    float FocalDistance;
};

mat3 GetViewMatrix(vec4 iMouse, vec3 iResolution)
{
    float camRotX = iMouse.x / iResolution.x;
    float camRotY = iMouse.y / iResolution.y;
    float xRotation = (( - camRotX * 2.0 + 1.0)) * PI;
    float yRotation = ((camRotY * 0.29 - 0.2)) * PI;
    mat3 cameraRotX = mat3(
                cos(xRotation), 0.0, sin(xRotation),
                0.0,           1.0, 0.0,    
                -sin(xRotation),0.0, cos(xRotation));
    mat3 cameraRotY = mat3( 1.0,           0.0, 0.0,
                 0.0, cos(yRotation), -sin(yRotation),
                 0.0, sin(yRotation), cos(yRotation));
    mat3 viewMatrix = cameraRotY * cameraRotX;
    return viewMatrix;
}

struct Material
{
    vec3 color;
    int flags;
};

struct Ray
{
    vec3 origin;
    vec3 direction;
};

struct LightSource
{  
    vec3 position;
    float radius;
    vec3 color;
};

// some random matrix for fbm
const mat3 m3  = mat3( 0.00,  0.80,  0.60,
                      -0.80,  0.36, -0.48,
                      -0.60, -0.48,  0.64 );

// https://www.scratchapixel.com/lessons/3d-basic-rendering/minimal-ray-tracer-rendering-simple-shapes/ray-plane-and-ray-disk-intersection
float PlaneIntersection(Ray ray, vec3 planeOrigin, vec3 planeNormal, out vec3 normal) 
{ 
    float t = -1.0f;
    normal = planeNormal;
    float denom = dot(-planeNormal, ray.direction);
    if (denom > EPSILON) { 
        vec3 rayToPlane = planeOrigin - ray.origin; 
        return dot(rayToPlane, -planeNormal) / denom; 
    } 

    return t; 
} 

// http://kylehalladay.com/blog/tutorial/math/2013/12/24/Ray-Sphere-Intersection.html
float SphereIntersection(Ray ray, in vec3 sphereCenter, in float sphereRadius, out vec3 normal)
{
      vec3 L = sphereCenter - ray.origin;
      float tc = dot(L, ray.direction);

      if (tc < 0.0f)
          return -1.0f;

      float d2 = dot(L,L) - (tc*tc);
      float radius2 = sphereRadius * sphereRadius;

      if ( d2 > radius2)
          return -1.0f;

      float t1c = sqrt( radius2 - d2 );
      float t1 = tc - t1c;

      normal = normalize(ray.origin + ray.direction * t1 - sphereCenter);
      return t1;
}

LightSource GetLight(int index, float iTime)
{
    LightSource orbLight;

    switch(index % NUMBER_LIGHTS)
    {
        case 0:
            orbLight.color = vec3(0, 1.0, 1.0);
            orbLight.position = vec3(6.0 + sin(1.0 * iTime) * 10.0, 20.0 + sin(iTime * 1.5) * 5.0, 4.0 + cos(iTime) * 5.0);
            break;
        case 1:
            orbLight.color = vec3(1.0, 1.0, 0.0);
            orbLight.position = vec3(-19, 20.0 + sin(2.0 * iTime) * 10.0,-1.0 + cos(2.0 * iTime) * 10.0);
            break;
        case 2:
            orbLight.color = vec3(1.0, 0.0, 1.0);
            orbLight.position = vec3(15.0 + sin(2.0 * iTime) * 5.0, 12.0, cos(2.0 * iTime) * 5.0);
            break;
    } 

    orbLight.radius = 0.8f;
    orbLight.color *= LIGHT_INTENSITY_MULTIPLIER;
    return orbLight;
}


Material materials[NUMBER_MATERIALS];


float AttenuateLight(float d)
{
    return 1.0 / pow(d, LIGHT_ATTENUATION_FACTOR);
}

vec3 Diffuse(in vec3 normal, in vec3 lightVec, in vec3 diffuse)
{
    float nDotL = dot(normal, lightVec);
    return clamp(nDotL * diffuse, 0.0, 1.0);
}

vec3 GetAmbientLight()
{
	return AMBIENT_LIGHT_STRENGTH * vec3(0.03, 0.018, 0.018);
}

void CalculateLighting(vec3 position, vec3 normal, vec3 reflectionDirection, Material material, float iTime, inout vec3 color)
{
    for(int i = 0; i < NUMBER_LIGHTS; ++i)
    {
        vec3 lightDirection = (GetLight(i, iTime).position - position);
        float lightDistance = length(lightDirection);
        lightDirection /= lightDistance;

        vec3 lightColor = GetLight(i, iTime).color * AttenuateLight(lightDistance); 

        color += lightColor * pow(max(dot(reflectionDirection, lightDirection), 0.0), 4.0);
        color += lightColor * Diffuse(normal, lightDirection, material.color);

    }
    color += GetAmbientLight() * material.color;
}

float sdSphere(vec3 p, vec3 origin, float s)
{
  p = p - origin;
  return length(p)-s;
}

float sdPlane( vec3 p )
{
	return p.y;
}

// Taken from https://iquilezles.org/articles/distfunctions
float sdSmoothUnion( float d1, float d2, float k ) 
{
    float h = clamp( 0.5 + 0.5*(d2-d1)/k, 0.0, 1.0 );
    return mix( d2, d1, h ) - k*h*(1.0-h); 
}


float BeerLambert(float absorption, float dist)
{
    return exp(-absorption * dist);
}

float GetFogDensity(vec3 position, float sdfDistance)
{
    bool insideSDF = sdfDistance < 0.0;
    return insideSDF ? min(abs(sdfDistance), MAX_FOG_DENSITY) : 0.0;
}

float Luminance(vec3 color)
{
    return (color.r * 0.3) + (color.g * 0.59) + (color.b * 0.11);
}

bool IsColorInsignificant(vec3 color)
{
    const float minValue = 0.005;
    return Luminance(color) < minValue;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord.xy / iResolution.xy;
	vec3 color = vec3(0.0);

    if( iFrame > 0 ) {
        color = texture( iChannel0, uv ).xyz;
        color /= float( iFrame );
        color = pow( color, vec3(0.4545) );
    }

    fragColor = vec4( color, 1.0 );
