object near(object A,vec3 B){
    object c;
    c.d2=A.d>abs(B.y)?B.y:A.d2;
    float tmp=mix2(A.i_id,B.z,float(B.y<0.));
    c.s=A.s+int(B.y<0.);
    B.y=abs(B.y);
    c.id=int(mix2(A.id,B.x,float(A.d>B.y)));
    c.d=min(A.d,B.y);
    c.i_id=int(tmp);
    return c;
}


vec2 rotClamp(vec2 pos,int n){
