    seed = mod(fract(sin(uv.x*875.87+12.8+iTime)*776.978)*2378.0 + fract(sin(uv.y*594.87+57.75)*689.655)*8938.0
            + fract(sin(iTime*798.43+89.24)*875.365)*5685.0 ,10000.0);
}
void next(){seed=mod(seed*348.12+77.0, 10000.0);}
