vec3 calcNormal(vec3 p){\
  vec3 n=vec3(0);\
  for(int i=0; i<4; i++){\
    vec3 e=DIST_MIN*(vec3(9>>i&1, i>>1&1, i&1)*2.-1.);\
    n+=e*map(p+e);\
  }\
  return normalize(n);\
}\
