    else if(fetch(C_CAMERA).y<.5 && bool(TURN_TABLE))\
        pos = normalize(vec3(sin(iTime*TURN_TABLE_SPEED), -1, cos(iTime*TURN_TABLE_SPEED))) * CAM_DIST;\
    else if(fetch(C_CAMERA).y>.5 || forceView.x>.5){\
