    col = mix(col, THM_GRID, g);\
    if(bool(UI_ISOLINE)) {\
        vec4 n;\
        int num;\
        if(forceView.x>.5) num = int(forceView.y);\
        else num = int(fetch(C_CAMERA).x);\
        if(num==1) n = vec4(0,0,1,0);\
        if(num==7) n = vec4(0,1,0,0);\
        if(num==3) n = vec4(1,0,0,0);\
