mat4 createCS(vec3 p, vec3 z, vec3 x) {
    z = normalize(z);

    x = normalize(orthogonalize(z, x));
    vec3 y = cross(z,x);

    //vec3 y = normalize(cross(z,x));
    //x = cross(y,z);

    return mat4(	vec4( x, 0.0 ), 
    			 	vec4( y, 0.0 ),
    				vec4( z, 0.0 ),
    				vec4( p, 1.0 ));
}



