#define TWOPI (2.*3.1415926)

#define bpm 100.
#define beatdur (60./bpm)

// Frequency Modulation

// f(t) instantaneous frequency
// sig = sin(phase(t))
// phase'(t) = TWOPI*f(t)
// phase(t) = integral of TWOPI*f(t) dt

// Constant frequency
// f(t) = f0
// phase'(t) = TWOPI*f0
// phase(t) = TWOPI*f0*t + c
// sig(t) = sin(TWOPI*f0*t + c)

// Sinusoidal variation
// carrier frequency fc
// modulation frequency fm
// frequency deviation df
// f(t) = fc + df * cos(TWOPI*fm*t)
// phase'(t) = TWOPI*fc + TWOPI*df * cos(TWOPI*fm*t))
// phase(t) = TWOPI*fc*t + df/fm * sin(TWOPI*fm*t)
// sig(t) = sin(TWOPI*fc*t + df/fm * sin(TWOPI*fm*t))

// index of modulation iom = df/fm


#define FM(fc, fm, iom) sin(TWOPI*fract((fc)*t) + (iom)*sin(TWOPI*fract((fm)*t)))
#define FM2(pc, pm, iom) sin(mod(pc,TWOPI) + (iom)*sin(mod(pm,TWOPI)))

#define N(nn) 440.*exp2(((nn)-9.)/12.)

// Center frequency = fc
// Audible sidebands : abs(fc +- n*fm) for n <= ~iom
// Negative frequencies get reflected back


// ========== PAD ==========

vec2 padSynth(float f, float t, float tt)
{
    vec2 sig = vec2(0);
    // body
    sig += FM(f, f+vec2(-1.,1.62), 1.) * 0.03;
    sig += FM(f+2., f+vec2(1.,-1.62), 1.) * 0.02;
    // personality
    float fc = f*round(2000./f);
    float iom = 1000./f;
    sig += FM(fc, f+vec2(0.7,-2.), iom * (1. - 0.5*sin(1.9*tt))) * 0.01;
    sig += FM(fc-2., f+vec2(-1.,1.6), iom * (1. + 0.5*sin(3.*tt))) * 0.007;

    float env = smoothstep(0., 0.3, t);
    return sig * env;
}

vec2 padChord(vec4 fs, float t, float tt)
{
    vec2 sig = vec2(0);
    sig += padSynth(fs.x, t, tt) * vec2(0.8,0.3);
    sig += padSynth(fs.y, t, tt-1.) * vec2(1., 0.1);
    sig += padSynth(fs.z, t, tt+1.) * vec2(0.1, 1.);
    sig += padSynth(fs.w, t, tt-2.) * vec2(0.3, 0.8);
    return sig;
}

vec2 padChordPattern(float t)
{
    t = max(t, 0.);
    t = mod(t, 16.*beatdur);
    vec4 chord = 
        (t < 4.*beatdur) ? vec4(-3., -1., 0., 4.) :
        (t < 8.*beatdur) ? vec4(-3., 0., 2., 5.) :
        (t < 12.*beatdur) ? vec4(-7., -3., 0., 7.) :
        (t < 14.*beatdur) ? vec4(-5., 2., 4., 7.) :
                            vec4(-5., -1., 2., 4.);
    float t_cur = mod(t, 4.*beatdur);
    float env = smoothstep(4.*beatdur, 3.99*beatdur, t_cur);
    return padChord(N(chord), t_cur, t) * env;
}

vec2 padChordPatternVerb(float t)
{
    return padChordPattern(t)
    //+ padChordPattern(t-0.01).yx * 0.8 * vec2(-1,1)
    + padChordPattern(t-0.75*beatdur) * 0.8
    + padChordPattern(t-1.5*beatdur) * 0.5
    + padChordPattern(t-3.62*beatdur) * 0.5;
}

// ========== LEAD SYNTH ==========

float vibratoPhase(float f0, float semitones, float vibHz, float t)
{
    float df = 0.06*f0*semitones;
    float phase = TWOPI*f0*t + df/vibHz*sin(TWOPI*vibHz*t);
    return phase;
}

vec2 leadSynth(float f, float t)
{
    vec2 sig = vec2(0);

    t = max(t, 0.); // To avoid problems with the exponential envelope

    // Vibrato
    // WRONG
    // f += 5.*sin(TWOPI*5.*t);
    // phase(t) = f(t)*t
    // phase'(t) = f(t) + f'(t)*t

    // RIGHT
    // f(t) = f0 + df*cos(TWOPI*fm*t)
    // phase(t) = TWOPI*f0*t + df/fm*sin(TWOPI*fm*t)
    // fm = 5 Hz
    // df = epsilon*f0
    float vibEnv = smoothstep(0., 0.5, t);
    float phase = vibratoPhase(f, 0.2*vibEnv, 5., t);
    float tpt = TWOPI*t;

    // body
    sig += FM2(phase, phase, 1.) * 0.05;
    sig += FM2(phase+5.*tpt, phase+vec2(-1.,0.8)*tpt, 3.) * 0.02;

    // presence
    float ratio = round(5000./f);
    float iom = 1500./f;
    sig += FM2(ratio*phase, phase, iom) * 0.01;
    sig += FM2(ratio*phase+5.*tpt, phase+vec2(3.,-3.)*tpt, iom) * 0.01;

    // attack
    float fc = f*round(10000./f);
    iom = 10000./f;
    sig += FM(fc, f, iom) * 0.05 * exp(-30.*t);

    float env = 1.;
    // Fake compression
    env *= 0.7*(1.+smoothstep(0.02,0.,t) + 0.3*smoothstep(0.,0.5,t));

    return sig * env;
}

vec2 leadSynthPattern(in float t)
{
    vec2 sig = vec2(0);
    t -= 1.75*beatdur;
    t = max(t, 0.);
    t = mod(t, 8.*beatdur);

    //#define P(nn, b) if(t>0. && t<(b)*beatdur) { sig += leadSynth(N(nn), t) * smoothstep((b)*beatdur, (b)*beatdur-0.01, t);  } t -= (b)*beatdur;
    #define P(nn, b) sig += leadSynth(N(nn), t) * step(0., t) * smoothstep((b)*beatdur, (b)*beatdur-0.01, t); t -= (b)*beatdur;

    P(7., 0.25);
    P(9., 0.5);
    P(7., 1.);
    P(9., 1.);
    P(9.+12., 0.5);
    P(16., 0.5);
    P(14., 1.);
    P(12., 0.5);
    P(9., 0.25);
    P(7., 0.25);
    P(9., 1.5);

    #undef P

    return sig;
}

vec2 leadSynthPatternVerb(float t)
{
    return leadSynthPattern(t)
    + leadSynthPattern(t-0.005).yx * vec2(0.3,0.7)
    + leadSynthPattern(t-0.75*beatdur) * 0.5 * vec2(-1,1)
    + leadSynthPattern(t-1.5*beatdur) * 0.25 * vec2(-1,-1);
}

// ========== BASS ==========

float filteredSaw(float f, float fc, float t)
{
    // f frequency
    // fc cutoff frequency
    // t time
    float x = f*t;
    float w = 0.5*f/fc;
    w = min(w, 0.5);
    x -= round(x);
    return mix(-2.*x-1., -2.*x+1., smoothstep(-w, w, x));
}

vec2 bassSynth(float f, float t)
{
    // Classic 80's "saw stab" bass
    vec2 sig = vec2(0);
    float fc = 15000.*exp(-80.*t) +100.; // cutoff envelope of the sub
    float fc2 = 15000.*exp(-40.*t) +100.; // cutoff envelope of the higher components
    //float fc = 5000.;
    sig += 0.1*filteredSaw(f/2., fc, t); // filtered sub-oscillator
    sig += 0.05*sin(TWOPI*fract(f/2.*t)); // some more sub
    sig += 0.1*filteredSaw(f+1.618, fc2, t+1.) * vec2(1.,0.2); // higher components
    sig += 0.1*filteredSaw(f-1., fc2, t+1.7) * vec2(0.2,1.); // with stereo + detuning
    return sig;
}

vec2 bassSynthPattern(float t)
{
    // Classic 80's bass pattern: just play eighth notes!
    t = max(t, 0.);
    t = mod(t, 16.*beatdur);
    float nn = 
        (t < 4.*beatdur) ?-3. :
        (t < 8.*beatdur) ? 2. :
        (t < 12.*beatdur) ? 5. :
        (t < 14.*beatdur) ? 0. :
                            -5.;
    float f = N(nn)/2.;
    t = mod(t, 0.5*beatdur);
    return bassSynth(f, t);
}

// ========== WAH LEAD ==========

float wahLead(float f, float t)
{
    // A short synth that goes "wah" (or "waw"?)
    float dur = 0.1;
    float env = smoothstep(0.,dur/2., t) * smoothstep(dur, dur/2., t);
    float env2 = smoothstep(0.,dur/4., t) * smoothstep(2.*dur, dur, t);
    float fc = 400.+10000.*env;
    float sig = filteredSaw(f, fc, t) * 0.1;
    return sig * env2;
}

float wahLeadPattern(float t)
{
    // Do a weird rhythm with the "wah" synth
    t = max(0.,t);
    t = mod(t, 16.*beatdur);
    // Notes are taken from the chords
    float nn = 
        (t < 4.*beatdur) ? 4. :
        (t < 8.*beatdur) ? 5. :
        (t < 12.*beatdur) ? 5. :
        (t < 14.*beatdur) ? 4. :
                            2.;
    t = mod(t, 8.*beatdur);
    float t1 = mod(t, 4.*beatdur);
    t1 = mod(t1, 1.75*beatdur);
    t1 = mod(t1, 1.5*beatdur);
    if(2.25*beatdur <= t && t < 4.*beatdur)
    {
        // Jump up an octave now and then
        nn += 12.;
        t -= 2.25*beatdur;
    }
    else
    {
        t = t1;
    }
    return wahLead(N(nn), t);
}

vec2 wahLeadPatternVerb(float t)
{
    // Trippy delay/reverb thing
    vec2 sig = vec2(0);
    sig.x += wahLeadPattern(t);
    sig.y += wahLeadPattern(t - 0.52*beatdur);
    sig += wahLeadPattern(t - 1.54*beatdur) * vec2(-0.5,0.1);
    sig += wahLeadPattern(t - 1.78*beatdur) * vec2(0.1,-0.5);
    return sig;
}

// ========== MARIMBA ==========

float marimba(float f, float t)
{
    // Classic FM "marimba" patch
    // Super simple and effective.
    return FM(f, 7.*f, 1.5*exp(-80.*t)) * exp(-5.*t) * 0.1;
}

vec2 marimbaPattern(float t)
{
    // Pop-ish dotted eighth note pattern
    t = mod(t, 16.*beatdur);
    // Take two notes from the chords
    vec2 nn = 
        (t < 4.5*beatdur) ? vec2(4.,12.) :
        (t < 8.*beatdur) ? vec2(5.,9.) :
        (t < 12.5*beatdur) ? vec2(9.,12.) :
        (t < 14.*beatdur) ? vec2(7.,12.) :
                            vec2(7.,11.);
    t = mod(t, 8.*beatdur); // Make sure we restart the notes every two bars
    t = mod(t, 6.*beatdur);
    t = mod(t, 0.75*beatdur); // and repeat them four times in three beats
    vec2 sig = vec2(0);
    sig += marimba(N(nn.x), t) * vec2(0.7,0.2);
    sig += marimba(N(nn.y), t) * vec2(0.1,0.5);
    return sig;
}



// ========== MAIN SOUND ==========

vec2 mainSound( int samp, float t )
{
    vec2 sig = vec2(0);

    // Fake sidechain compression
    // Turn the signal down during the first part of every beat
    float pumping = smoothstep(0.,0.2,mod(t,beatdur)) * smoothstep(beatdur, beatdur-0.01, mod(t,beatdur));
    //float pumping = 1.;


    //sig += leadSynth(440., t);
    //sig += wahLeadPattern(t) * mix(pumping, 1., 0.5) * 0.7;


    sig += padChordPatternVerb(t) * mix(pumping, 1., 0.5)*0.7;
    sig += leadSynthPatternVerb(t) * mix(pumping, 1., 0.7) * 0.8;
    sig += wahLeadPatternVerb(t) * mix(pumping, 1., 0.5) * 0.7;
    sig += bassSynthPattern(t) * mix(pumping, 1., 0.2);
    sig += marimbaPattern(t) * mix(pumping, 1., 0.7);

    return sig;
}

// here we just output texture computed in "Buf A"
// see dithering tutorial in https://www.shadertoy.com/view/XsdXzN

void mainImage( out vec4 fragColor, in vec2 fragCoord ){
    vec2 uv = fragCoord.xy / iResolution.xy;

    vec3 color = texture(iChannel0, uv).r*vec3(1.0, 0.5, 0.25);
    color = pow(color, vec3(1.8));
    color = color/(1.0 + color);
    fragColor = vec4(color,1.0);

}

// made using dithering thechnique from https://www.shadertoy.com/view/XsdXzN and volumetric raymarching. 
// Inspired by https://www.shadertoy.com/view/ltcXRf and https://www.shadertoy.com/view/MsVXWW

const float dtmax  = 1.0;

// Hacked up version of https://www.shadertoy.com/view/MsVXWW
#define R(p, a) p=cos(a)*p+sin(a)*vec2(p.y, -p.x)

const float nudge      = 0.739513;	                    // size of perpendicular vector
const float normalizer = 1.0 / sqrt(1.0 + nudge*nudge);	// pythagorean theorem on that perpendicular to maintain scale

float SpiralNoiseC(vec3 p){
    float n = 0.0;	// noise amount
    float iter = 1.0;
    for (int i = 0; i < 8; i++){
        n += -abs(sin(p.y*iter) + cos(p.x*iter)) / iter;	// abs for a ridged look
        p.xy += vec2(p.y, -p.x) * nudge;  p.xy *= normalizer;
        p.xz += vec2(p.z, -p.x) * nudge;  p.xz *= normalizer;
        iter *= 1.733733;
    }
    return n;
}

float NebulaNoise(vec3 p){
   float final = p.y + 4.5;
    final += SpiralNoiseC(p.zxy*0.6123 + 100.0)*4.0; // large scale features
    return final;
}

float scene(vec3 p){
    float r       = length(p);
    float NebulaNoise = SpiralNoiseC(2.5*p.zxy*0.6123 + 100.0)*4.0 + 6.0;
    //float noise   = 1.0 + pow(abs(NebulaNoise(p/0.5)*0.5), 2.0) + smoothstep(1.0,2.8,r);
    float noise   = 1.0 + pow(abs(NebulaNoise), 2.0) + smoothstep(1.0,2.8,r);
    float solids  = p.z+1.7; // ground
    float balls = length( vec3(fract(p.xy)-0.5, p.z+0.5 ) )+0.90;
    solids        = min( solids, balls ); // combine scene
    return min(solids,noise);
}

float dist2dens (float dist ){ return max(1.2-dist*dist, 0.0) + 0.002;       }
//float dens2block(float dens ){ return 1.0-pow(0.005, dens/0.05); }
float dens2block(float dt, float dens ){ return 1.0-pow(0.005, dt*dens/0.05); }
//float dens2block(float dt, float dens ){ return -dt*pow(1.5, dens)*0.1; }
float get_dt( float dist ){ return clamp(0.02*dist, 0.002, dtmax); }

// rayMarch integration step to calculate direct ray scattering and absorption (no self shadow, fast preview)
vec3 rayStep( vec3 ro, vec3 rd, vec3 S ){
    float Oc  = S.y;             // occlusion
    float t   = S.z;             // ray length
    vec3  pos     = ro + t*rd;   // pos from ray equation
    float dist    = scene(pos);  // distance from scene objects
    float density = dist2dens(dist);
    float dt      = get_dt(dist);   // ray step length
    float emit    = (300.0*dt*density/dot(pos,pos)); // ammount of light scattered by the density
    float block   = dens2block(dt,density);          // ammount of light absorbed by the density
    float w       = (1.0 - Oc);                      // to simulate exponential decay
    return S + vec3( w*emit, w*block, dt );  // update ray integral
}

// rayMarch integration step calculate light absorbed by density between light source and "ro" 
vec2 rayStepOcc( vec3 ro, vec3 rd, vec2 S ){
    float Oc   = S.x;
    float t    = S.y;
    vec3  pos     = ro + t*rd;
    float dist    = scene(pos);
    float density = dist2dens(dist);
    float dt      = get_dt   (dist);
    float block   = dens2block(dt,density);
    float w       = (1.0 - Oc);
    return S + vec2( w*block, dt );
}

// Self-shadow capable rayMarching
vec3 rayStepFine( vec3 ro, vec3 rd, vec3 S ){
    float Oc   = S.y;
    float t    = S.z;
    vec3  pos      = ro + t*rd;
    float dist     = scene(pos);
    float density  = dist2dens(dist);
    float dt       = get_dt(dist);

    // here we integrate occlusion by density between this step on camRay and light 
    vec2 SS        = vec2(0.0);
    float max_dist = length(pos);
    vec3 ld        = -normalize(pos);
    for(int i=0; i<64; i++){ 
		SS = rayStepOcc(pos,ld,SS);
        if( (SS.y>max_dist) ) break;
    }
    float emit = (800.0*dt*density/dot(pos,pos));
    emit *= clamp(1.0-SS.x,0.1,1.0);

    float block  = dens2block(dt,density);
    float w      = (1.0 - Oc);
    return S + vec3( w*emit, w*block, dt );
}

// sphere used for bounding volume to save some ray-marching steps
vec2 RaySphereIntersect(vec3 org, vec3 dir, float R){
	float b = dot(dir, org);
	float c = dot(org, org) - R*R;
	float d2 = b*b - c;
	if(d2 < 0.0) return vec2(-1.0,-1.0);
	float d = sqrt(d2);
    return vec2( -b-d, -b+d );
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ){

    // calculate ray parameters
    vec2 uv = fragCoord.xy / iResolution.xy;
    vec2 ruv  = (gl_FragCoord.xy-0.5*iResolution.xy)/iResolution.y;  
	vec3 rd  = normalize(vec3(ruv, 1.0));   // ray direction
	vec3 ro  = vec3(0.0, 0.0, -4.0);        // ray origin

    // camera rotation
    float pitch   = clamp( -iMouse.y*0.01,-3.0,-1.5);
    float azimuth = iMouse.x*0.01; 
    R(rd.yz, pitch);   R(ro.yz, pitch); 
    R(rd.xy, azimuth); R(ro.xy, azimuth);


    vec2 tbound = RaySphereIntersect(ro,rd,3.5); // bounding volume
    if( tbound.x>0.0 ){                          // if bounding volume hit, do something
        vec4 frag = texture(iChannel0, uv);      // load result from previous frame
        // note: frag stores (R,G,B,A) channels each contain partial results: 
        // R : last finished light integral
        // G : current partial light integral value
        // B : current partial occlusion integral value 
        // A : current ray length
        if( (frag.w<tbound.x)||(frag.w>tbound.y) ){       // if ray outside scene then restart
            float dither = texture(iChannel1, uv*25.0).r; // radom noise is nicer than ray-steping artifacts
            frag = vec4( frag.g, 0.0, 0.0, tbound.x + dtmax*dither ); // restart
        }
        if(iMouse.z>0.0){ // fast preview (no self shadow)
            for(int i = 0; i < 32; i++){ frag.gba = rayStep( ro, rd, frag.gba );  }
        }else{            // full render with self shadow
            for(int i = 0; i < 4; i++){ frag.gba  = rayStepFine( ro, rd, frag.gba ); }
        }
        fragColor = frag; // store result fo frambuffer texture
	}
}

