struct TransMat
{
    vec3 col_vol;
    vec3 col_dif;
    vec3 col_fil;
    vec3 col_dev;
    float specint;
    float specshin;
    float ior;
};

struct RenderData
{
  	vec3 col;
  	vec3 pos;
  	vec3 norm;
  	int objnr;
};

// Every object of the scene has its ID
#define SKY_OBJ        0
#define BUBBLE_OBJ     1

Lamp lamps[2];

// Campera options
vec3 campos = vec3(0., -0., 10.);
vec3 camtarget = vec3(0., 0., 0.);
vec3 camdir = vec3(0., 0., 0.);
float fov = 6.;

// Ambient light
const vec3 ambientColor = vec3(0.3);
const float ambientint = 0.025;

// Gold options
const vec3 goldColor = vec3(1.1, 0.91, 0.52);
const vec3 goldColor2 = vec3(1.1, 1.07, 0.88);
const vec3 goldColor3 = vec3(1.02, 0.82, 0.55);
const float goldRef = 0.99;

// Tracing options
const float normdelta = 0.001;
const float maxdist = 40.;
const int nbref = 7;

// Glass perameters
const float bubbleRadius = 1.2;
const float bubbleThickness = 0.001;
const float bumpFactor = 0.014;

// Antialias. Change from 1 to 2 or more AT YOUR OWN RISK! It may CRASH your browser while compiling!
const float aawidth = 0.8;
const int aasamples = 2;

TransMat glassMat;

void init()
{
    lamps[0] = Lamp(vec3(-5., 3., -5.), vec3(1., 1., 1.), 1.5, 0.01);
    lamps[1] = Lamp(vec3(1.5, 4., 2.), vec3(0.7, 0.8, 1.), 1.7, 0.01);

    glassMat = TransMat(vec3(0.96, 0.99, 0.96),
                        vec3(0.01, 0.02, 0.02),
                        vec3(1.),
                        vec3(0.3, 0.5, 0.9),
                        0.4,
                        45.,
                        1.47);
}

// Union operation from iq
vec2 opU(vec2 d1, vec2 d2)
{
	return (d1.x<d2.x) ? d1 : d2;
}

vec2 rotateVec(vec2 vect, float angle)
{
    vec2 rv;
    rv.x = vect.x*cos(angle) - vect.y*sin(angle);
    rv.y = vect.x*sin(angle) + vect.y*cos(angle);
    return rv;
}

// 1D hash function
float hash(float n)
{
    return fract(sin(n)*753.5453123);
}

// From https://www.shadertoy.com/view/4sfGzS
float noise(vec3 x)
{
    //x.x = mod(x.x, 0.4);
    vec3 p = floor(x);
    vec3 f = fract(x);
    f = f*f*(3.0-2.0*f);

    float n = p.x + p.y*157.0 + 113.0*p.z;
    return mix(mix(mix(hash(n+  0.0), hash(n+  1.0),f.x),
                   mix(hash(n+157.0), hash(n+158.0),f.x),f.y),
               mix(mix(hash(n+113.0), hash(n+114.0),f.x),
                   mix(hash(n+270.0), hash(n+271.0),f.x),f.y),f.z);
}

float bubblePattern(vec3 pos)
{
    return noise(normalize(pos)*2.5);
}

float goldValue(vec3 pos)
{
    #ifdef show_gold
    pos+= 0.04*noise(pos*26.7);
    return smoothstep(0.63, 0.64, bubblePattern(pos));
    #else
    return 0.;
    #endif
}

float bubbleBump(vec3 pos)
{
    #ifdef bumped_glass
    float wf = 65. + 15.*sin(iTime*0.08);
    float bp = bubblePattern(pos);
    float sa = smoothstep(0.1, 0.2, bp)*smoothstep(0.8, 0.65, bp);
    return sa*sin(bp*wf);
    #else
    return 0.;
    #endif
}

float map_bubble(vec3 pos)
{
   #ifdef thick_bottom
   float bubbleThickness2 = bubbleThickness*(1. + 500.*smoothstep(-0.25, -0.4, pos.y/bubbleRadius));
   #else
   float bubbleThickness2 = bubbleThickness;
   #endif

   float outside = length(pos) - bubbleRadius;
   outside-= bumpFactor*bubbleBump(pos);
   float inside = length(pos) - bubbleRadius + bubbleThickness2;
   inside-= bumpFactor*bubbleBump(pos);
   float df = max(outside, -inside);

   //df = max(df, pos.z);
   return df;
}

vec2 map(vec3 pos, bool inside)
{
    float bubble = map_bubble(pos);
    if (inside) bubble*=-1.;
    vec2 res = vec2(bubble, BUBBLE_OBJ);

    return res;
}

// Main tracing function
vec2 trace(vec3 cam, vec3 ray, float maxdist, bool inside) 
{
    float t = 0.1;
    float objnr = 0.;
    vec3 pos;
    float dist;
    float dist2;

  	for (int i = 0; i < 128; ++i)
    {
    	pos = ray*t + cam;
        vec2 res = map(pos, inside);
        dist = res.x;
        if (dist>maxdist || abs(dist)<0.002)
            break;
        t+= dist*0.43;
        objnr = abs(res.y);
  	}
  	return vec2(t, objnr);
}

// From https://www.shadertoy.com/view/MstGDM
// Here the texture maping is only used for the normal, not the raymarching, so it's a kind of bump mapping. Much faster
vec3 getNormal(vec3 pos, float e, bool inside)
{  
    vec2 q = vec2(0, e);
    return normalize(vec3(map(pos + q.yxx, inside).x - map(pos - q.yxx, inside).x,
                          map(pos + q.xyx, inside).x - map(pos - q.xyx, inside).x,
                          map(pos + q.xxy, inside).x - map(pos - q.xxy, inside).x));
}

// Gets the color of the sky
vec3 sky_color(vec3 ray)
{ 
    return texture(iChannel0, ray).rgb;
}

vec3 getGoldColor(vec3 pos)
{
    pos+= 0.4*noise(pos*24.);
    float t = noise(pos*30.);
    vec3 col = mix(goldColor, goldColor2, smoothstep(0.55, 0.95, t));
    col = mix(col, goldColor3, smoothstep(0.45, 0.25, t));
    return col;
}

vec3 getBubbleColor(vec3 pos)
{
	return mix(glassMat.col_dif, getGoldColor(pos), pow(goldValue(pos), 4.));
}

// Combines the colors
vec3 getColor(vec3 norm, vec3 pos, int objnr, vec3 ray)
{
   return objnr==BUBBLE_OBJ?getBubbleColor(pos):sky_color(ray);
}

// Fresnel reflectance factor through Schlick's approximation: https://en.wikipedia.org/wiki/Schlick's_approximation
float fresnel(vec3 ray, vec3 norm, float n2)
{
   float n1 = 1.; // air
   float angle = acos(-dot(ray, norm));
   float r0 = dot((n1-n2)/(n1+n2), (n1-n2)/(n1+n2));
   float r = r0 + (1. - r0)*pow(1. - cos(angle), 5.);
   return clamp(r, 0., 0.8);
}

// Shading of the objects pro lamp
vec3 lampShading(Lamp lamp, vec3 norm, vec3 pos, vec3 ocol, int objnr, int lampnr)
{   
    vec3 pl = normalize(lamp.position - pos);
    float dlp = distance(lamp.position, pos);
    vec3 pli = pl/pow(1. + lamp.attenuation*dlp, 2.);
    float dnp = dot(norm, pli);

    // Diffuse shading
    vec3 col;
    col = ocol*lamp.color*lamp.intensity*smoothstep(-0.1, 1., dnp); //clamp(dnp, 0., 1.);

    // Specular shading
    #ifdef specular

    float specint = glassMat.specint;
    float specshin = glassMat.specshin;  
    //if (dot(norm, lamp.position - pos) > 0.0)
        col+= lamp.color*lamp.intensity*specint*pow(max(0.0, dot(reflect(pl, norm), normalize(pos - campos))), specshin);
    #endif

    // Softshadow
    #ifdef shadow
    col*= shi*softshadow(pos, normalize(lamp.position - pos), shf, 100.) + 1. - shi;
    #endif

    return col;
}

// Shading of the objects over all lamps
vec3 lampsShading(vec3 norm, vec3 pos, vec3 ocol, int objnr)
{
    vec3 col = vec3(0.);
    for (int l=0; l<2; l++) // lamps.length()
        col+= lampShading(lamps[l], norm, pos, ocol, objnr, l);

    return col;
}

// From https://www.shadertoy.com/view/lsSXzD, modified
vec3 GetCameraRayDir(vec2 vWindow, vec3 vCameraDir, float fov)
{
	vec3 vForward = normalize(vCameraDir);
	vec3 vRight = normalize(cross(vec3(0.0, 1.0, 0.0), vForward));
	vec3 vUp = normalize(cross(vForward, vRight));

	vec3 vDir = normalize(vWindow.x * vRight + vWindow.y * vUp + vForward * fov);

	return vDir;
}

// Sets the position of the camera with the mouse and calculates its direction
const float axm = 4.;
const float aym = 1.5;
void setCamera()
{
   vec2 iMouse2;
   if (iMouse.x==0. && iMouse.y==0.)
      iMouse2 = vec2(0.5, 0.5);
   else
      iMouse2 = iMouse.xy/iResolution.xy;

   campos = vec3(8.5, 0., 0.);
   campos.xy = rotateVec(campos.xy, -iMouse2.y*aym + aym*0.5);
   campos.yz = rotateVec(campos.yz, -iMouse2.y*aym + aym*0.5);
   campos.xz = rotateVec(campos.xz, -iMouse2.x*axm);

   camtarget = vec3(0.);
   camdir = camtarget - campos;   
}

// Tracing and rendering a ray
RenderData trace0(vec3 tpos, vec3 ray, float maxdist, bool inside)
{
    vec2 tr = trace(tpos, ray, maxdist, inside);
    float tx = tr.x;
    int objnr = int(tr.y);
    vec3 col;
    vec3 pos = tpos + tx*ray;
    vec3 norm;

    if (tx<maxdist*0.95)
    {
        norm = getNormal(pos, normdelta, inside);
        col = getColor(norm, pos, objnr, ray);

        // Shading
        col = ambientColor*ambientint + lampsShading(norm, pos, col, objnr);
    }
    else
    {
        objnr = SKY_OBJ;
        col = vec3(0.);
    }
    return RenderData(col, pos, norm, objnr);
}

vec3 getGlassAbsColor(float dist, vec3 color)
{
    return pow(color, vec3(0.1 + pow(dist*8., 2.)));
}

// Main render function with reflections and refractions
vec4 render(vec2 fragCoord)
{   
  	vec2 uv = fragCoord.xy / iResolution.xy; 
  	uv = uv*2.0 - 1.0;
  	uv.x*= iResolution.x / iResolution.y;

  	vec3 ray = GetCameraRayDir(uv, camdir, fov);
  	RenderData traceinf = trace0(campos, ray, maxdist, false);
  	vec3 col = traceinf.col;
  	bool inside = false;
  	float cior = glassMat.ior;
  	vec3 glassf = vec3(1.);
    vec3 refray;

    glassf = vec3(1.);

    for (int i=0; i<nbref; i++)
    {
        if (traceinf.objnr==BUBBLE_OBJ)
        {	 
            float gv = glassf.r*goldValue(traceinf.pos);
            #ifdef reflections
            refray = reflect(ray, traceinf.norm);
            float rf = fresnel(ray, traceinf.norm, glassMat.ior); 
            vec3 colGl = mix(col, sky_color(refray), rf*glassf);
            vec3 colGo = mix(col, getGoldColor(traceinf.pos)*sky_color(refray), goldRef);

            if (!inside)
            {
            	col = mix(colGl, colGo, gv);
            	glassf*= (1. - gv)*(1.- rf);
            }
            #endif

            cior = inside?1./glassMat.ior:glassMat.ior;

            vec3 ray_r = refract(ray, traceinf.norm, 1./cior);
            if (length(ray_r)!=0.)
                inside = !inside;
            else
                ray_r = reflect(ray, traceinf.norm);            

            vec3 pos = traceinf.pos;

            traceinf = trace0(pos, ray_r, 20., inside);
            if (inside)
                glassf*= getGlassAbsColor(distance(pos, traceinf.pos), glassMat.col_vol);
            glassf*= glassMat.col_fil;

            col+= clamp(traceinf.col*glassf, 0., 1.);

            ray = ray_r;

        }
        if (traceinf.objnr==SKY_OBJ)
        {
            col+= sky_color(ray)*glassf;
            break;
        }
    }
  	return vec4(col, 1.0);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{   
    init();
    setCamera();

    // Antialiasing.
    #ifdef antialias
    vec4 vs = vec4(0.);
    for (int j=0;j<aasamples ;j++)
    {
       float oy = float(j)*aawidth/max(float(aasamples-1), 1.);
       for (int i=0;i<aasamples ;i++)
       {
          float ox = float(i)*aawidth/max(float(aasamples-1), 1.);
          vs+= render(fragCoord + vec2(ox, oy));
       }
    }
    vec2 uv = fragCoord.xy / iResolution.xy;
    fragColor = vs/vec4(aasamples*aasamples);
    #else
    fragColor = render(fragCoord);
    #endif
}

vec3 eye 					= vec3(0.f,0.f,5.f);
vec4 sphere					= vec4(0.f,0.f,0.f, 0.7f);
// vec3 spotLightDir 			= normalize(vec3(0.0f,0.0f,-1.f)); // front
vec3 spotLightDir 			= normalize(vec3(-0.75f,-0.15f,-1.f));
vec3 spotLightColor			= vec3(0.7f);
vec3 ambientColor 			= vec3(0.3f);
float camerafov 			= 45.f;
float scatteringProbability = 1.f;

vec3 rayDirection(float fieldOfView, vec2 size, vec2 fragCoord) {
    vec2 xy = fragCoord - size / 2.0;
    float z = size.y / tan(radians(fieldOfView) / 2.0);
    return normalize(vec3(xy, -z));
}

bool anyHit_sphere(vec3 rayEye, vec3 rayDir, vec4 sphere) {
    vec3 a = sphere.xyz - rayEye;
    float a1 = dot(a, rayDir);
    vec3 a2 = a - a1 * rayDir;
    float distSq = dot(a2,a2);
    float rSq = sphere.w*sphere.w;
    if (distSq < rSq) {
        float cSq = rSq - distSq;
        float t = a1 - sqrt(cSq);
        return t >= -0.01f;
    } else
        return false;
}

bool closestHit_sphere(vec3 rayEye, vec3 rayDir, vec4 sphere, out vec3 hit, out vec3 normal) {
    vec3 a = sphere.xyz - rayEye;
    float a1 = dot(a, rayDir);
    vec3 a2 = a - a1 * rayDir;
    float distSq = dot(a2,a2);
    float rSq = sphere.w*sphere.w;
    if (distSq < rSq) {
        float cSq = rSq - distSq;
        float t = a1 - sqrt(cSq);
        hit = rayEye + rayDir * t;
        normal = normalize(vec3(hit-sphere.xyz));
        return true;
    } else
        return false;
}

bool closestHit_plane(vec3 rayEye, vec3 rayDir, vec4 plane, out vec3 hit, out vec3 normal) {
	vec3 p0 = plane.xyz * plane.w;
    vec3 n = -plane.xyz;
    float d = dot(p0-rayEye,n)/dot(rayDir, n);
    hit = rayEye + rayDir * d;
    normal = n;
    return true;
}

float saturate(float x) { return clamp(x, 0.f, 1.f); }

bool inLightFoV(vec3 Ln, vec3 spotLightDir, float cosHalfAngle) {
    // return true;
    return dot(Ln, -spotLightDir) > cosHalfAngle;
}

vec2 lightUV(vec3 Ln, float fov, vec3 lightLookVector, vec3 lightUpVector, vec3 lightRightVector) {
    float x = dot(Ln, lightRightVector);
    float y = dot(Ln, lightUpVector);
    float d = -1. / dot(Ln, lightLookVector); // 'un-normalize Ln'

    float q = 1. / (2. * tan(fov));

    float u = d * x * q + 0.5;
    float v = d * y * q + 0.5;

    return vec2(u, v);
}

void shading(vec3 Nn, vec3 Ln, vec3 lightColor, inout vec3 result) {
 	// Diffuse (lambertian) reflectance
	float dotNL = saturate(dot(Nn, Ln));
	vec3 diffuse = dotNL * lightColor;
    result += diffuse;
}

// Fast inverse for affine matrix:
mat4 affineInverse(mat4 m) {
	mat3 rot;
	rot[0] = m[0].xyz;
	rot[1] = m[1].xyz;
	rot[2] = m[2].xyz;

	mat3 invRot = transpose(rot);

	mat4 result;
	result[0] = vec4(invRot[0], 0);
	result[1] = vec4(invRot[1], 0);
	result[2] = vec4(invRot[2], 0);
	result[3] = vec4(-(invRot * m[3].xyz), 1);
	return result;
}

void SolveQuadratic(float a, float b, float c, out float minT, out float maxT)
{
	float discriminant = b*b - 4.0*a*c;

	if (discriminant < 0.0)
	{
		// no real solutions so return a degenerate result
		maxT = 0.0;
		minT = 0.0;
		return;
	}

	// numerical receipes 5.6 (this method ensures numerical accuracy is preserved)
	float t = -0.5 * (b + sign(b)*sqrt(discriminant));
	float closestT = t / a;
	float furthestT = c / t;

	if (closestT > furthestT)
	{
		minT = furthestT;
		maxT = closestT;
	}
	else
	{
		minT = closestT;
		maxT = furthestT;
	}
}

void IntersectCone(vec3 rayOrigin, vec3 rayDir, mat4 invConeTransform, float tanAperture, float height, out float minT, out float maxT)
{
	vec4 localOrigin = invConeTransform * vec4(rayOrigin, 1.0);
	vec4 localDir = invConeTransform * vec4(rayDir, 0.0);

	float tanTheta = tanAperture * tanAperture;

	float a = localDir.x*localDir.x + localDir.z*localDir.z - localDir.y*localDir.y*tanTheta;
	float b = 2.0*(localOrigin.x*localDir.x + localOrigin.z*localDir.z - localOrigin.y*localDir.y*tanTheta);
	float c = localOrigin.x*localOrigin.x + localOrigin.z*localOrigin.z - localOrigin.y*localOrigin.y*tanTheta;

	SolveQuadratic(a, b, c, minT, maxT);

	float y1 = localOrigin.y + localDir.y*minT;
	float y2 = localOrigin.y + localDir.y*maxT;

	if (y1 > 0.0 && y2 > 0.0)
	{
		// both intersections are in the reflected cone so return degenerate value
		minT = 0.0;
		maxT = -1.0;
	}
	else if (y1 > 0.0 && y2 < 0.0)
	{
		// closest t on the wrong side, furthest on the right side => ray enters volume but doesn't leave it (so set maxT arbitrarily large)
		minT = maxT;
		maxT = 10000.0;
	}
	else if (y1 < 0.0 && y2 > 0.0)
	{
		// closest t on the right side, largest on the wrong side => ray starts in volume and exits once
		maxT = minT;
		minT = 0.0;
	}
}

float InScatter(vec3 start, vec3 dir, vec3 lightPos, float d, vec3 attenuation)
{
	// calculate quadratic coefficients a,b,c
	vec3 q = start - lightPos;

	float b = dot(dir, q);
	float c = dot(q, q);

	// evaluate integral
	float s = 1.0f / sqrt(c - b*b);

	float l = s * (atan((d + b) * s) - atan(b*s));

    // attenuation:
	//float lightDist = length(q);
	//l = l * saturate(1.0 / dot(vec3(1, sqrt(lightDist), lightDist), attenuation));
	return l;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec3 rayDir = rayDirection(camerafov, iResolution.xy, fragCoord.xy);

    float spotLightHalfAngle = 25.0f + sin(iTime) * 10.0f;
    // float spotLightHalfAngle = 35.0f;
    if (iMouse.z > 0.5f)
     	// spotLightDir = normalize(vec3(-normalize(iMouse.xy - iResolution.xy / 2.f), -1.f));
        spotLightDir = normalize(vec3(sin(6.28*iMouse.x/iResolution.x), cos(3.14*iMouse.y/iResolution.y), cos(6.28*iMouse.x/iResolution.x)));
    vec3 spotLightOrigin 	= (sphere.xyz - spotLightDir) * 1.4;
    vec3 lightUp = normalize(cross(spotLightDir, vec3(1,0,0)));
    vec3 lightRight = cross(spotLightDir, lightUp);
    float spotfov = radians(spotLightHalfAngle);
    float cosSpotHalfAngle = cos(spotfov);

    vec3 result = vec3(0.f);

    // lit sphere:
    vec3 hitPos, hitNormal;
    float hitDist = 1e5;
    if (closestHit_sphere(eye, rayDir, sphere, hitPos, hitNormal)) {
    // if (closestHit_plane(eye, rayDir, vec4(0,0,-1, 0), hitPos, hitNormal)) {
        hitDist = length(hitPos-eye); // used for cone

        // for each spotlight:
        vec3 Ln = normalize(spotLightOrigin-hitPos);
        if (inLightFoV(Ln, spotLightDir, cosSpotHalfAngle)) {
            // gobo:
            vec2 goboUV = lightUV(Ln, spotfov, spotLightDir, lightUp, lightRight);
            vec4 goboColor = texture(iChannel0, goboUV);

        	shading(hitNormal, Ln, goboColor.xyz * goboColor.a * spotLightColor, result);
        }

        shading(hitNormal, normalize(vec3(0.f,0.f,1.f)), ambientColor, result); // directional light
    } else {
        // checkerboard background
        int ix = int(fragCoord.x);
        int iy = int(fragCoord.y);

        result = (ix / 16) % 2 == 0 ^^ (iy / 16) % 2 == 0 ? vec3(0.1f) : vec3(0.15f);
    }

    // volumetric fog:
	float height = 30.0;
	float minT = 0.0;
	float maxT = 0.0;

	mat4 LightToWorld;
	LightToWorld[0] = vec4(lightRight, 0.0);
	LightToWorld[1] = vec4(-spotLightDir, 0.0); // change of basis from XYZ to X-ZY to rotate forward facing cone downward
	LightToWorld[2] = vec4(lightUp, 0.0);
	LightToWorld[3] = vec4(spotLightOrigin, 1);

	mat4 invLightToWorld = affineInverse(LightToWorld);

	float tanSpotAngle = tan(radians(spotLightHalfAngle));

	IntersectCone(eye, rayDir, invLightToWorld, tanSpotAngle, height, minT, maxT);

	minT = max(minT, 0.f);
	maxT = min(maxT, hitDist);
	float dt = max(0.0, maxT - minT);

    // analytic fog integral:
	vec3 scatter = spotLightColor * /* vec3(0.2, 0.5, 0.8) * */
        max(0.f, InScatter(eye + rayDir*minT, rayDir,spotLightOrigin, dt, vec3(1,1,1))) 
        * scatteringProbability * 0.5;

    // ray marched gobo fog:
    vec3 coneGoboColor = vec3(0.f);
    for (int i = 0; i < 16; ++i) {
    	float t = mix(minT, maxT, float(i) / float(16-1));
        vec3 p = eye + rayDir*t; // point in volume
        vec3 Ln = normalize(spotLightOrigin-p);
        // shadow ray:
        if (!anyHit_sphere(p, Ln, sphere)) 
        {
        	vec2 goboUV = lightUV(Ln, spotfov, spotLightDir, lightUp, lightRight);
        	vec4 goboColor = texture(iChannel0, goboUV);
        	coneGoboColor += goboColor.xyz * goboColor.a * spotLightColor;
        }
    }
    coneGoboColor /= 16.f;

	result += scatter * coneGoboColor;

    fragColor = vec4(result, 1.f);
}

// Given a path I: [0, 1] -> R^n, and a function defined on 
// this path f: [0, 1] -> R^n ->R^m
// Consider then the extension
// F: R^n -> R^m defined by
// F(x) = C * integral_{i in I} f(i) / (dist(X - I(i))) d I(i) 
// C being a normalizing constant, usually the length of the path I in R^n.
// Then F is a continuous extension of f in the entire space!
//
// We are going to extend the normal map.
// If we have the circle S1 = {x : |x| = 1}, then for each point in S1, it's normal is itself
// That is: N(x) = x for every point x in S1. 
// On the other hand, for a square, the normal of a point x is (+1, 0), (-1, 0), (0, +1) or (0, -1)
// depending on which side of the square the point is.
// Regardless, we have a normal N defined on this path.
// We are going to extend this normal onto the entire plane and then light using common techniques!

vec4 GetLight(vec2 uv) // Calculates the light of a point given it's normal
{
    vec3 ligdir = normalize(vec3(cos(iTime), sin(iTime), -0.4 + 0.4*sin(iTime*0.5))); //Direction of the Light

    vec2 tex = float(uv.x <= 1.0) *
                    texture(iChannel0, uv - vec2(0.0, 1.0)).xy + float(!(uv.x <= 1.0))*
                    texture(iChannel1, uv - vec2(1.0, 1.0)).xy;

    vec3 normal = normalize(2.0*vec3(tex, 0.0) - 1.0); //Convert RGB Coordinates back into Normal vectors

    float intensity = dot(ligdir, normal); //Light it

    vec4 Color = normalize(vec4(1.0, 0.0, 0.5, 0.0));
    vec4 BColor = vec4(0.0, 0.0, 0.2, 0.0);

    return intensity*Color + (1.0-intensity)*BColor;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = 2.0*fragCoord/iResolution.xy;
    fragColor = float(uv.y <= 1.0) * 
        (uv.x <= 1.0 ? texture(iChannel0, uv) : texture(iChannel1, uv - vec2(1.0, 0.0))) +  float(!(uv.y <= 1.0)) *// uv.y <= 1.0
        GetLight(uv); // 1.0 <= uv.y <= 2.0

    float border = 0.005;
    float condition = float(((uv.x <= 1.0 + border && uv.x >= 1.0 - border) || (uv.y <= 1.0 + border && uv.y >= 1.0 - border)));
    fragColor = condition *
                    vec4(0.0) + (1.0 - condition) *fragColor;
}

// This buffer gets the normal UV map of a circle

#define PI 3.14159265359

vec2 GetPoint(float alpha)
{
    vec2 circlepos = 0.7 * vec2(cos(alpha * 2.0 * PI / 4.0), sin(alpha * 2.0 * PI / 4.0));
    vec2 squarepos = float(alpha <= 1.0) * vec2(0.5, -0.5 + alpha) + float(!(alpha <= 1.0)) *(
                                float(alpha <= 2.0) * vec2(0.5 - (alpha - 1.0) , 0.5) + float(!(alpha <= 2.0))*(
                                  float(alpha <= 3.0) * vec2(-0.5, 0.5 - (alpha - 2.0)) + float(!(alpha <= 3.0))*
                                    vec2(-0.5 + (alpha - 3.0), -0.5)));
    float rate = 2.0*sin(iTime) - 1.0;
    return circlepos;
    return rate*circlepos + (1.0 - rate)*squarepos;
}
vec2 Normal(float alpha) //Calculates the normal of a point in the S1 circunference
{
    vec2 pos = GetPoint(alpha);
    vec2 circnormal = normalize(pos);
    vec2 squarenormal = float(pos.y >= 0.5) * vec2(0.0, 1.0) + float(!(pos.y >= 0.5))*(
               float(pos.y <= -0.5) * vec2(0.0, -1.0) + float(!(pos.y <= -0.5)) * (
                   float(pos.x >= 0.5) * vec2(1.0, 0.0) + float(!(pos.x >= 0.5))*
                       vec2(-1.0, 0.0) ));

    float rate = 2.0*sin(iTime) - 1.0;
    return circnormal;
    return rate*circnormal + (1.0-rate)*squarenormal; // The normal of the S1 circunference is the identity
}
vec2 integral(vec2 pos)
{
    float interval = 0.01; //Interval of the ingral
    vec2 sum = vec2(0.0, 0.0); //Value we are going to return

    for(float alpha = 0.0; alpha < 4.0; alpha += interval)
    {
        vec2 val = (1.0/(max(length(GetPoint(alpha) - pos), 0.001))) * Normal(alpha); // Normal of point Circlepos multiplied by the weight it has on position pos.
        sum = sum + interval * val;
    }
    return (1.0/(4.0*PI))*sum; // We normalize it by the length of the path, which is precisely the perimeter of S1. That is, 2PI
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from -1 to 1)
    vec2 uv = fragCoord/iResolution.xy;
    uv = 2.0*uv - 1.0;
    uv = uv * vec2(iResolution.x / iResolution.y, 1.0); //Corrects Distortion caused by screen

    vec2 i = integral(uv); // Gets the extension of the identity of function of the circunference to the entire space
    fragColor = vec4(0.5) + 0.5*vec4(i.xy, 1.0, 0.0); //Convert normal vector to standard RGB representation.



}

// This buffers get the normal UV map of a square

vec2 Normal(vec2 pos) //Calculates the normal of a point in the 2D Square
{
    return float(pos.y >= 0.5) * vec2(0.0, 1.0) + float(!(pos.y >= 0.5))*(
               float(pos.y <= -0.5) * vec2(0.0, -1.0) + float(!(pos.y <= -0.5)) * (
                   float(pos.x >= 0.5) * vec2(1.0, 0.0) + float(!(pos.x >= 0.5))*
                       vec2(-1.0, 0.0) ));
}
vec2 integral(vec2 pos)
{
    float interval = 0.01; //Interval of the integral
    vec2 sum = vec2(0.0, 0.0); 

    for(float alpha = 0.0; alpha < 4.0; alpha += interval)
    {
        vec2 squareposition = float(alpha <= 1.0) * vec2(0.5, -0.5 + alpha) + float(!(alpha <= 1.0)) *(
                                float(alpha <= 2.0) * vec2(0.5 - (alpha - 1.0) , 0.5) + float(!(alpha <= 2.0))*(
                                  float(alpha <= 3.0) * vec2(-0.5, 0.5 - (alpha - 2.0)) + float(!(alpha <= 3.0))*
                                    vec2(-0.5 + (alpha - 3.0), -0.5)));

        vec2 val = (1.0/(max(length(squareposition - pos), 0.001))) * Normal(squareposition); // Normal of point Square multiplied by the weight it has on position pos.

        sum = sum + interval * val;
    }
    return (1.0/(2.0*4.0))*sum; // Normalization of path length
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from -1 to 1)
    vec2 uv = fragCoord/iResolution.xy;
    uv = 2.0*uv - 1.0;
    uv = uv * vec2(iResolution.x / iResolution.y, 1.0); //Corrects Distortion caused by screen

    vec2 i = integral(uv); // Gets the extension of the identity of function of the circunference to the entire space
    fragColor = vec4(0.5) + 0.5*vec4(i.xy, 1.0, 0.0); //Convert normal vector to standard RGB representation.



}

// based on one desert canyon of the fantastic Shane shader

// best for small size
#define WITH_AA

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord/iResolution.xy;
    vec4 res = texture(iChannel0, uv);

#ifdef WITH_AA

    vec3 dp = vec3(1./iResolution.xy, 0);
    float needAA = 0.;
    for (int j=-1; j<3; j++) {
        for (int i=-1; i<3; i++) {
            needAA += texture(iChannel0, uv).w;
        }
    }

    // Antialising only on edges and big curvature
    if (needAA > .5) {
    	for (int k=0; k<4; k++)
        	res += render(fragCoord+.66*vec2(k%2-1,k/2-1)-.33, iTime, iResolution.xy, iChannel0);
        res /= 5.;
    }

#endif

    fragColor = res;

}

void mainImage(out vec4 fragColor, in vec2 fragCoord){
    fragColor = render(fragCoord.xy, iTime, iResolution.xy, iChannel0);
}

#define FAR 400.
//#define PRECISE
//#define WITH_AO

#define ID_SKY    0.
#define ID_SHIP   1.
#define ID_GROUND 2.
#define ID_PATH   3.

#define EDGE_WIDTH 5e-3



// Frequencies and amplitudes of the "path" function, used to shape the tunnel and guide the camera.
const float freqA = .34*.15/3.75;
const float freqB = .25*.25/2.75;
const float ampA = 20.;
const float ampB = 4.;


vec3 gRO;
mat3 gbaseShip;

float gedge;
float gedge2;
float glastt;


// 2x2 matrix rotation. Angle vector, courtesy of Fabrice.
mat2 rot2( float th ){ vec2 a = sin(vec2(1.5707963, 0) + th); return mat2(a, -a.y, a.x); }

// 1x1 and 3x1 hash functions.
float hash(float n){ return fract(cos(n)*45758.5453); }
float hash(vec3 p){ return fract(sin(dot(p, vec3(7, 157, 113)))*45758.5453); }


// Smooth maximum, based on the function above.
float smaxP(float a, float b, float s){    
    float h = clamp(.5 + .5*(a - b)/s, 0., 1.);
    return mix(b, a, h) + h*(1. - h)*s;
}

float sdVerticalCapsule( vec3 p, float h, float r ) {
  p.y -= clamp( p.y, 0.0, h );
  return length( p ) - r;
}

float sdTorus( vec3 p, vec2 t ) {
  vec2 q = vec2(length(p.xz)-t.x,p.y);
  return length(q)-t.y;
}

float sdBox( vec3 p, vec3 b ) {
  vec3 q = abs(p) - b;
  return length(max(q,0.0)) + min(max(q.x,max(q.y,q.z)),0.0);
}

float sdBox( in vec2 p, in vec2 b ) {
    vec2 d = abs(p)-b;
    return length(max(d,0.0)) + min(max(d.x,d.y),0.0);
}

float sdCappedCylinder( vec3 p, float h, float r ) {
  vec2 d = abs(vec2(length(p.xz),p.y)) - vec2(h,r);
  return min(max(d.x,d.y),0.0) + length(max(d,0.0));
}

void pModPolar(inout vec2 p, float repetitions) {
	float angle = 2.*3.141592/repetitions;
	float a = atan(p.y, p.x) + angle*.5;
	a = mod(a,angle) - angle*.5;
	p = vec2(cos(a), sin(a))*length(p);
}

void pR45(inout vec2 p) {
	p = (p + vec2(p.y, -p.x))*sqrt(0.5);
}

// The path is a 2D sinusoid that varies over time, depending upon the frequencies, and amplitudes.
vec2 path(in float z){ 
    return vec2(ampA*sin(z * freqA) + 2.*cos(z*.0252) - 1., 10.+ ampB*cos(z * freqB) * (.5+ .5*sin(z*0.0015)));
}

float sdGround(in vec3 p, sampler2D channel){
    p += vec3(0,2,0);
    float tx1 = 2.5*textureLod(channel, p.xz/28. + p.xy/100., 0.).x;
    float tx2 = 2.*textureLod(channel, p.xy/vec2(31.,15.), 0.).x;
  	float tx = tx1 - tx2;

    vec3 q = p*.125;
    float h = dot(sin(q)*cos(q.yzx), vec3(.222)) + dot(sin(q*1.5)*cos(q.yzx*1.5), vec3(.111));

    float d = p.y + h*6.;
    q = p*.07125;
    float h3 = dot(sin(q)*cos(q.yzx), vec3(.222)) + dot(sin(q*1.5)*cos(q.yzx*1.5), vec3(.111));
    float d3 = p.y + h3*22.-22.;

    q = sin(p*.5 + h);
    float h2 = q.x*q.y*q.z;

    vec3 p0 = p;
    p.xy -= path(p.z);

    float dPath = length(p.xy)-38.;

    vec3 p1 = p;
    float tnl = 1.5 - length(p.xy*vec2(1.2, 1.96)) + h2;// - (1. - tx)*.25;

    p.xz = mod(p0.xz+150.,300.)-150.; 

    float dCaps = mix(999., sdVerticalCapsule(p+vec3(45,60,50), 130., 15.) + tx1, step(2500., p0.z));

    p = p1;
    p.z = mod(p.z+250.,500.)-250.; 

    float dGate = sdTorus(p.yzx-vec3(25,25,5), vec2(50.,15.))+tx1;
	dCaps = mix(dCaps, dGate, step(4600., p0.z));

    p.xz = mod(p0.xz+450.,900.)-450.;
    float dCaps2 = sdVerticalCapsule(p+vec3(20,55,0), 100., 30.) + .5*tx;

    float d4 = smaxP(d - tx*.5+ tnl*.4, .2*tnl, 8.);
    d3 = mix(d3, d4, smoothstep(.5,1., .5+.5*(sin(p0.z*.001-.8))));

    d = min(dCaps, smaxP(d3, d4, 10.));
    float dend = max(p0.y-60., -dPath-.5*tx+.25*tx2);
    d = mix(d, dend, smoothstep(7000.,9000., p0.z)*smoothstep(12000.,9000., p0.z));
    d = smaxP(-dCaps2, d,2.);

    return d;
}

float sdShip(in vec3 p0) {
    p0 -= vec3(4,0,0);
    float d = length(p0) -4.;

    vec3 pRot = p0;
    pModPolar(pRot.zy, 16.);
    pRot.x = abs(pRot.x);
    d = min(d, length(pRot-vec3(2.6,0,3.))-.2);
	d = min(d, sdBox(pRot-vec3(4.5,0,.8), vec3(.5,.1,.2)));    

    vec3 p = p0;
    p.zy = abs(p.zy);
    p -= vec3(-5.6,2.5,2);
    pR45(p.yz);
    pR45(p.xy);
    return min(d, sdBox(p, vec3(1.,2,.2)));  
}

float sdPath(in vec3 p0) {
    float d2 = length(path(p0.z)-p0.xy)-.5;
    return max(d2, -gRO.z + p0.z);
}

float map(in vec3 p0, sampler2D channel) {
    float d = sdGround(p0,channel);
    float dPath = sdPath(p0-vec3(0,0,0));
    return min(dPath,d); 
}

float mapFull(in vec3 p0, sampler2D channel) {
    float d = sdGround(p0,channel);
    float dPath = sdPath(p0);
    return min(sdShip((p0-gRO)*gbaseShip),min(dPath,d)); 
}

vec2 min2(vec2 c0, vec2 c1) {
	return c0.x < c1.x ? c0 : c1;
}

vec2 mapColor(in vec3 p0, sampler2D channel) {
    float d = sdGround(p0, channel);
    float dPath = sdPath(p0);
    return min2(vec2(sdShip((p0-gRO)*gbaseShip), ID_SHIP), 
                min2(vec2(dPath, ID_PATH), vec2(d, ID_GROUND))); 
}


float logBisectTrace(in vec3 ro, in vec3 rd, sampler2D channel){
    float t = 0., told = 0., mid, dn;
    float d = map(rd*t + ro, channel);
    float sgn = sign(d);

    float lastDistEval = 1e10, lastt = 0.;
	vec3 rdShip = rd*gbaseShip;
	vec3 roShip = (ro-gRO)*gbaseShip;

    for (int i=0; i<164; i++){
        if (sign(d) != sgn || d < 0.01 || t > FAR) break;

        told = t;    
        t += step(d, 1.)*(log(abs(d) + 1.1) - d) + d;

        d = map(rd*t + ro, channel);
        d = min(d, sdShip(rdShip*t + roShip));

        if (d < lastDistEval) {
            lastt = t;
            lastDistEval = d;
        } else {
            if (d > lastDistEval + 0.0001 &&  lastDistEval/mix(30., lastt, smoothstep(FAR*.75, FAR*.9, t)) < EDGE_WIDTH) {
            	gedge = 1.f;
                if (glastt == 0.) glastt = lastt;
            }
            if (d > lastDistEval + 0.0001 && (lastDistEval < EDGE_WIDTH*40. || lastDistEval/lastt < EDGE_WIDTH*2.)) {
            	gedge2 = 1.f;
            }
			//edge = smoothstep(-EDGE_WIDTH,-EDGE_WIDTH*.5f,-(lastDistEval/100.));///lastt));
		}
    }
    if (glastt == 0.)  glastt = lastt;

#ifdef PRECISE
    // If a threshold was crossed without a solution, use the bisection method.
    if (sign(d) != sgn){

        // Based on suggestions from CeeJayDK, with some minor changes.

        dn = sign(map(rd*told + ro, channel));

        vec2 iv = vec2(told, t); // Near, Far

        // 6 iterations seems to be more than enough, for most cases...
        // but there's an early exit, so I've added a couple more.
        for (int ii=0; ii<8; ii++) { 
            //Evaluate midpoint
            mid = dot(iv, vec2(.5));
            float d = map(rd*mid + ro, channel);
            if (abs(d) < 0.001)break;
            iv = mix(vec2(iv.x, mid), vec2(mid, iv.y), step(0.0, d*dn));
        }

        t = mid;       
    }
#endif

    return min(t, FAR);
}


vec3 normal(in vec3 p, sampler2D channel) {  
    vec2 e = vec2(-1, 1)*.001;   
	return normalize(e.yxx*mapFull(p + e.yxx, channel) + e.xxy*mapFull(p + e.xxy, channel) + 
					 e.xyx*mapFull(p + e.xyx, channel) + e.yyy*mapFull(p + e.yyy, channel) );   
}


float softShadow(in vec3 ro, in vec3 rd, in float start, in float end, in float k, sampler2D channel){
    ro += rd*hash(ro);
    vec3 rdShip = rd*gbaseShip;
	vec3 roShip = (ro-gRO)*gbaseShip;
    float shade = 1.;
    const int maxIterationsShad = 24; 
    float dist = start;
    float stepDist = end/float(maxIterationsShad);
    for (int i=0; i<maxIterationsShad; i++){
        float h = min(map(ro + rd*dist, channel), sdShip(roShip + dist*rdShip));
        shade = min(shade, smoothstep(0., 1., k*h/dist));
        dist += clamp(h, .2, stepDist*2.);
        if (abs(h)<.001 || dist > end) break; 
    }
    return min(max(shade, 0.) + .1, 1.); 
}

#ifdef WITH_AO

float calculateAO( in vec3 p, in vec3 n, float maxDist, sampler2D channel )
{
	float ao = 0., l;
	const float nbIte = 6.;
    for(float i=1.; i< nbIte+.5; i++){
        l = (i + hash(i))*.5/nbIte*maxDist;
        ao += (l - mapFull( p + n*l, channel))/(1. + l);
    }
    return clamp(1. - ao/nbIte, 0., 1.);
}
#endif

// Pretty standard way to make a sky. 
vec3 getSky(in vec3 ro, in vec3 rd, vec3 sunDir){
	return vec3(smoothstep(.97,1.,max(dot(rd, sunDir), 0.)));
}

// Curve function, by Shadertoy user, Nimitz.
// Original usage (I think?) - Cheap curvature: https://www.shadertoy.com/view/Xts3WM
float curve(in vec3 p, sampler2D channel){
    const float eps = .05, amp = 4., ampInit = .5;
	vec2 e = vec2(-1, 1)*eps; // 0.05->3.5 - 0.04->5.5 - 0.03->10.->0.1->1.
    float t1 = mapFull(p + e.yxx, channel), t2 = mapFull(p + e.xxy, channel);
    float t3 = mapFull(p + e.xyx, channel), t4 = mapFull(p + e.yyy, channel);
    return clamp((t1 + t2 + t3 + t4 - 4.*mapFull(p, channel))*amp + ampInit, 0., 1.);
}


vec4 render(in vec2 fragCoord, float Time, vec2 Resolution, sampler2D channel){

    gedge = 0.;
    gedge2= 0.;
    glastt = 0.;

	// Screen coordinates.
	vec2 u = (fragCoord - Resolution.xy*.5)/Resolution.y;
    float dBox = sdBox(u, vec2(.5*Resolution.x/Resolution.y-.1,.4));

    vec3 col = vec3(.2);
   	float needAA = 0.; 
    float ed = 0., ed2 = 0., lastt1 = 0.;

    if (dBox <0.){	

        // Camera Setup.
        vec3 lookAt = vec3(0, 0, Time*100.);  // "Look At" position.
        vec3 ro = lookAt + vec3(0, 0, -.25); // Camera position, doubling as the ray origin.

        lookAt.xy += path(lookAt.z);
        ro.xy += path(ro.z);
        lookAt.y -= .071;

        // Using the above to produce the unit ray-direction vector.
        float FOV = 3.14159/2.; // FOV - Field of view.

        vec3 forward = normalize(lookAt - ro);
        vec3 right = normalize(vec3(forward.z, 0, -forward.x )); 

        right.xy *= rot2( path(lookAt.z).x/64.);
        right.xy *= rot2( -.7*cos(Time*.12));


        vec3 up = cross(forward, right);

        vec3 rd = normalize(forward + FOV*u.x*right + FOV*u.y*up);
        vec3 lp = vec3(.5*FAR, FAR, 1.5*FAR) + vec3(0, 0, ro.z);


        gRO = ro+vec3(0,0,1);
        gRO.xy = path(gRO.z);
        vec3 p2 = vec3(path(gRO.z+1.), gRO.z+1.);

        forward = normalize(p2 - gRO);
        right = normalize(vec3(forward.z, 0, -forward.x )); 
        right.xy *= rot2( path(lookAt.z).x/32.);
        up = cross(forward, right);
        gbaseShip = mat3(forward, up, right);

        float dist = mix(35., 15., smoothstep(7000.,8500., gRO.z));
        dist = mix(dist, 45., smoothstep(10000.,12000., gRO.z));
        ro += (dist*(.5+.5*cos(.31*Time))+2.)*vec3(.3,1,-2.);
        ro.x += .3*dist*cos(.31*Time);

        float t = logBisectTrace(ro, rd, channel);
        ed = gedge; ed2 = gedge2;  lastt1 = glastt;


        vec3 sky = getSky(ro, rd, normalize(lp - ro));

        col = sky;

        vec2 mapCol = mapColor(ro+t*rd, channel);

        vec3 sp;
		float cur;
        if (t < FAR){

            sp = ro+t*rd; // Surface point.
            vec3 sn = normal(sp, channel); // Surface normal.
            vec3 ld = lp-sp;
            ld /= max(length(ld), 0.001); // Normalize the light direct vector.

            float shd = softShadow(sp, ld, .1, FAR, 8., channel); // Shadows.
            cur = curve(sp, channel);
            float curv = cur*.9 +.1; // Surface curvature.
#ifdef WITH_AO
            float ao = calculateAO(sp, sn, 4., channel); // Ambient occlusion.
#else
            float ao = 1.;//calculateAO(sp, sn, 4., channel); // Ambient occlusion.
#endif
            float dif = max( dot( ld, sn ), 0.); // Diffuse term.
            float spe = pow(max( dot( reflect(-ld, sn), -rd ), 0. ), 5.); // Specular term.
            float fre = clamp(1.0 + dot(rd, sn), 0., 1.); // Fresnel reflection term.
            float Schlick = pow( 1. - max(dot(rd, normalize(rd + ld)), 0.), 5.);
            float fre2 = mix(.2, 1., Schlick);  //F0 = .2 - Hard clay... or close enough.
            float amb = fre*fre2 + .06*ao;        

            col = clamp(mix(vec3(.8, .5, .3), vec3(.5, .25, .125),(sp.y+1.)*.15), vec3(.5, .25, .125), vec3(1));
            col = pow(col, vec3(1.5));
            col = (col*(dif + .1) + fre2*spe)*shd*ao + amb*col;      
        }

        col = pow(max(col, 0.), vec3(.75));

        u = fragCoord/Resolution.xy;

        vec3 cGround = vec3(248,210,155)/256.;
        vec3 cSky = vec3(177,186,213)/256.;

        if (t < FAR){

            vec3 cFill;
            if (mapCol.y == ID_PATH) {
                cFill = vec3(1,.01,0.01);//mix(vec3(248,210,155)/256., vec3(248,185,155)/256., smoothstep(12.0,12.1,(sp.y)));
            }
            else if (mapCol.y == ID_SHIP) {
               	vec3 pShip = (sp-gRO)*gbaseShip;
                cFill = mix(vec3(0,1,1),vec3(.7),smoothstep(.0,.1, pShip.x-1.3));
            } else {
                cFill = mix(vec3(248,210,155)/256., vec3(248,185,155)/256., smoothstep(.0,.1,sp.y-8.));
                cFill = mix(cFill, vec3(1,0,0), .4*smoothstep(1000.,3000., gRO.z));
            	vec3 col3 = cos(sp.y*.08+1.1)*clamp(mix(vec3(.8, .5, .3), vec3(.5, .25, .125),(sp.y+1.)*.15), vec3(.5, .25, .125), vec3(1));

                cFill = mix(cFill, col3, .5*smoothstep(6000.,8500., gRO.z));
            }

            col = mix(cFill,cSky,t/FAR)*(.5+.5*smoothstep(.4,.5,length(col)));
            col = mix(col, vec3(.0), ed);
            col = mix(vec3(0), col, .5+.5*smoothstep(.4,.41,cur)); // Surface curvature.;
            ed2 += cur<.35?1.:0.;

        } else {
            col = mix(cSky*abs(1.-rd.y),vec3(1),smoothstep(1.3,1.4,length(col)));
            col = mix(col, vec3(.1), ed);
        	float sun = max(dot(rd, normalize(lp - ro)), 0.); // Sun strength.
			col = mix(vec3(0), col, smoothstep(.09/Resolution.y,.2/Resolution.y, abs(sun-.9892)));//.zyx;	
        }

        col = mix(col, cSky*abs(1.-rd.y), sqrt(smoothstep(FAR - (ed <0. ? 200. : 100.), FAR, lastt1)));

    }  

    // BD frame
    col = mix(col, vec3(.2),smoothstep(.0,1./Resolution.y,dBox));
    col = mix(col, vec3(0.),smoothstep(1./Resolution.y,.0,abs(dBox)-.005));

    return vec4(clamp(col, 0., 1.), ed2);
}

// Comparaison of the reflectance of different metals
//  using Lazanyi approximation with RGB rendering versus exact fresnel with spectral rendering 
// BufferA contains the code for the RGB rendering
// BufferB contains the code for the spectral rendering
// BufferC was used to find the reflection coefficients for Lazanyi
// Common contains the metal models, the fresnel functions, and some pieces of code used in multiple buffers
//
// To look at another metal, edit the first 3 lines of the "Common" tab accordingly
// Supported metals are: Iron, Gold(un-normalized!), Aluminium, Chromium, Copper(un-normalized), Lead, Platinium, Silver

//To find the values for a new metal, import a table contating 
// the index of refraction and extinction coefficient for several visible wavelegth
// and write a function to interolate this data (you can look at resampleIor_49() in common tab)
// then redefine getIOR(w) to point towards your new interpolation function
