    vec3 p = ro+rd*i.a;

    vec3 n = normalize(p);
    float r = getRoughness(p.xzy, iChannel3);
    r*=r;

    const int samples = 1;
    for(int i = 0;i<samples;i++){
        importanceSampling_s(fragColor, n, rd, r, dithering, (iFrame)*samples+i);
    }
}

