mat3 rotationAxisAngle( vec3 v, float angle )
{
    float s = sin( angle );
    float c = cos( angle );
    float ic = 1.0 - c;

    return mat3( v.x*v.x*ic + c,     v.y*v.x*ic - s*v.z, v.z*v.x*ic + s*v.y,
                 v.x*v.y*ic + s*v.z, v.y*v.y*ic + c,     v.z*v.y*ic - s*v.x,
                 v.x*v.z*ic - s*v.y, v.y*v.z*ic + s*v.x, v.z*v.z*ic + c);
}

#define PATH_LENGTH 10
#define MAX_DIST 1e10
//
// Hash functions by Nimitz:
// https://www.shadertoy.com/view/Xt3cDn
//

uint baseHash( uvec2 p ) {
    p = 1103515245U*((p >> 1U)^(p.yx));
    uint h32 = 1103515245U*((p.x)^(p.y>>3U));
    return h32^(h32 >> 16);
}

float hash1( inout float seed ) {
    uint n = baseHash(floatBitsToUint(vec2(seed+=.1,seed+=.1)));
    return float(n)/float(0xffffffffU);
}

vec2 hash2( inout float seed ) {
    uint n = baseHash(floatBitsToUint(vec2(seed+=.1,seed+=.1)));
    uvec2 rz = uvec2(n, n*48271U);
    return vec2(rz.xy & uvec2(0x7fffffffU))/float(0x7fffffff);
}

//
// Ray tracer helper functions
//

float FresnelSchlickRoughness( float cosTheta, float F0, float roughness ) {
    return F0 + (max((1. - roughness), F0) - F0) * pow(abs(1. - cosTheta), 5.0);
}

vec3 cosWeightedRandomHemisphereDirection( const vec3 n, inout float seed ) {
  	vec2 r = hash2(seed);
	vec3  uu = normalize(cross(n, abs(n.y) > .5 ? vec3(1.,0.,0.) : vec3(0.,1.,0.)));
	vec3  vv = cross(uu, n);
	float ra = sqrt(r.y);
	float rx = ra*cos(6.28318530718*r.x); 
	float ry = ra*sin(6.28318530718*r.x);
	float rz = sqrt(1.-r.y);
	vec3  rr = vec3(rx*uu + ry*vv + rz*n);
    return normalize(rr);
}

vec3 modifyDirectionWithRoughness( const vec3 normal, const vec3 n, const float roughness, inout float seed ) {
    vec2 r = hash2(seed);

	vec3  uu = normalize(cross(n, abs(n.y) > .5 ? vec3(1.,0.,0.) : vec3(0.,1.,0.)));
	vec3  vv = cross(uu, n);

    float a = roughness*roughness;

	float rz = sqrt(abs((1.0-r.y) / clamp(1.+(a - 1.)*r.y,.00001,1.)));
	float ra = sqrt(abs(1.-rz*rz));
	float rx = ra*cos(6.28318530718*r.x); 
	float ry = ra*sin(6.28318530718*r.x);
	vec3  rr = vec3(rx*uu + ry*vv + rz*n);

    vec3 ret = normalize(rr);
    return dot(ret,normal) > 0. ? ret : n;
}

vec2 randomInUnitDisk( inout float seed ) {
    vec2 h = hash2(seed) * vec2(1,6.28318530718);
    float phi = h.y;
    float r = sqrt(h.x);
	return r*vec2(sin(phi),cos(phi));
}

//
// Scene description
//

vec3 rotateY( const in vec3 p, const in float t ) {
    float co = cos(t);
    float si = sin(t);
    vec2 xz = mat2(co,si,-si,co)*p.xz;
    return vec3(xz.x, p.y, xz.y);
}

vec3 opU( vec3 d, span s, inout vec3 normal, float mat ) {
    if( s.n.t<d.y && s.n.t>d.x) {
        normal=s.n.n;
        d=vec3(d.x, s.n.t, mat);
    }
	return d;
}

vec3 worldhit( in vec3 ro, in vec3 rd, in vec2 dist, out vec3 normal ) {

   vec3  d = vec3(dist, 0.);

    span s = iBox(ro-vec3(0.,-.4,0.),rd,vec3(10.,.4,10.));
        iPlane(ro,rd,-vec3(0,1.,0),1.);           
    d= opU(  d,  s,  normal, 1. ) ;

    span s2,s3;

    // DICE= sphere * cube
    s2= iBox(ro-vec3(0.,.4,0.),rd,vec3(.4));
    s3= iSphere(ro-vec3(0.,.4,0.),rd,.5);
    d= opU(  d,  Inter(s2,s3),normal , 7.);   

    // LAMP= cube -sphere 
    s2= iBox(ro-vec3(1.,.4,0.),rd,vec3(.4));
    s3= iSphere(ro-vec3(1.,.4,0.),rd,-.5);
    d= opU(  d,  Sub(s2,s3),normal , 6.);   

   // RAMP= box * plane
    s2= iBox(ro-vec3(-1.,.4,0.),rd,vec3(.4));
    s3= iPlane(ro-vec3(-1.,.4,0.),rd,normalize(-vec3(1.,1.,0.)),2.);
    d= opU(  d,  Inter(s2,s3),normal , 10.);


    // HEMISPHERE = sphere * plane
    s2= iSphere(ro-vec3(1.,.4,1.),rd,.4);
    s3= iPlane(ro-vec3(-1.,.4,0.),rd,normalize(vec3(0.,-1.,0.)),.4);    
     d= opU(  d,  Inter(s2,s3),normal , 10.);


    // SNOWMAN = sphere  + sphere
    s2= iSphere(ro-vec3(0.,.2,1.),rd,.2);
    s3= iSphere(ro-vec3(0.,.5,1.),rd,.2);
     d= opU(  d,  Union(s2,s3),normal , 4.);

    // UFO = sphere * sphere
    s2= iSphere(ro-vec3(-1.,.4,1.),rd,.4);
    s3= iSphere(ro-vec3(-1.,0.,1.),rd,.4);
    d= opU(  d,  Inter(s2,s3),normal , 8.);

    //POT = box - box
    s2= iBox(ro-vec3(1.,.4,-1.),rd,vec3(.4));
    s3= iBox(ro-vec3(1.,.6,-1.),rd,vec3(.3,.4,.3));
    d= opU(  d,  Sub(s2,s3),normal , 9.);

    //POT2= box - sphere
    s2= iBox(ro-vec3(0.,.4,-1.),rd,vec3(.4));
    s3= iSphere(ro-vec3(0.,.8,-1.),rd,.4);
   d= opU(  d,  Sub(s2,s3),normal , 11.);

    //MAGNET=box - box
    s2= iBox(ro-vec3(-1.,.4,-1.),rd,vec3(.4,.4,.2));
    s3= iBox(ro-vec3(-1.,.6,-1.),rd,vec3(.2,.4,.8));
    d= opU(  d,  Sub(s2,s3),normal , 5.);

     if(dot(rd,normal)>0.) normal=-normal;
    return d;
}

//
// Palette by Íñigo Quílez: 
// https://www.shadertoy.com/view/ll2GD3
//
vec3 pal(in float t, in vec3 a, in vec3 b, in vec3 c, in vec3 d) {
    return a + b*cos(6.28318530718*(c*t+d));
}

float checkerBoard( vec2 p ) {
   return mod(floor(p.x) + floor(p.y), 2.);
}

vec3 getSkyColor( vec3 rd ) {
    vec3 col = mix(vec3(1),vec3(.5,.7,1), .5+.5*rd.y);
    float sun = clamp(dot(normalize(vec3(-.4,.7,-.6)),rd), 0., 1.);
    col += vec3(1,.6,.1)*(pow(sun,4.) + 10.*pow(sun,32.));
    return col;
}

#define LAMBERTIAN 0.
#define METAL 1.
#define DIELECTRIC 2.

float gpuIndepentHash(float p) {
    p = fract(p * .1031);
    p *= p + 19.19;
    p *= p + p;
    return fract(p);
}

void getMaterialProperties(in vec3 pos, in float mat, 
                           out vec3 albedo, out float type, out float roughness) {
    albedo = pal(mat*.59996323+.5, vec3(.5),vec3(.5),vec3(1),vec3(0,.1,.2));

    if( mat < 1.5 ) {            
        albedo = vec3(.25 + .25*checkerBoard(pos.xz * 5.));
        roughness = .75 * albedo.x - .15;
        type = METAL;
    } else {
        type = floor(gpuIndepentHash(mat+.3) * 3.);
        roughness = (1.-type*.475) * gpuIndepentHash(mat);
    }
}

//
// Simple ray tracer
//

float schlick(float cosine, float r0) {
    return r0 + (1.-r0)*pow((1.-cosine),5.);
}
vec3 render( in vec3 ro, in vec3 rd, inout float seed ) {
    vec3 albedo, normal, col = vec3(1.); 
    float roughness, type;

    for (int i=0; i<PATH_LENGTH; ++i) {    
    	vec3 res = worldhit( ro, rd, vec2(.0001, 100), normal );
		if (res.z > 0.) {
			ro += rd * res.y;

            getMaterialProperties(ro, res.z, albedo, type, roughness);

            if (type < LAMBERTIAN+.5) { // Added/hacked a reflection term
                float F = FresnelSchlickRoughness(max(0.,-dot(normal, rd)), .04, roughness);
                if (F > hash1(seed)) {
                    rd = modifyDirectionWithRoughness(normal, reflect(rd,normal), roughness, seed);
                } else {
                    col *= albedo;
			        rd = cosWeightedRandomHemisphereDirection(normal, seed);
                }
            } else if (type < METAL+.5) {
                col *= albedo;
                rd = modifyDirectionWithRoughness(normal, reflect(rd,normal), roughness, seed);            
            } else { // DIELECTRIC
                vec3 normalOut, refracted;
                float ni_over_nt, cosine, reflectProb = 1.;
                if (dot(rd, normal) > 0.) {
                    normalOut = -normal;
            		ni_over_nt = 1.4;
                    cosine = dot(rd, normal);
                    cosine = sqrt(1.-(1.4*1.4)-(1.4*1.4)*cosine*cosine);
                } else {
                    normalOut = normal;
                    ni_over_nt = 1./1.4;
                    cosine = -dot(rd, normal);
                }

	            // Refract the ray.
	            refracted = refract(normalize(rd), normalOut, ni_over_nt);

        	    // Handle total internal reflection.
                if(refracted != vec3(0)) {
                	float r0 = (1.-ni_over_nt)/(1.+ni_over_nt);
	        		reflectProb = FresnelSchlickRoughness(cosine, r0*r0, roughness);
                }

                rd = hash1(seed) <= reflectProb ? reflect(rd,normal) : refracted;
                rd = modifyDirectionWithRoughness(-normalOut, rd, roughness, seed);            
            }
        } else {
            col *= getSkyColor(rd);
			return col;
        }
    }  
    return vec3(0);
}

mat3 setCamera( in vec3 ro, in vec3 ta, float cr ) {
	vec3 cw = normalize(ta-ro);
	vec3 cp = vec3(sin(cr), cos(cr),0.0);
	vec3 cu = normalize( cross(cw,cp) );
	vec3 cv =          ( cross(cu,cw) );
    return mat3( cu, cv, cw );
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ) {
    bool reset = iFrame == 0;

    vec2 mo = iMouse.xy == vec2(0) ? vec2(.125) : 
              abs(iMouse.xy)/iResolution.xy - .5;

    vec4 data = texelFetch(iChannel0, ivec2(0), 0);
    if (round(mo*iResolution.xy) != round(data.yz) || round(data.w) != round(iResolution.x)) {
        reset = true;
    }

    vec3 ro = vec3(+2.5*cos(1.5+6.*mo.x), 1.+2.*mo.y, +2.5*sin(1.5+6.*mo.x));
    vec3 ta = vec3(0.,0.,0.);
    mat3 ca = setCamera(ro, ta, 0.);    
    vec3 normal;

    float fpd = data.x;
    if(all(equal(ivec2(fragCoord), ivec2(0)))) {
        // Calculate focus plane.
        float nfpd = worldhit(ro, normalize(vec3(.0,0.4,0)-ro), vec2(0, 100), normal).y;
		fragColor = vec4(nfpd, mo*iResolution.xy, iResolution.x);
    } else { 
        vec2 p = (-iResolution.xy + 2.*fragCoord - 1.)/iResolution.y;
        float seed = float(baseHash(floatBitsToUint(p - iTime)))/float(0xffffffffU);

        // AA
        p += 2.*hash2(seed)/iResolution.y;
        vec3 rd = ca * normalize( vec3(p.xy,1.6) );  

        // DOF
        vec3 fp = ro + rd * fpd;
        ro = ro + ca * vec3(randomInUnitDisk(seed), 0.)*.02;
        rd = normalize(fp - ro);

        vec3 col = render(ro, rd, seed);

        if (reset) {
           fragColor = vec4(col, 1);
        } else {
           fragColor = vec4(col, 1) + texelFetch(iChannel0, ivec2(fragCoord), 0);
        }
    }
}

// thanks to cornusammois for the rotation :)
// thanks to unbird, for removing the normalize in cubemap

// permutation trick for normal calculus based on classic differential way
#define E (n=n.zxy, d(p+n)-d(p-n))

// sphere with radius 2. and some texture displace, illusion of sphere rotation and shape
#define d(p) (length(p) - 2. + texture(iChannel1, (p+iTime/5.).xy).x*.01)

// other with better shape for 276c :
//#define d(p) (length(p) - 2. + textureLod(iChannel1, (p).xy/5.+iTime/15.,1.).x*.1)

void mainImage( out vec4 f, vec2 g )
{
    vec3 
        n = iResolution,					// screensize, normal variable
    	r = normalize(vec3(g+g-n.xy,n.y)),	// ray direction
    	p = n -= n;							// ray origin at zero, normal reset to zero

    p.z -= 3.;								// ray origin at -3 along z axis

    //for (int i=99;i-->0;p+=r*d(p));		// webgl2 form of for loop with included sphere tracing iteration
    for(int i=99;i>0;i--)
    	p+=r*d(p);

    n.z=.01;								// normal precision

    f = texture(iChannel0,vec3(E,E,E));		// cubemap lookup with calculated normal
}

#define PI 3.14159265359
#define DEG_TO_RAD PI / 180.0

// configure
#define AA 4
#define TEXTURE 1
#define NORMAL_BUMP 1

// math
mat2 rot2( float angle ) {
	float c = cos( angle );
	float s = sin( angle );

	return mat2(
		 c, s,
		-s, c
	);
}

// rotate over the xy plane
mat3 rot3xy( vec2 angle ) {
	vec2 c = cos( angle );
	vec2 s = sin( angle );

	return mat3(
		c.y      ,  0.0, -s.y,
		s.y * s.x,  c.x,  c.y * s.x,
		s.y * c.x, -s.x,  c.y * c.x
	);
}

float sqr(float x) {
    return x * x;
}

// distance functions
float sdPlane(vec3 v) {
    return v.y;
}

float sdBox( vec3 v, vec3 size, float r ) {
	return length( max( abs( v ) - size, 0.0 ) ) - r;
}

float sdSphere(vec3 v, float r) {
    return length(v) - r;
}

vec2 scene(vec3 v) {
	// sphere
	float sphere = sdSphere( v - vec3(0.0, 0.4, 0.0), 2.7 );

	// box
	v.xz = rot2( v.y ) * v.xz;
	float box = sdBox( v - vec3(0.0, 0.4, 0.0), vec3( 2.0, 2.0, 2.0 ), 0.05 );

    // blend sphere and the box
	return vec2(min( sphere, box ),1.0);
}

// gets the direction of the camera through the pixel coordinates
vec3 rayDir(float fov, vec2 size, vec2 pos) {
    // get the xy between -1 and 1;
    vec2 xy = pos - size * 0.5;

    float halfFov = tan( (90.0 - fov * 0.5) * DEG_TO_RAD);
    float z = size.y * 0.5 * halfFov;

    return normalize( vec3(xy, -z));
}

// basic raymarching
vec2 rayMarching(vec3 origin, vec3 direction) {
    const float NEAR_CLIPPING_PLANE = 0.1;
	const float FAR_CLIPPING_PLANE = 100.0;
	const int MAX_MARCH_STEPS = 64;
    const float DISTANCE_BIAS = 0.4;
	const float EPSILON = 0.01;

    float t = NEAR_CLIPPING_PLANE;
    float material = -1.0;

    for( int i=0; i < MAX_MARCH_STEPS; i++ )
    {
	    vec2 hit = scene( origin + direction * t );
        if( hit.x < EPSILON || t > FAR_CLIPPING_PLANE) break;
        t += hit.x * DISTANCE_BIAS;
	    material= hit.y;
    }

    if( t > FAR_CLIPPING_PLANE ) material = -1.0;
    return vec2(t, material);
}

// takes the absolutes of the dot product (since we are between -1 and 1)
float minMax(float d) {
    return max(abs(d),0.0001);
}

// calculate micro normal of p on the scene
vec3 normal(vec3 p, float smoothness)
{	
    // From https://www.shadertoy.com/view/MdSGDW
	vec3 n;
	vec2 dn = vec2(smoothness, 0.0);
	n.x	= scene(p + dn.xyy).x - scene(p - dn.xyy).x;
	n.y	= scene(p + dn.yxy).x - scene(p - dn.yxy).x;
	n.z	= scene(p + dn.yyx).x - scene(p - dn.yyx).x;
	return normalize(n);
}


// Ashikmin-Shirely BRDF function
vec3 brdf(vec3 p, vec3 n, vec3 eye, vec3 lightPos, vec3 lightCol, vec3 mat) {
    vec3 k1 = normalize(lightPos - p);
    vec3 k2 = normalize(eye - p);
    vec3 h = normalize(k1 + k2);
    vec3 u = cross(n, vec3(1.0,0.0,0.0));
    vec3 v = cross(n, u);
    u = normalize(u);
    v = normalize(v);

    // You can tweak n_u,n_v,Rs and the normal bump map 
    // to get different material metal look.
    float n_u = 10.0;
    float n_v = 100.0;

    float nDoth = minMax(dot(n,h));
    float nDotk1 = minMax(dot(n,k1));
    float nDotk2 = minMax(dot(n,k2));
    float hDotu = minMax(dot(h,u));
    float hDotv = minMax(dot(h,v));
    float hDotn = minMax(dot(h,n));
    float hDotk = minMax(dot(h,k1));

    vec3 Rs = vec3(0.1);
    vec3 Rd =  mat * lightCol;

    // fresnal
    vec3 F = Rs + (vec3(1.0) - Rs) * pow(1.0 - hDotk, 5.0);

    // specular
    float specExp = (n_u * sqr(hDotu) + n_v * sqr(hDotv)) / (1.0 - sqr(hDotn));
    vec3 spec = (sqrt((n_u + 1.0) * (n_v + 1.0)) / 8.0 * PI) *
        (pow(nDoth, specExp) / (hDotk * max(nDotk1, nDotk2))) * F;

    // diffuse
    vec3 diff = ((28.0 * Rd) / (23.0 * PI)) *
        (vec3(1.0) - Rs) *
        (1.0 - pow(1.0 - 0.5 * nDotk1, 5.0)) *
        (1.0 - pow(1.0 - 0.5 * nDotk2, 5.0));

    diff *= 2.0;

    return diff + spec;
}

// Calculates the color at the given position with the normal, eye position and material color
// for every light there is.
vec3 shading(vec3 p, vec3 n, vec3 eye, vec3 mat) {
	vec3 final = vec3( 0.0 );	
	mat3 rot = rot3xy( vec2( -DEG_TO_RAD*30.0, iTime * 0.5 ) );

	// light 0
	{
		vec3 light = vec3( 2.0, 5.0, 2.0 );
		vec3 lightColor = vec3( 0.4, 0.6, 0.8 );

		final += brdf(p,n,eye,light,lightColor,mat);
	}

	// light 1
	{
		vec3 light = vec3( -3.0, 7.0, -3.0 );
		vec3 lightColor = vec3( 0.8, 0.5, 0.3 );

		final += brdf(p,n,eye,light,lightColor,mat);
	}

	return final;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec3 totalColor = vec3(0.0);
    for( int m=0; m<AA; m++ )
    for( int n=0; n<AA; n++ )
    {
        vec2 offset = vec2(float(m),float(n)) / float(AA) - 0.5;

        vec3 dir = rayDir(45.0, iResolution.xy + offset, fragCoord.xy);

        vec3 color = vec3(0.7) + dir.y * 0.72;

        vec3 eye = vec3(0.0,0.0,10.0);

        // rotate camera
        mat3 rot = rot3xy( vec2( -DEG_TO_RAD*30.0, iTime * 0.5 ) );
        dir = rot * dir;
        eye = rot * eye;

        vec2 hit = rayMarching(eye, dir);
        float depth = hit.x;

        // if hit
        if (hit.y == 1.0) {
            vec3 p = eye + dir * depth;
            vec3 n = normal(p, 0.1);

            #if TEXTURE
            // material color from texture
            float u = atan(n.z, n.x) / PI*2.0;
            float v = asin(n.y) / PI*2.0 + 0.5;
            vec3 mat = texture( iChannel0, vec2(u,v)).xyz;
            #else
            vec3 mat = vec3(0.6);
            #endif

            #if TEXTURE&&NORMAL_BUMP
            // bumbmapping
            float maxVariance = 2.0; 
            float minVariance = maxVariance / 6.0;
            n += normalize(mat * maxVariance - minVariance);
			#endif 

            color = shading(p,n,eye,mat); 
        }
        totalColor += color;
    }

    totalColor /= float(AA*AA);

    fragColor = vec4(totalColor, 1.0);        
}

// IMAGE-BASED LIGHTING OF CUSTOM MATERIALS
// Alexis THIBAULT - 09/2020


#define MIN_BLUR 1.
#define MAX_BLUR 64.
#define GAMMA 2.2




// The material model is inspired from
// https://blog.selfshadow.com/publications/s2013-shading-course/karis/s2013_pbs_epic_notes_v2.pdf
// "Metallic" and "roughness" range from 0 to 1 and are
// approximately perceptually linear.
struct Material
{
    vec3 baseColor;
    float metallic;
    float roughness;
};

const vec3 DIELECTRIC_F0 = vec3(0.04);

// Some examples of materials
const Material CHROME = Material(vec3(0.9,0.92,0.95), 1.0, 0.0);
const Material RED_PLASTIC = Material(vec3(0.95,0.3,0.2), 0.0, 0.1);
const Material RED_METAL = Material(vec3(0.95,0.3,0.2), 1.0, 0.2);
const Material BLUE_GRIME = Material(vec3(0.0,0.4,0.7), 0.0, 1.0);
const Material BLACK_PLASTIC = Material(vec3(0), 0.0, 0.0);
const Material GREEN_PLASTIC = Material(vec3(0.2,0.9,0.2), 0.0, 0.6);

// Materials can be blended together, e.g. for layering.
Material matmix(Material a, Material b, float x)
{
    return Material(mix(a.baseColor, b.baseColor, x),
                    mix(a.metallic, b.metallic, x),
                    mix(a.roughness,  b.roughness, x));
}

// Image-based lighting trick by reinder:
// To approximate the integrated specular lobe in
// environment maps, we can use them with
// varying levels of detail.
// https://www.shadertoy.com/view/lscBW4
vec3 getSpecularLightColor( vec3 rd, float roughness )
{
    roughness = clamp(roughness, 0.0, 1.0);
    float lod = log2(mix(MIN_BLUR, MAX_BLUR, roughness));
    // The large cubemap does not capture well high-intensity lights,
    // so mix it with the small version.
    vec3 t0 = pow(textureLod(iChannel0, rd.xzy, lod).rgb, vec3(GAMMA));
    vec3 t1 = pow(textureLod(iChannel1, rd.xzy, lod).rgb, vec3(GAMMA));
    vec3 col = mix(t0, t1, roughness);
    // White balance
    vec3 wb = pow(vec3(205.,159.,147.)/255.,vec3(-GAMMA));
    return 3.0*wb*col;
}

vec3 getDiffuseLightColor( vec3 rd )
{
    // So yeah, we don't really have a diffuse model
    return getSpecularLightColor(rd, 1.0);
}


float map(vec3 p);

// Ambient Occlusion computation stolen from iq
// https://www.shadertoy.com/view/Xds3zN
float calcAO( in vec3 pos, in vec3 nor )
{
	float occ = 0.0;
    float sca = 1.0;
    for( int i=0; i<5; i++ )
    {
        float h = 0.01 + 0.12*float(i)/4.0;
        float d = map( pos + h*nor );
        occ += (h-d)*sca;
        sca *= 0.95;
        if( occ>0.5 ) break;
    }
    return clamp( 1.0 - 2.0*occ, 0.0, 1.0 ) * (0.5+0.5*nor.z);
}


vec3 renderMaterial( vec3 p, vec3 rd, vec3 normal, Material mat )
{
    vec3 diffuseBaseColor = mix(mat.baseColor, vec3(0), mat.metallic);
    vec3 diffuseCol = getDiffuseLightColor(normal) * diffuseBaseColor;
    vec3 specularCol = getSpecularLightColor(reflect(rd, normal), mat.roughness);
    vec3 F0 = mix(DIELECTRIC_F0, mat.baseColor, mat.metallic);
    vec3 fre = F0 + (1.0-F0)*pow(clamp(1.0-dot(-rd,normal),0.0,1.0), 5.0);
    vec3 col = mix(diffuseCol, specularCol, fre);

    // Add ambient occlusion for more convincing lighting
    // (bouncing rays would be better)
    float ao = calcAO(p, normal);
    return col*ao;
}


float map( vec3 p )
{
    p.xy = mod(p.xy+0.5, 1.0)-0.5;
    float d = length(p)-0.4;
    d = min(d, p.z+0.41);
	return d;
}

float bump( vec3 p )
{
    if(p.z > -0.4)// && mod(p.x-0.5, 2.0) < 1.0)
        return 0.;
    p = vec3(p.x+p.z, sqrt(2.)*p.y, p.x-p.z);
    p = vec3(p.x+p.y, p.x-p.y, sqrt(2.)*p.z);
    p = fract(p*4.);
    float d = length(p - 0.5);
    d = d*d;
    return -d*0.002;
}

float bumpMap( vec3 p )
{
    return map(p) - bump(p);
}


vec3 calcNormal( vec3 p, float eps )
{
    //float eps = 1e-3;
    vec2 e = eps*vec2(1,-1);
    return normalize(
          e.xxx*bumpMap(p+e.xxx)
        + e.xyy*bumpMap(p+e.xyy)
        + e.yxy*bumpMap(p+e.yxy)
        + e.yyx*bumpMap(p+e.yyx));
}


Material getMaterial( vec3 p )
{

    Material mat;

    mat = Material(vec3(0.5),0.,0.);
    mat.metallic = 1.0-step(0.0,p.y);
    mat.roughness = smoothstep(-3.0,3.0,p.x);
    return mat;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (2.0*fragCoord.xy - iResolution.xy)/iResolution.x;

    float th = iTime * 0.2;
    vec3 ro = vec3(4.0*sin(th), -4.0*cos(th), 3.0+2.0*sin(th*1.618));
    //vec3 ro = vec3(0.0,-3.0+2.0*sin(th),6.0 + 2.0*cos(th));
    vec3 target = vec3(0);
    vec3 camFwd = normalize(target-ro);
    vec3 camRight = normalize(cross(camFwd, vec3(0,0,1)));
    vec3 camUp = cross(camRight, camFwd);
    float fov = 0.5;
    vec3 rd = normalize(camFwd + fov*(uv.x*camRight + uv.y * camUp));

    vec3 col;

    float d;
    float t=0.0;
    for(int i=0;i<256;i++)
    {
        d = map(ro+t*rd);
        if(d < 0.001 || t > 100.) break;
        t += d;
    }

    if(t < 100.)
    {
        vec3 p = ro+t*rd;
        vec3 normal = calcNormal(p, 0.001);
        Material mat = getMaterial(p);
        col = renderMaterial(p, rd, normal, mat);
    }
    else
    {
        // We didn't hit anything, return world color
        col = getSpecularLightColor(rd, 0.0);
    }

    col = pow(col, vec3(1.0/GAMMA));

    // Output to screen
    fragColor = vec4(col,1.0);
}

