const int SPH = 27; //3x3x3

vec4 sphere[SPH];
vec4 L;

vec3 rand3( float x, float seed )
{ 
  float f = x+seed;
  return fract( PI*sin( vec3(f,f+5.33,f+7.7)) );
}

float areaShadow( in vec3 P )
{
  float s = 1.0;
  for( int i=0; i<SPH; i++ )
    s = min( s, sphAreaShadow(P, L, sphere[i] ) );
  return s;           
}

vec3 reflections( vec3 P, vec3 R, vec3 tint, int iid )
{
  float t = 1e20;

  vec3 s = vec3(R.y < 0. ? 1.-sqrt(-R.y/(P.y+1.)) : 1.); // P.y+1 floor pos
  for( int i=0; i<SPH; i++ )
  {    
    float h = sphIntersect( P, R, sphere[i] );
    if( h>0.0 && h<t )
    {
      s = i == iid ? tint * 2. : vec3(0.);
      t = h;
    }
  }     
  return max( vec3(0.), s);           
}

float occlusion( vec3 P, vec3 N )
{
  float s = 1.0;
  for( int i=0; i<SPH; i++ )
    s *= 1.0 - sphOcclusion( P, N, sphere[i] ); 
  return s;           
}

float sphLight( vec3 P, vec3 N, vec4 L)
{
  vec3 oc = L.xyz  - P;
  float dst = sqrt( dot( oc, oc ));
  vec3 dir = oc / dst;

  float c = dot( N, dir );
  float s = L.w  / dst;
  return max(0., c * s);
}

//-------------------------------------------------------------------------------------------

vec3 shade( vec3 I, vec3 P, vec3 N, float id, float iid )
{
  vec3 base = rand3( id, SEED );
  vec3 wash = mix( vec3(0.9), base, 0.4);
  vec3 hero = rand3( iid, SEED );

  vec3 ref = reflections( P, I - 2.*(dot(I,N))*N, hero, int(iid) );
  float occ = occlusion( P, N );
  float ocf = 1.-sqrt((0.5 + 0.5*-N.y)/(P.y+1.25))*.5; //floor occusion. 1.25 floor P.
  float fre = clamp(1. + dot(I, N), 0., 1.); fre = (0.01+0.2*pow(fre,3.5));
  vec3 dir = -(L.xyz  - P);
    float len = dot(dir, dir);
    dir = normalize(dir);
  float thickness = abs(dot(I, N));
  float sub = subsurface(dir, N, I, 0.5 - thickness * 0.3);
  float lgh = sphLight( P, N, L)  *  areaShadow( P );
  float inc = ( id == iid ? 1.0 : 0.0 );


  // Env light
  vec3 C = vec3(1., 1., 1.) * occ * ocf * 0.5;
  // C = vec3(0., 0., 0.);
  // subsurface
  if( id>-0.5 )
  {
      inc += sub / len * 3.;
  }
  // Sphere light
  C += ( inc + lgh * 1.3 ) * hero;


  // Reflections
  C = mix( C, ref, fre );

  return C;
}    

vec3 trace( vec3 E, vec3 I, vec3 C, float px, float iid )
{
  float t = 1e20;
  float id  = -1.0;
  vec4  obj = vec4(0.);
  for( int i=0; i<SPH; i++ )
  {
    vec4 sph = sphere[i];
    float h = sphIntersect( E, I, sph ); 
    if( h>0.0 && h<t ) 
    {
      t = h;
      obj = sph;
      id = float(i);
    }
  }

  if( id>-0.5 )
  {
    vec3 P = E + t*I;
    vec3 N = normalize(P-obj.xyz);
    C = shade( I, P, N, id, iid  );
  }

  return C;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 q = fragCoord.xy / iResolution.xy;
    vec2 p = (2.0*fragCoord.xy-iResolution.xy)/iResolution.y;
    vec2 m = step(0.0001,iMouse.z) * iMouse.xy/iResolution.xy;

    //-----------------------------------------------------

    float time = iTime;
    float an = 0.3*time - 7.0*m.x;
    float sec = mod(time,1.);

    float spI = floor(mod(time,float(SPH)));
    // float spI = 
    //-----------------------------------------------------
    for( int i=0; i<SPH; i++ )
    {
      float ra = 0.4;
      float id = float(i);
      sphere[i] = vec4( mod( id, 3.0) - 1.0,
                        mod( floor( id/3.0 ), 3.0 ) - .55,
                        floor( id/9.0 )-1.0, ra );

      if( i == int(spI) )
      {
        sphere[i].w += 0.025 * sin(sec*50.) / sqrt(sec) * ( 1.-sqrt(sec));
        L = sphere[i];
      }
    }

    //-----------------------------------------------------

    float fov = 1.8;
    vec3 E = vec3( 3.5*sin(an), 2.0, 3.5*cos(an));
    vec3 V = normalize( -E );
    vec3 uu = normalize( cross( V, vec3(0., 1., 0.)));
    vec3 vv = normalize( cross( uu, V));
    vec3 I = normalize( p.x*uu + p.y*vv + fov*V );

    float px = 1.0*(2.0/iResolution.y)*(1.0/fov);


    //-----------------------------------------------------

    vec3 C = vec3(1.);

    float tmin = 1e20;
    float t = -(1.0+E.y)/I.y;
    if( t>0.0 )
    {
        tmin = t;
        vec3 pos = E + t*I;
        vec3 nor = vec3(0.0,1.0,0.0);
        C = shade( I, pos, nor, -1.0, spI );
    }    

    C = trace( E, I, C, px, spI );

    // post
    C = pow( C, vec3(0.41545) );   
    C *= 0.5 + 0.5*pow(18.0*q.x*q.y*(1.0-q.x)*(1.0-q.y),0.12);

    fragColor = vec4( C, 1. );
}

#define MAX_STEPS 1000
#define MAX_DIST 1000.
#define SURF_DIST .01
#define saturate(x) clamp(x, 0.0, 1.0)
#define rcp(x) 1.0 / (x)
#define PI 3.14159265359

float dot2( in vec2 v ) { return dot(v,v); }// 二维向量模长
float dot2( in vec3 v ) { return dot(v,v); }// 三维向量模长
float ndot( in vec2 a, in vec2 b ) { return a.x * b.x - a.y * b.y; }
float Pow4( float x ) { float xx = x * x; return xx * xx; }
float Pow5( float x ) { return Pow4(x) * x; }

vec3 lerp( vec3 a, vec3 b, float c)
{
    float x = mix(a.x, b.x, c);
    float y = mix(a.y, b.y, c);
    float z = mix(a.z, b.z, c);
    return vec3(x, y, z);
}

/////////////////////SDF/////////////////////

float sdPlane(vec3 p) { return p.y; }

float dSphere(vec3 p, vec3 o, float radius) { return length(p - o.xyz) - radius; }

vec2 opUnion(vec2 d1, vec2 d2) {
    return d1.x < d2.x ? d1 : d2;
}

// 场景
vec2 GetDist(vec3 p)
{
    float planeDist = sdPlane(p);// ground

    // 遍历形式所有物体 物体摆放
    float sd = dSphere(p, vec3(0, 1, 3), 1.25);
    vec2 hit = opUnion(vec2(planeDist, 0), vec2(sd, 1));

    return hit;
}

vec2 RayMarch(vec3 ro, vec3 rd)
{
    float dO = 0.;
    float MaterialID = 0.0;

    for(int i = 0; i < MAX_STEPS; i++){
        vec3 p = ro + rd * dO;
        vec2 dS = GetDist(p);
        dO += dS.x;
        MaterialID = dS.y;
        if (dO > MAX_DIST || dS.x < SURF_DIST) break;     
    }

    return vec2(dO, MaterialID);
}

vec3 GetNormal(vec3 p)
{
    float d = GetDist(p).x;
    vec2 e = vec2(.01,0);

    vec3 n = d - vec3(
        GetDist(p - e.xyy).x,
        GetDist(p - e.yxy).x,
        GetDist(p - e.yyx).x);
    return normalize(n);
}

float GetLight(vec3 p, vec3 lightPos)
{
    vec3 l = normalize(lightPos - p);
    vec3 n = GetNormal(p);

    float dif = clamp(dot(n,l),0.,1.);
    float d = RayMarch(p + n * SURF_DIST * 2.,l).x;
    if(d < length(lightPos - p)) dif*=.1;

    return dif;
}

float GetShadow(vec3 P, vec3 LightPos)
{
    vec3 L = normalize(LightPos - P);
    vec3 N = GetNormal(P);

    float Shadow = 1.0;
    float Dist = RayMarch(P + N * SURF_DIST * 2., L).x;
    if(Dist < length(LightPos - P)) Shadow = 0.0;

    return Shadow;
}

/////////////////////BSDF/////////////////////

// GGX / Trowbridge-Reitz
// [Walter et al. 2007, "Microfacet models for refraction through rough surfaces"]
float D_GGX( float a2, float NoH )
{
	float d = ( NoH * a2 - NoH ) * NoH + 1.0;	// 2 mad
    return a2 / ( PI * d * d );					    // 4 mul, 1 rcp
}

// Appoximation of joint Smith term for GGX
// [Heitz 2014, "Understanding the Masking-Shadowing Function in Microfacet-Based BRDFs"]
float Vis_SmithJointApprox( float a2, float NoV, float NoL )
{
	float a = sqrt(a2);
	float Vis_SmithV = NoL * ( NoV * ( 1.0 - a ) + a );
	float Vis_SmithL = NoV * ( NoL * ( 1.0 - a ) + a );
	return 0.5 * rcp( Vis_SmithV + Vis_SmithL );
}

// [Schlick 1994, "An Inexpensive BRDF Model for Physically-Based Rendering"]
vec3 F_Schlick( vec3 SpecularColor, float VoH )
{
	float Fc = Pow5( 1.0 - VoH );				// 1 sub, 3 mul
	//return Fc + (1 - Fc) * SpecularColor;		  // 1 add, 3 mad

	// Anything less than 2% is physically impossible and is instead considered to be shadowing
	return saturate( 50.0 * SpecularColor.y ) * Fc + (1.0 - Fc) * SpecularColor;
}

float DielectricSpecularToF0(float Specular)
{
	return 0.08f * Specular;
}

vec3 ComputeF0(float Specular, vec3 BaseColor, float Metallic)
{
	return lerp(vec3(DielectricSpecularToF0(Specular)), BaseColor, Metallic);
}


/////////////////////Tone mapping and transfer functions/////////////////////

vec3 Tonemap_ACES(const vec3 x)
{
    // Narkowicz 2015, "ACES Filmic Tone Mapping Curve"
    const float a = 2.51;
    const float b = 0.03;
    const float c = 2.43;
    const float d = 0.59;
    const float e = 0.14;
    return (x * (a * x + b)) / (x * (c * x + d) + e);
}

vec3 OECF_sRGBFast(const vec3 linear)
{
    return pow(linear, vec3(1.0 / 2.2));
}

