void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // User Control
    vec3 BaseColor = vec3(1.0, 1.0, 1.0);
    float Specular = 0.9f;
    float Roughness = 0.9f;
    float Metalic = 0.9f;

    vec3 Ray0 = vec3(0, 3, 0);// CameraPos
    vec3 LightPos = vec3(0, 3, 1);
    //LightPos.xz += vec2(sin(iTime), cos(iTime)) * 2.;
    LightPos.x += sin(iTime) * 2.5;// Time varying pixel color

    // Normalized pixel coordinates (from 0 to 1)
    vec2 UV = (fragCoord - .5 * iResolution.xy) / iResolution.y;

    // RayTracing
    vec3 RayDir = normalize(vec3(UV.x, UV.y -.3, .35));// cameraDir
    vec2 Dist = RayMarch(Ray0, RayDir);   
    vec3 Pos = Ray0 + RayDir * Dist.x;

    // BSDF
    vec3 N = GetNormal(Pos);
    vec3 V = normalize(Ray0 - Pos);
    vec3 L = normalize(LightPos - Pos);
    vec3 H = normalize(L + V);

    float NoV = abs(dot(N, V)) + 1e-5;
    float NoL = saturate(dot(N, L));
    float NoH = saturate(dot(N, H));
    float LoH = saturate(dot(L, H));
    float VoH = saturate(dot(V, H));

    float a2 = Pow4(Roughness);

    float D = D_GGX(a2, NoH);

    float G = Vis_SmithJointApprox(a2, NoV, NoL);

    // Diffuse
    vec3 DiffuseColor = BaseColor - BaseColor * Metalic;
    vec3 LightingDiffuse = DiffuseColor * (1.0 / PI);// Diffuse_Lambert

    // Specular
    vec3 SpecularColor = ComputeF0(Specular, BaseColor, Metalic);
    vec3 F = F_Schlick(SpecularColor, VoH);

    vec3 LightingSpecular = vec3(G);//D * G * F;

    vec3 FinalColor = LightingSpecular;// + LightingDiffuse;

    float MaterialID = Dist.y;
    if (MaterialID < 1.0)
        FinalColor = vec3(0.3);

    // Shadow
    float Shadow = GetShadow(Pos, LightPos);
    FinalColor *= Shadow;

    // Tone mapping
    FinalColor = Tonemap_ACES(FinalColor);

    // Exponential distance fog
    //color = mix(color, 0.8 * vec3(0.7, 0.8, 1.0), 1.0 - exp2(-0.011 * distance * distance));

    // Gamma compression
    FinalColor = OECF_sRGBFast(FinalColor);

    // Output to screen
    fragColor = vec4(FinalColor, 1.0);
}

#define rot(a)  mat2(cos(a+vec4(0,11,33,0)))                       // rotation
#define rB      length(max(a,0.)) + min(max(a.x,max(a.y,a.z)),0.)  // round cube https://iquilezles.org/articles/distfunctions
#define C(r,l)  max( length(q.xy) - r, a.z-l )                     // cylinder
float h;                                                           // material id

float map( vec3 q) {               // --- scene SDF
    vec3 a = abs(q) - vec3(1,1,0);                                 // glass part
    float t = rB - 1., c,b,j;
    q.xy -= .5,
    c = min(q.x, j=.5*q.x+q.y),
    t = h = max(t, -c );

    t = min(t, length(q-vec3(-.2,.5,0)) - 1. );                    // rear part

    a = abs(q) - vec3(.5,.5,0),                                    // top & jow arch
    b = rB - 1.1;
    b = max( b, abs(c)-.15 );
    a.x+=.2; b = min( b, max(rB-1., j-.8 ) );                      // rear arch
    q -= vec3(-.2,.1,0);
    b = min(b, C(.7,1.1 ) );                                       // ears
    b = min(b, c = max( abs(length(q.xy)-.45)-.05,a.z-1.2) );
    b = min(b, max(C(.5,1.2), abs(j+.05)-.1));
    q.y-=.08; b = min(b, C(.2,1.2) );
    t = min( t,b );
    t = max( t, -min(j+.15, rB-.95) );
    return t;
}

void M(out vec4 O, vec2 U)       // --- mainImage, oversampled below
{
    float t=9.,_h;                                                 // hit object id 
    vec3  R = iResolution, e = vec3(-1,1,1)*1e-3, N,
          D = normalize(vec3(U+U, -3.5*R.y) - R),                  // ray direction
          p = 9./R, q,                                             // marching point along ray 
          M = iMouse.z > 0. ? iMouse.xyz/R -.5: vec3(20,8,0)/1e2*cos(.3*iTime+vec3(0,11,0)); // auto thumbnail

    for (O=vec4(1); O.x > 0. && t > .01; O-=.01)
        q = p,
        q.yz *= rot(.5-6.*M.y),                                    // rotations
        q.xz *= rot(2.-6.*M.x), 
        t = map(q),
        p += .5*t*D;                                               // step forward = dist to obj

    _h=h;                                                          // normal
    N = normalize( vec3( map(q+e.xyy)/e.xyy + map(q+e.yxy)/e.yxy + map(q+e.yyx)/e.yyx + map(q+e.xxx)/e.xxx ));
    N.xz *= rot(-2.+6.*M.x);
    N.yz *= rot(-.5+6.*M.y);                                       // back to cam space

    if (t>=.01) return;
  //O = vec4(dot(N,vec3(1,1,1))/1.7);
    O = texture(iChannel0, reflect(D,N));                          // reflection map
    t==_h ? O *= 10.*mix(pow(1.+dot(D,N),5.),1., .03)              // glass: Fresnel ( Schlick approx )
          : O *= 2.*vec4(1,.8,.4,1);                               // metal: gold
}




// === easy adaptive sampling. === https://shadertoyunofficial.wordpress.com/2021/03/09/advanced-tricks/
//                           more: https://www.shadertoy.com/results?query=easy+adaptive+sampling
void mainImage(out vec4 O, vec2 U) {
    M(O,U);
    if ( fwidth(length(O)) > .01 ) {  // difference threshold between neighbor pixels
        vec4 o;
        for (int k=0; k < 9; k+= k==3?2:1 )
          { M(o,U+vec2(k%3-1,k/3-1)/3.); O += o; }
        O /= 9.;
     // O.r++;                        // uncomment to see where the oversampling occurs
    }
}

// ray marching
const int max_iterations = 255;
const float stop_threshold = 0.001;
const float grad_step = 0.1;
const float clip_far = 1000.0;

// math
const float PI = 3.14159265359;
const float DEG_TO_RAD = PI / 180.0;

// distance function
float dist_sphere( vec3 pos, float r ) {
	return length( pos ) - r;
}

float dist_box( vec3 pos, vec3 size ) {
	return length( max( abs( pos ) - size, 0.0 ) );
}

// get distance in the world
float dist_field( vec3 pos ) {
	// ...add objects here...

	// object 0 : sphere
	float d0 = dist_sphere( pos, 2.7 );

	// object 1 : cube
	float d1 = dist_box( pos, vec3( 2.0 ) );

	// union     : min( d0,  d1 )
	// intersect : max( d0,  d1 )
	// subtract  : max( d1, -d0 )
	return max( d1, -d0 );
}

// gouraud shading
vec3 g_shading(vec3 v, vec3 n, vec3 eye)
{
    vec3 final = vec3(0.0);

	vec3 ev = normalize( v - eye );
	vec3 ref_ev = reflect( ev, n );

	// light 0
    {
		vec3 light_pos   = vec3( 20.0, 20.0, 20.0 );
		vec3 light_color = vec3( 1.0, 0.7, 0.7 );

        float dist = length(light_pos - v);

        vec3 light_vec = normalize(light_pos - v);

        float diffuse = max(dot(n, light_vec), 0.1);
        float specular = max(dot(ref_ev, light_vec), 0.1);
        specular = pow(specular, 16.0);

        final += (diffuse + specular) * light_color;
    }

    // light 1
    {
		vec3 light_pos   = vec3( -20.0, -20.0, -20.0 );
		vec3 light_color = vec3( 0.3, 0.7, 1.0 );

        float dist = length(light_pos - v);

        vec3 light_vec = normalize(light_pos - v);

        float diffuse = max(dot(n, light_vec), 0.1);
        float specular = max(dot(ref_ev, light_vec), 0.1);
        specular = pow(specular, 16.0);

        final += (diffuse + specular) * light_color;
    }

    return final;
}

// phong shading
vec3 p_shading( vec3 v, vec3 n, vec3 eye ) {
	// ...add lights here...

	float shininess = 16.0;

	vec3 final = vec3( 0.0 );

	vec3 ev = normalize( v - eye );
	vec3 ref_ev = reflect( ev, n );

	// light 0
	{
		vec3 light_pos   = vec3( 20.0, 20.0, 20.0 );
		vec3 light_color = vec3( 1.0, 0.7, 0.7 );

		vec3 vl = normalize( light_pos - v );

		float diffuse  = max( 0.0, dot( vl, n ) );
		float specular = max( 0.0, dot( vl, ref_ev ) );
		specular = pow( specular, shininess );

		final += light_color * ( diffuse + specular ); 
	}

	// light 1
	{
		vec3 light_pos   = vec3( -20.0, -20.0, -20.0 );
		vec3 light_color = vec3( 0.3, 0.7, 1.0 );

		vec3 vl = normalize( light_pos - v );

		float diffuse  = max( 0.0, dot( vl, n ) );
		float specular = max( 0.0, dot( vl, ref_ev ) );
		specular = pow( specular, shininess );

		final += light_color * ( diffuse + specular ); 
	}

	return final;
}

// get gradient in the world
vec3 gradient( vec3 pos ) {
	const vec3 dx = vec3( grad_step, 0.0, 0.0 );
	const vec3 dy = vec3( 0.0, grad_step, 0.0 );
	const vec3 dz = vec3( 0.0, 0.0, grad_step );
	return normalize (
		vec3(
			dist_field( pos + dx ) - dist_field( pos - dx ),
			dist_field( pos + dy ) - dist_field( pos - dy ),
			dist_field( pos + dz ) - dist_field( pos - dz )			
		)
	);
}

// ray marching
float ray_marching( vec3 origin, vec3 dir, float start, float end ) {
	float depth = start;
	for ( int i = 0; i < max_iterations; i++ ) {
		float dist = dist_field( origin + dir * depth );
		if ( dist < stop_threshold ) {
			return depth;
		}
		depth += dist;
		if ( depth >= end) {
			return end;
		}
	}
	return end;
}

// get ray direction
vec3 ray_dir( float fov, vec2 size, vec2 pos ) {
	vec2 xy = pos - size * 0.5;

	float cot_half_fov = tan( ( 90.0 - fov * 0.5 ) * DEG_TO_RAD );	
	float z = size.y * 0.5 * cot_half_fov;

	return normalize( vec3( xy, -z ) );
}

// camera rotation : pitch, yaw
mat3 rotationXY( vec2 angle ) {
	vec2 c = cos( angle );
	vec2 s = sin( angle );

	return mat3(
		c.y      ,  0.0, -s.y,
		s.y * s.x,  c.x,  c.y * s.x,
		s.y * c.x, -s.x,  c.y * c.x
	);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
	// default ray dir
	vec3 dir = ray_dir( 45.0, iResolution.xy, fragCoord.xy );

	// default ray origin
	vec3 eye = vec3( 0.0, 0.0, 10.0 );

	// rotate camera
	mat3 rot = rotationXY( vec2( 0.25 * iTime ) );
    //mat3 rot = rotationXY(vec2(0.25 * iTime, -0.6));
    dir = rot * dir;
	eye = rot * eye;

	// ray marching
	float depth = ray_marching( eye, dir, 0.0, clip_far );
	if ( depth >= clip_far ) {
	    fragColor = vec4( 0.0, 0.0, 0.0, 1.0 );
        return;
	}

	// shading
	vec3 pos = eye + dir * depth;
	vec3 n = gradient( pos );
    fragCoord.xy /= iResolution.xy;

    if (fragCoord.x > 0.5)
    {
		fragColor = vec4( g_shading( pos, n, eye ), 1.0 );
    }
    else
    {
        fragColor = vec4( p_shading( pos, n, eye ), 1.0 );
    }

    if (fragCoord.x > 0.499 && fragCoord.x < 0.501)
    {
    	fragColor = vec4(0.0, 0.0, 0.0, 1.0);
    }
}

