float fbm(in vec3 p, in float repeat, in float scale) {
	float noi = .5  * mnoise(p * 1.00 * scale, scale)
             + .31 * mnoise(p * 2.00 * scale, 2.0 * scale)
             + .21 * mnoise(p * 4.00 * scale, 4.0 * scale);
    noi /= 1.02;
    return noi;    
}


vec3 two2three(in vec2 uv, in vec2 res)
{
    vec2 rr = 8.*floor(res*.125);
    uv *= res/rr;
    float z = .125*floor(uv.y*8.)+0.015625*floor(uv.x*8.);
    vec2 hp = 4./rr;
    vec2 xy = unmix(hp, 1.-hp,fract(uv*8.));
    return vec3(xy, z);
}
vec2 three2two(in vec3 p, in vec2 res, out float partialZ)
{
    float z64 = p.z*64.;
    partialZ = fract(z64);
    float enc = floor(z64)*.125;
    vec2 ints = vec2(fract(enc),.125*floor(enc));    
    vec2 rr = 8.*floor(res*.125);
    vec2 ehp = .5/rr;
    return (rr/res)*(ints+mix(ehp,.125-ehp,p.xy));
}

const float NOISE_SCALE = 3.;

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord/iResolution.xy;
    vec4 pre = texture(iChannel0, uv);
    if (pre.w >= 0. && any(greaterThan(abs(iResolution.xy-pre.zw)*iResolution.xy, vec2(.7))))
    {
        // Res change;
        pre = vec2(0.,-two2three(uv, iResolution.xy).z).xxxy; // We use w to time the reset
    }

    if (pre.w > 0.5) // Already initialized
    {
        fragColor = pre;
        return;
    }

    pre.w -= 69./64.;

    if (pre.w <= -1.)
    {
        vec3 p = two2three(uv, iResolution.xy);
        float noil = fbm(p, NOISE_SCALE, NOISE_SCALE);
        vec3 q = p;
        q.z = fract(q.z + 0.015625);
        float noih = fbm(q, NOISE_SCALE, NOISE_SCALE);
    	fragColor = vec4(noil,noih,iResolution.xy);
    }
    else
        fragColor = vec4(pre.xyzw);
}

