	vec3 screen;
	vec3 ray;
    vec2 moro = vec2 (iTime);

	dir.x = 0.0;
	dir.y = 0.0;
	dir.z = -2.8;

	mat3 rot = rotationXY(moro);
	screen.x = q.x;
	screen.y = q.y;
	screen.z = -2.0;
	ray = screen - dir;


	float s = rm(rot*dir, rot*ray, 1.0, 4.0);

	vec3 col;

	if (s == -1.0) {
				col.x = 0.0;
				col.y = 0.0;
				col.z = 0.0;

	} else {

		col = vec3(s-.8*.8+0.4*q.y *sin(q.x))*marched/1.76;
		col.rg *= marched*.4;
	}

	return col;

	}

