}

float calcAO( in vec3 pos, in vec3 nor )
{
	float occ = 0.0;
    float sca = 1.0;
    for( int i=ZERO; i<5; i++ )
    {
        float h = 0.01 + 0.12*float(i)/4.0;
        float d = map( pos + h*nor ).x;
        occ += (h-d)*sca;
        sca *= 0.95;
        if( occ>0.35 ) break;
    }
    return clamp( 1.0 - 3.0*occ, 0.0, 1.0 ) * (0.5+0.5*nor.y);
}

// https://iquilezles.org/articles/checkerfiltering
float checkersGradBox( in vec2 p, in vec2 dpdx, in vec2 dpdy )
{
    // filter kernel
    vec2 w = abs(dpdx)+abs(dpdy) + 0.001;
    // analytical integral (box filter)
    vec2 i = 2.0*(abs(fract((p-0.5*w)*0.5)-0.5)-abs(fract((p+0.5*w)*0.5)-0.5))/w;
    // xor pattern
    return 0.5 - 0.5*i.x*i.y;                  
}

vec3 render( in vec3 ro, in vec3 rd, in vec3 rdx, in vec3 rdy )
{ 
    // background
    vec3 col = vec3(0.7, 0.7, 0.9) - max(rd.y,0.0)*0.3;

    // raycast scene
    vec2 res = castRay(ro,rd);
    float t = res.x;
	float m = res.y;
    if( m>-0.5 )
    {
        vec3 pos = ro + t*rd;
        vec3 nor = (m<1.5) ? vec3(0.0,1.0,0.0) : calcNormal( pos );
        vec3 ref = reflect( rd, nor );

        // material        
        col = 0.2 + 0.2*sin( m*2.0 + vec3(0.0,1.0,2.0) );
        float ks = 1.0;

        if( m<1.5 )
        {
            // project pixel footprint into the plane
            vec3 dpdx = ro.y*(rd/rd.y-rdx/rdx.y);
            vec3 dpdy = ro.y*(rd/rd.y-rdy/rdy.y);

            float f = checkersGradBox( 3.0*pos.xz, 3.0*dpdx.xz, 3.0*dpdy.xz );
            col = 0.15 + f*vec3(0.05);
            ks = 0.4;
        }

        // lighting
        float occ = calcAO( pos, nor );

		vec3 lin = vec3(0.0);

        // sun
        {
            vec3  lig = normalize( vec3(-0.5, 0.4, -0.6) );
            vec3  hal = normalize( lig-rd );
            float dif = clamp( dot( nor, lig ), 0.0, 1.0 );
        	      dif *= calcSoftshadow( pos, lig, 0.02, 2.5 );
			float spe = pow( clamp( dot( nor, hal ), 0.0, 1.0 ),16.0);
                  spe *= dif;
                  spe *= 0.04+0.96*pow(clamp(1.0-dot(hal,lig),0.0,1.0),5.0);
            lin += col*2.20*dif*vec3(1.30,1.00,0.70);
            lin +=     5.00*spe*vec3(1.30,1.00,0.70)*ks;
        }
        // sky
        {
            float dif = sqrt(clamp( 0.5+0.5*nor.y, 0.0, 1.0 ));
                  dif *= occ;
            float spe = smoothstep( -0.2, 0.2, ref.y );
                  spe *= dif;
                  spe *= calcSoftshadow( pos, ref, 0.02, 2.5 );
                  spe *= 0.04+0.96*pow(clamp(1.0+dot(nor,rd),0.0,1.0), 5.0 );
            lin += col*0.60*dif*vec3(0.40,0.60,1.15);
            lin +=     2.00*spe*vec3(0.40,0.60,1.30)*ks;
        }
        // back
        {
        	float dif = clamp( dot( nor, normalize(vec3(0.5,0.0,0.6))), 0.0, 1.0 )*clamp( 1.0-pos.y,0.0,1.0);
                  dif *= occ;
        	lin += col*0.55*dif*vec3(0.25,0.25,0.25);
        }
        // sss
        {
            float dif = pow(clamp(1.0+dot(nor,rd),0.0,1.0),2.0);
                  dif *= occ;
        	lin += col*0.25*dif*vec3(1.00,1.00,1.00);
        }

		col = lin;

        col = mix( col, vec3(0.7,0.7,0.9), 1.0-exp( -0.0001*t*t*t ) );
    }

	return vec3( clamp(col,0.0,1.0) );
}

mat3 setCamera( in vec3 ro, in vec3 ta, float cr )
{
	vec3 cw = normalize(ta-ro);
	vec3 cp = vec3(sin(cr), cos(cr),0.0);
	vec3 cu = normalize( cross(cw,cp) );
	vec3 cv =          ( cross(cu,cw) );
    return mat3( cu, cv, cw );
}

float PackMouseXY(vec2 mouse) {
    uvec2 uv = uvec2(mouse);
    uint ui = uv.x + (uv.y << 16);
    return uintBitsToFloat(ui);
}

vec2 UnpackMouseXY(float mouse) {
    uint ui = floatBitsToUint(mouse);
    uvec2 uv = uvec2(ui % 65536u, ui >> 16);
    return vec2(uv);

    return unpackUnorm2x16(floatBitsToUint(mouse))*65536.0;
}

float keydown(int code) {
    return texelFetch(iChannel3, ivec2(code, 0),  0).x;
}

mat3 rotation3d(vec3 axis, float angle) {
  axis = normalize(axis);
  float s = sin(angle);
  float c = cos(angle);
  float oc = 1.0 - c;

  return mat3(
		oc * axis.x * axis.x + c,           oc * axis.x * axis.y - axis.z * s,  oc * axis.z * axis.x + axis.y * s,
    oc * axis.x * axis.y + axis.z * s,  oc * axis.y * axis.y + c,           oc * axis.y * axis.z - axis.x * s,
    oc * axis.z * axis.x - axis.y * s,  oc * axis.y * axis.z + axis.x * s,  oc * axis.z * axis.z + c
	);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    ivec2 tCoord = ivec2(fragCoord);

    vec2 start = texelFetch(iChannel0, tCoord, 0).xy;

    vec2 signal = texelFetch(iChannel0, ivec2(0), 0).xy;
    signal.y = clamp(signal.y, -3.14/2., 3.14/2.);
    vec3 pos = texelFetch(iChannel0, ivec2(1, 0), 0).xyz;

    if (all(equal(tCoord, ivec2(0)))) {
        bool lastClick = texelFetch(iChannel0, ivec2(0), 0).a > 0.0;
        bool click = bool(iMouse.z > 0.0);
        bool update = click && !lastClick;

        float prevF = texelFetch(iChannel0, tCoord, 0).z;
        float currF = PackMouseXY(iMouse.xy);
        vec2 iMousePrev = UnpackMouseXY(prevF);
        vec2 diff = (iMouse.xy - iMousePrev) / iResolution.xy * float(!update);

        signal += diff*(mix(3.0, 5.0, keydown(16)) / mix(1.0, 5.0, keydown(17)));

        fragColor = vec4( signal, currF, float(click) );

        if (iFrame == 0) fragColor = vec4( vec2(0.0), currF, float(click) );

        return;
    }

    signal.x += 3.14/2.0;

    vec2 mo = signal.xy * vec2(1,-5);
	float time = 32.0 + iTime*1.5*0.0;

    // camera	
    vec3 ta = vec3( 0.5, -0.4, -0.5 );
    vec3 ro = ta + vec3( 4.5*cos(0.1*time + 6.0*mo.x*0.0), 1.5 + 2.0*mo.y*0.0, 4.5*sin(0.1*time + 6.0*mo.x*0.0) ) + pos;
    // camera-to-world transformation
    mat3 ca = setCamera( ro, ta, 0.0 );
    ca = rotation3d(vec3(0.,1.,0.), -signal.x) * rotation3d(vec3(1.,0.,0.), signal.y);

    if (all(equal(tCoord, ivec2(1,0)))) {
        float right = keydown(68) - keydown(65);
        float forward = keydown(87) - keydown(83);
        float up = keydown(32) - keydown(90);

        pos += (rotation3d(vec3(0.,1.,0.), -signal.x) * vec3(right, 0.0, forward) + vec3(0.,up,0.)) * iTimeDelta * 3.0;

        fragColor = vec4( pos, 0.0 );

        if (iFrame == 0) fragColor = vec4( 0.0 );

        return;
    }


    vec3 tot = vec3(0.0);
#if AA>1
    for( int m=ZERO; m<AA; m++ )
    for( int n=ZERO; n<AA; n++ )
    {
        // pixel coordinates
        vec2 o = vec2(float(m),float(n)) / float(AA) - 0.5;
        vec2 p = (2.0*(fragCoord+o)-iResolution.xy)/iResolution.y;
#else    
        vec2 p = (2.0*fragCoord-iResolution.xy)/iResolution.y;
#endif

        // ray direction
        vec3 rd = ca * normalize( vec3(p,2.5) );

         // ray differentials
        vec2 px = (2.0*(fragCoord+vec2(1.0,0.0))-iResolution.xy)/iResolution.y;
        vec2 py = (2.0*(fragCoord+vec2(0.0,1.0))-iResolution.xy)/iResolution.y;
        vec3 rdx = ca * normalize( vec3(px,2.5) );
        vec3 rdy = ca * normalize( vec3(py,2.5) );

        // render	
        vec3 col = render( ro, rd, rdx, rdy );

        // gain
        // col = col*3.0/(2.5+col);

		// gamma
        col = pow( col, vec3(0.4545) );

        tot += col;
#if AA>1
    }
    tot /= float(AA*AA);
#endif

    fragColor = vec4( tot, 1.0 );
}

#define pi 3.14159265359
#define tau 6.28318530718

#define MAXSAMPLES 15
#define RAYEXP 2.0

#define SKY 0.4 * vec3(76.0, 94.0, 112.0)/255.0

#define FOV 4.0
#define CAM_FREQ 1.1
#define CAM_DIST 7.0

vec2 r2d(vec2 p,float a)
{
	float c = cos(a);
    float s = sin(a);
    return vec2(p.x * c - p.y * s, p.x * s + p.y * c);
}

int iMod(int a, int b)
{
    return a - b * (a/b);
}


float density(vec3 p)
{
    vec3 p1 = 3.0 * (p*pi/6.0);

    p1.y -= 3.0 * iTime;

    p1.x += sin(p1.y + iTime*3.0)*0.5;
    p1.y += cos(p1.z + iTime*3.0)*0.5;
    p1.z += sin(p1.x - iTime*3.0)*0.5;

    float noise = pow(cos(p1.x) * cos(p1.y) * cos(p1.z), 2.0);

    return mix(0.05, 0.9, smoothstep(0.1, 0.6, noise));

}

vec3 color(vec3 p)
{
    float d = density(p);
    return mix(vec3(0.0, 0.5, 1.0), vec3(0.5, 1.0, 0.0), density(p));
}

bool in_cube(vec3 p, vec3 c_o, vec3 c_d)
{
    return (p.x>c_o.x)&&(p.x<c_o.x+c_d.x)&&(p.y>c_o.y)&&(p.y<c_o.y+c_d.y)&&(p.z>c_o.z)&&(p.z<c_o.z+c_d.z);
}

float transmittance(vec3 p_a, vec3 p_b, float samples)
{
    float l_i = 1.0;

    float dx = length(p_a - p_b) / samples;

    for (float i=0.0; i<samples; i++)
    {
        vec3 sample_pos = mix(p_a, p_b, 1.0 - i/samples);

        if (in_cube(sample_pos, vec3(-3.0), vec3(6.0)))
        {
            float sample_density = density(sample_pos);

            l_i  *= pow(1.0 - sample_density, dx);
        }
    }
    return l_i;
}


float plane_hit(vec3 o, vec3 d, int axis, float depth, vec2 p_o, vec2 p_d)
{
    float hit_dist = 0.0;
    float rayl = (depth - o[axis]) / d[axis] ;

    if (rayl<=0.0)
    {
        return -1.0;
    }

    vec3 intpoint = o + d * rayl;

    int axis_1 = iMod(axis+1, 3);
    int axis_2 = iMod(axis+2, 3);

    if ((intpoint[axis_1]>p_o.x)&&(intpoint[axis_1]<p_o.x+p_d.x)&&(intpoint[axis_2]>p_o.y)&&(intpoint[axis_2]<p_o.y+p_d.y)){
        return rayl;
    }

    return -1.0;
}

vec3 cube_hit(vec3 p, vec3 d, vec3 c_o, vec3 c_d)
{ //(x, y) -> scalars for ray ; (z) -> number of intersections

    vec3 hit_dist = vec3(0.0);
    int hit_ind = 0;

    //x1
    float i1 = plane_hit(p, d, 0, c_o.x, c_o.yz, c_d.yz);

    if (i1>0.0){
        hit_dist[hit_ind]=i1;
        hit_ind+=1;
    }

    //x2
    i1 = plane_hit(p, d, 0, c_o.x+c_d.x, c_o.yz, c_d.yz);
    if (i1>0.0){
        hit_dist[hit_ind]=i1;
        hit_ind+=1;
    }

    //y1
    i1 = plane_hit(p, d, 1, c_o.y, c_o.zx, c_d.zx);
    if (i1>0.0){
        hit_dist[hit_ind]=i1;
        hit_ind+=1;
    }

    //y2
    i1 = plane_hit(p, d, 1, c_o.y+c_d.y, c_o.zx, c_d.zx);
    if (i1>0.0){
        hit_dist[hit_ind]=i1;
        hit_ind+=1;
    }

    //z1
    i1 = plane_hit(p, d, 2, c_o.z, c_o.xy, c_d.xy);
    if (i1>0.0){
        hit_dist[hit_ind]=i1;
        hit_ind+=1;
    }

    //z2
    i1 = plane_hit(p, d, 2, c_o.z+c_d.z, c_o.xy, c_d.xy);
    if (i1>0.0){
        hit_dist[hit_ind]=i1;
        hit_ind+=1;
    }

    hit_dist.z = float(hit_ind);

    hit_dist.xy = vec2(max(hit_dist.x, hit_dist.y), min(hit_dist.x, hit_dist.y));

    //if (hit_ind<2 && hit_ind>0){hit_dist.x = hit_dist.y;}

    return hit_dist;
}


void mainImage( out vec4 fragColor, in vec2 fragCoord ) {

    vec2 uv = (gl_FragCoord.xy - iResolution.xy * 0.5)/iResolution.x;

    vec3 col = SKY;

    vec3 ray = vec3(uv * FOV, 1.0);

    float rotr = iTime * CAM_FREQ;

    vec3 ori = vec3(sin(rotr), 0.0, cos(rotr)) * CAM_DIST;

    ray.zx = r2d(ray.zx, rotr - pi);


    vec3 light_pos = vec3(cos(iTime), sin(2.0 * iTime), 0.0)*3.0;
    vec3 light_col = vec3(8.0);

    vec3 rayhit = cube_hit(ori, ray, vec3(-3.0, -3.0, -3.0), vec3(6.0, 6.0, 6.0)) ;

    float rayd = length(ray * (rayhit.x - rayhit.y));
    float rayd2 = length(ori + ray * rayhit.y);

    vec3 u = cube_hit(ori, ray, light_pos, vec3(0.25));

    if (u.z>0.1){col = light_col;}

    if (rayhit.z>0.0 && (u.z<0.1 || u.y>rayhit.y)){
        float k = round(64.0 * rayd / 6.0 + 2.0);
        float dx = rayd / k;

        float ray_intensity = 1.0; // transmittance between current sample position and camera
        vec3 pixel_color = vec3(0.0); // sum of reflected light

        for (float i=0.0; i<k; i++){

            float ray_scale = mix(rayhit.y, rayhit.x, (1.0*i)/(k-1.0));

            vec3 sample_pos = ori + ray * ray_scale;

            float sample_density = density(sample_pos);

            vec3 sample_color = color(sample_pos);

            vec3 light_int = light_pos + (sample_pos - light_pos) * cube_hit(light_pos, sample_pos - light_pos, vec3(-3.0), vec3(6.0)).y;

            vec3 light_intensity = transmittance(light_int, sample_pos, 20.0) * light_col * pow(0.3 * length(light_pos - sample_pos)+1.0, -2.0);

            // * pow(length(light_pos - sample_pos)+1.0, -2.0)

            float scatter = (1.0 - pow((1.0 - sample_density), dx));

            pixel_color += pow(ray_intensity, RAYEXP) * scatter * (light_intensity + SKY) * sample_color;
            ray_intensity *= (1.0 - scatter); //take into account that different wavelengths are passsed
        }
        col = pixel_color + col * ray_intensity;
    }

    fragColor = vec4(col,1.0);
}

// Noise ---------------------------------------------------------------

// Hashing function, use sin instead of table with permutations
// n : Real value
float hash( float n ) 
{
    return fract(sin(n)*43758.5453123); 
}

// Noise
// x : Point in space
float noise( in vec3 x )
{
    vec3 p = floor(x);
    vec3 f = fract(x);
    f = f*f*(3.0-2.0*f);

    float n = p.x + p.y*157.0 + 113.0*p.z;
    return mix(mix(mix( hash(n+  0.0), hash(n+  1.0),f.x),
                   mix( hash(n+157.0), hash(n+158.0),f.x),f.y),
               mix(mix( hash(n+113.0), hash(n+114.0),f.x),
                   mix( hash(n+270.0), hash(n+271.0),f.x),f.y),f.z);
}

// Rotation ------------------------------------------------------------

// Rotation around y axis
// v : Vector
// a : Angle
vec3 rotate(in vec3 v,in float a)
{
    return vec3(v.x*cos(a)+v.z*sin(a),v.y,-v.x*sin(a)+v.z*cos(a));
}

// Textures ------------------------------------------------------------

const vec3 blue=vec3(0.05,0.35,0.65);
const vec3 deepblue=vec3(0.05,0.05,0.85);
const vec3 green=vec3(0.15,0.95,0.75);
const vec3 red=vec3(0.75,0.35,0.35);
const vec3 black=vec3(0.0,0.0,0.0);
const vec3 white=vec3(1.0,1.0,1.0);
const vec3 violet=vec3(0.35,0.35,0.65);

// Checker
// p : Point on object
// n : Normal at point
vec3 checker(in vec3 p,in vec3 n)
{
    float v=mod(floor(p.x)+floor(p.y)+floor(p.z),2.0);
    return mix(blue,green,v);
}


// Turbulence
// p : Point
// n : Normal
float turbulence(in vec3 p,in vec3 n)
{
    // Add scaled noises
    float t=noise(p);
    t+=0.25*noise(2.0*p);
    t+=0.125*noise(5.0*p);
    t+=0.025*noise(13.0*p);
    // Scale
    t/=(1.0+0.25+0.125+0.025);
    return t;
}

// Turbulence with color
vec3 scaled(in vec3 p,in vec3 n)
{
    // Add scaled noises
    float t=turbulence(p,n);

    return mix(blue,green,t);
}

float scaledNoise(float i,vec3 p, vec3 n){

    float t=turbulence (i*p,n);;
    t=1.0-pow((1.0-t*t),4.0);
    t=0.5+abs(t-0.5);
    t=1.0-pow((1.0-t*t),2.0);
    return t;

}

// Marble
// p : Point
// n : Normal
vec3 marble(in vec3 p,in vec3 n)
{

    vec3 cc;

    // turbulences multiples
    float t1=scaledNoise(7.0,p,n);

    float t2=scaledNoise(2.25,rotate(p,38.0),n);


    float t3=scaledNoise(2.18,rotate(p,148.0),n);

    float t4=scaledNoise(6.5,rotate(p,48.0),n);



    //couleur de base, double marbré
    cc = 0.6*mix(black,white,t1)+0.5*mix(white, violet,t4);

    //veines violettes avec falloff
    if(t2>0.70 && t2<0.90){

    	float mx = 25.0*pow((0.10-abs(0.80-t2)),1.65);

        cc =mix(cc,violet,mx);
    }

    //veines blanches avec falloff
    if(t3>0.70 && t3<0.90){

    	float mx = 25.0*pow((0.10-abs(0.80-t3)),1.65);

        cc =mix(cc,white,mx);

    }


    return cc;
}

// Warped checker
// p : Point
// n : Normal
// a : amount of warping
vec3 warped(in vec3 p,in vec3 n,in float a)
{
    return checker(p+a*noise(2.0*p),n);
}


vec3 wood(in vec3 p, in vec3 n)
{
    vec3 c1 = vec3(139,69,19);
    vec3 c2 = vec3(205,133,63);


    float d = sqrt(p.y*p.y+p.x*p.x);


