// --- If no path tracing, use IQs softshadow to add detail
// --- https://iquilezles.org/articles/rmshadows

float softshadow( in vec3 ro, in vec3 rd )
{
    float res = 1.0;
    for( float t=0.02; t < 2.; )
    {
        float h = map(ro + rd*t).x;
        if( h<0.001 ) return 0.0;
        res = min( res, 8.0*h/t );
        t += h;
    }
    return res;
}
