// rd to screen UV, UV in 0-1 range
vec2 rd_to_screen_uv(vec3 rd, vec2 ires, vec2 mouse)
{
    vec2 res = (ires.xy / ires.y);
    vec2 im = (mouse.xy) / ires.y - res/2.0;
    im*=3.14159263*1.15;
    im.y = -im.y;

    rd=rd*(roty(-im.x) * rotx(im.y));

    if(rd.z<0.0001)return vec2(0.0);

    float fov = 70.;
    float aspect = ires.x / ires.y;
    float screenSize = (1.0 / (tan(((180.-fov)* (3.14159263 / 180.0)) / 2.0)));

    vec2 uv = rd.xy/rd.z;
    uv = uv/vec2(screenSize*aspect,screenSize);
    uv*=0.5;
    uv+=0.5;
    return uv;
}

vec3 cam(vec2 uv, vec2 ires, vec2 mouse)
{
    vec2 res = (ires.xy / ires.y);
    vec2 im = (mouse.xy) / ires.y - res/2.0;
    im*=3.14159263*1.15;
    im.y = -im.y;

    float fov = 70.;
    float aspect = ires.x / ires.y;
    float screenSize = (1.0 / (tan(((180.-fov)* (3.14159263 / 180.0)) / 2.0)));
    vec3 rd = normalize(vec3(uv*screenSize, 1./aspect));
    rd = (roty(-im.x) * rotx(im.y)) * rd;
    return rd;
}

