// return rd in Equirectangular projection
// uv is screen space
void panorama_screen_uv_to_rd(vec2 uv, out vec3 rd){
    float M_PI = 3.1415926535;
    float ymul = 2.0; float ydiff = -1.0;
    uv.x = 2.0 * uv.x - 1.0;
    uv.y = ymul * uv.y + ydiff;
    rd=vec3(0.0, 0.0, 1.0)*rotx(-uv.y*M_PI/2.0)*roty(-uv.x*M_PI);
    if(length(rd)<0.0001)rd+=0.0001;
    rd = normalize(rd);
}

// return uv for panorama texture
// rd is cubemap rayDir
void panorama_rd_to_pan_uv(vec3 rd, out vec2 uv){
    if(length(rd)<0.0001)rd+=0.0001;
    rd=normalize(rd);
    float M_PI = 3.1415926535;
    float theta = atan(rd.z,rd.x);
    float r = max(length(rd),0.0001);
    float phi =  asin(rd.y/r);
    uv = 0.5 + vec2(theta/(M_PI*2.), -phi/M_PI);
}

