// https://en.wikipedia.org/wiki/Cube_mapping

void convert_xyz_to_cube_uv(in vec3 rd, out int index, out vec2 uv)
{
    int Front_side = 0;
    int Back_side = 1;
    int Up_side = 2;
    int Down_side = 3;
    int Left_side = 4;
    int Right_side = 5;

    uv = vec2(0.);
    index = -1;
    if(length(rd)<0.0001)return;

    vec3 a = abs(rd);
    bvec3 ip = greaterThan(rd,vec3(0.));
    vec2 uvc = vec2(0.);
    if (ip.x && a.x >= a.y && a.x >= a.z) {uvc.x = -rd.z;uvc.y = rd.y;
    uv = vec2(0.5 * (uvc / a.x + 1.)); index = Front_side;return;
    }else
    if (!ip.x && a.x >= a.y && a.x >= a.z) {uvc.x = rd.z;uvc.y = rd.y;
    uv = vec2(0.5 * (uvc / a.x + 1.)); index = Back_side;return;
    }else
    if (ip.y && a.y >= a.x && a.y >= a.z) {uvc.x = rd.x;uvc.y = -rd.z;
    uv = vec2(0.5 * (uvc / a.y + 1.)); index = Up_side;return;
    }else
    if (!ip.y && a.y >= a.x && a.y >= a.z) {uvc.x = rd.x;uvc.y = rd.z;
    uv = vec2(0.5 * (uvc / a.y + 1.)); index = Down_side;return;
    }else
    if (ip.z && a.z >= a.x && a.z >= a.y) {uvc.x = rd.x;uvc.y = rd.y;
    uv = vec2(0.5 * (uvc / a.z + 1.)); index = Left_side;return;
    }else
    if (!ip.z && a.z >= a.x && a.z >= a.y) {uvc.x = -rd.x;uvc.y = rd.y;
    uv = vec2(0.5 * (uvc / a.z + 1.)); index = Right_side;return;
    }
}

void convert_cube_uv_to_xyz(in int index, in vec2 uv, out vec3 rd)
{
  float uc = 2.0 * uv.x - 1.0;
  float vc = 2.0 * uv.y - 1.0;
  rd=vec3(0.0001,0.9999,0.0001);
  if(index==0){rd=normalize(vec3(1.0, vc, -uc));return;}
  if(index==1){rd=normalize(vec3(-1.0, vc, uc));return;}
  if(index==2){rd=normalize(vec3(uc, 1.0, -vc));return;}
  if(index==3){rd=normalize(vec3(uc,-1.0, vc));return;}
  if(index==4){rd=normalize(vec3(uc, vc, 1.0));return;}
  if(index==5){rd=normalize(vec3(-uc, vc, -1.0));return;}
}

