//cubemap emulation in buffer

// fragCoord and fbo_resolution is screen space buffer coord and iResolution
// return rd, fc_side-fragCoord for cube side, index-side index (in Wikipedia cubemap order)
// side_size-size of cube side in channel
void buffer_cubemap_rd(in vec2 fragCoord, out vec3 rd, out vec2 fc_side, out int index,
                        out int side_size, vec2 fbo_resolution){
    fc_side = vec2(0.5);
    rd = vec3(0.0001, 0.9999, 0.0001);
    index = -1;

    ivec2 ipx = ivec2(fragCoord.xy);
    side_size = min(int(fbo_resolution.x)/3,int(fbo_resolution.y)/2);
    bvec2 box = lessThan(ipx/side_size,ivec2(3,2));

    if(!(box.x&&box.y))return;

    fc_side = vec2(ipx%side_size)+0.5001;
    index = ipx.x/side_size + (ipx.y/side_size)*3;

    convert_cube_uv_to_xyz(index, fc_side/vec2(side_size), rd);
}

// return color of buffered cubemap
// Fixed interpolation issue https://www.shadertoy.com/view/sdBfzw
// if you need exact fragCoord on cube side look code after this function
vec4 texture_buffer_cubemap(sampler2D c, vec3 rd){
    int index; vec2 side_uv;
    convert_xyz_to_cube_uv(rd, index, side_uv);

    ivec2 shift=ivec2(0);
    if(index==0)shift=ivec2(0, 0); else
    if(index==1)shift=ivec2(1, 0); else
    if(index==2)shift=ivec2(2, 0); else
    if(index==3)shift=ivec2(0, 1); else
    if(index==4)shift=ivec2(1, 1); else
    if(index==5)shift=ivec2(2, 1);


    vec2 s = vec2(1./3.,1./2.);

    // fixed interpolation

    vec2 fbo_resolution = vec2(textureSize(c, 0).xy);
    int side_size = min(int(fbo_resolution.x)/3,int(fbo_resolution.y)/2);
    vec2 tres = float(side_size)*(1./s);
    vec2 prop = (tres/fbo_resolution)*s;

    vec2 uv = side_uv*prop + vec2(shift)*prop;

    return textureLod(c, uv, 0.);
}

