vec3 random_unit_vector(float seed) // based on https://math.stackexchange.com/questions/44689/how-to-find-a-random-axis-or-unit-vector-in-3d
{
    vec2 rnd = hash21(seed);
    float phi = tau*rnd.x;
    vec2 polar = vec2(cos(phi),sin(phi));
    float z = 2.0*rnd.y-1.0;
    return vec3(sqrt(1.0-z*z)*polar,z);
}

vec4 random_unit_quaternion(vec3 r) // r in [0,1] https://stackoverflow.com/questions/31600717/how-to-generate-a-random-quaternion-quickly
{
    return
        vec4
        (
            sqrt(1.0-r.x) * sin(2.0*pi*r.y),
            sqrt(1.0-r.x) * cos(2.0*pi*r.y),
            sqrt(    r.x) * sin(2.0*pi*r.z),
            sqrt(    r.x) * cos(2.0*pi*r.z)
        );
}

