mat3 rotate_z(float angle)
{
    return
        mat3
        (
            vec3( cos(angle), sin(angle), 0.0),
            vec3(-sin(angle), cos(angle), 0.0),
            vec3(        0.0,        0.0, 1.0)
        );
}

mat3 rotate(vec3 axis, float angle) // https://www.euclideanspace.com/maths/geometry/rotations/conversions/angleToMatrix/
{
    float l = length(axis);
    float x = axis.x/l;
    float y = axis.y/l;
    float z = axis.z/l;
    float c = cos(angle);
    float s = sin(angle);
    float t = 1.0 - c;
    return
        mat3
        (
            vec3(t*x*x+  c, t*x*y+z*s, t*x*z-y*s),
            vec3(t*x*y-z*s, t*y*y+  c, t*y*z+x*s),
            vec3(t*x*z+y*s, t*y*z-x*s, t*z*z+  c)
        );
}

