void mainImage(out vec4 o, vec2 I)
{
    bool demo = all(lessThan(iMouse.xy, vec2(10.0)));
    vec2 R = iResolution.xy;
    I = (I + I - R) / R.y; // concise scaling thanks to Fabrice
    float yaw = 2.0 * pi * float(iMouse.x) / float(R.x);
    float pitch = pi - pi * float(iMouse.y) / float(R.y);
    yaw = !demo ? yaw : 2.0 * pi * fract(iTime * 0.01);
    pitch = !demo ? pitch : 4.0/3.0 * pi / 2.0;

    vec3 ro = vec3(0.0, 0.0,-4.0);
    vec3 rd = normalize(vec3(I.xy, 2.5)); // NOTE: omitting normalization results in clipped edges artifact

    mat3 M = yaw_pitch_roll(yaw, pitch, 0.0);
    ro = M * ro;
    rd = M * rd;

    //vec3 lightdir = normalize(vec3(1.0, 1.0, 1.0));
    vec3 lightdir = normalize(vec3(2.0,1.0, 3.0));

    // NOTE: obviously it would be more efficient to calculate the bounding boxes outside of the shader. But I want a bufferless, self-contained shadertoy shader so...

    // direct approach: results in inefficient/overlapping bounding box structure - still faster than naive rendering
    {
        //bounding_boxes[BOUNDING_BOX_LEAF_BASE + 0u] = bounding_box(vec3(0),vec3(1));
        //for(uint i = 1u; i < BOUNDING_BOX_LEAF_COUNT; i++)
        for(uint i = 0u; i < BOUNDING_BOX_LEAF_COUNT; i++)
        {
/*
            vec3 v0 = mix(vec3(-1),vec3(+1),hash31(+float(i+1u)*123.456));
            vec3 v1 = mix(vec3(-1),vec3(+1),hash31(-float(i+1u)*123.456));

            vec3 c = (v1 + v0) / 2.0;
            vec3 e = abs(v1-v0) / 2.0;
            //float r = min(min(e.x, e.y), e.z)/2.0;
            vec3 o = vec3(1) - e;

            c = o*bounce(vec3(iTime/25.0)/o);

            bounding_boxes[BOUNDING_BOX_LEAF_BASE + i] = bounding_box(c,e);
*/
            vec3 color = hash31(float(i+1u)*123.456);
            vec3 axis = random_unit_vector(float(i+1u)*123.456);

            float r = mix(0.1,0.25,hash11(float(i+1u)*123.456)); // radius
            vec3 c = mix(vec3(-1.0+r),vec3(+1.0-r),hash31(float(i+1u)*123.456)); // fit sphere into unit box
            vec3 o = vec3(1.0-r);
            c = o*bounce(c+vec3(iTime/50.0)/o); // animate bouncing in unit box
            bounding_boxes[BOUNDING_BOX_LEAF_BASE + i] = bounding_box(c,vec3(r),axis,color);
        }

        // construct enclosing boxes
        //for(uint level = BOUNDING_BOX_LEVELS - 1u; level > 0u; level--)
        for(uint j = 1u; j < BOUNDING_BOX_LEVELS; j++)
        {
            uint level = BOUNDING_BOX_LEVELS - j;
            uint node_count = (1u << (level - 1u));
            uint node_base = (1u << (level - 1u)) - 1u;
            uint leaf_base = (1u << level) - 1u;
            for(uint i = 0u; i < node_count; i++)
            {
                bounding_boxes[node_base + i] = enclosing_box(bounding_boxes[leaf_base + 2u * i + 0u],bounding_boxes[leaf_base + 2u * i + 1u]);
            }
        }
    }

    vec4 result = trace(ro, rd, 0.0, DIST_MAX);
    vec3 color = result.xyz;
    float dist = result.w;
    if(dist < DIST_MAX)
    {
        vec3 dst = ro + rd * dist;
        //vec3 n = normal(dst); // standard normals
        vec3 n = normal(ro + rd * (dist-EPSILON)); // reduce edge-glint by normal-backoff as suggested by elenzil

        //color = n * 0.5 + 0.5;

        vec3 ambient = vec3(0.1);
        float brightness = max(dot(lightdir, n), 0.0) * 2.0;
        if(brightness > 0.0)
            brightness *= shadow(ro + rd * dist + n * 0.01, lightdir, 0.0, DIST_MAX);
            //brightness *= softshadow(ro + rd * dist + n * 0.01, lightdir, 0.0, DIST_MAX, 25.0);
        color *= (ambient * calcAO(dst, n, 0u/*index*/)) + brightness;

        if(brightness > 0.0)
        {
            float specular = pow(max(0.0, dot(n, normalize(-rd + lightdir))), 250.0);
            color += specular;
        }

        vec3 fog_color = vec3(0);
        color = mix(fog_color, vec3(color), exp(-pow(dist/20.0, 2.0))); // fog
    }
    else
    {
        color = vec3(0);
    }
//    #if BOUNDING_BOX_LEAF_BASE + 3u == 6u
//    color = vec3(0,1,0);
//    #endif
    color = tanh(color); // roll-off overly bright colors
    color = sqrt(color); // approximate gamma

    //color += hash32(I*123.0)/255.0; // dither to remove banding in the background

    o = vec4(color, 1);
}

