void initLights() {

    for(int lightID = 0; lightID < NUM_LIGHTS; lightID += 1) {
        Light light;

        light.type = SPHERE_LIGHT;
        light.position = vec3(0., 39., -43.9);
        light.emission = vec3(80., 80., 80.);
