// Materials
Material createMaterial(int materialID) {
    Material mat;

    // Initialize default values
    mat.opacity = 1.0;
    mat.alphaMode = ALPHA_MODE_OPAQUE;
    mat.alphaCutoff = 0.5;
    mat.emission = vec3(0.0);
    mat.anisotropic = 0.0;
    mat.metallic = 0.0;
    mat.roughness = 0.5;
    mat.subsurface = 0.0;
    mat.specularTint = 0.0;
    mat.sheen = 0.0;
    mat.sheenTint = 0.0;
    mat.clearcoat = 0.0;
    mat.clearcoatRoughness = 0.1;
    mat.specTrans = 0.0;
    mat.ior = 1.5;
    mat.medium.type = MEDIUM_NONE;
    mat.medium.density = 0.0;
    mat.medium.color = vec3(1.0);
    mat.medium.anisotropy = 0.0;

    if (materialID == 1) {
        // orange material
        mat.baseColor = vec3(1.0, 0.186, 0.0);
        mat.roughness = 0.001;
        mat.specularTint = 0.5;
        mat.clearcoat = 1.0;
        mat.clearcoatRoughness = mix(0.1, 0.001, 0.93); // clearcoatgloss 0.93
    }
    else if (materialID == 2) {
        // glass material
        mat.baseColor = vec3(1.0, 1.0, 1.0);
        mat.specTrans = 1.0;
        mat.ior = 1.45;
        mat.roughness = 0.05;
    }
    else if (materialID == 3) {
        // silver material
        mat.baseColor = vec3(0.9, 0.9, 0.9);
        mat.specularTint = 0.5;
        mat.roughness = 0.2;
        mat.metallic = 1.0;
        mat.anisotropic = 1.0;
    }
    else if (materialID == 4) {
        // ring_silver material
        mat.baseColor = vec3(1.0, 1.0, 1.0);
        mat.roughness = 0.01;
        mat.specularTint = 0.5;
        mat.metallic = 1.0;
    }
    else if (materialID == 5) {
        // off_white material
        mat.baseColor = vec3(1.0, 0.94, 0.8);
        mat.roughness = 1.0;
        mat.specularTint = 0.5;
    }
    else if (materialID == 6) {
        // ping material
        mat.baseColor = vec3(0.93, 0.89, 0.85);
        mat.roughness = 1.0;
        mat.subsurface = 1.0;
        mat.specularTint = 0.5;
    }
    else if (materialID == 7) {
        // marb1 material
        mat.baseColor = vec3(0.026, 0.147, 0.075);
        mat.roughness = 0.077;
        mat.specularTint = 0.5;
        mat.subsurface = 1.0;
        mat.clearcoat = 1.0;
        mat.clearcoatRoughness = mix(0.1, 0.001, 0.93); // clearcoatgloss 0.93
    }
    else if (materialID == 8) {
        // marb2 material
        mat.baseColor = vec3(0.099, 0.24, 0.134);
        mat.roughness = 0.077;
        mat.specularTint = 0.5;
        mat.subsurface = 1.0;
        mat.clearcoat = 1.0;
        mat.clearcoatRoughness = mix(0.1, 0.001, 0.93); // clearcoatgloss 0.93
    }
    else {
        // default material
        mat.baseColor = vec3(0.5, 0.5, 0.5);
        mat.roughness = 0.5;
        mat.metallic = 0.0;
    }

    // Calculate anisotropy parameters
    float aspect = sqrt(1.0 - mat.anisotropic * 0.9);
    mat.ax = max(0.001, mat.roughness / aspect);
    mat.ay = max(0.001, mat.roughness * aspect);

    return mat;
}

// Helper function to get material by mesh name/ID
int getMaterialIDByMesh(int meshID) {
    if (meshID < 0) return 5;

    // Glass Ball -> glass (2)
    if (meshID == 1) return 2;
    // Chrome Ball -> silver (3)
    if (meshID == 2) return 3;
    // Platform -> off_white (5)
    if (meshID == 3) return 5;
    // Floor -> off_white (5)
    if (meshID == 4) return 5;
    // Orange Ball -> orange (1)
    if (meshID == 5) return 1;
    // Ring 1 -> ring_silver (4)
    if (meshID == 6) return 4;
    // Ring 2 -> ring_silver (4)
    if (meshID == 7) return 4;
    // Ring 3 -> ring_silver (4)
    if (meshID == 8) return 4;
    // Marble 1 -> marb1 (7)
    if (meshID == 9) return 7;
    // Marble 2 -> marb2 (8)
    if (meshID == 10) return 8;
    // Ping Pong -> ping (6)
    if (meshID == 11) return 6;

    return 1; // default to orange material
}

// SDF

vec2 opU(vec2 d1, vec2 d2) {
    return (d1.x < d2.x) ? d1 : d2;
}

float sdSphere(vec3 p, float r) {
    return length(p) - r;
}

float sdBox(vec3 p, vec3 b) {
    vec3 q = abs(p) - b;
    return length(max(q, 0.0)) + min(max(q.x, max(q.y, q.z)), 0.0);
}

float sdRoundBox(vec3 p, vec3 b, float r) {
    vec3 q = abs(p) - b;
    return length(max(q, 0.0)) + min(max(q.x, max(q.y, q.z)), 0.0) - r;
}

float sdRing(vec3 p, float diameter, float height, float thickness) {
    vec3 q = p;
    q.y = abs(q.y) - height * 0.5;

    float ringRadius = diameter * 0.5;
    float distanceToRing = length(vec2(length(q.xz) - ringRadius, max(q.y, 0.0)));

    return distanceToRing - thickness * 0.5;
}

vec2 map(vec3 pos) {
    vec2 res = vec2(1e10, 0.0);

    // Glass Ball - sphere
    vec3 glassBallPos = vec3(-0.57, 1.87, 6.55);
    float glassBall = sdSphere(pos - glassBallPos, 1.2);
    res = opU(res, vec2(glassBall, 1.0)); // glass material

    // Chrome Ball - sphere  
    vec3 chromeBallPos = vec3(0.4, 1.86, -6.59);
    float chromeBall = sdSphere(pos - chromeBallPos, 1.2);
    res = opU(res, vec2(chromeBall, 2.0)); // silver material

    // Platform - rounded box
    vec3 platformPos = vec3(0.0, 0.36, 0.0);
    float platform = sdRoundBox(pos - platformPos, vec3(5.0, 0.3, 9.0), 0.05);
    res = opU(res, vec2(platform, 3.0)); // off_white material

    // Floor - large flat box
    vec3 floorPos = vec3(0.0, 0.0, 0.0);
    float floor = sdBox(pos - floorPos, vec3(20.0, 0.1, 20.0));
    res = opU(res, vec2(floor, 4.0)); // off_white material

    // Orange Ball - sphere
    vec3 orangeBallPos = vec3(1.646, 1.6861, 3.5662);
    float orangeBall = sdSphere(pos - orangeBallPos, 1.);
    res = opU(res, vec2(orangeBall, 5.0)); // orange material

    // Ring 1 - torus
    vec3 ring1Pos = vec3(-0.308737, 0.805763, -1.42968);
    float ring1 = sdRing(pos - ring1Pos, 1.0, 0.26, 0.1);
    res = opU(res, vec2(ring1, 6.0)); // ring_silver material

    // Ring 2 - torus
    vec3 ring2Pos = vec3(-0.6706, 0.808472, 0.626798);
    float ring2 = sdRing(pos - ring2Pos, 1.0, 0.26, 0.1);
    res = opU(res, vec2(ring2, 7.0)); // ring_silver material

    // Ring 3 - torus
    vec3 ring3Pos = vec3(-1.44541, 0.808472, 1.72607);
    float ring3 = sdRing(pos - ring3Pos, 1.0, 0.26, 0.1);
    res = opU(res, vec2(ring3, 8.0)); // ring_silver material

    // Marble 1 - sphere
    vec3 marble1Pos = vec3(-3.78, 0.88, -0.84);
    float marble1 = sdSphere(pos - marble1Pos, 0.2);
    res = opU(res, vec2(marble1, 9.0)); // marb1 material

    // Marble 2 - sphere
    vec3 marble2Pos = vec3(-3.746, 0.969453, 0.974294);
    float marble2 = sdSphere(pos - marble2Pos, 0.3);
    res = opU(res, vec2(marble2, 10.0)); // marb2 material

    // Ping Pong Ball - sphere
    vec3 pingPongPos = vec3(-3.14, 1.51, -4.12);
    float pingPong = sdSphere(pos - pingPongPos, 0.8);
    res = opU(res, vec2(pingPong, 11.0)); // ping material

    return res;
}

