/*
 * Port of https://github.com/knightcrawler25/GLSL-PathTracer
 * Copyright(c) 2019-2021 Asif Ali
 *
 * v0.1 - Initial Release
 *
 */

float Luminance(vec3 c)
{
    return 0.212671 * c.x + 0.715160 * c.y + 0.072169 * c.z;
}

vec3 Tonemap(in vec3 c, float limit)
{
    return c * 1.0 / (1.0 + Luminance(c) / limit);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
	vec2 uv = fragCoord.xy / iResolution.xy;
	fragColor = texture(iChannel0, uv);
    fragColor.rgb = Tonemap(fragColor.rgb, 1.5);
    fragColor.rgb = pow(fragColor.rgb, vec3(0.4545));
}

// Input.
const int KEY_LEFT  = 37;
const int KEY_UP    = 38;
const int KEY_RIGHT = 39;
const int KEY_DOWN  = 40;
const int KEY_SHIFT = 16;
const int KEY_CTRL  = 17;
const int KEY_SPACE  = 32;
const int KEY_W  = 87;
const int KEY_A = 65;
const int KEY_S  = 83;
const int KEY_D  = 68;
const int KEY_C  = 67;
const int KEY_V  = 86;
const int KEY_E  = 69;
const int KEY_R  = 82;
const int KEY_T  = 84;

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    Camera cam = getCamera();

    vec4 prevColor = texelFetch(iChannel0, ivec2(fragCoord), 0);
    bool updated = false;

    // Accelerate.
    float sensitivity = texelFetch(iChannel0, ivec2(CAMERA_SENSITIVITY, 0), 0).x;
    if(ivec2(fragCoord) == ivec2(CAMERA_SENSITIVITY,0)){
        if(sensitivity == 0.){
            sensitivity = 0.03;
            prevColor.r = 0.03;
        }
        if(texelFetch( iChannel1, ivec2(KEY_C,0), 0 ).x > 0.5 && prevColor.r < 1000.){
            prevColor.r *= 1.05;
        }
        if(texelFetch( iChannel1, ivec2(KEY_V,0), 0 ).x > 0.5 && prevColor.r > 0.00001){
            prevColor.r /= 1.05;
        }
    }

    // Zoom.
    float zoom = texelFetch(iChannel0, ivec2(CAMERA_ZOOM, 0), 0).x;
    if(ivec2(fragCoord) == ivec2(CAMERA_ZOOM,0)){
        if(zoom == 0.){
            zoom = 1.0;
            prevColor.r = 1.0;
        }
        if(texelFetch( iChannel1, ivec2(KEY_R,0), 0 ).x > 0.5){
            updated = true;
            prevColor.r *= 1.02;
        }
        if(texelFetch( iChannel1, ivec2(KEY_T,0), 0 ).x > 0.5){
            updated = true;
            prevColor.r /= 1.02;
        }
    }

    // Calculate camera basis vectors
    // Rotate.
    vec3 forward = texelFetch(iChannel0, ivec2(CAMERA_DIRECTION, 0), 0).xyz;
    if(length(forward) == 0.){
        forward = cam.lookAt - cam.origin;
    }
    forward = normalize(forward);
    vec3 right = normalize(cross(forward, vec3(0.0, 1.0, 0.0)));
    vec3 up = normalize(cross(right, forward));

    if(ivec2(fragCoord) == ivec2(CAMERA_DIRECTION,0)){
        bool arrowRight = texelFetch( iChannel1, ivec2(KEY_RIGHT,0), 0 ).x > 0.5;
        bool arrowLeft = texelFetch( iChannel1, ivec2(KEY_LEFT,0), 0 ).x > 0.5;
        bool arrowUp = texelFetch( iChannel1, ivec2(KEY_UP,0), 0 ).x > 0.5;
        bool arrowDown = texelFetch( iChannel1, ivec2(KEY_DOWN,0), 0 ).x > 0.5;
        float rotationSensitivity = 0.018/zoom;
        if(arrowRight){
            updated = true;
            forward = normalize(forward + right*rotationSensitivity);
        }
        if(arrowLeft){
            updated = true;
            forward = normalize(forward - right*rotationSensitivity);
        }
        if(arrowUp){
            updated = true;
            forward = normalize(forward + up*rotationSensitivity);
        }
        if(arrowDown){
            updated = true;
            forward = normalize(forward - up*rotationSensitivity);
        }
        prevColor.xyz = normalize(forward);
    }

    // Translate.
    vec3 pos = texelFetch(iChannel0, ivec2(CAMERA_POS, 0), 0).xyz;
    if(length(pos) == 0.){
        pos = cam.origin;
    }
    if(ivec2(fragCoord) == ivec2(CAMERA_POS,0)){
        bool dDown = texelFetch( iChannel1, ivec2(KEY_D,0), 0 ).x > 0.5;
        bool aDown = texelFetch( iChannel1, ivec2(KEY_A,0), 0 ).x > 0.5;
        bool spaceDown = texelFetch( iChannel1, ivec2(KEY_SPACE,0), 0 ).x > 0.5;
        bool shiftDown = texelFetch( iChannel1, ivec2(KEY_SHIFT,0), 0 ).x > 0.5;
        bool wDown = texelFetch( iChannel1, ivec2(KEY_W,0), 0 ).x > 0.5;
        bool sDown = texelFetch( iChannel1, ivec2(KEY_S,0), 0 ).x > 0.5;
        if(wDown){
            updated = true;
        	pos += forward*sensitivity;
        }
        if(sDown){
            updated = true;
        	pos -= forward*sensitivity;
        }
        if(dDown){
            updated = true;
        	pos += right*sensitivity;
        }
        if(aDown){
            updated = true;
        	pos -= right*sensitivity;
        }
        if(spaceDown){
            updated = true;
        	pos += up*sensitivity;
        }
        if(shiftDown){
            updated = true;
        	pos -= up*sensitivity;
        }
        prevColor.xyz = pos;
    }

    prevColor.w = updated ? 1. : 0.;

    // Write data/color.
    fragColor = prevColor;
}

