vec4 cubemap( sampler2D sam, in vec3 d )
{
    // intersect cube
    vec3 n = abs(d);
    vec3 v = (n.x>n.y && n.x>n.z) ? d.xyz: 
             (n.y>n.x && n.y>n.z) ? d.yzx:
                                    d.zxy;
    // project into face
    vec2 q = v.yz/v.x;
    // undistort in the edges
    q *= 1.25 - 0.25*q*q;
    // sample
    return texture( sam, 0.5+0.5*q );
}

// SDF

vec3 calculateNormal(vec3 p) {

    vec3 epsilon = vec3(0.001, 0., 1.);

    vec3 n = vec3(map(p + epsilon.xyy).x - map(p - epsilon.xyy).x,
                  map(p + epsilon.yxy).x - map(p - epsilon.yxy).x,
                  map(p + epsilon.yyx).x - map(p - epsilon.yyx).x);

    return normalize(n);
}

// Get the scene hit record
bool getSceneHit(Ray ray, inout State state) {

    float t = 0.001;

    float matId = -1.;
    bool hit = false;

    // Raymarch the rest 
    for(int i = 0; i < 120; ++i) {
        vec3 p = ray.origin + ray.direction * t;

        vec2 d = map(p);
        float ad = abs(d.x);

        if (ad < (0.0001)) {
            hit = true;
            matId = d.y;
            break;
         }

         t += ad;

         if (t>TMAX) { break; }
    }

    if (hit) {
        state.fhp = ray.origin + ray.direction * t;
        state.normal = calculateNormal(state.fhp);
        state.hitDist = t;

        state.mat = getMaterial(getMaterialIDByMesh(int(matId)), state.fhp, state.normal, iChannel1, iChannel2, iChannel3 );
    }

    return hit;
}

uvec4 seed;
ivec2 pixel;

void InitRNG(vec2 p, int frame)
{
    pixel = ivec2(p);
    seed = uvec4(p, uint(frame), uint(p.x) + uint(p.y));
}

void pcg4d(inout uvec4 v)
{
    v = v * 1664525u + 1013904223u;
    v.x += v.y * v.w; v.y += v.z * v.x; v.z += v.x * v.y; v.w += v.y * v.z;
    v = v ^ (v >> 16u);
    v.x += v.y * v.w; v.y += v.z * v.x; v.z += v.x * v.y; v.w += v.y * v.z;
}

float rand()
{
    pcg4d(seed); return float(seed.x) / float(0xffffffffu);
}

vec3 FaceForward(vec3 a, vec3 b)
{
    return dot(a, b) < 0.0 ? -b : b;
}

float Luminance(vec3 c)
{
    return 0.212671 * c.x + 0.715160 * c.y + 0.072169 * c.z;
}

// Sampling

float GTR1(float NDotH, float a)
{
    if (a >= 1.0)
        return INV_PI;
    float a2 = a * a;
    float t = 1.0 + (a2 - 1.0) * NDotH * NDotH;
    return (a2 - 1.0) / (PI * log(a2) * t);
}

vec3 SampleGTR1(float rgh, float r1, float r2)
{
    float a = max(0.001, rgh);
    float a2 = a * a;

    float phi = r1 * TWO_PI;

    float cosTheta = sqrt((1.0 - pow(a2, 1.0 - r2)) / (1.0 - a2));
    float sinTheta = clamp(sqrt(1.0 - (cosTheta * cosTheta)), 0.0, 1.0);
    float sinPhi = sin(phi);
    float cosPhi = cos(phi);

    return vec3(sinTheta * cosPhi, sinTheta * sinPhi, cosTheta);
}

float GTR2(float NDotH, float a)
{
    float a2 = a * a;
    float t = 1.0 + (a2 - 1.0) * NDotH * NDotH;
    return a2 / (PI * t * t);
}

vec3 SampleGTR2(float rgh, float r1, float r2)
{
    float a = max(0.001, rgh);

    float phi = r1 * TWO_PI;

    float cosTheta = sqrt((1.0 - r2) / (1.0 + (a * a - 1.0) * r2));
    float sinTheta = clamp(sqrt(1.0 - (cosTheta * cosTheta)), 0.0, 1.0);
    float sinPhi = sin(phi);
    float cosPhi = cos(phi);

    return vec3(sinTheta * cosPhi, sinTheta * sinPhi, cosTheta);
}

vec3 SampleGGXVNDF(vec3 V, float ax, float ay, float r1, float r2)
{
    vec3 Vh = normalize(vec3(ax * V.x, ay * V.y, V.z));

    float lensq = Vh.x * Vh.x + Vh.y * Vh.y;
    vec3 T1 = lensq > 0. ? vec3(-Vh.y, Vh.x, 0) * inversesqrt(lensq) : vec3(1, 0, 0);
    vec3 T2 = cross(Vh, T1);

    float r = sqrt(r1);
    float phi = 2.0 * PI * r2;
    float t1 = r * cos(phi);
    float t2 = r * sin(phi);
    float s = 0.5 * (1.0 + Vh.z);
    t2 = (1.0 - s) * sqrt(1.0 - t1 * t1) + s * t2;

    vec3 Nh = t1 * T1 + t2 * T2 + sqrt(max(0.0, 1.0 - t1 * t1 - t2 * t2)) * Vh;

    return normalize(vec3(ax * Nh.x, ay * Nh.y, max(0.0, Nh.z)));
}

float GTR2Aniso(float NDotH, float HDotX, float HDotY, float ax, float ay)
{
    float a = HDotX / ax;
    float b = HDotY / ay;
    float c = a * a + b * b + NDotH * NDotH;
    return 1.0 / (PI * ax * ay * c * c);
}

vec3 SampleGTR2Aniso(float ax, float ay, float r1, float r2)
{
    float phi = r1 * TWO_PI;

    float sinPhi = ay * sin(phi);
    float cosPhi = ax * cos(phi);
    float tanTheta = sqrt(r2 / (1. - r2));

    return vec3(tanTheta * cosPhi, tanTheta * sinPhi, 1.0);
}

float SmithG(float NDotV, float alphaG)
{
    float a = alphaG * alphaG;
    float b = NDotV * NDotV;
    return (2.0 * NDotV) / (NDotV + sqrt(a + b - a * b));
}

float SmithGAniso(float NDotV, float VDotX, float VDotY, float ax, float ay)
{
    float a = VDotX * ax;
    float b = VDotY * ay;
    float c = NDotV;
    return (2.0 * NDotV) / (NDotV + sqrt(a * a + b * b + c * c));
}

float SchlickWeight(float u)
{
    float m = clamp(1.0 - u, 0.0, 1.0);
    float m2 = m * m;
    return m2 * m2 * m;
}

float DielectricFresnel(float cosThetaI, float eta)
{
    float sinThetaTSq = eta * eta * (1.0f - cosThetaI * cosThetaI);

    // Total internal reflection
    if (sinThetaTSq > 1.0)
        return 1.0;

    float cosThetaT = sqrt(max(1.0 - sinThetaTSq, 0.0));

    float rs = (eta * cosThetaT - cosThetaI) / (eta * cosThetaT + cosThetaI);
    float rp = (eta * cosThetaI - cosThetaT) / (eta * cosThetaI + cosThetaT);

    return 0.5f * (rs * rs + rp * rp);
}

vec3 CosineSampleHemisphere(float r1, float r2)
{
    vec3 dir;
    float r = sqrt(r1);
    float phi = TWO_PI * r2;
    dir.x = r * cos(phi);
    dir.y = r * sin(phi);
    dir.z = sqrt(max(0.0, 1.0 - dir.x * dir.x - dir.y * dir.y));
    return dir;
}

vec3 UniformSampleHemisphere(float r1, float r2)
{
    float r = sqrt(max(0.0, 1.0 - r1 * r1));
    float phi = TWO_PI * r2;
    return vec3(r * cos(phi), r * sin(phi), r1);
}

vec3 UniformSampleSphere(float r1, float r2)
{
    float z = 1.0 - 2.0 * r1;
    float r = sqrt(max(0.0, 1.0 - z * z));
    float phi = TWO_PI * r2;
    return vec3(r * cos(phi), r * sin(phi), z);
}

float PowerHeuristic(float a, float b)
{
    float t = a * a;
    return t / (b * b + t);
}

void Onb(in vec3 N, inout vec3 T, inout vec3 B)
{
    vec3 up = abs(N.z) < 0.9999999 ? vec3(0, 0, 1) : vec3(1, 0, 0);
    T = normalize(cross(up, N));
    B = cross(N, T);
}

void SampleSphereLight(in Light light, in vec3 scatterPos, inout LightSampleRec lightSample)
{
    float r1 = rand();
    float r2 = rand();

    vec3 sphereCentertoSurface = scatterPos - light.position;
    float distToSphereCenter = length(sphereCentertoSurface);
    vec3 sampledDir;

    // TODO: Fix this. Currently assumes the light will be hit only from the outside
    sphereCentertoSurface /= distToSphereCenter;
    sampledDir = UniformSampleHemisphere(r1, r2);
    vec3 T, B;
    Onb(sphereCentertoSurface, T, B);
    sampledDir = T * sampledDir.x + B * sampledDir.y + sphereCentertoSurface * sampledDir.z;

    vec3 lightSurfacePos = light.position + sampledDir * light.radius;

    lightSample.direction = lightSurfacePos - scatterPos;
    lightSample.dist = length(lightSample.direction);
    float distSq = lightSample.dist * lightSample.dist;

    lightSample.direction /= lightSample.dist;
    lightSample.normal = normalize(lightSurfacePos - light.position);
    lightSample.emission = light.emission * float(numOfLights());
    lightSample.pdf = distSq / (light.area * 0.5 * abs(dot(lightSample.normal, lightSample.direction)));
}

void SampleRectLight(in Light light, in vec3 scatterPos, inout LightSampleRec lightSample)
{
    float r1 = rand();
    float r2 = rand();

    vec3 lightSurfacePos = light.position + light.u * r1 + light.v * r2;
    lightSample.direction = lightSurfacePos - scatterPos;
    lightSample.dist = length(lightSample.direction);
    float distSq = lightSample.dist * lightSample.dist;
    lightSample.direction /= lightSample.dist;
    lightSample.normal = normalize(cross(light.u, light.v));
    lightSample.emission = light.emission * float(numOfLights());
    lightSample.pdf = distSq / (light.area * abs(dot(lightSample.normal, lightSample.direction)));
}

void SampleDistantLight(in Light light, in vec3 scatterPos, inout LightSampleRec lightSample)
{
    lightSample.direction = normalize(light.position - vec3(0.0));
    lightSample.normal = normalize(scatterPos - light.position);
    lightSample.emission = light.emission * float(numOfLights());
    lightSample.dist = INF;
    lightSample.pdf = 1.0;
}

void SampleOneLight(in Light light, in vec3 scatterPos, inout LightSampleRec lightSample)
{
    int type = int(light.type);

    if (type == QUAD_LIGHT)
        SampleRectLight(light, scatterPos, lightSample);
    else if (type == SPHERE_LIGHT)
        SampleSphereLight(light, scatterPos, lightSample);
    else
        SampleDistantLight(light, scatterPos, lightSample);
}

vec3 SampleHG(vec3 V, float g, float r1, float r2)
{
    float cosTheta;

    if (abs(g) < 0.001)
        cosTheta = 1. - 2. * r2;
    else 
    {
        float sqrTerm = (1. - g * g) / (1. + g - 2. * g * r2);
        cosTheta = -(1. + g * g - sqrTerm * sqrTerm) / (2. * g);
    }

    float phi = r1 * TWO_PI;
    float sinTheta = clamp(sqrt(1.0 - (cosTheta * cosTheta)), 0.0, 1.0);
    float sinPhi = sin(phi);
    float cosPhi = cos(phi);

    vec3 v1, v2;
    Onb(V, v1, v2);

    return sinTheta * cosPhi * v1 + sinTheta * sinPhi * v2 + cosTheta * V;
}

float PhaseHG(float cosTheta, float g)
{
    float denom = 1. + g * g + 2. * g * cosTheta;
    return INV_4_PI * (1. - g * g) / (denom * sqrt(denom));
}

// Disney

vec3 DisneyEval(State state, vec3 V, vec3 N, vec3 L, out float pdf);

vec3 ToWorld(vec3 X, vec3 Y, vec3 Z, vec3 V)
{
    return V.x * X + V.y * Y + V.z * Z;
}

vec3 ToLocal(vec3 X, vec3 Y, vec3 Z, vec3 V)
{
    return vec3(dot(V, X), dot(V, Y), dot(V, Z));
}

void TintColors(Material mat, float eta, out float F0, out vec3 Csheen, out vec3 Cspec0)
{
    float lum = Luminance(mat.baseColor);
    vec3 ctint = lum > 0.0 ? mat.baseColor / lum : vec3(1.0);

    F0 = (1.0 - eta) / (1.0 + eta);
    F0 *= F0;

    Cspec0 = F0 * mix(vec3(1.0), ctint, mat.specularTint);
    Csheen = mix(vec3(1.0), ctint, mat.sheenTint);
}

vec3 EvalDisneyDiffuse(Material mat, vec3 Csheen, vec3 V, vec3 L, vec3 H, out float pdf)
{
    pdf = 0.0;
    if (L.z <= 0.0)
        return vec3(0.0);

    float LDotH = dot(L, H);

    float Rr = 2.0 * mat.roughness * LDotH * LDotH;

    // Diffuse
    float FL = SchlickWeight(L.z);
    float FV = SchlickWeight(V.z);
    float Fretro = Rr * (FL + FV + FL * FV * (Rr - 1.0));

    float Fd = (1.0 - 0.5 * FL) * (1.0 - 0.5 * FV);

    // Fake subsurface
    float Fss90 = 0.5 * Rr;
    float Fss = mix(1.0, Fss90, FL) * mix(1.0, Fss90, FV);
    float ss = 1.25 * (Fss * (1.0 / (L.z + V.z) - 0.5) + 0.5);

    // Sheen
    float FH = SchlickWeight(LDotH);
    vec3 Fsheen = FH * mat.sheen * Csheen;

    pdf = L.z * INV_PI;
    return INV_PI * mat.baseColor * mix(Fd + Fretro, ss, mat.subsurface) + Fsheen;
}

vec3 EvalMicrofacetReflection(Material mat, vec3 V, vec3 L, vec3 H, vec3 F, out float pdf)
{
    pdf = 0.0;
    if (L.z <= 0.0)
        return vec3(0.0);

    float D = GTR2Aniso(H.z, H.x, H.y, mat.ax, mat.ay);
    float G1 = SmithGAniso(abs(V.z), V.x, V.y, mat.ax, mat.ay);
    float G2 = G1 * SmithGAniso(abs(L.z), L.x, L.y, mat.ax, mat.ay);

    pdf = G1 * D / (4.0 * V.z);
    return F * D * G2 / (4.0 * L.z * V.z);
}

vec3 EvalMicrofacetRefraction(Material mat, float eta, vec3 V, vec3 L, vec3 H, vec3 F, out float pdf)
{
    pdf = 0.0;
    if (L.z >= 0.0)
        return vec3(0.0);

    float LDotH = dot(L, H);
    float VDotH = dot(V, H);

    float D = GTR2Aniso(H.z, H.x, H.y, mat.ax, mat.ay);
    float G1 = SmithGAniso(abs(V.z), V.x, V.y, mat.ax, mat.ay);
    float G2 = G1 * SmithGAniso(abs(L.z), L.x, L.y, mat.ax, mat.ay);
    float denom = LDotH + VDotH * eta;
    denom *= denom;
    float eta2 = eta * eta;
    float jacobian = abs(LDotH) / denom;

    pdf = G1 * max(0.0, VDotH) * D * jacobian / V.z;
    return pow(mat.baseColor, vec3(0.5)) * (1.0 - F) * D * G2 * abs(VDotH) * jacobian * eta2 / abs(L.z * V.z);
}

vec3 EvalClearcoat(Material mat, vec3 V, vec3 L, vec3 H, out float pdf)
{
    pdf = 0.0;
    if (L.z <= 0.0)
        return vec3(0.0);

    float VDotH = dot(V, H);

    float F = mix(0.04, 1.0, SchlickWeight(VDotH));
    float D = GTR1(H.z, mat.clearcoatRoughness);
    float G = SmithG(L.z, 0.25) * SmithG(V.z, 0.25);
    float jacobian = 1.0 / (4.0 * VDotH);

    pdf = D * H.z * jacobian;
    return vec3(F) * D * G;
}

vec3 DisneySample(State state, vec3 V, vec3 N, out vec3 L, out float pdf)
{
    pdf = 0.0;

    float r1 = rand();
    float r2 = rand();

    // TODO: Tangent and bitangent should be calculated from mesh (provided, the mesh has proper uvs)
    vec3 T, B;
    Onb(N, T, B);

    // Transform to shading space to simplify operations (NDotL = L.z; NDotV = V.z; NDotH = H.z)
    V = ToLocal(T, B, N, V);

    // Tint colors
    vec3 Csheen, Cspec0;
    float F0;
    TintColors(state.mat, state.eta, F0, Csheen, Cspec0);

    // Model weights
    float dielectricWt = (1.0 - state.mat.metallic) * (1.0 - state.mat.specTrans);
    float metalWt = state.mat.metallic;
    float glassWt = (1.0 - state.mat.metallic) * state.mat.specTrans;

    // Lobe probabilities
    float schlickWt = SchlickWeight(V.z);

    float diffPr = dielectricWt * Luminance(state.mat.baseColor);
    float dielectricPr = dielectricWt * Luminance(mix(Cspec0, vec3(1.0), schlickWt));
    float metalPr = metalWt * Luminance(mix(state.mat.baseColor, vec3(1.0), schlickWt));
    float glassPr = glassWt;
    float clearCtPr = 0.25 * state.mat.clearcoat;

    // Normalize probabilities
    float invTotalWt = 1.0 / (diffPr + dielectricPr + metalPr + glassPr + clearCtPr);
    diffPr *= invTotalWt;
    dielectricPr *= invTotalWt;
    metalPr *= invTotalWt;
    glassPr *= invTotalWt;
    clearCtPr *= invTotalWt;

    // CDF of the sampling probabilities
    float cdf[5];
    cdf[0] = diffPr;
    cdf[1] = cdf[0] + dielectricPr;
    cdf[2] = cdf[1] + metalPr;
    cdf[3] = cdf[2] + glassPr;
    cdf[4] = cdf[3] + clearCtPr;

    // Sample a lobe based on its importance
    float r3 = rand();

    if (r3 < cdf[0]) // Diffuse
    {
        L = CosineSampleHemisphere(r1, r2);
    }
    else if (r3 < cdf[2]) // Dielectric + Metallic reflection
    {
        vec3 H = SampleGGXVNDF(V, state.mat.ax, state.mat.ay, r1, r2);

        if (H.z < 0.0)
            H = -H;

        L = normalize(reflect(-V, H));
    }
    else if (r3 < cdf[3]) // Glass
    {
        vec3 H = SampleGGXVNDF(V, state.mat.ax, state.mat.ay, r1, r2);
        float F = DielectricFresnel(abs(dot(V, H)), state.eta);

        if (H.z < 0.0)
            H = -H;

        // Rescale random number for reuse
        r3 = (r3 - cdf[2]) / (cdf[3] - cdf[2]);

        // Reflection
        if (r3 < F)
        {
            L = normalize(reflect(-V, H));
        }
        else // Transmission
        {
            L = normalize(refract(-V, H, state.eta));
        }
    }
    else // Clearcoat
    {
        vec3 H = SampleGTR1(state.mat.clearcoatRoughness, r1, r2);

        if (H.z < 0.0)
            H = -H;

        L = normalize(reflect(-V, H));
    }

    L = ToWorld(T, B, N, L);
    V = ToWorld(T, B, N, V);

    return DisneyEval(state, V, N, L, pdf);
}

vec3 DisneyEval(State state, vec3 V, vec3 N, vec3 L, out float pdf)
{
    pdf = 0.0;
    vec3 f = vec3(0.0);

    // TODO: Tangent and bitangent should be calculated from mesh (provided, the mesh has proper uvs)
    vec3 T, B;
    Onb(N, T, B);

    // Transform to shading space to simplify operations (NDotL = L.z; NDotV = V.z; NDotH = H.z)
    V = ToLocal(T, B, N, V);
    L = ToLocal(T, B, N, L);

    vec3 H;
    if (L.z > 0.0)
        H = normalize(L + V);
    else
        H = normalize(L + V * state.eta);

    if (H.z < 0.0)
        H = -H;

    // Tint colors
    vec3 Csheen, Cspec0;
    float F0;
    TintColors(state.mat, state.eta, F0, Csheen, Cspec0);

    // Model weights
    float dielectricWt = (1.0 - state.mat.metallic) * (1.0 - state.mat.specTrans);
    float metalWt = state.mat.metallic;
    float glassWt = (1.0 - state.mat.metallic) * state.mat.specTrans;

    // Lobe probabilities
    float schlickWt = SchlickWeight(V.z);

    float diffPr = dielectricWt * Luminance(state.mat.baseColor);
    float dielectricPr = dielectricWt * Luminance(mix(Cspec0, vec3(1.0), schlickWt));
    float metalPr = metalWt * Luminance(mix(state.mat.baseColor, vec3(1.0), schlickWt));
    float glassPr = glassWt;
    float clearCtPr = 0.25 * state.mat.clearcoat;

    // Normalize probabilities
    float invTotalWt = 1.0 / (diffPr + dielectricPr + metalPr + glassPr + clearCtPr);
    diffPr *= invTotalWt;
    dielectricPr *= invTotalWt;
    metalPr *= invTotalWt;
    glassPr *= invTotalWt;
    clearCtPr *= invTotalWt;

    bool reflect = L.z * V.z > 0.;

    float tmpPdf = 0.0;
    float VDotH = abs(dot(V, H));

    // Diffuse
    if (diffPr > 0.0 && reflect)
    {
        f += EvalDisneyDiffuse(state.mat, Csheen, V, L, H, tmpPdf) * dielectricWt;
        pdf += tmpPdf * diffPr;
    }

    // Dielectric Reflection
    if (dielectricPr > 0.0 && reflect)
    {
        // Normalize for interpolating based on Cspec0
        float F = (DielectricFresnel(VDotH, 1.0 / state.mat.ior) - F0) / (1.0 - F0);

        f += EvalMicrofacetReflection(state.mat, V, L, H, mix(Cspec0, vec3(1.0), F), tmpPdf) * dielectricWt;
        pdf += tmpPdf * dielectricPr;
    }

    // Metallic Reflection
    if (metalPr > 0.0 && reflect)
    {
        // Tinted to base color
        vec3 F = mix(state.mat.baseColor, vec3(1.0), SchlickWeight(VDotH));

        f += EvalMicrofacetReflection(state.mat, V, L, H, F, tmpPdf) * metalWt;
        pdf += tmpPdf * metalPr;
    }

    // Glass/Specular BSDF
    if (glassPr > 0.0)
    {
        // Dielectric fresnel (achromatic)
        float F = DielectricFresnel(VDotH, state.eta);

        if (reflect)
        {
            f += EvalMicrofacetReflection(state.mat, V, L, H, vec3(F), tmpPdf) * glassWt;
            pdf += tmpPdf * glassPr * F;
        }
        else
        {
            f += EvalMicrofacetRefraction(state.mat, state.eta, V, L, H, vec3(F), tmpPdf) * glassWt;
            pdf += tmpPdf * glassPr * (1.0 - F);
        }
    }

    // Clearcoat
    if (clearCtPr > 0.0 && reflect)
    {
        f += EvalClearcoat(state.mat, V, L, H, tmpPdf) * 0.25 * state.mat.clearcoat;
        pdf += tmpPdf * clearCtPr;
    }

    return f * abs(L.z);
}

// Intersection

float SphereIntersect(float rad, vec3 pos, Ray r)
{
    vec3 op = pos - r.origin;
    float eps = 0.001;
    float b = dot(op, r.direction);
    float det = b * b - dot(op, op) + rad * rad;
    if (det < 0.0)
        return INF;

    det = sqrt(det);
    float t1 = b - det;
    if (t1 > eps)
        return t1;

    float t2 = b + det;
    if (t2 > eps)
        return t2;

    return INF;
}

float RectIntersect(in vec3 pos, in vec3 u, in vec3 v, in vec4 plane, in Ray r)
{
    vec3 n = vec3(plane);
    float dt = dot(r.direction, n);
    float t = (plane.w - dot(n, r.origin)) / dt;

    if (t > EPS)
    {
        vec3 p = r.origin + r.direction * t;
        vec3 vi = p - pos;
        float a1 = dot(u, vi);
        if (a1 >= 0.0 && a1 <= 1.0)
        {
            float a2 = dot(v, vi);
            if (a2 >= 0.0 && a2 <= 1.0)
                return t;
        }
    }

    return INF;
}

// Closest Hit

bool ClosestHit(Ray r, inout State state, inout LightSampleRec lightSample)
{
    float t = INF;
    float d;

#ifdef OPT_LIGHTS
    // Intersect Emitters
#ifdef OPT_HIDE_EMITTERS
if(state.depth > 0)
#endif
    for (int i = 0; i < numOfLights(); i++)
    {
        // Fetch light Data
		Light light = getLight(i);
        vec3 position = light.position;
        vec3 emission = light.emission;
        vec3 u        = light.u;
        vec3 v        = light.v;
        float radius  = light.radius;
        float area    = light.area;
        int type      = light.type;

        if (type == QUAD_LIGHT)
        {
           vec3 normal = normalize(cross(u, v));
#ifdef OPT_HIDE_EMITTERS
           if (dot(normal, r.direction) > 0.) // Hide backfacing quad light
                continue;
#endif 

            vec4 plane = vec4(normal, dot(normal, position));
            u *= 1.0f / dot(u, u);
            v *= 1.0f / dot(v, v);

            d = RectIntersect(position, u, v, plane, r);
            if (d < 0.)
                d = INF;
            if (d < t)
            {
                t = d;
                float cosTheta = dot(-r.direction, normal);
                lightSample.pdf = (t * t) / (area * cosTheta);
                lightSample.emission = emission;
                state.isEmitter = true;
            }
        }

        if (type == SPHERE_LIGHT)
        {
            d = SphereIntersect(radius, position, r);
            if (d < 0.)
                d = INF;
            if (d < t)
            {
                t = d;
                vec3 hitPt = r.origin + t * r.direction;
                float cosTheta = dot(-r.direction, normalize(hitPt - position));
                // TODO: Fix this. Currently assumes the light will be hit only from the outside
                lightSample.pdf = (t * t) / (area * cosTheta * 0.5);
                lightSample.emission = emission;
                state.isEmitter = true;
            }
        }
    }
#endif

	bool hit = getSceneHit(r, state);

    if (state.isEmitter && (!hit || state.hitDist > t))
        return true;

    // No intersections
    if (!hit)
        return false;

    // Ray hit a triangle and not a light source
    state.isEmitter = false;

    state.ffnormal = dot(state.normal, r.direction) <= 0.0 ? state.normal : -state.normal;

    return true;
}

bool AnyHit(Ray r, inout State state, float maxDist)
{

#ifdef OPT_LIGHTS
    // Intersect Emitters
    for (int i = 0; i < numOfLights(); i++)
    {
        // Fetch light Data
		Light light = getLight(i);
        vec3 position = light.position;
        vec3 emission = light.emission;
        vec3 u        = light.u;
        vec3 v        = light.v;
        float radius  = light.radius;
        float area    = light.area;
        int type      = light.type;

        // Intersect rectangular area light
        if (type == QUAD_LIGHT)
        {
            vec3 normal = normalize(cross(u, v));
            vec4 plane = vec4(normal, dot(normal, position));
            u *= 1.0f / dot(u, u);
            v *= 1.0f / dot(v, v);

            float d = RectIntersect(position, u, v, plane, r);
            if (d > 0.0 && d < maxDist)
                return true;
        }

        // Intersect spherical area light
        if (type == SPHERE_LIGHT)
        {
            float d = SphereIntersect(radius, position, r);
            if (d > 0.0 && d < maxDist)
                return true;
        }
    }
#endif

	bool hit = getSceneHit(r, state);
    return hit;
}

// Path tracer

void GetMaterial(inout State state, in Ray r)
{
    Material mat = state.mat;

    mat.roughness          = max(mat.roughness, 0.001);

    mat.clearcoatRoughness = mix(0.1, 0.001, mat.clearcoatRoughness); // Remapping from gloss to roughness

    mat.medium.anisotropy  = clamp(mat.medium.anisotropy, -0.9, 0.9);

#ifdef OPT_ROUGHNESS_MOLLIFICATION
    if(state.depth > 0)
        mat.roughness = max(mix(0.0, state.mat.roughness, roughnessMollificationAmt), mat.roughness);
#endif

    float aspect = sqrt(1.0 - mat.anisotropic * 0.9);
    mat.ax = max(0.001, mat.roughness / aspect);
    mat.ay = max(0.001, mat.roughness * aspect);

    state.mat = mat;
    state.eta = dot(r.direction, state.normal) < 0.0 ? (1.0 / mat.ior) : mat.ior;
}

// TODO: Recheck all of this
#if defined(OPT_MEDIUM) && defined(OPT_VOL_MIS)
vec3 EvalTransmittance(Ray r)
{
    LightSampleRec lightSample;
    State state;
    vec3 transmittance = vec3(1.0);

    for (int depth = 0; depth < maxDepth; depth++)
    {
        bool hit = ClosestHit(r, state, lightSample);

        // If no hit (environment map) or if ray hit a light source then return transmittance
        if (!hit || state.isEmitter)
            break;

        // TODO: Get only parameters that are needed to calculate transmittance
        GetMaterial(state, r);

        bool alphatest = (state.mat.alphaMode == ALPHA_MODE_MASK && state.mat.opacity < state.mat.alphaCutoff) || (state.mat.alphaMode == ALPHA_MODE_BLEND && rand() > state.mat.opacity);
        bool refractive = (1.0 - state.mat.metallic) * state.mat.specTrans > 0.0;

        // Refraction is ignored (Not physically correct but helps with sampling lights from inside refractive objects)
        if(hit && !(alphatest || refractive))
            return vec3(0.0);

        // Evaluate transmittance
        if (dot(r.direction, state.normal) > 0. && state.mat.medium.type != MEDIUM_NONE)
        {
            vec3 color = state.mat.medium.type == MEDIUM_ABSORB ? vec3(1.0) - state.mat.medium.color : vec3(1.0);
            transmittance *= exp(-color * state.mat.medium.density * state.hitDist);
        }

        // Move ray origin to hit point
        r.origin = state.fhp + r.direction * EPS;
    }

    return transmittance;
}
#endif

// DirectLight
vec3 DirectLight(in Ray r, in State state, bool isSurface)
{
    vec3 Ld = vec3(0.0);
    vec3 Li = vec3(0.0);
    vec3 scatterPos = state.fhp + state.normal * EPS;

    ScatterSampleRec scatterSample;

    // Environment Light
#ifdef OPT_ENVMAP
#ifndef OPT_UNIFORM_LIGHT
    {
        vec3 color;
        vec4 dirPdf = SampleEnvMap(Li);
        vec3 lightDir = dirPdf.xyz;
        float lightPdf = dirPdf.w;

        Ray shadowRay = Ray(scatterPos, lightDir);

#if defined(OPT_MEDIUM) && defined(OPT_VOL_MIS)
        // If there are volumes in the scene then evaluate transmittance rather than a binary anyhit test
        Li *= EvalTransmittance(shadowRay);

        if (isSurface)
            scatterSample.f = DisneyEval(state, -r.direction, state.ffnormal, lightDir, scatterSample.pdf);
        else
        {
            float p = PhaseHG(dot(-r.direction, lightDir), state.medium.anisotropy);
            scatterSample.f = vec3(p);
            scatterSample.pdf = p;
        }

        if (scatterSample.pdf > 0.0)
        {
            float misWeight = PowerHeuristic(lightPdf, scatterSample.pdf);
            if (misWeight > 0.0)
                Ld += misWeight * Li * scatterSample.f * envMapIntensity / lightPdf;
        }
#else
        // If there are no volumes in the scene then use a simple binary hit test
        bool inShadow = AnyHit(shadowRay, state, INF - EPS);

        if (!inShadow)
        {
            scatterSample.f = DisneyEval(state, -r.direction, state.ffnormal, lightDir, scatterSample.pdf);

            if (scatterSample.pdf > 0.0)
            {
                float misWeight = PowerHeuristic(lightPdf, scatterSample.pdf);
                if (misWeight > 0.0)
                    Ld += misWeight * Li * scatterSample.f * envMapIntensity / lightPdf;
            }
        }
#endif
    }
#endif
#endif

    // Analytic Lights 
#ifdef OPT_LIGHTS
    {
        LightSampleRec lightSample;
        Light light;

        //Pick a light to sample
        int index = int(rand() * float(numOfLights()));

        light = getLight(index);

        light = Light(light.position, light.emission, light.u, light.v, light.radius, light.area, light.type);
        SampleOneLight(light, scatterPos, lightSample);
        Li = lightSample.emission;

        if (dot(lightSample.direction, lightSample.normal) < 0.0) // Required for quad lights with single sided emission
        {
            Ray shadowRay = Ray(scatterPos, lightSample.direction);

            // If there are volumes in the scene then evaluate transmittance rather than a binary anyhit test
#if defined(OPT_MEDIUM) && defined(OPT_VOL_MIS)
            Li *= EvalTransmittance(shadowRay);

            if (isSurface)
                scatterSample.f = DisneyEval(state, -r.direction, state.ffnormal, lightSample.direction, scatterSample.pdf);
            else
            {
                float p = PhaseHG(dot(-r.direction, lightSample.direction), state.medium.anisotropy);
                scatterSample.f = vec3(p);
                scatterSample.pdf = p;
            }

            float misWeight = 1.0;
            if(light.area > 0.0) // No MIS for distant light
                misWeight = PowerHeuristic(lightSample.pdf, scatterSample.pdf);

            if (scatterSample.pdf > 0.0)
                Ld += misWeight * scatterSample.f * Li / lightSample.pdf;
#else
            // If there are no volumes in the scene then use a simple binary hit test
            bool inShadow = AnyHit(shadowRay, state, lightSample.dist - EPS);

            if (!inShadow)
            {
                scatterSample.f = DisneyEval(state, -r.direction, state.ffnormal, lightSample.direction, scatterSample.pdf);

                float misWeight = 1.0;
                if(light.area > 0.0) // No MIS for distant light
                    misWeight = PowerHeuristic(lightSample.pdf, scatterSample.pdf);

                if (scatterSample.pdf > 0.0)
                    Ld += misWeight * Li * scatterSample.f / lightSample.pdf;
            }
#endif
        }
    }
#endif

    return Ld;
}

vec4 PathTrace(Ray r)
{
    vec3 radiance = vec3(0.0);
    vec3 throughput = vec3(1.0);
    State state;
    LightSampleRec lightSample;
    ScatterSampleRec scatterSample;

    // FIXME: alpha from material opacity/medium density
    float alpha = 1.0;

    // For medium tracking
    bool inMedium = false;
    bool mediumSampled = false;
    bool surfaceScatter = false;

    initLights();

    const int maxDepth = 4;
    for (int depth = 0; depth < maxDepth; depth++)
    {
        state.depth = depth;
        bool hit = ClosestHit(r, state, lightSample);

        if (!hit)
        {
#if defined(OPT_BACKGROUND) || defined(OPT_TRANSPARENT_BACKGROUND)
            if (state.depth == 0)
                alpha = 0.0;
#endif

#ifdef OPT_HIDE_EMITTERS
            if(state.depth > 0)
#endif
            {
#ifdef OPT_UNIFORM_LIGHT
                radiance += getBackground(r) * throughput;
#else
#ifdef OPT_ENVMAP
                vec4 envMapColPdf = EvalEnvMap(r);

                float misWeight = 1.0;

                // Gather radiance from envmap and use scatterSample.pdf from previous bounce for MIS
                if (state.depth > 0)
                    misWeight = PowerHeuristic(scatterSample.pdf, envMapColPdf.w);

#if defined(OPT_MEDIUM) && !defined(OPT_VOL_MIS)
                if(!surfaceScatter)
                    misWeight = 1.0f;
#endif

                if(misWeight > 0.)
                    radiance += misWeight * envMapColPdf.rgb * throughput * envMapIntensity;
#endif
#endif
             }
             break;
        }

        GetMaterial(state, r);

        // Gather radiance from emissive objects. Emission from meshes is not importance sampled
        radiance += state.mat.emission * throughput;

#ifdef OPT_LIGHTS

        // Gather radiance from light and use scatterSample.pdf from previous bounce for MIS
        if (state.isEmitter)
        {
            float misWeight = 1.0;

            if (state.depth > 0)
                misWeight = PowerHeuristic(scatterSample.pdf, lightSample.pdf);

#if defined(OPT_MEDIUM) && !defined(OPT_VOL_MIS)
            if(!surfaceScatter)
                misWeight = 1.0f;
#endif

            radiance += misWeight * lightSample.emission * throughput;

            break;
        }
#endif
        // Stop tracing ray if maximum depth was reached
        if(state.depth == maxDepth)
            break;

#ifdef OPT_MEDIUM

        mediumSampled = false;
        surfaceScatter = false;

        // Handle absorption/emission/scattering from medium
        // TODO: Handle light sources placed inside medium
        if(inMedium)
        {
            if(state.medium.type == MEDIUM_ABSORB)
            {
                throughput *= exp(-(1.0 - state.medium.color) * state.hitDist * state.medium.density);
            }
            else if(state.medium.type == MEDIUM_EMISSIVE)
            {
                radiance += state.medium.color * state.hitDist * state.medium.density * throughput;
            }
            else
            {
                // Sample a distance in the medium
                float scatterDist = min(-log(rand()) / state.medium.density, state.hitDist);
                mediumSampled = scatterDist < state.hitDist;

                if (mediumSampled)
                {
                    throughput *= state.medium.color;

                    // Move ray origin to scattering position
                    r.origin += r.direction * scatterDist;
                    state.fhp = r.origin;

                    // Transmittance Evaluation
                    radiance += DirectLight(r, state, false) * throughput;

                    // Pick a new direction based on the phase function
                    vec3 scatterDir = SampleHG(-r.direction, state.medium.anisotropy, rand(), rand());
                    scatterSample.pdf = PhaseHG(dot(-r.direction, scatterDir), state.medium.anisotropy);
                    r.direction = scatterDir;
                }
            }
        }

        // If medium was not sampled then proceed with surface BSDF evaluation
        if (!mediumSampled)
        {
#endif
#ifdef OPT_ALPHA_TEST

            // Ignore intersection and continue ray based on alpha test
            if ((state.mat.alphaMode == ALPHA_MODE_MASK && state.mat.opacity < state.mat.alphaCutoff) ||
                (state.mat.alphaMode == ALPHA_MODE_BLEND && rand() > state.mat.opacity))
            {
                scatterSample.L = r.direction;
                state.depth--;
            }
            else
#endif
            {
                surfaceScatter = true;

                // Next event estimation
                radiance += DirectLight(r, state, true) * throughput;

                // Sample BSDF for color and outgoing direction
                scatterSample.f = DisneySample(state, -r.direction, state.ffnormal, scatterSample.L, scatterSample.pdf);
                if (scatterSample.pdf > 0.0)
                    throughput *= scatterSample.f / scatterSample.pdf;
                else
                    break;
            }

            // Move ray origin to hit point and set direction for next bounce
            r.direction = scatterSample.L;
            r.origin = state.fhp + r.direction * EPS;

#ifdef OPT_MEDIUM

            // Note: Nesting of volumes isn't supported due to lack of a volume stack for performance reasons
            // Ray is in medium only if it is entering a surface containing a medium
            if (dot(r.direction, state.normal) < 0. && state.mat.medium.type != MEDIUM_NONE)
            {
                inMedium = true;
                // Get medium params from the intersected object
                state.medium = state.mat.medium;
            }
            // FIXME: Objects clipping or inside a medium were shaded incorrectly as inMedium would be set to false.
            // This hack works for now but needs some rethinking
            else if(state.mat.medium.type != MEDIUM_NONE)
                inMedium = false;
        }
#endif

#ifdef OPT_RR
        // Russian roulette
        if (state.depth >= OPT_RR_DEPTH)
        {
            float q = min(max(throughput.x, max(throughput.y, throughput.z)) + 0.001, 0.95);
            if (rand() > q)
                break;
            throughput /= q;
        }
#endif

    }

    return vec4(radiance, alpha);
}

float keydown(int code) {
    return texelFetch(iChannel3, ivec2(code, 0),  0).x;
}

float PackMouseXY(vec2 mouse) {
    uvec2 uv = uvec2(mouse);
    uint ui = uv.x + (uv.y << 16);
    return uintBitsToFloat(ui);
}

vec2 UnpackMouseXY(float mouse) {
    uint ui = floatBitsToUint(mouse);
    uvec2 uv = uvec2(ui % 65536u, ui >> 16);
    return vec2(uv);
    return unpackUnorm2x16(floatBitsToUint(mouse))*65536.0;
}

// Camera

mat3 yaw_pitch_roll(float yaw, float pitch, float roll)
{
    mat3 R = mat3(vec3(cos(yaw), sin(yaw), 0.0), vec3(-sin(yaw), cos(yaw), 0.0), vec3(0.0, 0.0, 1.0));
    mat3 S = mat3(vec3(1.0, 0.0, 0.0), vec3(0.0, cos(pitch), sin(pitch)), vec3(0.0, -sin(pitch), cos(pitch)));
    mat3 T = mat3(vec3(cos(roll), 0.0, sin(roll)), vec3(0.0, 1.0, 0.0), vec3(-sin(roll), 0.0, cos(roll)));

    return R * S * T;
}

Ray getCamerayRay(vec2 fragCoord) {

    vec4 cameraData = texelFetch(iChannel0, ivec2(CAMERA_POS, 0), 0);
    vec3 cameraPos = cameraData.xyz;

    vec4 forwardData = texelFetch(iChannel0, ivec2(CAMERA_DIRECTION, 0), 0);
    vec3 forward = normalize(forwardData.xyz);

    vec4 zoomData = texelFetch(iChannel0, ivec2(CAMERA_ZOOM, 0), 0);
    float zoom = zoomData.x;

    vec3 right = normalize(cross(forward, vec3(0.0, 1.0, 0.0)));
    vec3 up = normalize(cross(right, forward));

    vec2 uv = (fragCoord+vec2(rand(), rand())-0.5*iResolution.xy)/iResolution.x;
    vec3 viewDir = normalize(forward * zoom + right * uv.x + up * uv.y);

    //if (iMouse.z > 0.) 
    {
        vec2 R = iResolution.xy;
        float roll = 2. * PI * float(iMouse.x - R.x / 2.) / float(R.x);
        float yaw = PI * float(iMouse.y - R.y / 2.) / float(R.y);

        mat3 M = yaw_pitch_roll(yaw, 0., roll);
        cameraPos = M * cameraPos;
        viewDir = M * viewDir;
    } 

    Ray ray = Ray(cameraPos, viewDir);
    return ray;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    InitRNG(fragCoord, iFrame);

    // Camera    
    Ray ray = getCamerayRay(fragCoord);

    // Pathtrace
    vec4 col = PathTrace(ray);

    fragColor = col;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec4 cameraData = texelFetch(iChannel0, ivec2(CAMERA_POS, 0), 0);
    bool cameraUpdated = cameraData.w > 0.;

    vec4 forwardData = texelFetch(iChannel0, ivec2(CAMERA_DIRECTION, 0), 0);
    bool forwardUpdated = forwardData.w > 0.;

    vec4 zoomData = texelFetch(iChannel0, ivec2(CAMERA_ZOOM, 0), 0);
    bool zoomUpdated = zoomData.w > 0.;

    bool dataUpdated = cameraUpdated || forwardUpdated || zoomUpdated || iMouse.z > 0.;

    // Read data
    vec2 uv = fragCoord.xy / iResolution.xy;
    vec4 col = texture(iChannel1, uv);

    int iFrameLast = int(texelFetch(iChannel2, ivec2(0.), 0).x);

    // Accumulate
    if(all(equal(ivec2(fragCoord), ivec2(0)))) {
        fragColor = vec4(dataUpdated ? iFrame : iFrameLast, 0., 0., 0.);
    } else {
        if (dataUpdated) {
            fragColor = col;
        } else {
            vec4 previousCol = texelFetch(iChannel2, ivec2(fragCoord), 0);
            float coeff = 1./float((iFrame - iFrameLast)+1);
            fragColor = previousCol * (1. - coeff) + col * coeff;
        }
    }
}

// Fork of "Stanford Bunny ZMAABB." by BrunoLevy. https://shadertoy.com/view/ttcSzr
// 2025-10-20 11:33:32

// A more efficient version of https://www.shadertoy.com/view/wtG3z3
// This one uses a version of Terdiman's zero-memory AABB
//      and loads mesh data in Buffer A.

// Uncomment next line to deactivate acceleration structure.
// #define NAIVE


ivec3 get_facet(in int f) {
    return ivec3(
        get_data(MESH_DATA_OFFSET,3*f),
        get_data(MESH_DATA_OFFSET,3*f+1),
        get_data(MESH_DATA_OFFSET,3*f+2)
    );
}

const float FARAWAY=1e30;

struct Camera {
    vec3 Obs;
    vec3 View;
    vec3 Up;
    vec3 Horiz;
    float H;
    float W;
    float z;
};

struct Ray {
    vec3 Origin;
    vec3 Dir;
};

Camera camera(in vec3 Obs, in vec3 LookAt, in float aperture) {
   Camera C;
   C.Obs = Obs;
   C.View = normalize(LookAt - Obs);
   C.Horiz = normalize(cross(vec3(0.0, 0.0, 1.0), C.View));
   C.Up = cross(C.View, C.Horiz);
   C.W = float(iResolution.x);
   C.H = float(iResolution.y);
   C.z = (C.H/2.0) / tan((aperture * 3.1415 / 180.0) / 2.0);
   return C;
}

Ray launch(in Camera C, in vec2 XY) {
   return Ray(
      C.Obs,
      C.Obs+C.z*C.View+(XY.x-C.W/2.0)*C.Horiz+(XY.y-C.H/2.0)*C.Up 
   );
}

struct Material {
   vec3 Ka;
   vec3 Kd;
   vec3 Ks;
   float s;
   vec3 Ke;
};

struct Intersection {
   float t;
   Material material;
   vec3 P;
   vec3 N;
};

Intersection intersection() {
   Intersection I;
   I.t = FARAWAY;
   return I;
}

struct Sphere {
   vec3 Center;
   float R;
};

bool intersect_sphere(in Ray R, in Sphere S, out float t) {
   vec3 CO = R.Origin - S.Center;
   float a = dot(R.Dir, R.Dir);
   float b = 2.0*dot(R.Dir, CO);
   float c = dot(CO, CO) - S.R*S.R;
   float delta = b*b - 4.0*a*c;
   if(delta < 0.0) {
      return false;
   }
   t = (-b-sqrt(delta)) / (2.0*a);
   return (t > 0.0);
}

void sphere(in Ray R, in Sphere S, in Material M, inout Intersection I) {
   float t;
   if(intersect_sphere(R, S, t) && t < I.t) {
      I.t = t;
      I.material = M;
      I.P = R.Origin + t*R.Dir;
      I.N = normalize(I.P - S.Center);
   }
}


bool intersect_triangle(
    in Ray R, in vec3 A, in vec3 B, in vec3 C, out float t, 
    out float u, out float v, out vec3 N
) { 
   // Möller et Trumbore, « Fast, Minimum Storage Ray-Triangle Intersection », 
   // Journal of Graphics Tools, vol. 2,‎ 1997, p. 21–28 
   // https://en.wikipedia.org/wiki/M%C3%B6ller%E2%80%93Trumbore_intersection_algorithm 
   // (with small adaptations: branchless, and reusing the normal vector)
   // 
   // Notation: O = R.Origin; D = R.Dir)
   //           E1 = B-A; E2 = C-A
   // 
   // (1) O + tD = A + uE1 + vE2 
   // (2) uE1 + vE2 -tD = O-A
   // 
   //                [u]
   // (3) [E1|E2|-D] [v] = O-A
   //                [t]
   // 
   //  (where [E1|E2|-D] is the 3x3 matrix with E1,E2,-D as its columns)
   //
   //  Using Cramer's formula for the solution of:
   //
   //    [a11 a12 a13][x1]   [b1]
   //    [a12 a22 a23][x2] = [b2]
   //    [a31 a32 a33][x3]   [b3]
   //
   //  gives: 
   // 
   //        |b1 a12 a13|   |a11 a12 a13|
   //   x1 = |b2 a22 a23| / |a21 a22 a23|
   //        |b3 a32 a33|   |a31 a32 a33|
   //
   //        |a11 b1 a13|   |a11 a12 a13|
   //   x2 = |a21 b2 a23| / |a21 a22 a23|
   //        |a31 b3 a33|   |a31 a32 a33|
   //
   //        |a11 a12 b1|   |a11 a12 a13|
   //   x3 = |a21 a22 b2| / |a21 a22 a23|
   //        |a31 a32 b3|   |a31 a32 a33|
   // 
   // Now we get:
   //
   //   u = (O-A,E2,-D) / (E1,E2,-D)
   //   v = (E1,O-A,-D) / (E1,E2,-D)
   //   t = (E1,E2,O-A) / (E1,E2,-D)
   // 
   // where (A,B,C) denotes the determinant of the 3x3 matrix with A,B,C as its
   //  column vectors.
   // 
   // Now we use the following identities:
   //   (A,B,C) = dot(A,cross(B,C))  (develop the determinant w.r.t. first column)
   //   (B,A,C) = -(A,B,C)           (swapping two vectors changes the sign)
   //   (B,C,A) =  (A,B,C)           (circular permutation does not change the sign)
   // 
   // Now we get:
   //
   // u = -(E2,O-A,D)  / (D,E1,E2)
   // v =  (E1,O-A,D)  / (D,E1,E2)
   // t = -(O-A,E1,E2) / (D,E1,E2)  
   //
   // Using N=cross(E1,E2); AO = O-A; DAO = cross(D,AO)
   //  gives the following code : 
   vec3 E1 = B-A;
   vec3 E2 = C-A;
         N = cross(E1,E2);
   float det = -dot(R.Dir, N);
   float invdet = 1.0/det;
   vec3 AO  = R.Origin - A;
   vec3 DAO = cross(AO, R.Dir);
   u =  dot(E2,DAO) * invdet;
   v = -dot(E1,DAO) * invdet;
   t =  dot(AO,N)  * invdet; 
   return (det >= 1e-6 && t >= 0.0 && u >= 0.0 && v >= 0.0 && (u+v) <= 1.0);
}

void triangle(in Ray R, vec3 A, vec3 B, vec3 C, in Material M, inout Intersection I) {
   float t,u,v;
   vec3 N;
   if(intersect_triangle(R, A,B,C, t, u, v, N) && t < I.t) {
      I.t = t;
      I.material = M;
      I.P = R.Origin + t*R.Dir;
      I.N = normalize(N);
   }
}

bool segment_box_intersection(
  in vec3 q1,
  in vec3 dirinv,
  in vec3 boxmin,
  in vec3 boxmax,
  in float t // t of current intersection, used for pruning, see iq's comment.
) {  
   // References: 
   //    https://tavianator.com/fast-branchless-raybounding-box-intersections/ 
   vec3 T1 = dirinv*(boxmin - q1);
   vec3 T2 = dirinv*(boxmax - q1);
   vec3 Tmin = min(T1,T2);
   vec3 Tmax = max(T1,T2);
   float tmin = max(max(Tmin.x, Tmin.y),Tmin.z);
   float tmax = min(min(Tmax.x, Tmax.y),Tmax.z);    
   return (tmax >= 0.0) && (tmin <= tmax) && (tmin <= t);
}

int stack_top = -1;
int stack_b[10];
int stack_e[10];

bool stack_empty() {
  return (stack_top < 0);
}

void stack_push(in int b, in int e) {
  stack_top++;
  stack_b[stack_top] = b;
  stack_e[stack_top] = e;  
}

void stack_pop(out int b, out int e) {
  b = stack_b[stack_top];
  e = stack_e[stack_top];
  --stack_top;
}

vec3 decode_vertex(int xyz) {
   int x = (xyz & 1023);
   int y = (xyz & (1023 << 10)) >> 10;
   int z = (xyz & (1023 << 20)) >> 20;
   return bbox_min + vec3(float(x), float(y), float(z)) / 1023.0 * (bbox_max - bbox_min);
}

vec3 min3(in vec3 p1, in vec3 p2, in vec3 p3) {
    return min(min(p1,p2),p3);
}

vec3 max3(in vec3 p1, in vec3 p2, in vec3 p3) {
    return max(max(p1,p2),p3);
}

void mesh_AABB(in Ray R, in Material M, inout Intersection I) {
  // References:
  //   http://www.codercorner.com/ZeroByteBVH.pdf 
  // With some adaptations:
  //   a) here the tree is balanced
  //   b) sorting coord. simply cycles between X,Y,Z   
  //   c) for now I always use 6 triangles to compute bbox
  // Consequence of a,b,c: the AABB is fully implicit, fully described by
  //  the order of the triangles in the mesh.
  // Mesh sorting program will be posted here shortly.

#ifdef NAIVE    
  for(int i=0; i<facets_data_size; ++i) {
      ivec3 F = get_facet(i);
      vec3 p1 = decode_vertex(F.x);
      vec3 p2 = decode_vertex(F.y);
      vec3 p3 = decode_vertex(F.z);
      triangle(R, p1, p2, p3, M, I);      
  }
#else    
    vec3 invDir = vec3(1.0/R.Dir.x, 1.0/R.Dir.y, 1.0/R.Dir.z);
    stack_push(0, facets_data_size);
    while(!stack_empty()) {
        int b,e;
        stack_pop(b,e);
        if(e-b <= 16) {
            for(int i=b; i<e; ++i) {
                ivec3 F = get_facet(i);
                vec3 p1 = decode_vertex(F.x);
                vec3 p2 = decode_vertex(F.y);
                vec3 p3 = decode_vertex(F.z);
                triangle(R, p1, p2, p3, M, I);
            }
        } else {
           ivec3 F = get_facet(b);
           vec3 p1 = decode_vertex(F.x);
           vec3 p2 = decode_vertex(F.y);
           vec3 p3 = decode_vertex(F.z);
           const int nbb = 6; // Number of triangles used to compute the bbox
                              // (for now fixed, could be stored in the mesh as well).

           // Compute bbox (and test triangles used to compute the bbox, they
           // are not part of the tree).
           triangle(R, p1, p2, p3, M, I);
           vec3 bbox_min = min3(p1,p2,p3); 
           vec3 bbox_max = max3(p1,p2,p3);
           for(int i=b+1; i<b+nbb; ++i) {
              ivec3 F = get_facet(i);
              vec3 p1 = decode_vertex(F.x);
              vec3 p2 = decode_vertex(F.y);
              vec3 p3 = decode_vertex(F.z);
              triangle(R, p1, p2, p3, M, I);
              bbox_min = min(bbox_min, min3(p1,p2,p3)); 
              bbox_max = max(bbox_max, max3(p1,p2,p3));
           }

           if(segment_box_intersection(R.Origin, invDir, bbox_min, bbox_max, I.t)) { 
              b += nbb;
              int m = b + (e-b)/2;
              // Small optimization: traverse nearest child first (so that pruning is
              // more likely to occur).
              int coord = (stack_top + 1)%3; // coord along which current node is split
              if(R.Dir[coord] < 0.0) {
                stack_push(b,m);
                stack_push(m,e);                  
              } else {
                stack_push(m,e);
                stack_push(b,m); // positive -> process this child first                                    
              } 
              // TODO: elimination of the terminal recursion (latest pushed node is
              // popped immediatly after, see iq's comment).
           }     
        }
    }
#endif    
}  


void sky(out vec4 fragColor, in Ray R) {
   vec3 V = normalize(R.Dir);
   float s = 0.5 * (V.z + 1.0);
   fragColor = mix( 
      vec4(0.0, 0.0, 0.0, 1.0),
      vec4(1.0, 1.0, 2.0, 1.0),
      s
   );
}


vec3 lighting( in Intersection I, in vec3 LightPos) {
   vec3 L = LightPos - I.P;
   float diffuse = max(dot(I.N, L)/length(L),0.0);
   return diffuse * I.material.Kd;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ) {
   float alpha = float(iFrame)/30.0;
   float c = cos(alpha);
   float s = sin(alpha);
   Camera C = camera(
       vec3(2.0*c, 2.0*s, 1.5),
       vec3(0.0, 0.0, 0.0),
       30.0       
   );
   Ray R = launch(C, fragCoord);
   Intersection I = intersection();

   const Material WHITE = Material(
      vec3(0.0, 0.0, 0.0),
      vec3(1.0, 1.0, 1.0),
      vec3(0.0, 0.0, 0.0),
      0.0,
      vec3(0.0, 0.0, 0.0)
   );

   const Material RED = Material(
      vec3(0.0, 0.0, 0.0),
      vec3(1.0, 0.0, 0.0),
      vec3(0.0, 0.0, 0.0),
      0.0,
      vec3(0.0, 0.0, 0.0)
   );

   mesh_AABB(R, WHITE, I);
   sphere(R, Sphere(vec3(0.0, 0.0, -1001.0), 1000.0), WHITE, I);

   if(I.t == FARAWAY) {
      sky(fragColor, R);
   } else {
      fragColor.xyz = I.material.Ka;
      fragColor.xyz += lighting(I, vec3(0.5, 1.3, 0.5));
   }
}

#pragma optimize(on)

// An array implemented as a huge switch() statement.
// Inspired from https://www.shadertoy.com/view/tlX3W7 (see 'microcode RAM')
// See also my earlier experiment here: https://www.shadertoy.com/view/3lK3Wd
//   I did not find a better way of sending a large array,
//   * using a big const array eats up all the registers in some implementations,
//      See for instance my previous version: https://www.shadertoy.com/view/wtG3z3
//        Works well on my Linux box (driver probably uses a SSBO), 
//           but lags at 0.5 FPS :-( under windows. 
//   * using a function instead stores all the values in the code segment. The function
//      is only called at the first frame to send all the data to BufferA. Then all this
//      code is probably evicted from the GPU code cache.
//   * one can send large arrays using this trick 
//   * note the #pragma optimize(off) (since this shader is only executed once, it is OK),
//     without it compilation time becomes veeeery long !
//     (https://shadertoyunofficial.wordpress.com/2017/11/19/avoiding-compiler-crash-or-endless-compilation/)
//     ... argh, under windows, even with the flag, it takes ages (100 seconds if THE_BIG_ONE is defined)
//     Got it: it is the angle GLSL to HLSL transpiler that takes all the time. 
//      You can try disable it and using OpenGL directly instead (about:config in firefox).

/*
// MeshCompiler [Bruno Levy Jan 2020]
// Converts a .obj (Alias|Wavefront) tri mesh into an AABB, encoded in GLSL, for ShaderToy.
//
// Fits in 256 lines :-)

#include <iostream>
#include <vector>
#include <algorithm>

// Sorts a vector and removes duplicated entries.
template <typename VECTOR> inline void sort_unique(VECTOR& v) {
    std::sort(v.begin(), v.end()); v.erase(std::unique(v.begin(), v.end()), v.end());
}

// -------- GLSL-compatible types //-----------------------------------------------------

template <class T> class gvec3 {
public:
    gvec3() {  }
    gvec3(T x_in, T y_in, T z_in) : x(x_in), y(y_in), z(z_in) {  }
    T& operator[](int i)             { return (&x)[i]; }
    const T& operator[](int i) const { return (&x)[i]; }
    T x,y,z;
};

template <class T> inline gvec3<T> operator+(gvec3<T> u, gvec3<T> v) {
    return gvec3<T>(u.x+v.x,u.y+v.y,u.z+v.z);
}

template <class T> inline gvec3<T> min(gvec3<T> u, gvec3<T> v) {
    return gvec3<T>(std::min(u.x,v.x),std::min(u.y,v.y),std::min(u.z,v.z));
}

template <class T> inline gvec3<T> max(gvec3<T> u, gvec3<T> v) {
    return gvec3<T>(std::max(u.x,v.x),std::max(u.y,v.y),std::max(u.z,v.z));
}

typedef gvec3<double> vec3; typedef gvec3<int> ivec3;

// -------- Encode/Decode //----------------------------------------------------------

// Encodes a vertex, using 10 bits per coordinate, relative to bbox
int encode_vertex(vec3 p, vec3 bbox_min, vec3 bbox_max) {
    double x = (p.x - bbox_min.x) / (bbox_max.x - bbox_min.x);
    double y = (p.y - bbox_min.y) / (bbox_max.y - bbox_min.y);
    double z = (p.z - bbox_min.z) / (bbox_max.z - bbox_min.z);
    int ix = int(x * 1023.0); int iy = int(y * 1023.0); int iz = int(z * 1023.0);
    return ix | (iy << 10) | (iz << 20);
}

// Decodes the three integer coordinates of a vertex (10 bits per coordinate)
ivec3 decode_vertex(int xyz) {
   return ivec3( 
       (xyz & 1023),	
       (xyz & (1023 << 10)) >> 10, 
       (xyz & (1023 << 20)) >> 20
   );
}

// Encodes the coordinates of the three vertices of a triangle in an ivec3
ivec3 encode_facet(vec3 p1, vec3 p2, vec3 p3, vec3 bbox_min, vec3 bbox_max) {
    return ivec3(
	encode_vertex(p1, bbox_min, bbox_max),
	encode_vertex(p2, bbox_min, bbox_max),
	encode_vertex(p3, bbox_min, bbox_max)	    
    );
}

// -------- Mesh geometry //-------------------------------------------------------------------

// Computes (three times) the barycenter of a facet
ivec3 facet_center(ivec3 f) {
    return decode_vertex(f.x) + decode_vertex(f.y) + decode_vertex(f.z);
}

// Computes the (floating-point) bbox of a pointset
void get_bbox(const std::vector<vec3>& pts, vec3& bbox_min, vec3& bbox_max) {
    bbox_min = pts[0]; bbox_max = pts[0];
    for(int i=1; i<pts.size(); ++i) {
	bbox_min = min(bbox_min, pts[i]); bbox_max = max(bbox_max, pts[i]);	
    }
}

// Computes the (integer) bbox of a triangle
void get_facet_bbox(ivec3 f, ivec3& bbox_min, ivec3& bbox_max) {
    bbox_min = decode_vertex(f.x); bbox_max = decode_vertex(f.x);
     ivec3 p = decode_vertex(f.y); bbox_min = min(bbox_min, p); bbox_max = max(bbox_max, p);
           p = decode_vertex(f.z); bbox_min = min(bbox_min, p); bbox_max = max(bbox_max, p);
}

// -------- I/O //---------------------------------------------------------------------------

// Outputs a floating point number, 6.6 digits
std::string format(double x) {
    static char buff[300]; sprintf(buff,"%-6.6f",x); return std::string(buff);
}

// Outputs an integer in hexa, 8 digits
std::string format_int(int x) {
    static char buff[300]; sprintf(buff,"0x%08x",x); return buff;
}

// Outputs an integer in hexa, 4 digits
std::string format_small_int(int x) {
    static char buff[300]; sprintf(buff,"0x%04x",x); return buff;
}

// Generates a GLSL function that encodes an array of ivec3, as a (huge) switch statement
// (It is stupid, I know, but this is the only way I found to send a big array to ShaderToy).
void gen_ivec3_func(std::ostream& out, const std::vector<ivec3>& array, std::string name) {
    out << "#pragma optimize(off)" << std::endl;
    out << "const int " << name << "_size = " << array.size() << ";" << std::endl;
    out << "ivec3 " << name << "(in int i) {" << std::endl;
    out << "#  ifdef R"   << std::endl;
    out << "#    undef R" << std::endl;
    out << "#  endif"     << std::endl;
    out << "#  define R(i,a,b,c) case i: r=ivec3(a,b,c); break;" << std::endl;
    out << "  ivec3 r;" << std::endl;
    out << "  switch(i) {" << std::endl;
    for(int i=0; i<int(array.size()); ++i) {
       out << "    R(" << format_small_int(i) << ","
	               << format_int(array[i].x) << "," << format_int(array[i].y) << "," << format_int(array[i].z) << ")";
       if(!((i+1)%10)) { out << std::endl; }
    }
    out << "  }" << std::endl;
    out << "  return r;" << std::endl;
    out << "}" << std::endl;
}

// Loads a mesh from a .obj (Alias|Wavefront) file. Gets the point coordinates and triangle vertex indices.
bool load_mesh(const std::string& filename, std::vector<vec3>& points, std::vector<ivec3>& triangles) {
    points.clear();
    triangles.clear();
    FILE* F = fopen(filename.c_str(),"r");
    if(!F) { return false;  }
    char* line=nullptr;
    size_t linelen=0;
    int lineno = 0;
    while(getline(&line,&linelen,F) >= 0) {
	++lineno;
	switch(line[0]) {
	    case 'v': {
		float x,y,z;
		bool ok = (sscanf(line+1, "%f %f %f", &x, &y, &z) == 3);
		if(!ok) {
		    std::cerr << lineno << ": malformed vertex" << std::endl;
		    std::cerr << line << std::endl;
		    return false;
		}
		points.push_back(vec3(double(x),double(y),double(z)));
	    } break;
	    case 'f': {
		int v1 =-1,v2 =-1,v3 =-1;
		int vt1=-1,vt2=-1,vt3=-1;
		int vn1=-1,vn2=-1,vn3=-1;
		bool ok = false;
		ok = ok || (sscanf(line+1,"%d %d %d",                   &v1,&v2,&v3                              ) == 3);
		ok = ok || (sscanf(line+1,"%d/%d %d/%d %d/%d",          &v1,&vn1,&v2,&vn2,&v3,&vn3               ) == 6);
		ok = ok || (sscanf(line+1,"%d/%d/%d %d/%d/%d %d/%d/%d", &v1,&vn1,&vt1,&v2,&vn2,&vt2,&v3,&vn3,&vt3) == 9);
		ok = ok || (sscanf(line+1,"%d//%d %d//%d %d//%d",       &v1,&vt1,&v2,&vt2,&v3,&vt3               ) == 6);
		if(!ok || v1 < 1 || v2 < 1 || v3 < 1) {
		    std::cerr << lineno << ": malformed facet" << std::endl;
		    std::cerr << line << std::endl;
		    return false;
		}
		triangles.push_back(ivec3(v1-1,v2-1,v3-1));
	    } break;
	}
    }
    free(line);
    fclose(F);
    return true;
}

// Loads a mesh from a .obj (Alias|Wavefront) file. Gets the bbox and for each triangle its vertices coordinates packed
// in a single integer (10 bits per component).
bool load_and_convert_mesh(const std::string& filename, std::vector<ivec3>& triangles_out, vec3& bbox_min, vec3& bbox_max) {
    std::vector<vec3> points;
    std::vector<ivec3> triangles;
    if(!load_mesh(filename, points, triangles)) { return false; }
    get_bbox(points, bbox_min, bbox_max);
    triangles_out.resize(triangles.size());
    for(int t=0; t<triangles.size(); ++t) {
	ivec3 T = triangles[t];
	triangles_out[t] = ivec3(
	    encode_vertex(points[T.x], bbox_min, bbox_max),
	    encode_vertex(points[T.y], bbox_min, bbox_max),
	    encode_vertex(points[T.z], bbox_min, bbox_max)
	);
    }
    return true;
}

// -------- Zero-memory AABB //----------------------------------------------------------------

// Creates a zero-memory Axis-Aligned Bounding Box tree.
// Nothing needs to be stored, it is completely defined by the order of the triangles.
//  - The sequence [b,e[ of triangles is processed
//  - coord: the axis along which bboxes are sorted (one of 0,1,2)
void init_ZMAABB(std::vector<ivec3>& mesh, int b, int e, int coord) {
    if(e-b <= 8) { return; }
    // Sort facets along coord
    std::sort(
	mesh.begin() + b, mesh.begin() + e,
	[coord](const ivec3& F1, const ivec3& F2) {
	    return (facet_center(F1)[coord] < facet_center(F2)[coord]);
	}
    );
    // Get sequence's bbox, and the indices of the triangles that touch the bbox
    ivec3 bbox_min, bbox_max;
    get_facet_bbox(mesh[b], bbox_min, bbox_max);
    ivec3 index_bbox_min(b,b,b), index_bbox_max(b,b,b);
    for(int i=b+1; i<e; ++i) {
	ivec3 cur_bbox_min, cur_bbox_max;
	get_facet_bbox(mesh[i], cur_bbox_min, cur_bbox_max);
	for(int coord=0; coord<3; ++coord) {
	    if(cur_bbox_min[coord] < bbox_min[coord]) {
		bbox_min[coord] = cur_bbox_min[coord];
		index_bbox_min[coord] = i;
	    }
	    if(cur_bbox_max[coord] > bbox_max[coord]) {
		bbox_max[coord] = cur_bbox_max[coord];
		index_bbox_max[coord] = i;
	    }
	}
    }
    // Put the triangles that touch the bbox first (there are at most 6 of them)
    std::vector<int> box_indices;
    box_indices.push_back(index_bbox_min.x); box_indices.push_back(index_bbox_min.y); box_indices.push_back(index_bbox_min.z);
    box_indices.push_back(index_bbox_max.x); box_indices.push_back(index_bbox_max.y); box_indices.push_back(index_bbox_max.z);
    sort_unique(box_indices);
    int nbb = int(box_indices.size());
    for(int i=0; i<nbb; ++i) {
	std::swap(mesh[b+i], mesh[box_indices[i]]);
    }
    b += 6; // The triangles that touch the bbox are no longer in the tree
    // Recurse in the rest of the triangles
    int m = b + (e-b)/2; // We use a balanced tree (a bit less efficient, but then we do not need storing number of triangles)
    init_ZMAABB(mesh, b, m, (coord + 1)%3);
    init_ZMAABB(mesh, m, e, (coord + 1)%3);	
}

