uint pack(vec2 vec) {
    const float maxValue = 65536.0;
    uint res = 0u;

    res += uint(vec.y * maxValue);
    res *= uint(maxValue);

    res += uint(vec.x * maxValue);

    return res;
}

vec2 unpack(uint value) {
    const uint maxValue = 65536u;
    const float invMaxValue = 1.0 / float(maxValue);
    vec2 vec;
    vec.x = float(value % maxValue) * invMaxValue;
    vec.y = float(value / maxValue) * invMaxValue;
    return vec;
}

