vec2 pack(vec3 v0, float v1) {
    return pack(vec4(v0, v1));
}

vec4 packMaterial(inout Material material) {
    return vec4(pack(material.color, material.metal), pack(material.emission, material.gloss));
}

Material unpackMaterial(vec4 value) {
    Material material;
    vec4 color_metal = unpack(value.xy);
    vec4 emission_gloss = unpack(value.zw);
    material.normal = vec3(0.0);
    material.color = color_metal.xyz;
    material.metal = color_metal.w;

    material.emission = emission_gloss.rgb;
    material.gloss = emission_gloss.w;
    return material;
}

vec3 random(inout uvec3 v) {

    v = v * 1664525u + 1013904223u;

    v.x += v.y*v.z;
    v.y += v.z*v.x;
    v.z += v.x*v.y;

    v ^= v >> 16u;

    v.x += v.y*v.z;
    v.y += v.z*v.x;
    v.z += v.x*v.y;

    return vec3(v)*(1.0/float(0xffffffffU));

}

vec3 randomNormal(vec3 n, inout uvec3 state) {

    vec2 rv2 = random(state).xy;

    vec3  uu = normalize( cross( n, vec3(0.0,1.0,1.0) ) );
	vec3  vv = cross( uu, n );

	float ra = sqrt(rv2.y);
	float rx = ra*cos(6.2831*rv2.x); 
	float ry = ra*sin(6.2831*rv2.x);
	float rz = sqrt( 1.0-rv2.y );
	vec3  rr = vec3( rx*uu + ry*vv + rz*n );

    return normalize( rr );

}

vec3 importanceSampleGGX(vec3 N, inout uvec3 state, float roughness) {
	vec2 Xi = random(state).xy;
    float alpha = roughness * roughness;
    float alpha2 = alpha * alpha;

    float phi = 2.0 * PI * Xi.x;
    float cosTheta = sqrt((1.0 - Xi.y) / (1.0 + (alpha2 - 1.0) * Xi.y));
    float sinTheta = sqrt(1.0 - cosTheta * cosTheta);

    // from spherical coordinates to cartesian coordinates
    vec3 H;
    H.x = cos(phi) * sinTheta;
    H.y = sin(phi) * sinTheta;
    H.z = cosTheta;

    // from tangent-space vector to world-space sample vector
    vec3 up        = abs(N.z) < 0.999 ? vec3(0.0, 0.0, 1.0) : vec3(1.0, 0.0, 0.0);
    vec3 tangent   = normalize(cross(up, N));
    vec3 bitangent = cross(N, tangent);

    vec3 sampleVec = tangent * H.x + bitangent * H.y + N * H.z;
    return normalize(sampleVec);
}

float schlick(float f0, float theta) {
    return f0 + (1.0 - f0) * pow(1.0 - theta, 5.0);
}

float generateGloss(vec3 color) {
    return length(color);//pow(clamp(1.15 - pow(length(color), 4.0), 0.0, 1.0), 2.0);
}


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord / iResolution.xy;
    Material material;
    material.color = texture(iChannel0, uv).rgb;
    material.emission = 0.05 * texture(iChannel1, uv).rgb;
    material.gloss = generateGloss(texture(iChannel2, uv).rgb);
    material.metal = length(texture(iChannel3, uv).rgb);

    fragColor = packMaterial(material);
}

