// geometryData is ivec4 array (nodes + indices + vertices)

struct Node
{
    int leftChild;
    int rightChild;
    vec3 aabbMin;
    vec3 aabbMax;
};

struct Ray
{
    vec3 origin;
    vec3 direction;
    float tStart;
    float tEnd;
};

struct Hit
{
    vec3 position;
    vec3 normal;
    vec2 uv;
    bool isHit;
};


struct Vertex {
    vec3 p;
    vec3 n;
    vec2 t;
};

struct IndexedTriangle
{
   Vertex v0;
   Vertex v1;
   Vertex v2;
};

ivec4 getData(int index) { 
    int SizeX = int(iChannelResolution[0].x);
    int X = index % SizeX;
    int Y = index / SizeX;
    vec4 result = texelFetch(iChannel0, ivec2(index, 0), 0);
    //return ivec4(unpack(result));
    return floatBitsToInt(result);
    //return geometryData[index]; 
}
//{ return vec4(0); }

Node getNode(int index)
{
    ivec4 data0 = getData(index + 0);
    ivec4 data1 = getData(index + 1);

	Node node;

    node.leftChild = data0.r;
    node.rightChild = data0.g;

	node.aabbMin = intBitsToFloat(ivec3(data0.ba, data1.r));
	node.aabbMax = intBitsToFloat(data1.gba);
	return node;
}


IndexedTriangle getIndexedTriangle(int triIndex)
{
    ivec3 triIndices = getData(triIndex).rgb;

    vec4 data0, data1;
    IndexedTriangle triangle;

    data0 = intBitsToFloat(getData(triIndices.r));
    data1 = intBitsToFloat(getData(triIndices.r + 1));
    triangle.v0.p = data0.rgb; triangle.v0.n = vec3(data0.a, data1.rg); triangle.v0.t = data1.ba;

    data0 = intBitsToFloat(getData(triIndices.g));
    data1 = intBitsToFloat(getData(triIndices.g + 1));
    triangle.v1.p = data0.rgb; triangle.v1.n = vec3(data0.a, data1.rg); triangle.v1.t = data1.ba;

    data0 = intBitsToFloat(getData(triIndices.b));
    data1 = intBitsToFloat(getData(triIndices.b + 1));
    triangle.v2.p = data0.rgb; triangle.v2.n = vec3(data0.a, data1.rg); triangle.v2.t = data1.ba;

    return triangle;
}

//------------------- STACK -----------------------
#define MAX_STACK_SIZE 16
int countTI = 0;
int _stack[MAX_STACK_SIZE];
int _index = -1;
void stackClear() { _index = -1; }
int stackSize() { return _index + 1; }
bool stackIsFull() {return _index >= MAX_STACK_SIZE;}
void stackPush(in int node) { ++_index; if(stackIsFull()) return; _stack[_index] = node; }
int stackPop() { return _stack[_index--]; }

//------------------- RAY BB INTESECT -----------------------

bool slabs(in Ray ray, in vec3 minB, in vec3 maxB, inout float localMin) {

    if(all(greaterThan(ray.origin, minB)) && all(lessThan(ray.origin, maxB)))
        return true;

    vec3 t0 = (minB - ray.origin)/ray.direction;
    vec3 t1 = (maxB - ray.origin)/ray.direction;
    vec3 tmin = min(t0, t1), tmax = max(t0, t1);
    float tminf = max(max(tmin.x, tmin.y), tmin.z);
    float tmaxf = min(min(tmax.x, tmax.y), tmax.z);

    if (tminf > tmaxf)
        return false;

    localMin = tminf;
    return tminf < ray.tEnd && tminf > ray.tStart;
}

//------------------- RAY TRI INTERSECT -----------------------

bool isect_tri(inout Ray ray, in IndexedTriangle tri, inout Hit hit) {
	vec3 e1 = tri.v1.p - tri.v0.p;
	vec3 e2 = tri.v2.p - tri.v0.p;
    // if(dot(cross(e1,e2), ray.direction) > 0) return false; // backface culling

	vec3 P = cross(ray.direction, e2);
	float det = dot(e1, P);
        // if (abs(det) < 1e-10) // small parts can disappear here
        // return false;

	float inv_det = 1. / det;
	vec3 T = (ray.origin - tri.v0.p);
	float u = dot(T, P) * inv_det;
	if (u < 0.0 || u > 1.0)
        return false;

	vec3 Q = cross(T, e1);
	float v = dot(ray.direction, Q) * inv_det;
	if (v < 0.0 || (v+u) > 1.0)
        return false;

	float tt = dot(e2, Q) * inv_det;

    if(ray.tEnd > tt && ray.tStart < tt )
    {
        vec3 c = vec3(u, v, 1.0 - u - v);
        countTI++;
        hit.position = (ray.origin + ray.direction * tt);
        hit.normal = normalize(tri.v0.n * c.z + tri.v1.n * c.x + tri.v2.n * c.y);
        hit.uv = tri.v0.t * c.z + tri.v1.t * c.x + tri.v2.t * c.y;

        hit.isHit = true;
        ray.tEnd = tt;
        return true;
    }
    return false;
}

//------------------- TRACE -----------------------

bool traceRay(inout Ray ray, inout Hit hit) {
	stackClear();
    stackPush(0);
    hit.isHit = false;
    Node select;
    IndexedTriangle try;
    float tempt;

    for(int i = 0; (i < 64) && (stackSize() > 0 && !stackIsFull()); i++)
    {
        select = getNode(stackPop());
        if(!slabs(ray, select.aabbMin, select.aabbMax, tempt))
            continue;

        if(select.leftChild > 0 && select.rightChild > 0)
        {
            float leftMinT = 0.;
            float rightMinT = 0.;
            Node right = getNode(select.rightChild);
            Node left = getNode(select.leftChild);
            bool rightI = slabs(ray, right.aabbMin, right.aabbMax,  rightMinT);
            bool leftI = slabs(ray, left.aabbMin, left.aabbMax,  leftMinT);

            if(rightI && leftI)
            {
                if (rightMinT < leftMinT)
                {
                    stackPush(select.leftChild);
                    stackPush(select.rightChild);
                }
                else
                {
                    stackPush(select.rightChild);
                    stackPush(select.leftChild);
                }
                continue;
            }
            if(rightI)
                stackPush(select.rightChild);
            else
                stackPush(select.leftChild);
            continue;
        }

        if (select.rightChild > 0)
            stackPush(select.rightChild);

        if (select.leftChild > 0)
            stackPush(select.leftChild);

        if(select.rightChild <= 0)
        {
            try = getIndexedTriangle(-select.rightChild);
            isect_tri(ray, try, hit);
        }

        if(select.leftChild <= 0)
        {
            try = getIndexedTriangle(-select.leftChild);
            isect_tri(ray, try, hit);
        }
    }

	return hit.isHit;
}

void traceCloseHitV2(inout Ray ray, inout Hit hit)
{
    stackClear();
    stackPush(0);
    hit.isHit = false;
    Node select;
    IndexedTriangle try;
    float tempt;

    for(int i = 0; (i < 64) && (stackSize() > 0 && !stackIsFull()); i++)
    {
        select = getNode(stackPop());
        if(!slabs(ray, select.aabbMin, select.aabbMax, tempt))
            continue;

        if(select.leftChild > 0 && select.rightChild > 0)
        {
            float leftMinT = 0.;
            float rightMinT = 0.;
            Node right = getNode(select.rightChild);
            Node left = getNode(select.leftChild);
            bool rightI = slabs(ray, right.aabbMin, right.aabbMax,  rightMinT);
            bool leftI = slabs(ray, left.aabbMin, left.aabbMax,  leftMinT);

            if(rightI && leftI)
            {
                if (rightMinT < leftMinT)
                {
                    stackPush(select.leftChild);
                    stackPush(select.rightChild);
                }
                else
                {
                    stackPush(select.rightChild);
                    stackPush(select.leftChild);
                }
                continue;
            }
            if(rightI)
                stackPush(select.rightChild);
            else
                stackPush(select.leftChild);
            continue;
        }

        if (select.rightChild > 0)
            stackPush(select.rightChild);

        if (select.leftChild > 0)
            stackPush(select.leftChild);

        if(select.rightChild <= 0)
        {
            try = getIndexedTriangle(-select.rightChild);
            isect_tri(ray, try, hit);
        }

        if(select.leftChild <= 0)
        {
            try = getIndexedTriangle(-select.leftChild);
            isect_tri(ray, try, hit);
        }
    }
}


mat3 setCamera( in vec3 rayOrigin, in vec3 target, float cameraRotation )
{
	vec3 cw = normalize(target - rayOrigin);
	vec3 cp = vec3(sin(cameraRotation), cos(cameraRotation),0.0);
	vec3 cu = normalize( cross(cw,cp) );
	vec3 cv =          ( cross(cu,cw) );
    return mat3( cu, cv, cw );
}

vec2 hash2(vec3 p3) {
	p3 = fract(p3 * vec3(5.3983, 5.4427, 6.9371));
    p3 += dot(p3, p3.yzx + 19.19);
    return fract((p3.xx + p3.yz) * p3.zy);
}

vec3 getMissColor(vec3 dir) {
	return textureLod(iChannel3, dir, 0.0).xyz;
}

vec3 getNewRayDirection(vec3 incoming, inout Material material, uvec3 state, out float spec) {
    vec3 n = material.normal;
    float theta = dot(n, -incoming);

    float sheen = schlick(material.gloss, theta);
    spec = float(sheen > random(state).x);
#if 0
    vec3 resultNormal = importanceSampleGGX(n, state, 1.2 - material.gloss);
    return reflect(incoming, normalize(resultNormal));

#else


    vec3 diffuceN = randomNormal(n, state);

    vec3 resultNormal = mix(diffuceN, n, sheen * spec);

    return reflect(incoming, normalize(resultNormal));
#endif
}

Material getMaterial(inout Hit hit) {
    vec4 c = textureLod(iChannel1, hit.uv, 0.0);

    Material material = unpackMaterial(c);
    material.normal = hit.normal;
;

    return material;
}

vec3 getMaterialColor(inout Material material, float spec) {
    vec3 diffuseColor = material.color * (1.0 - material.metal);
    vec3 specularColor = mix(vec3(1.0), material.color, material.metal);
    return mix(diffuseColor, specularColor, spec);
}

vec3 getRayColor(inout Hit firstHit, Ray ray, vec2 fragCoord, int ray_index, out bool wasHit) {
    const int maxBounds = 1;
    uvec3 state = uvec3(uvec2(fragCoord.xy), uint(iFrame * 15647 + ray_index));   
    vec3 result = vec3(0);

    vec3 energy = vec3(1);
    wasHit = false;
    Hit hit = firstHit;
    for(int i = 0; i < maxBounds; ++i) {
        if (ray_index == 0 || i != 0) {
            traceCloseHitV2(ray, hit);
            if (i == 0) {
                firstHit = hit;
            }
        }

        if (!hit.isHit) {
            break;
        }

        float spec = 0.0;
        wasHit = true;
        Material material = getMaterial(hit);
        vec3 outCome = getNewRayDirection(ray.direction, material, state, spec);
        result += energy * material.emission;
        energy *= getMaterialColor(material, spec);
        ray.direction = outCome;
        ray.origin = hit.position + ray.direction * 0.001;
    }

    energy *= getMissColor(ray.direction);

    result += energy;

    return result;
}

