vec4 get_data_raw(in int index) {
    int width = int(iChannelResolution[0].x);
    vec4 col = texelFetch(iChannel0, ivec2(index%width,index/width), 0);
    return col;
}

float bytesToFloat(vec4 bytes) {
    // bytes.x = LSB, bytes.w = MSB (little endian)
    uint u = uint(bytes.x) | (uint(bytes.y) << 8) | (uint(bytes.z) << 16) | (uint(bytes.w) << 24);
    return uintBitsToFloat(u);
}

vec4 texelFetch(int offset, ivec2 index, int pos) {
    float x = bytesToFloat(get_data_raw(offset + index.x * 3));
    float y = bytesToFloat(get_data_raw(offset + index.x * 3 + 1));
    float z = bytesToFloat(get_data_raw(offset + index.x * 3 + 2));
    return vec4(x, y, z, 0);
}
vec4 texelFetch(int offset, int index) {
    return (get_data_raw(offset + index));
    float x = bytesToFloat(get_data_raw(offset + index * 3));
    float y = bytesToFloat(get_data_raw(offset + index * 3 + 1));
    float z = bytesToFloat(get_data_raw(offset + index * 3 + 2));
    return vec4(x, y, z, 0);
}
ivec4 texelFetchI(int offset, int index) {
    return ivec4(get_data_raw(offset + index));
}

