    }

    // Get current digit
    int digit_index = x - str1_length;
    if (digit_index > digit_count) {
        // Offset by 1 for digits located after the decimal point
        digit_index--;
    }
    float exponent = float(digit_count - digit_index);
    int n = 48 + int(10.*fract(num/.999999/pow(10., exponent)));

    // Print digit
    return print_char(n);
}
*/

/*
    > See "Common" Tab for usage detail.

    This shader is an improved version of my previous text utility (see fork) that was designed
    to facilitate string manipulation in shaders. This version greatly improves performance.

    === What's new ? ===

    In short, I'm now using int[] arrays to declare strings. I only create 1 function per string
    instead of creating 1 function per character like the previous version did.
    The idea for this new approach came from @jiang on my recent code-golfing challenge (https://www.shadertoy.com/view/lXt3zf)

    1. One Texture Call Per Line

        The performance impact of the previous version scaled with the total number of characters in
        each string. For every character that was defined, there was one associated texture sample.

        In this new version, there is only 1 texture sample per string definition, greatly reducing 
        the performance impact. A 20-character string now contains 20x less texture samples.

    2. No "For" Loop

        The floating point debug of my previous algorithm was using 3 for-loops to print a number,
        and had precision issues.

        This is also greatly improved in this version as this shader doesn't rely on any loop whatsoever.
        Moreover, the algorithm now supports integer debugging (which wasn't possible in the previous
        version), and the precision is slightly improved.

    3. Fast Compile Time

        In the previous version, each character was calling a function to calculate
        its position in the alphabet texture in order to sample the texture at that position.
        This was done using well-crafted #defines for every character, but could lead to 
        excessive compile times.

        In this version, the #defines are much simpler as I'm using integer arrays instead
        of complex define trickery.

        Previously, "_A" was defined as: #define _A ); u.x -= CHAR_SPACING; d += _char(FONT_TEXTURE, u, 65

        Now, "_A" simply is "65," (a single element in an int[] array) and the compilation time is greatly improved.

        Moreover, I managed to keep each int[] array as a compile-time constant (const) in order to
        maximize performance.

    ===================================================================================================
*/

// Fork of "Smooth Crystal Bunny" by BrunoLevy. https://shadertoy.com/view/WlcXRS
// 2025-11-14 16:17:42

// Default settings
#if 1
const float refract_index = 1.3;  // 1.0: no refraction   1.3: water
const float extinction = 0.3;     // the higher, the darker (in function of thicness) 
const float reflect_coeff = 0.75; // 0.0: no reflection   1.0: shiny reflections
const vec3  core_color = vec3(0,0.5,0.5); 
#endif 

// Show mesh thickness
#if 0
const float refract_index = 1.0;  
const float extinction = 0.3;     
const float reflect_coeff = 0.0; 
const vec3  core_color = vec3(0,0,0); 
#define WHITE_BACKGROUND
#endif 

// Smooth normals or per-facet normals.
const bool smooth_shading = true;

// Gets x,y,z, coordinates packed in a single 32 bits int (10 bits per coordinate)
int get_compressed_point(in int v) {
    return get_data(points_offset, v);
}

// Converts a single-int 10 bits per components packed point into a standard vec3.
vec3 uncompress_point(in int xyz) {
   ivec3 XYZ = (ivec3(xyz) >> ivec3(0,10,20)) & ivec3(1023); 
   return bbox_min + (bbox_max - bbox_min) * vec3(XYZ) / 1023.0;
}

// Gets a point from a vertex index
vec3 get_point(int v) {
   return uncompress_point(get_compressed_point(v));
}

// Gets a normal from a vertex index
vec3 get_normal(int v) {
   int xyz = get_data(normals_offset, v);
   ivec3 XYZ = (ivec3(xyz) >> ivec3(0,10,20)) & ivec3(1023); 
   return vec3(-1) + vec3(XYZ) / 512.0;    
}

// Gets an AABB node from a node index.
// An AABB node can be either an internal node (bbox + axis + number of subnodes 
//  in left subtree) or a leaf node (single triangle, with indives of its tree vertices)
ivec3 get_AABB_node(in int n) {
    return ivec3(
        get_data(AABB_offset,3*n),
        get_data(AABB_offset,3*n+1),
        get_data(AABB_offset,3*n+2)
    );
}

const float FARAWAY=1e30;

struct Camera {
    vec3 Obs;
    vec3 View;
    vec3 Up;
    vec3 Horiz;
    float H;
    float W;
    float z;
};

struct Ray {
    vec3 Origin;
    vec3 Dir;
};

Camera camera(in vec3 Obs, in vec3 LookAt, in float aperture) {
   Camera C;
   C.Obs = Obs;
   C.View = normalize(LookAt - Obs);
   C.Horiz = normalize(cross(vec3(0.0, 0.0, 1.0), C.View));
   C.Up = cross(C.View, C.Horiz);
   C.W = float(iResolution.x);
   C.H = float(iResolution.y);
   C.z = (C.H/2.0) / tan((aperture * 3.1415 / 180.0) / 2.0);
   return C;
}

Ray launch(in Camera C, in vec2 XY) {
   return Ray(
      C.Obs,
      C.Obs+C.z*C.View+(XY.x-C.W/2.0)*C.Horiz+(XY.y-C.H/2.0)*C.Up 
   );
}

struct Intersection {
   float t;
   vec3 P;
   vec3 N;
   int id; // index of latest intersected triangle, used to avoid finding the point
           //  where you started from when computing multiple bounces.
};

Intersection intersection() {
   Intersection I;
   I.t = FARAWAY;
   I.id = -1; 
   return I;
}

Ray reflect_ray(in Ray R, in Intersection I) {
    return Ray(I.P, reflect(R.Dir, I.N));
}

Ray refract_ray(in Ray R, in Intersection I, in float n1, in float n2) {
    return Ray(I.P, refract(normalize(R.Dir), I.N, n1/n2));
}

// Branchless ray-triangle intersection that gives, for free, as by-products:
//   Normal N
//   Barycentric coordinates (1-u-v, u, v)
// (slightly modified Moller-Trumbore algorithm)
// References and explanations here:
// https://stackoverflow.com/questions/42740765/intersection-between-line-and-triangle-in-3d/42752998#42752998
bool intersect_triangle(
    in Ray R, in vec3 A, in vec3 B, in vec3 C, out float t, 
    out float u, out float v, out vec3 N
) { 
   vec3 E1 = B-A;
   vec3 E2 = C-A;
         N = cross(E1,E2);
   float det = -dot(R.Dir, N);
   float invdet = 1.0/det;
   vec3 AO  = R.Origin - A;
   vec3 DAO = cross(AO, R.Dir);
   u =  dot(E2,DAO) * invdet;
   v = -dot(E1,DAO) * invdet;
   t =  dot(AO,N)   * invdet;
   return (abs(det) >= 1e-6 && t >= 0.0 && u >= 0.0 && v >= 0.0 && (u+v) <= 1.0);
}

// Computes ray-triangle intersection from node index (i)
// Returns true if there was an intersection.
// Note: normal is not normalized
bool triangle(in Ray R, in int i, inout Intersection I) {
   ivec3 T = get_AABB_node(i);
   vec3 A = get_point(T.x);
   vec3 B = get_point(T.y);
   vec3 C = get_point(T.z);    
   float t,u,v;
   vec3 N;
   if(intersect_triangle(R, A,B,C, t, u, v, N) && t < I.t) {
      I.t = t;
      I.P = R.Origin + t*R.Dir;
      I.id = i;
      if(smooth_shading) {
         vec3 N1 = get_normal(T.x);
         vec3 N2 = get_normal(T.y);
         vec3 N3 = get_normal(T.z);       
         I.N = (1.0-u-v)*N1 + u*N2 + v*N3;
      } else {
         I.N = N;
      }
      return true;
   }
   return false;
}

// Good explanations here:
// https://tavianator.com/fast-branchless-raybounding-box-intersections/
bool segment_box_intersection(
  in vec3 q1,
  in vec3 dirinv,
  in vec3 boxmin,
  in vec3 boxmax,
  in float t 
) {  
   vec3 T1 = dirinv*(boxmin - q1);
   vec3 T2 = dirinv*(boxmax - q1);
   vec3 Tmin = min(T1,T2);
   vec3 Tmax = max(T1,T2);
   float tmin = max(max(Tmin.x, Tmin.y),Tmin.z);
   float tmax = min(min(Tmax.x, Tmax.y),Tmax.z);    
   return (tmax >= 0.0) && (tmin <= tmax) && (tmin <= t);
}

// The stack used for recursive traversal of the AABB
// Traversal context is just the bounds b,e of the [b,e[ 
// sequence of AABB nodes that correspond to a subtree.

int stack_top = -1;
int stack_b[10];
int stack_e[10];

bool stack_empty() {
  return (stack_top < 0);
}

void stack_push(in int b, in int e) {
  stack_top++;
  stack_b[stack_top] = b;
  stack_e[stack_top] = e;  
}

void stack_pop(out int b, out int e) {
  b = stack_b[stack_top];
  e = stack_e[stack_top];
  --stack_top;
}

// AABB walkthrough
// (C++ code to convert .obj file into AABB at the end
//  of Buffer A, in a big comment)
// Some inspiration taken from Terdiman's OpCode:
//   http://www.codercorner.com/Opcode.htm
bool mesh_AABB(in Ray R, inout Intersection I) {
    int prev_id = I.id; // index of latest intersected triangle
    bool result = false;
    vec3 invDir = vec3(1.0/R.Dir.x, 1.0/R.Dir.y, 1.0/R.Dir.z);
    stack_push(0, AABB_data_size/3);
    while(!stack_empty()) {
        int b,e;
        stack_pop(b,e);
        ivec3 node = get_AABB_node(b);
        vec3 bbox_min = uncompress_point(node.x);
        vec3 bbox_max = uncompress_point(node.y);
        if(!segment_box_intersection(R.Origin, invDir, bbox_min, bbox_max, I.t)) {
            continue;
        }
        b++;
        if(node.z == -1) {   // Node is a leaf, intersect full sequence of triangles
           for(int i=b; i<e; ++i) {
              if(i == prev_id) { continue; } // skip latest triangle
              bool t_isect = triangle(R, i, I);
              result = result || t_isect;
          }
        } else { // Node is internal, decode splitting coord and nb in left child
          int coord = node.z & 3;
          int nb    = node.z >> 2; 
          int m     = b + nb;  
          // Traverse nearest first (so that pruning can occur, thanks @iq for the tips)  
          if(R.Dir[coord] < 0.0) {
             stack_push(b,m);
             stack_push(m,e);                  
          } else {
             stack_push(m,e);
             stack_push(b,m); // positive -> process this child first                                    
          } 
        }
    }
    if(result) { I.N = normalize(I.N); }
    return result;
}  

// Modifies ray and intersection, returns total length of traversed matter.
float multi_refract(inout Ray R, inout Intersection I) {
    float result = 0.0;
    for(int i=0; i<10; ++i) {
        if(dot(R.Dir,I.N) > 0.0) { // Exiting matter
            result += I.t;
            vec3 old_dir = R.Dir;
            I.N = -I.N;
            R = refract_ray(R, I, refract_index, 1.0);
            if(R.Dir == vec3(0)) { 
               //R.Dir = reflect(old_dir, I.N); // total reflection (what I should do I think) 
               R.Dir = old_dir; // I do that instead (not correct but looks better).
            }
        } else { // Entering matter
            R = refract_ray(R, I, 1.0, refract_index);
            R.Dir = normalize(R.Dir); // Needs to be unit, so that on exit, I.t is distance
        }
        I.t = FARAWAY;
        if(!mesh_AABB(R, I)) { break; }  
    }
    return result;
}

vec3 sky(in Ray R) {
#ifdef WHITE_BACKGROUND
   return vec3(1);
#else
   return vec3(textureLod(iChannel1, R.Dir, 0.0));
#endif    
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ) {
#ifdef DEBUG_DATA    
   fragColor = texelFetch(iChannel0,ivec2(fragCoord),0);
   return; 
#endif    
   float alpha = iTime;
   float c = cos(alpha);
   float s = sin(alpha);
   Camera C = camera(
       vec3(20.0*c, 20.0*s, 1.5),
       vec3(0.0, 0.0, 0.0),
       30.0       
   );
   Ray R = launch(C, fragCoord);
   Intersection I = intersection();
   mesh_AABB(R, I);

   if(I.t == FARAWAY) {
      fragColor.xyz = sky(R); 
    } else {        
      float fresnel = 1.0 + dot(R.Dir,I.N) / length(R.Dir);
      fresnel = clamp(fresnel, 0.0, 1.0); 
      fragColor.xyz = reflect_coeff * fresnel * sky(reflect_ray(R,I)); 

      float l = multi_refract(R,I);
      float d = exp(-l * extinction);
      fragColor.xyz += mix(core_color, sky(R), d);
    }
}

//  A version of https://www.shadertoy.com/view/3ltSzM (Crystal Bunny)
// with smooth normals.
//  
//  Sources of the "mesh compiler" as a big comment in the end of Buffer A
// (used to generate the AABB and encode it as GLSL sources).

// Mesh data description: bbox and number of AABB nodes, points and normals
const vec3 bbox_min = 10.0*vec3(-0.253035,-0.340497,-0.346693);
const vec3 bbox_max = 10.0*vec3(0.252403,0.340004,0.345965);
const int AABB_data_size = 6399;
const int points_data_size = 1024;
const int normals_data_size = 1024;


// Reads a 32 bits integer encoded in a pixel of BufferA
// (implementation of get_data(), do not call directly)
int get_data_raw(in sampler2D channel, in int width, in int index) {
   vec4 col = 255.0*vec4(texelFetch(channel, ivec2(index%width,index/width), 0));
   return (int(col.r)      ) | 
          (int(col.g) << 8 ) |
          (int(col.b) << 16) |
          (int(col.a) << 24) ;
}


// Reads a 32 bits integer encoded in a pixel of BufferA
//  offset: one of RESOLUTION_OFFSET, MESH_DATA_OFFSET
//  index: the index of the data to be read
#define get_data(offset, index) \
    get_data_raw(iChannel0, int(iChannelResolution[0].x), (offset)+(index))

// In BufferA, data is organized in four sections
// - resolution: stores width and height of window, to detect resize/fullscreen
// - AABB: the mixed AABB-nodes + mesh triangles structure
// - points: compressed vertices coordinates  (xyz quantized in 10 bits packed in an int)
// - normals: compressed per-vertices normals (xyz quantized in 10 bits packed in an int)
const int resolution_offset=0;
const int resolution_data_size=2;
const int AABB_offset =resolution_offset+resolution_data_size;
const int points_offset = AABB_offset+AABB_data_size;
const int normals_offset = points_offset+points_data_size;

// Fork of "Stanford Bunny ZMAABB." by BrunoLevy. https://shadertoy.com/view/ttcSzr
// 2025-11-14 16:19:12

// A more efficient version of https://www.shadertoy.com/view/wtG3z3
// This one uses a version of Terdiman's zero-memory AABB
//      and loads mesh data in Buffer A.

// Uncomment next line to deactivate acceleration structure.
// #define NAIVE


ivec3 get_facet(in int f) {
    return ivec3(
        get_data(MESH_DATA_OFFSET,3*f),
        get_data(MESH_DATA_OFFSET,3*f+1),
        get_data(MESH_DATA_OFFSET,3*f+2)
    );
}

const float FARAWAY=1e30;

struct Camera {
    vec3 Obs;
    vec3 View;
    vec3 Up;
    vec3 Horiz;
    float H;
    float W;
    float z;
};

struct Ray {
    vec3 Origin;
    vec3 Dir;
};

Camera camera(in vec3 Obs, in vec3 LookAt, in float aperture) {
   Camera C;
   C.Obs = Obs;
   C.View = normalize(LookAt - Obs);
   C.Horiz = normalize(cross(vec3(0.0, 0.0, 1.0), C.View));
   C.Up = cross(C.View, C.Horiz);
   C.W = float(iResolution.x);
   C.H = float(iResolution.y);
   C.z = (C.H/2.0) / tan((aperture * 3.1415 / 180.0) / 2.0);
   return C;
}

Ray launch(in Camera C, in vec2 XY) {
   return Ray(
      C.Obs,
      C.Obs+C.z*C.View+(XY.x-C.W/2.0)*C.Horiz+(XY.y-C.H/2.0)*C.Up 
   );
}

struct Material {
   vec3 Ka;
   vec3 Kd;
   vec3 Ks;
   float s;
   vec3 Ke;
};

struct Intersection {
   float t;
   Material material;
   vec3 P;
   vec3 N;
};

Intersection intersection() {
   Intersection I;
   I.t = FARAWAY;
   return I;
}

struct Sphere {
   vec3 Center;
   float R;
};

bool intersect_sphere(in Ray R, in Sphere S, out float t) {
   vec3 CO = R.Origin - S.Center;
   float a = dot(R.Dir, R.Dir);
   float b = 2.0*dot(R.Dir, CO);
   float c = dot(CO, CO) - S.R*S.R;
   float delta = b*b - 4.0*a*c;
   if(delta < 0.0) {
      return false;
   }
   t = (-b-sqrt(delta)) / (2.0*a);
   return (t > 0.0);
}

void sphere(in Ray R, in Sphere S, in Material M, inout Intersection I) {
   float t;
   if(intersect_sphere(R, S, t) && t < I.t) {
      I.t = t;
      I.material = M;
      I.P = R.Origin + t*R.Dir;
      I.N = normalize(I.P - S.Center);
   }
}


bool intersect_triangle(
    in Ray R, in vec3 A, in vec3 B, in vec3 C, out float t, 
    out float u, out float v, out vec3 N
) { 
   // Möller et Trumbore, « Fast, Minimum Storage Ray-Triangle Intersection », 
   // Journal of Graphics Tools, vol. 2,‎ 1997, p. 21–28 
   // https://en.wikipedia.org/wiki/M%C3%B6ller%E2%80%93Trumbore_intersection_algorithm 
   // (with small adaptations: branchless, and reusing the normal vector)
   // 
   // Notation: O = R.Origin; D = R.Dir)
   //           E1 = B-A; E2 = C-A
   // 
   // (1) O + tD = A + uE1 + vE2 
   // (2) uE1 + vE2 -tD = O-A
   // 
   //                [u]
   // (3) [E1|E2|-D] [v] = O-A
   //                [t]
   // 
   //  (where [E1|E2|-D] is the 3x3 matrix with E1,E2,-D as its columns)
   //
   //  Using Cramer's formula for the solution of:
   //
   //    [a11 a12 a13][x1]   [b1]
   //    [a12 a22 a23][x2] = [b2]
   //    [a31 a32 a33][x3]   [b3]
   //
   //  gives: 
   // 
   //        |b1 a12 a13|   |a11 a12 a13|
   //   x1 = |b2 a22 a23| / |a21 a22 a23|
   //        |b3 a32 a33|   |a31 a32 a33|
   //
   //        |a11 b1 a13|   |a11 a12 a13|
   //   x2 = |a21 b2 a23| / |a21 a22 a23|
   //        |a31 b3 a33|   |a31 a32 a33|
   //
   //        |a11 a12 b1|   |a11 a12 a13|
   //   x3 = |a21 a22 b2| / |a21 a22 a23|
   //        |a31 a32 b3|   |a31 a32 a33|
   // 
   // Now we get:
   //
   //   u = (O-A,E2,-D) / (E1,E2,-D)
   //   v = (E1,O-A,-D) / (E1,E2,-D)
   //   t = (E1,E2,O-A) / (E1,E2,-D)
   // 
   // where (A,B,C) denotes the determinant of the 3x3 matrix with A,B,C as its
   //  column vectors.
   // 
   // Now we use the following identities:
   //   (A,B,C) = dot(A,cross(B,C))  (develop the determinant w.r.t. first column)
   //   (B,A,C) = -(A,B,C)           (swapping two vectors changes the sign)
   //   (B,C,A) =  (A,B,C)           (circular permutation does not change the sign)
   // 
   // Now we get:
   //
   // u = -(E2,O-A,D)  / (D,E1,E2)
   // v =  (E1,O-A,D)  / (D,E1,E2)
   // t = -(O-A,E1,E2) / (D,E1,E2)  
   //
   // Using N=cross(E1,E2); AO = O-A; DAO = cross(D,AO)
   //  gives the following code : 
   /*
   vec3 E1 = B-A;
   vec3 E2 = C-A;
         N = cross(E1,E2);
   float det = -dot(R.Dir, N);
   float invdet = 1.0/det;
   vec3 AO  = R.Origin - A;
   vec3 DAO = cross(AO, R.Dir);
   u =  dot(E2,DAO) * invdet;
   v = -dot(E1,DAO) * invdet;
   t =  dot(AO,N)  * invdet; 
   return (det >= 1e-6 && t >= 0.0 && u >= 0.0 && v >= 0.0 && (u+v) <= 1.0);
   */

    vec3 e0 = B - A;
    vec3 e1 = C - A;
    vec3 tv = R.Origin - A;

    vec3 pv = cross(R.Dir, e1);
    float det = dot(e0, pv);

    vec3 qv = cross(tv, e0);

    vec4 uvt;
    uvt.x = dot(tv, pv);
    uvt.y = dot(R.Dir, qv);
    uvt.z = dot(e1, qv);
    uvt.xyz = uvt.xyz / det;
    uvt.w = 1.0 - uvt.x - uvt.y;

    u = uvt.x;
    v = uvt.y;
    t = uvt.z;
    N = cross(e0,e1);
    return (det >= 1e-6 && t >= 0.0 && u >= 0.0 && v >= 0.0 && (u+v) <= 1.0);

}

void triangle(in Ray R, vec3 A, vec3 B, vec3 C, in Material M, inout Intersection I) {
   float t,u,v;
   vec3 N;
   if(intersect_triangle(R, A,B,C, t, u, v, N) && t < I.t) {
      I.t = t;
      I.material = M;
      I.P = R.Origin + t*R.Dir;
      I.N = normalize(N);
   }
}

bool segment_box_intersection(
  in vec3 q1,
  in vec3 dirinv,
  in vec3 boxmin,
  in vec3 boxmax,
  in float t // t of current intersection, used for pruning, see iq's comment.
) {  
   // References: 
   //    https://tavianator.com/fast-branchless-raybounding-box-intersections/ 
   vec3 T1 = dirinv*(boxmin - q1);
   vec3 T2 = dirinv*(boxmax - q1);
   vec3 Tmin = min(T1,T2);
   vec3 Tmax = max(T1,T2);
   float tmin = max(max(Tmin.x, Tmin.y),Tmin.z);
   float tmax = min(min(Tmax.x, Tmax.y),Tmax.z);    
   return (tmax >= 0.0) && (tmin <= tmax) && (tmin <= t);
}

int stack_top = -1;
int stack_b[10];
int stack_e[10];

bool stack_empty() {
  return (stack_top < 0);
}

void stack_push(in int b, in int e) {
  stack_top++;
  stack_b[stack_top] = b;
  stack_e[stack_top] = e;  
}

void stack_pop(out int b, out int e) {
  b = stack_b[stack_top];
  e = stack_e[stack_top];
  --stack_top;
}

vec3 decode_vertex(int xyz) {
   int x = (xyz & 1023);
   int y = (xyz & (1023 << 10)) >> 10;
   int z = (xyz & (1023 << 20)) >> 20;
   return bbox_min + vec3(float(x), float(y), float(z)) / 1023.0 * (bbox_max - bbox_min);
}

vec3 min3(in vec3 p1, in vec3 p2, in vec3 p3) {
    return min(min(p1,p2),p3);
}

vec3 max3(in vec3 p1, in vec3 p2, in vec3 p3) {
    return max(max(p1,p2),p3);
}

void mesh_AABB(in Ray R, in Material M, inout Intersection I) {
  // References:
  //   http://www.codercorner.com/ZeroByteBVH.pdf 
  // With some adaptations:
  //   a) here the tree is balanced
  //   b) sorting coord. simply cycles between X,Y,Z   
  //   c) for now I always use 6 triangles to compute bbox
  // Consequence of a,b,c: the AABB is fully implicit, fully described by
  //  the order of the triangles in the mesh.
  // Mesh sorting program will be posted here shortly.

#ifdef NAIVE    
  for(int i=0; i<facets_data_size; ++i) {
      ivec3 F = get_facet(i);
      vec3 p1 = decode_vertex(F.x);
      vec3 p2 = decode_vertex(F.y);
      vec3 p3 = decode_vertex(F.z);
      triangle(R, p1, p2, p3, M, I);      
  }
#else    
    vec3 invDir = vec3(1.0/R.Dir.x, 1.0/R.Dir.y, 1.0/R.Dir.z);
    stack_push(0, facets_data_size);
    while(!stack_empty()) {
        int b,e;
        stack_pop(b,e);
        if(e-b <= 16) {
            for(int i=b; i<e; ++i) {
                ivec3 F = get_facet(i);
                vec3 p1 = decode_vertex(F.x);
                vec3 p2 = decode_vertex(F.y);
                vec3 p3 = decode_vertex(F.z);
                triangle(R, p1, p2, p3, M, I);
            }
        } else {
           ivec3 F = get_facet(b);
           vec3 p1 = decode_vertex(F.x);
           vec3 p2 = decode_vertex(F.y);
           vec3 p3 = decode_vertex(F.z);
           const int nbb = 6; // Number of triangles used to compute the bbox
                              // (for now fixed, could be stored in the mesh as well).

           // Compute bbox (and test triangles used to compute the bbox, they
           // are not part of the tree).
           triangle(R, p1, p2, p3, M, I);
           vec3 bbox_min = min3(p1,p2,p3); 
           vec3 bbox_max = max3(p1,p2,p3);
           for(int i=b+1; i<b+nbb; ++i) {
              ivec3 F = get_facet(i);
              vec3 p1 = decode_vertex(F.x);
              vec3 p2 = decode_vertex(F.y);
              vec3 p3 = decode_vertex(F.z);
              triangle(R, p1, p2, p3, M, I);
              bbox_min = min(bbox_min, min3(p1,p2,p3)); 
              bbox_max = max(bbox_max, max3(p1,p2,p3));
           }

           if(segment_box_intersection(R.Origin, invDir, bbox_min, bbox_max, I.t)) { 
              b += nbb;
              int m = b + (e-b)/2;
              // Small optimization: traverse nearest child first (so that pruning is
              // more likely to occur).
              int coord = (stack_top + 1)%3; // coord along which current node is split
              if(R.Dir[coord] < 0.0) {
                stack_push(b,m);
                stack_push(m,e);                  
              } else {
                stack_push(m,e);
                stack_push(b,m); // positive -> process this child first                                    
              } 
              // TODO: elimination of the terminal recursion (latest pushed node is
              // popped immediatly after, see iq's comment).
           }     
        }
    }
#endif    
}  


void sky(out vec4 fragColor, in Ray R) {
   vec3 V = normalize(R.Dir);
   float s = 0.5 * (V.z + 1.0);
   fragColor = mix( 
      vec4(0.0, 0.0, 0.0, 1.0),
      vec4(1.0, 1.0, 2.0, 1.0),
      s
   );
}


vec3 lighting( in Intersection I, in vec3 LightPos) {
   vec3 L = LightPos - I.P;
   float diffuse = max(dot(I.N, L)/length(L),0.0);
   return diffuse * I.material.Kd;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ) {
   float alpha = float(iFrame)/30.0;
   float c = cos(alpha);
   float s = sin(alpha);
   Camera C = camera(
