float bytesToFloat(vec4 bytes) {
    // bytes.x = LSB, bytes.w = MSB (little endian)
    uint u = uint(bytes.x) | (uint(bytes.y) << 8) | (uint(bytes.z) << 16) | (uint(bytes.w) << 24);
    return uintBitsToFloat(u);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ) {

    ivec2 v = ivec2(fragCoord.xy);

    int width = int(iResolution.x);
    int index = v.x + v.y * width;

    fragColor = texelFetch(iChannel0, v, 0); 

    if (index == INFO_FRAME_POS) {  

        if (isMouseDown()) {
            fragColor = vec4(float(iFrame), 0., 0., 0.);
        }

    } else if (index == INFO_RESOLUTION_POS) {

        float resolutionChangeFlag = 0.0;
        vec2 oldResolution = texelFetch(iChannel0, ivec2(0, INFO_RESOLUTION_POS), 0).yz;

        if (iResolution.xy != oldResolution) {
            resolutionChangeFlag = 1.0;
        }

        fragColor = vec4(resolutionChangeFlag, iResolution.xy, 1.0);

    } else if (iFrame < 2) {

        fragColor = vec4(0.0, 0.0, 0.0, 1.0);

        index -= MESH_DATA_OFFSET;

#if defined(OPT_USE_MESHDATA_BLOB)

        int width = int(iChannelResolution[1].x);
        int height = int(iChannelResolution[1].y);
        if(index < width * height / 4) {
            vec4 col;
            for (int i = 0; i < 4; i++) {
                int I = index * 4 + i;
                col[i] = bytesToFloat(texelFetch(iChannel1, ivec2(I%width,I/width), 0)*255.); 
            }
            fragColor = col;
        }

#else

        if(index < VEC4_COUNT) {
            vec4[] data = getData();
            fragColor = data[index]; 
        }

#endif   

    }

}

