#define dataArrayTex iChannel0
#define textureMapsArrayTex iChannel1
#define envMapTex iChannel2

vec4 get_vec4(in int index) {
    int width = int(iChannelResolution[0].x);
    vec4 col = texelFetch(dataArrayTex, ivec2(index%width,index/width), 0);
    return col;
}

vec4 texelFetch(int offset, ivec2 index, int pos) {
    return get_vec4(offset + index.x);
}
vec4 texelFetch(int offset, int index) {
    return get_vec4(offset + index);
}
ivec4 texelFetchI(int offset, int index) {
    return ivec4(get_vec4(offset + index));
}

vec4 texture(sampler2D sampler, vec3 pos) {
    int textureId = int(pos.z);
    vec4 col = texelFetch(sampler, ivec2(pos.xy) + ivec2(0, textureMapsArrayIndices[textureId]), 0);
    return col;
}

